// ============================================================
// DATABASE
// ============================================================

const db = new Database(DATABASE_PATH);
db.pragma('journal_mode = WAL');

function ensureColumnExists(tableName, columnName, definition) {
    const columns = db.prepare(`PRAGMA table_info(${tableName})`).all();
    const exists = columns.some(column => column.name === columnName);

    if (!exists) {
        db.exec(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${definition}`);
        console.log(`Database migration: added ${tableName}.${columnName}`);
    }
}

// ============================================================
// ACTIVE NORMAL GAME
// ============================================================

db.exec(`
    CREATE TABLE IF NOT EXISTS active_game (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        status TEXT NOT NULL,
        source TEXT NOT NULL DEFAULT 'AUTO',
        channel_id TEXT,
        message_id TEXT,
        course_folder TEXT,
        course_display TEXT,
        hole_number INTEGER,
        image_path TEXT,
        required_smashes INTEGER,
        current_smashes INTEGER DEFAULT 0,
        started_at TEXT,
        winner_user_id TEXT,
        winner_display_name TEXT,
        completed_at TEXT,
        result_key TEXT,
        result_display TEXT,
        reward_rarity TEXT,
        score_earned INTEGER DEFAULT 0,
        reward_item_type TEXT,
        reward_item_id TEXT,
        reward_item_name TEXT,
        reward_image_path TEXT,
        duplicate INTEGER DEFAULT 0,
        duplicate_bonus INTEGER DEFAULT 0
    );
`);

ensureColumnExists('active_game', 'result_key', 'TEXT');
ensureColumnExists('active_game', 'result_display', 'TEXT');
ensureColumnExists('active_game', 'reward_rarity', 'TEXT');
ensureColumnExists('active_game', 'score_earned', 'INTEGER DEFAULT 0');
ensureColumnExists('active_game', 'reward_item_type', 'TEXT');
ensureColumnExists('active_game', 'reward_item_id', 'TEXT');
ensureColumnExists('active_game', 'reward_item_name', 'TEXT');
ensureColumnExists('active_game', 'reward_image_path', 'TEXT');
ensureColumnExists('active_game', 'duplicate', 'INTEGER DEFAULT 0');
ensureColumnExists('active_game', 'duplicate_bonus', 'INTEGER DEFAULT 0');
ensureColumnExists('active_game', 'source', "TEXT NOT NULL DEFAULT 'AUTO'");

