// ============================================================
// SMASHPUTT SMASH DUB
// ============================================================

let smashDubDeadlineTimer = null;
let smashDubSpawnInProgress = false;

function clearSmashDubTimer() {
    if (smashDubDeadlineTimer) {
        clearTimeout(smashDubDeadlineTimer);
        smashDubDeadlineTimer = null;
    }
}

function listSmashDubSceneFilesRecursive(directoryPath) {
    if (!fs.existsSync(directoryPath)) return [];
    const results = [];
    for (const entry of fs.readdirSync(directoryPath, { withFileTypes: true })) {
        const fullPath = path.join(directoryPath, entry.name);
        if (entry.isDirectory()) {
            results.push(...listSmashDubSceneFilesRecursive(fullPath));
            continue;
        }
        if (/\.(png|jpe?g|webp)$/i.test(entry.name)) {
            results.push(fullPath);
        }
    }
    return results.sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

function getSmashDubStartersForScene(scenePath) {
    const sceneFilename = path.basename(scenePath);
    const starters = SMASH_DUB_SCENE_PROMPTS[sceneFilename];
    if (!starters || !starters.length) {
        throw new Error(`No Smash Dub prompts are configured for scene: ${sceneFilename}`);
    }
    return starters;
}

function pickRandomSmashDubScene() {
    const sceneFiles = listSmashDubSceneFilesRecursive(SMASH_DUB_SCENE_DIR);
    if (!sceneFiles.length) {
        throw new Error(`No Smash Dub scene images were found in ${SMASH_DUB_SCENE_DIR}`);
    }

    const supportedSceneFiles = sceneFiles.filter(scenePath =>
        Object.prototype.hasOwnProperty.call(SMASH_DUB_SCENE_PROMPTS, path.basename(scenePath))
    );

    if (!supportedSceneFiles.length) {
        throw new Error(`No configured Smash Dub scene filenames were found in ${SMASH_DUB_SCENE_DIR}`);
    }

    const scenePath = supportedSceneFiles[randomInteger(0, supportedSceneFiles.length - 1)];
    const starters = getSmashDubStartersForScene(scenePath);
    const starterText = starters[randomInteger(0, starters.length - 1)];

    return {
        scenePath,
        sceneFilename: path.basename(scenePath),
        starterText
    };
}

function containsBlockedSmashDubText(text) {
    const normalized = String(text || '').normalize('NFKC');
    return SMASH_DUB_BLOCK_PATTERNS.some(pattern => pattern.test(normalized));
}

function measureSmashDubTextWidth(text, fontSize) {
    // Deliberately conservative. The previous estimate was too narrow for
    // the bold sans-serif face used by librsvg/Sharp and could allow a line
    // that looked valid mathematically to render past the right edge.
    let units = 0;
    for (const char of String(text || '')) {
        if (char === ' ') units += 0.38;
        else if (/[MW@#%&]/.test(char)) units += 0.95;
        else if (/[A-Z]/.test(char)) units += 0.82;
        else if (/[ilI1|]/.test(char)) units += 0.36;
        else if (/[.,;:!?\'\-]/.test(char)) units += 0.40;
        else units += 0.72;
    }
    return units * fontSize;
}

function wrapSmashDubText(text, fontSize, maxWidth) {
    const rawWords = String(text || '').trim().split(/\s+/).filter(Boolean);
    if (!rawWords.length) return [''];

    const words = [];
    for (const rawWord of rawWords) {
        if (measureSmashDubTextWidth(rawWord, fontSize) <= maxWidth) {
            words.push(rawWord);
            continue;
        }

        let chunk = '';
        for (const char of rawWord) {
            const candidate = chunk + char;
            if (!chunk || measureSmashDubTextWidth(candidate, fontSize) <= maxWidth) {
                chunk = candidate;
            } else {
                words.push(chunk);
                chunk = char;
            }
        }
        if (chunk) words.push(chunk);
    }

    const lines = [];
    let current = '';

    for (const word of words) {
        const candidate = current ? `${current} ${word}` : word;
        if (!current || measureSmashDubTextWidth(candidate, fontSize) <= maxWidth) {
            current = candidate;
            continue;
        }
        lines.push(current);
        current = word;
    }
    if (current) lines.push(current);
    return lines;
}

function fitSmashDubText(text, { fontSizes, maxWidth, maxLines }) {
    for (const fontSize of fontSizes) {
        const lines = wrapSmashDubText(text, fontSize, maxWidth);
        if (lines.length <= maxLines) {
            return { lines, fontSize, lineHeight: Math.round(fontSize * 1.2) };
        }
    }
    const smallest = fontSizes[fontSizes.length - 1];
    return {
        lines: wrapSmashDubText(text, smallest, maxWidth).slice(0, maxLines),
        fontSize: smallest,
        lineHeight: Math.round(smallest * 1.2)
    };
}

function fitSmashDubCaptionPair(starterText, responseText, { maxWidth, maxHeight }) {
    const fontSizes = [30, 28, 26, 24, 22, 20, 18, 16, 14];
    const gap = 10;

    for (const fontSize of fontSizes) {
        const lineHeight = Math.round(fontSize * 1.18);
        const setupLines = wrapSmashDubText(starterText, fontSize, maxWidth);
        const responseLines = wrapSmashDubText(responseText, fontSize, maxWidth);
        const totalHeight = (setupLines.length + responseLines.length) * lineHeight + gap;

        if (
            setupLines.length <= 3 &&
            responseLines.length <= 4 &&
            totalHeight <= maxHeight
        ) {
            return { setupLines, responseLines, fontSize, lineHeight, gap, totalHeight };
        }
    }

    const fontSize = 14;
    const lineHeight = Math.round(fontSize * 1.18);
    const setupLines = wrapSmashDubText(starterText, fontSize, maxWidth);
    const responseLines = wrapSmashDubText(responseText, fontSize, maxWidth);
    const totalHeight = (setupLines.length + responseLines.length) * lineHeight + gap;
    return { setupLines, responseLines, fontSize, lineHeight, gap, totalHeight };
}

function buildSmashDubActionRow(disabled = false) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(SMASH_DUB_WRITE_BUTTON_ID)
            .setLabel('FINISH THE LINE')
            .setEmoji('✍️')
            .setStyle(ButtonStyle.Primary)
            .setDisabled(disabled)
    );
}

function buildSmashDubActiveEmbed(state) {
    const deadlineUnix = Math.floor(new Date(state.deadline_at).getTime() / 1000);

    return new EmbedBuilder()
        .setColor(0x9B59B6)
        .setTitle('✍️ FINISH THE LINE')
        .setDescription(
            `**A player is creating...**\n\n` +
            `Press **FINISH THE LINE** to write your line privately.\n` +
            `Only the player who started this round can submit a line.\n\n` +
            `⏱️ **TIME LEFT:** <t:${deadlineUnix}:R>`
        )
        .setImage(SMASH_DUB_BANNER_URL);
}

function buildSmashDubExpiredEmbed(state) {
    return new EmbedBuilder()
        .setColor(0x747F8D)
        .setTitle('✍️ FINISH THE LINE — EXPIRED')
        .setDescription('**No line was submitted in time.**');
}

function buildSmashDubResultEmbed(state) {
    return new EmbedBuilder()
        .setColor(0x2ECC71)
        .setTitle('✍️ FINISH THE LINE')
        .setImage(`attachment://${SMASH_DUB_ATTACHMENT_NAME}`);
}

function buildSmashDubModal(gameKey, starterText) {
    const promptText = String(starterText || '').trim();
    if (!promptText || promptText.length > 42) {
        throw new Error(`Finish the Line prompt must be 1-42 characters for the modal label: ${promptText}`);
    }

    const input = new TextInputBuilder()
        .setCustomId(SMASH_DUB_RESPONSE_INPUT_ID)
        .setLabel(`✍️ ${promptText}`)
        .setStyle(TextInputStyle.Paragraph)
        .setRequired(true)
        .setMinLength(1)
        .setMaxLength(SMASH_DUB_RESPONSE_MAX_LENGTH);

    return new ModalBuilder()
        .setCustomId(`${SMASH_DUB_MODAL_PREFIX}${gameKey}`)
        .setTitle('YOU HAVE 2 MINUTES • FINISH THIS LINE')
        .addComponents(new ActionRowBuilder().addComponents(input));
}

async function generateSmashDubImage({ scenePath, starterText, responseText, creatorName }) {
    const width = 1200;
    const height = 800;
    const preparedBackground = await sharp(scenePath).resize(width, height, { fit: 'cover' }).png().toBuffer();

    const boxX = 48;
    const boxY = 560;
    const boxWidth = 1104;
    const boxHeight = 186;
    const textX = boxX + 28;

    // Leave a large safety margin on the right instead of using nearly the
    // whole caption box width. The same font size is used for both lines.
    const maxWidth = boxWidth - 124;
    const maxTextHeight = boxHeight - 34;
    const captionFit = fitSmashDubCaptionPair(
        starterText,
        responseText,
        { maxWidth, maxHeight: maxTextHeight }
    );

    const { setupLines, responseLines, fontSize, lineHeight, gap, totalHeight } = captionFit;
    const blockTop = Math.round(boxY + (boxHeight - totalHeight) / 2);
    const setupBaselineY = Math.round(blockTop + fontSize);
    const responseBaselineY = Math.round(
        setupBaselineY + setupLines.length * lineHeight + gap
    );

    const setupLinesSvg = setupLines.map((line, index) => `
        <text x="${textX}" y="${Math.round(setupBaselineY + index * lineHeight)}" font-family="sans-serif" font-size="${fontSize}" font-weight="700" fill="#ffffff">${escapeXml(line)}</text>
    `).join('');

    const responseLinesSvg = responseLines.map((line, index) => `
        <text x="${textX}" y="${Math.round(responseBaselineY + index * lineHeight)}" font-family="sans-serif" font-size="${fontSize}" font-weight="700" fill="#ffd166">${escapeXml(line)}</text>
    `).join('');

    const overlaySvg = `
        <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <defs>
                <linearGradient id="captionfade" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stop-color="#000000" stop-opacity="0.78"/>
                    <stop offset="100%" stop-color="#000000" stop-opacity="0.66"/>
                </linearGradient>
            </defs>
            <rect x="${boxX}" y="${boxY}" width="${boxWidth}" height="${boxHeight}" rx="26" fill="url(#captionfade)" stroke="#ffffff" stroke-opacity="0.16" stroke-width="2"/>
            ${setupLinesSvg}
            ${responseLinesSvg}
        </svg>
    `;

    return sharp(preparedBackground).composite([{ input: Buffer.from(overlaySvg), left: 0, top: 0 }]).png().toBuffer();
}

async function fetchSmashDubControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Smash Dub channel could not be found: ${state.channel_id}`);
    }
    return { channel, message: await channel.messages.fetch(state.control_message_id) };
}

async function finishExpiredSmashDubIfDue(gameKey) {
    const state = getActiveSmashDubStmt.get();
    if (!state || state.game_key !== gameKey) return;
    if (new Date(state.deadline_at).getTime() > Date.now()) return;

    clearSmashDubTimer();
    const completedAt = new Date().toISOString();
    cancelSmashDubStmt.run({ game_key: gameKey, completed_at: completedAt, result_announced_at: completedAt });
    const cancelledState = getSmashDubStmt.get();

    try {
        const { message } = await fetchSmashDubControlMessage(cancelledState);
        await message.edit({ embeds: [buildSmashDubExpiredEmbed(cancelledState)], components: [buildSmashDubActionRow(true)] });
    } catch (error) {
        console.error('[SMASH DUB] Could not update expired game message:', error);
    }

    await refreshPurchasePanelGameLock();
    console.log(`[SMASH DUB] Timed out | Key ${gameKey}`);
    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: false, reason: 'manual Smash Dub complete; automatic schedule resumed' });
    }
}

function armSmashDubTimer(state) {
    clearSmashDubTimer();
    const deadlineMs = new Date(state.deadline_at).getTime();
    const remaining = deadlineMs - Date.now();
    if (remaining <= 0) {
        finishExpiredSmashDubIfDue(state.game_key).catch(error => console.error('[SMASH DUB] Expired finish failed:', error));
        return;
    }
    smashDubDeadlineTimer = setTimeout(() => {
        smashDubDeadlineTimer = null;
        finishExpiredSmashDubIfDue(state.game_key).catch(error => console.error('[SMASH DUB] Timer finish failed:', error));
    }, Math.min(remaining + 25, 2_147_000_000));
}

async function createSmashDubInChannel(channelId, creatorUserId, creatorDisplayName, creatorCleanName) {
    if (!channelId) return { ok: false, reason: 'NO_CHANNEL' };
    if (smashDubSpawnInProgress || hasActiveSmashPuttActivity()) return { ok: false, reason: 'ACTIVE_ACTIVITY' };

    smashDubSpawnInProgress = true;
    let controlMessage = null;

    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) throw new Error(`Smash Dub channel could not be found: ${channelId}`);

        const scene = pickRandomSmashDubScene();
        const startedAt = new Date();
        const deadlineAt = new Date(startedAt.getTime() + SMASH_DUB_SUBMISSION_WINDOW_MS);

        const provisionalState = {
            creator_clean_name: creatorCleanName,
            creator_display_name: creatorDisplayName,
            starter_text: scene.starterText,
            deadline_at: deadlineAt.toISOString()
        };

        controlMessage = await channel.send({
            embeds: [buildSmashDubActiveEmbed(provisionalState)],
            components: [buildSmashDubActionRow(false)],
            allowedMentions: { parse: [] }
        });

        const confirmedStartedAt = new Date(Number(controlMessage.createdTimestamp) || Date.now());
        const confirmedDeadlineAt = new Date(confirmedStartedAt.getTime() + SMASH_DUB_SUBMISSION_WINDOW_MS);

        createSmashDubStmt.run({
            game_key: controlMessage.id,
            channel_id: controlMessage.channelId,
            control_message_id: controlMessage.id,
            creator_user_id: creatorUserId,
            creator_display_name: creatorDisplayName,
            creator_clean_name: creatorCleanName,
            scene_filename: scene.sceneFilename,
            scene_path: scene.scenePath,
            starter_text: scene.starterText,
            started_at: confirmedStartedAt.toISOString(),
            deadline_at: confirmedDeadlineAt.toISOString()
        });

        const state = getActiveSmashDubStmt.get();
        await controlMessage.edit({ embeds: [buildSmashDubActiveEmbed(state)], components: [buildSmashDubActionRow(false)] });
        await refreshPurchasePanelGameLock();

        pauseSchedulerForActiveGame();
        armSmashDubTimer(state);
        console.log(`[SMASH DUB] Round started | Key ${state.game_key} | Scene ${state.scene_filename}`);
        return { ok: true, state };
    } catch (error) {
        console.error('[SMASH DUB] Could not start:', error);
        if (controlMessage) {
            try { await controlMessage.delete(); } catch (_) {}
        }
        return { ok: false, reason: 'ERROR', error };
    } finally {
        smashDubSpawnInProgress = false;
    }
}

async function handleSmashDubWriteButton(interaction) {
    const state = getActiveSmashDubStmt.get();
    if (!state) {
        await interaction.reply({ content: 'This Finish the Line round has ended.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (new Date(state.deadline_at).getTime() <= Date.now()) {
        await interaction.reply({ content: 'This Finish the Line round has expired.', flags: MessageFlags.Ephemeral });
        finishExpiredSmashDubIfDue(state.game_key).catch(error => console.error('[SMASH DUB] Late-button finish failed:', error));
        return;
    }

    if (interaction.user.id !== state.creator_user_id) {
        await interaction.reply({ content: 'This Finish the Line belongs to another player.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.showModal(buildSmashDubModal(state.game_key, state.starter_text));
}

async function handleSmashDubModal(interaction) {
    const gameKey = interaction.customId.substring(SMASH_DUB_MODAL_PREFIX.length);
    const state = getActiveSmashDubStmt.get();
    const responseText = String(interaction.fields.getTextInputValue(SMASH_DUB_RESPONSE_INPUT_ID) || '').normalize('NFKC').replace(/\s+/g, ' ').trim();

    if (!state || state.game_key !== gameKey) {
        await interaction.reply({ content: 'This Finish the Line round is no longer active.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (interaction.user.id !== state.creator_user_id) {
        await interaction.reply({ content: 'This Finish the Line belongs to another player.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (!responseText) {
        await interaction.reply({ content: 'Your line cannot be empty.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (new Date(state.deadline_at).getTime() <= Date.now()) {
        await interaction.reply({ content: 'This Finish the Line round has expired.', flags: MessageFlags.Ephemeral });
        finishExpiredSmashDubIfDue(state.game_key).catch(error => console.error('[SMASH DUB] Late-modal finish failed:', error));
        return;
    }

    if (containsBlockedSmashDubText(responseText)) {
        await interaction.reply({ content: 'That line uses a blocked word. Try a different line.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });

    try {
        const imageBuffer = await generateSmashDubImage({
            scenePath: state.scene_path,
            starterText: state.starter_text,
            responseText,
            creatorName: state.creator_clean_name || state.creator_display_name || 'Player'
        });

        const completedAt = new Date().toISOString();
        completeSmashDubStmt.run({
            game_key: gameKey,
            response_text: responseText,
            completed_at: completedAt,
            result_announced_at: completedAt
        });

        clearSmashDubTimer();
        const completedState = getSmashDubStmt.get();
        const attachment = new AttachmentBuilder(imageBuffer, { name: SMASH_DUB_ATTACHMENT_NAME });

        try {
            const { message } = await fetchSmashDubControlMessage(completedState);
            await message.edit({
                embeds: [buildSmashDubResultEmbed(completedState)],
                components: [buildSmashDubActionRow(true)],
                files: [attachment]
            });
        } catch (error) {
            console.error('[SMASH DUB] Could not update completed game message:', error);
        }

        await refreshPurchasePanelGameLock();
        console.log(`[SMASH DUB] Completed | Key ${gameKey} | Scene ${completedState.scene_filename}`);
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: false, reason: 'manual Smash Dub complete; automatic schedule resumed' });
        }

        await interaction.editReply({ content: '✅ Finish the Line posted.' });
    } catch (error) {
        console.error('[SMASH DUB] Could not render final image:', error);
        await interaction.editReply({ content: 'Finish the Line could not be rendered. The round is still active, so you can try again.' });
    }
}

function getSmashDubBuyCooldownMinutes() {
    const stored = Number.parseInt(getSetting(SMASH_DUB_BUY_COOLDOWN_SETTING), 10);
    if (SMASH_DUB_ALLOWED_BUY_COOLDOWN_MINUTES.includes(stored)) {
        return stored;
    }
    return SMASH_DUB_DEFAULT_BUY_COOLDOWN_MINUTES;
}

function getSmashDubBuyCooldownMs() {
    return getSmashDubBuyCooldownMinutes() * 60 * 1000;
}

async function handleSmashDubCooldownCommand(interaction) {
    const requestedMinutes = interaction.options.getInteger('minutes');

    if (!SMASH_DUB_ALLOWED_BUY_COOLDOWN_MINUTES.includes(requestedMinutes)) {
        await interaction.reply({
            content: 'Finish the Line cooldown must be 5, 10, 15, 20, or 30 minutes.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    setSetting(SMASH_DUB_BUY_COOLDOWN_SETTING, requestedMinutes);

    await interaction.reply({
        content: `✅ Finish the Line per-player cooldown changed to **${requestedMinutes} minutes**.`,
        flags: MessageFlags.Ephemeral
    });

    console.log(`[SMASH DUB] Per-player activation cooldown changed to ${requestedMinutes} minutes.`);
}

function getSmashDubBuyCooldownStatus(userId) {
    const row = getSmashDubBuyCooldownStmt.get(userId);
    if (!row) return { available: true, remainingMs: 0 };

    const startedAt = new Date(row.last_started_at);
    const effectiveNext = Number.isNaN(startedAt.getTime())
        ? new Date(row.next_available_at)
        : new Date(startedAt.getTime() + getSmashDubBuyCooldownMs());

    const remainingMs = effectiveNext.getTime() - Date.now();
    return { available: remainingMs <= 0, remainingMs: Math.max(0, remainingMs) };
}

function formatSmashDubBuyCooldown(remainingMs) {
    const minutes = Math.max(1, Math.ceil(Number(remainingMs || 0) / 60000));
    return `${minutes} minute${minutes === 1 ? '' : 's'}`;
}

async function handlePurchasePanelSmashDubButton(interaction) {
    const storedMessageId = getSetting(PURCHASE_PANEL_MESSAGE_SETTING);
    if (!storedMessageId || interaction.message.id !== storedMessageId) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }

    if (interaction.channelId !== PURCHASE_PANEL_CHANNEL_ID) {
        await interaction.reply({
            content: 'Finish the Line is only available from the official SmashPutt Games panel.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const cooldown = getSmashDubBuyCooldownStatus(interaction.user.id);
    if (!cooldown.available) {
        await interaction.reply({
            content: `Your next Finish the Line activation is available in **${formatSmashDubBuyCooldown(cooldown.remainingMs)}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (smashDubSpawnInProgress || hasActiveSmashPuttActivity()) {
        await interaction.reply({
            content: 'SmashPutt is busy with another activity right now. No cooldown was used.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });

    const latestCooldown = getSmashDubBuyCooldownStatus(interaction.user.id);
    if (!latestCooldown.available) {
        await interaction.editReply({
            content: `Your next Finish the Line activation is available in **${formatSmashDubBuyCooldown(latestCooldown.remainingMs)}**.`
        });
        return;
    }

    if (smashDubSpawnInProgress || hasActiveSmashPuttActivity()) {
        await interaction.editReply({
            content: 'SmashPutt is busy with another activity right now. No cooldown was used.'
        });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const cleanName = getCleanDiscordName(interaction);
    const result = await createSmashDubInChannel(
        PURCHASE_PANEL_CHANNEL_ID,
        interaction.user.id,
        displayName,
        cleanName
    );

    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({
                forceNew: false,
                reason: 'player Smash Dub launch failed; automatic schedule resumed'
            });
        }
        await interaction.editReply({
            content: 'Finish the Line could not be started. No cooldown was used.'
        });
        return;
    }

    const startedAt = new Date(result.state.started_at);
    const safeStartedAt = Number.isNaN(startedAt.getTime()) ? new Date() : startedAt;
    upsertSmashDubBuyCooldownStmt.run({
        user_id: interaction.user.id,
        last_started_at: safeStartedAt.toISOString(),
        next_available_at: new Date(safeStartedAt.getTime() + getSmashDubBuyCooldownMs()).toISOString()
    });

    const cooldownMinutes = getSmashDubBuyCooldownMinutes();
    console.log(`[SMASH DUB BUY] ${cleanName} | Player-launched round live | Cooldown ${cooldownMinutes} minutes`);
    await interaction.editReply({
        content: `✅ Finish the Line is live now. Your next activation is available in ${cooldownMinutes} minutes.`
    });
}

async function handleSmashDubCommand(interaction) {
    if (smashDubSpawnInProgress || hasActiveSmashPuttActivity()) {
        await interaction.reply({ content: 'A SmashPutt activity is already live.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    const creatorDisplayName = interaction.member?.displayName || interaction.user.globalName || interaction.user.username;
    const creatorCleanName = getCleanDiscordName(interaction);

    const result = await createSmashDubInChannel(interaction.channelId, interaction.user.id, creatorDisplayName, creatorCleanName);
    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: false, reason: 'manual Smash Dub launch failed; automatic schedule resumed' });
        }
        await interaction.editReply({ content: 'Finish the Line could not be started.' });
        return;
    }

    await interaction.editReply({ content: '✅ Finish the Line is live. Press **FINISH THE LINE** on the message to write your line.' });
}

async function resumeSmashDubOnStartup() {
    clearSmashDubTimer();
    const state = getSmashDubStmt.get();
    if (!state || state.status !== 'ACTIVE') {
        console.log('No active Smash Dub currently exists.');
        return;
    }

    if (new Date(state.deadline_at).getTime() <= Date.now()) {
        await finishExpiredSmashDubIfDue(state.game_key);
        return;
    }

    try {
        const { message } = await fetchSmashDubControlMessage(state);
        await message.edit({ embeds: [buildSmashDubActiveEmbed(state)], components: [buildSmashDubActionRow(false)] });
    } catch (error) {
        console.error('[SMASH DUB] Active display recovery failed:', error);
    }

    pauseSchedulerForActiveGame();
    await refreshPurchasePanelGameLock();
    armSmashDubTimer(state);
    console.log(`[SMASH DUB] Recovered active game ${state.game_key}.`);
}

