let blackMarketPanelTimer = null;
let blackMarketGenerationInProgress = false;
let blackMarketTestGenerationInProgress = false;

function clearBlackMarketTimer() {
    if (blackMarketPanelTimer) {
        clearTimeout(blackMarketPanelTimer);
        blackMarketPanelTimer = null;
    }
}

function slugifyBlackMarketText(value) {
    return String(value || '')
        .normalize('NFKD')
        .replace(/[^\w\s-]/g, '')
        .trim()
        .replace(/[-\s]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .toLowerCase() || 'item';
}

function getBlackMarketCentralDateKey(date = new Date()) {
    const parts = getCentralDateTimeParts(date);
    return `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
}

function normalizeBlackMarketDailyCounters(date = new Date()) {
    const dateKey = getBlackMarketCentralDateKey(date);
    const storedDate = getSetting(BLACK_MARKET_DAILY_DATE_SETTING);
    let sold = Number.parseInt(getSetting(BLACK_MARKET_DAILY_SOLD_SETTING), 10);
    if (!Number.isFinite(sold) || sold < 0) sold = 0;
    if (storedDate !== dateKey) {
        sold = 0;
        setSetting(BLACK_MARKET_DAILY_DATE_SETTING, dateKey);
        setSetting(BLACK_MARKET_DAILY_SOLD_SETTING, '0');
    }
    sold = Math.min(sold, BLACK_MARKET_DAILY_STOCK);
    return { dateKey, sold, available: Math.max(0, BLACK_MARKET_DAILY_STOCK - sold) };
}

function decrementBlackMarketDailySoldIfPossible(stockDate) {
    const counters = normalizeBlackMarketDailyCounters();
    if (stockDate && counters.dateKey === stockDate && counters.sold > 0) {
        const sold = Math.max(0, counters.sold - 1);
        setSetting(BLACK_MARKET_DAILY_SOLD_SETTING, String(sold));
        return { ...counters, sold, available: Math.max(0, BLACK_MARKET_DAILY_STOCK - sold) };
    }
    return counters;
}

function titleCaseBlackMarketWord(value) {
    return String(value || '').replace(/\b\w/g, char => char.toUpperCase());
}

