function buildBlackMarketActionRow({ soldOut = false, disabled = false } = {}) {
    if (soldOut) {
        return new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId(BLACK_MARKET_CLOSE_BUTTON_ID)
                .setLabel('CLOSE')
                .setStyle(ButtonStyle.Secondary)
                .setDisabled(disabled)
        );
    }
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(BLACK_MARKET_BUY_BUTTON_ID)
            .setLabel('BUY')
            .setStyle(ButtonStyle.Success)
            .setDisabled(disabled),
        new ButtonBuilder()
            .setCustomId(BLACK_MARKET_CANCEL_BUTTON_ID)
            .setLabel('CANCEL')
            .setStyle(ButtonStyle.Secondary)
            .setDisabled(disabled)
    );
}

async function fetchBlackMarketControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Black Market channel could not be found: ${state.channel_id}`);
    }
    return { channel, message: await channel.messages.fetch(state.control_message_id) };
}

function armBlackMarketTimer(state) {
    clearBlackMarketTimer();
    if (!state || !['OPEN', 'SOLD_OUT'].includes(state.status)) return;
    const expiresAt = new Date(state.expires_at).getTime();
    const remaining = expiresAt - Date.now();
    if (remaining <= 0) {
        expireBlackMarketIfDue().catch(error => console.error('[BLACK MARKET] Immediate expiration failed:', error));
        return;
    }
    blackMarketPanelTimer = setTimeout(() => {
        blackMarketPanelTimer = null;
        expireBlackMarketIfDue().catch(error => console.error('[BLACK MARKET] Timer expiration failed:', error));
    }, Math.min(remaining + 25, 2_147_000_000));
}

async function concludeBlackMarket(reason = 'closed') {
    clearBlackMarketTimer();
    const state = getActiveBlackMarketStmt.get();
    if (!state) return;
    try {
        const { message } = await fetchBlackMarketControlMessage(state);
        await message.delete().catch(() => null);
    } catch (_) {
        // ignore cleanup fetch errors
    }
    deleteBlackMarketStateStmt.run();
    await refreshPurchasePanelGameLock();
    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: false, reason: `black market ${reason}; automatic schedule resumed` });
    }
}

async function expireBlackMarketIfDue() {
    const state = getActiveBlackMarketStmt.get();
    if (!state || !['OPEN', 'SOLD_OUT'].includes(state.status)) return;
    if (new Date(state.expires_at).getTime() > Date.now()) return;
    await concludeBlackMarket('expired');
}

const beginBlackMarketPurchaseTransaction = db.transaction(({ controlMessageId, userId, displayName, cleanName }) => {
    const state = getBlackMarketStmt.get();
    if (!state || state.status !== 'OPEN' || state.control_message_id !== controlMessageId) {
        return { type: 'NO_ACTIVE' };
    }
    if (state.opener_user_id !== userId) {
        return { type: 'NOT_OWNER' };
    }
    if (new Date(state.expires_at).getTime() <= Date.now()) {
        return { type: 'EXPIRED' };
    }

    const counters = normalizeBlackMarketDailyCounters();
    if (counters.available <= 0) {
        return { type: 'SOLD_OUT' };
    }

    ensurePlayer(userId, displayName);
    const player = getPlayerStmt.get(userId);
    if (!player || Number(player.smash_score || 0) < BLACK_MARKET_COST) {
        return { type: 'INSUFFICIENT', currentScore: Number(player?.smash_score || 0) };
    }

    const conceptIndex = getBlackMarketNextConceptIndex();
    const concept = BLACK_MARKET_CONCEPT_BANK[conceptIndex];
    if (!concept) {
        return { type: 'NO_CONCEPT' };
    }

    const now = new Date().toISOString();
    const removal = removeSmashScoreStmt.run({
        user_id: userId,
        display_name: displayName,
        amount: BLACK_MARKET_COST,
        updated_at: now
    });
    if (removal.changes !== 1) {
        return { type: 'INSUFFICIENT', currentScore: Number(getPlayerStmt.get(userId)?.smash_score || 0) };
    }

    insertScoreTransactionStmt.run({
        user_id: userId,
        display_name: displayName,
        transaction_type: 'REMOVE',
        amount: BLACK_MARKET_COST,
        reason: 'Black Market purchase',
        admin_user_id: userId,
        admin_display_name: displayName,
        created_at: now
    });

    setSetting(BLACK_MARKET_DAILY_DATE_SETTING, counters.dateKey);
    setSetting(BLACK_MARKET_DAILY_SOLD_SETTING, String(counters.sold + 1));

    const itemId = `black_market/${counters.dateKey}/${Date.now()}-${randomInteger(1000, 9999)}-${String(concept.id).padStart(4, '0')}`;
    const itemName = `Black Market ${concept.title}`;

    const update = markBlackMarketProcessingStmt.run({
        control_message_id: controlMessageId,
        opener_user_id: userId,
        stock_date: counters.dateKey,
        concept_index: conceptIndex,
        concept_title: concept.title,
        item_id: itemId,
        item_name: itemName,
        purchased_at: now
    });

    if (update.changes !== 1) {
        addSmashScoreStmt.run({
            user_id: userId,
            display_name: displayName,
            amount: BLACK_MARKET_COST,
            updated_at: now
        });
        insertScoreTransactionStmt.run({
            user_id: userId,
            display_name: displayName,
            transaction_type: 'ADD',
            amount: BLACK_MARKET_COST,
            reason: 'Black Market purchase rollback',
            admin_user_id: userId,
            admin_display_name: displayName,
            created_at: now
        });
        decrementBlackMarketDailySoldIfPossible(counters.dateKey);
        return { type: 'NO_ACTIVE' };
    }

    return {
        type: 'READY',
        state: getBlackMarketStmt.get(),
        concept,
        conceptIndex,
        itemId,
        itemName,
        stockDate: counters.dateKey,
        player: getPlayerStmt.get(userId)
    };
});

const refundBlackMarketPurchaseTransaction = db.transaction(({ userId, displayName, stockDate, reason }) => {
    const now = new Date().toISOString();
    decrementBlackMarketDailySoldIfPossible(stockDate);
    addSmashScoreStmt.run({
        user_id: userId,
        display_name: displayName,
        amount: BLACK_MARKET_COST,
        updated_at: now
    });
    insertScoreTransactionStmt.run({
        user_id: userId,
        display_name: displayName,
        transaction_type: 'ADD',
        amount: BLACK_MARKET_COST,
        reason,
        admin_user_id: userId,
        admin_display_name: displayName,
        created_at: now
    });
    deleteBlackMarketStateStmt.run();
    return getPlayerStmt.get(userId);
});

function getBlackMarketPrompt(concept) {
    return [
        concept.prompt,
        'Create a realistic golf ball based on this concept.',
        'PNG transparent background.',
        'No floor or shadow.',
        'Not cartoon.'
    ].join(' ');
}

async function generateBlackMarketImageBuffer(concept) {
    const apiKey = String(process.env.OPENAI_API_KEY || '').trim();
    if (!apiKey) {
        const error = new Error('OPENAI_API_KEY is not configured.');
        error.code = 'MISSING_OPENAI_API_KEY';
        throw error;
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), PICTIONARY_API_TIMEOUT_MS);

    try {
        const response = await fetch(BLACK_MARKET_IMAGE_API_URL, {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${apiKey}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                model: BLACK_MARKET_IMAGE_MODEL,
                prompt: getBlackMarketPrompt(concept),
                size: BLACK_MARKET_IMAGE_SIZE,
                quality: BLACK_MARKET_IMAGE_QUALITY,
                output_format: 'png',
                background: 'transparent',
                n: 1
            }),
            signal: controller.signal
        });

        const payload = await response.json().catch(() => null);
        if (!response.ok) {
            const apiMessage = payload?.error?.message || `HTTP ${response.status}`;
            const error = new Error(`OpenAI Black Market image request failed: ${apiMessage}`);
            error.code = payload?.error?.code || payload?.error?.type || 'OPENAI_ERROR';
            error.status = response.status;
            throw error;
        }

        const imageBase64 = payload?.data?.[0]?.b64_json;
        let imageBuffer = imageBase64 ? Buffer.from(imageBase64, 'base64') : null;

        if (!imageBuffer && payload?.data?.[0]?.url) {
            const imageResponse = await fetch(payload.data[0].url, { signal: controller.signal });
            if (!imageResponse.ok) {
                throw new Error(`Generated Black Market image download failed with HTTP ${imageResponse.status}.`);
            }
            imageBuffer = Buffer.from(await imageResponse.arrayBuffer());
        }

        if (!imageBuffer || imageBuffer.length < 1024) {
            throw new Error('OpenAI returned no usable Black Market image data.');
        }

        return await sharp(imageBuffer)
            .resize(800, 800, {
                fit: 'contain',
                background: { r: 0, g: 0, b: 0, alpha: 0 }
            })
            .png()
            .toBuffer();
    } finally {
        clearTimeout(timeout);
    }
}

async function uploadBlackMarketAssetToPrivateChannel({ itemName, buffer, purchaserName, conceptNumber }) {
    try {
        const channel = await client.channels.fetch(BLACK_MARKET_ASSET_CHANNEL_ID);
        if (!channel || !channel.isTextBased()) {
            throw new Error(`Black Market asset channel unavailable: ${BLACK_MARKET_ASSET_CHANNEL_ID}`);
        }
        await channel.send({
            content:
                `🕶️ **BLACK MARKET ASSET**\n` +
                `Item: **${escapeDiscordMarkdown(itemName)}**\n` +
                `Buyer: **${escapeDiscordMarkdown(purchaserName)}**\n` +
                `Concept #: **${conceptNumber}**\n` +
                `Time: ${getCentralTimeString()}`,
            files: [new AttachmentBuilder(buffer, { name: BLACK_MARKET_IMAGE_ATTACHMENT_NAME })],
            allowedMentions: { parse: [] }
        });
    } catch (error) {
        console.error('[BLACK MARKET] Private asset upload failed:', error);
    }
}

async function failBlackMarketPurchase(purchase, error, interaction = null) {
    console.error('[BLACK MARKET] Purchase failed:', error);

    try {
        refundBlackMarketPurchaseTransaction({
            userId: purchase.state.opener_user_id,
            displayName: purchase.state.opener_display_name,
            stockDate: purchase.stockDate,
            reason: 'Black Market purchase refunded after failure'
        });
    } catch (refundError) {
        console.error('[BLACK MARKET] Refund failed:', refundError);
    }

    try {
        const { channel, message } = await fetchBlackMarketControlMessage(purchase.state);
        await message.delete().catch(() => null);
        await channel.send({
            content: `🕶️ **${escapeDiscordMarkdown(purchase.state.opener_clean_name || purchase.state.opener_display_name)}** had a Black Market problem. Their **${BLACK_MARKET_COST} Smash Score** was refunded.`,
            allowedMentions: { parse: [] }
        }).catch(() => null);
    } catch (_) {
        // ignore channel errors
    }

    if (interaction) {
        try {
            await interaction.followUp({
                content: `Your Black Market purchase failed. You were refunded **${BLACK_MARKET_COST} Smash Score**.`,
                flags: MessageFlags.Ephemeral
            });
        } catch (_) {
            // ignore follow-up failure
        }
    }

    updateLeaderboard().catch(error => console.error('Leaderboard refresh after Black Market refund failed:', error));
}

async function fulfillBlackMarketPurchase(purchase, interaction) {
    blackMarketGenerationInProgress = true;
    let itemGranted = false;
    let shouldResumeSchedule = false;
    try {
        fs.mkdirSync(BLACK_MARKET_IMAGES_FOLDER, { recursive: true });
        const buffer = await generateBlackMarketImageBuffer(purchase.concept);
        const slug = slugifyBlackMarketText(purchase.itemName);
        const filePath = path.join(
            BLACK_MARKET_IMAGES_FOLDER,
            `${String(purchase.concept.id).padStart(4, '0')}-${Date.now()}-${slug}.png`
        );
        fs.writeFileSync(filePath, buffer);
        setBlackMarketImagePathStmt.run({
            control_message_id: purchase.state.control_message_id,
            image_path: filePath,
            completed_at: new Date().toISOString()
        });

        await uploadBlackMarketAssetToPrivateChannel({
            itemName: purchase.itemName,
            buffer,
            purchaserName: purchase.state.opener_clean_name || purchase.state.opener_display_name,
            conceptNumber: purchase.concept.id
        });

        insertInventoryItemStmt.run({
            user_id: purchase.state.opener_user_id,
            item_type: 'misc',
            item_id: purchase.itemId,
            item_name: purchase.itemName,
            image_path: filePath,
            first_collected_at: new Date().toISOString()
        });
        advanceBlackMarketConceptIndex(purchase.conceptIndex);
        deleteBlackMarketStateStmt.run();
        itemGranted = true;

        const reward = {
            type: 'misc',
            id: purchase.itemId,
            name: purchase.itemName,
            imagePath: filePath
        };
        await processMiscBallMilestonesAfterReward(purchase.state.opener_user_id, reward, false, false);

        try {
            const channel = await client.channels.fetch(purchase.state.channel_id);
            if (!channel || !channel.isTextBased()) {
                throw new Error(`Black Market delivery channel unavailable: ${purchase.state.channel_id}`);
            }

            const revealEmbed = new EmbedBuilder()
                .setColor(0x111111)
                .setTitle(`🕶️ ${String(purchase.state.opener_clean_name || purchase.state.opener_display_name || 'Player').toUpperCase()}'S BLACK MARKET`)
                .setDescription(
                    `**${escapeDiscordMarkdown(purchase.itemName)}**\n\n` +
                    `🎒 **Added to your Common Miscellaneous collection.**\n` +
                    `View it in your inventory with \`/smashputt inventory\`.`
                )
                .setImage(`attachment://${BLACK_MARKET_IMAGE_ATTACHMENT_NAME}`);

            await channel.send({
                embeds: [revealEmbed],
                files: [new AttachmentBuilder(filePath, { name: BLACK_MARKET_IMAGE_ATTACHMENT_NAME })],
                allowedMentions: { parse: [] }
            });
        } catch (deliveryError) {
            console.error('[BLACK MARKET] Delivery message failed after item grant:', deliveryError);
        }

        try {
            const { message } = await fetchBlackMarketControlMessage(purchase.state);
            await message.delete().catch(() => null);
        } catch (_) {
            // ignore original cleanup failure
        }

        console.log(`[BLACK MARKET] Delivered | ${purchase.state.opener_clean_name} | ${purchase.itemName} | Concept #${purchase.concept.id}`);
        shouldResumeSchedule = true;
        await sendLogMessage(
            `🕶️ **Black Market Purchase Complete**\n` +
            `Player: ${purchase.state.opener_clean_name}\n` +
            `Item: ${purchase.itemName}\n` +
            `Concept #: ${purchase.concept.id}\n` +
            `Cost: ${BLACK_MARKET_COST} Smash Score\n` +
            `Time: ${getCentralTimeString()}`
        );

        updateLeaderboard().catch(error => console.error('Leaderboard refresh after Black Market purchase failed:', error));
    } catch (error) {
        if (itemGranted) {
            console.error('[BLACK MARKET] Post-grant follow-up error:', error);
            shouldResumeSchedule = true;
            try {
                const { message } = await fetchBlackMarketControlMessage(purchase.state);
                await message.delete().catch(() => null);
            } catch (_) {
                // ignore cleanup failure
            }
        } else {
            await failBlackMarketPurchase(purchase, error, interaction);
            shouldResumeSchedule = true;
        }
    } finally {
        blackMarketGenerationInProgress = false;
        await refreshPurchasePanelGameLock();
        if (shouldResumeSchedule && getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: false, reason: 'black market completed; automatic schedule resumed' });
        }
    }
}

let nextBlackMarketTestConceptIndex = 0;

function pickBlackMarketTestConcept() {
    if (!BLACK_MARKET_TEST_CONCEPTS.length) {
        throw new Error('Black Market test concept bank is empty.');
    }

    const index = nextBlackMarketTestConceptIndex % BLACK_MARKET_TEST_CONCEPTS.length;
    nextBlackMarketTestConceptIndex = (index + 1) % BLACK_MARKET_TEST_CONCEPTS.length;
    return { index, concept: BLACK_MARKET_TEST_CONCEPTS[index] };
}

async function handleBlackMarketTestCommand(interaction) {
    if (blackMarketTestGenerationInProgress) {
        await interaction.reply({
            content: 'A Black Market test image is already being prepared. Try again when it finishes.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply();
    blackMarketTestGenerationInProgress = true;

    try {
        const { concept } = pickBlackMarketTestConcept();
        const buffer = await generateBlackMarketImageBuffer(concept);
        const itemName = `Black Market ${concept.title}`;

        const embed = new EmbedBuilder()
            .setColor(0x111111)
            .setTitle('🕶️ BLACK MARKET TEST')
            .setDescription(`**${escapeDiscordMarkdown(itemName)}**`)
            .setImage(`attachment://${BLACK_MARKET_IMAGE_ATTACHMENT_NAME}`);

        await interaction.editReply({
            embeds: [embed],
            files: [new AttachmentBuilder(buffer, { name: BLACK_MARKET_IMAGE_ATTACHMENT_NAME })],
            allowedMentions: { parse: [] }
        });

        console.log(`[BLACK MARKET TEST] ${concept.category} | ${itemName} | Concept #${concept.id}`);
    } catch (error) {
        console.error('[BLACK MARKET TEST] Generation failed:', error);
        await interaction.editReply({
            content: 'Black Market test image generation failed. Check the bot logs.'
        });
    } finally {
        blackMarketTestGenerationInProgress = false;
    }
}

async function handlePurchasePanelBlackMarketButton(interaction) {
    if (interaction.channelId !== PURCHASE_PANEL_CHANNEL_ID) {
        return;
    }

    if (hasActiveSmashPuttActivity()) {
        await interaction.reply({
            content: 'SmashPutt is busy with another activity right now. No Black Market panel was opened.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const cleanName = getCleanDiscordName(interaction);
    const counters = normalizeBlackMarketDailyCounters();
    const status = counters.available > 0 ? 'OPEN' : 'SOLD_OUT';
    const now = new Date();
    const expiresAt = new Date(now.getTime() + BLACK_MARKET_PANEL_TIMEOUT_MS).toISOString();

    const embed = counters.available > 0
        ? buildBlackMarketOpenEmbed(cleanName, counters.available)
        : buildBlackMarketSoldOutEmbed(cleanName);

    await interaction.reply({
        embeds: [embed],
        components: [buildBlackMarketActionRow({ soldOut: counters.available <= 0 })],
        allowedMentions: { parse: [] }
    });

    const reply = await interaction.fetchReply();
    createBlackMarketStateStmt.run({
        status,
        channel_id: interaction.channelId,
        control_message_id: reply.id,
        opener_user_id: interaction.user.id,
        opener_display_name: displayName,
        opener_clean_name: cleanName,
        price: BLACK_MARKET_COST,
        started_at: now.toISOString(),
        expires_at: expiresAt
    });

    armBlackMarketTimer(getBlackMarketStmt.get());
    await refreshPurchasePanelGameLock();
}

async function handleBlackMarketCloseButton(interaction) {
    const state = getActiveBlackMarketStmt.get();
    if (!state || !['OPEN', 'SOLD_OUT'].includes(state.status) || interaction.message.id !== state.control_message_id) {
        await interaction.reply({ content: 'That Black Market panel is no longer active.', flags: MessageFlags.Ephemeral });
        return;
    }
    if (interaction.user.id !== state.opener_user_id) {
        await interaction.reply({ content: 'This Black Market panel belongs to another player.', flags: MessageFlags.Ephemeral });
        return;
    }
    await interaction.deferUpdate();
    await concludeBlackMarket('closed');
}

async function handleBlackMarketBuyButton(interaction) {
    const state = getActiveBlackMarketStmt.get();
    if (!state || interaction.message.id !== state.control_message_id) {
        await interaction.reply({ content: 'That Black Market panel is no longer active.', flags: MessageFlags.Ephemeral });
        return;
    }
    if (interaction.user.id !== state.opener_user_id) {
        await interaction.reply({ content: 'This Black Market panel belongs to another player.', flags: MessageFlags.Ephemeral });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const cleanName = getCleanDiscordName(interaction);
    const result = beginBlackMarketPurchaseTransaction({
        controlMessageId: interaction.message.id,
        userId: interaction.user.id,
        displayName,
        cleanName
    });

    if (result.type === 'INSUFFICIENT') {
        await interaction.reply({
            content: `You need **${BLACK_MARKET_COST} Smash Score** to buy a Black Market ball. Your balance was not changed.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (result.type === 'SOLD_OUT') {
        const expiresAt = new Date(Date.now() + BLACK_MARKET_PANEL_TIMEOUT_MS).toISOString();
        markBlackMarketSoldOutStateStmt.run({ control_message_id: interaction.message.id, expires_at: expiresAt });
        armBlackMarketTimer(getBlackMarketStmt.get());
        await interaction.update({ embeds: [buildBlackMarketSoldOutEmbed(state.opener_clean_name || state.opener_display_name)], components: [buildBlackMarketActionRow({ soldOut: true })] });
        return;
    }

    if (result.type !== 'READY') {
        await interaction.reply({ content: 'That Black Market panel is no longer active.', flags: MessageFlags.Ephemeral });
        return;
    }

    clearBlackMarketTimer();
    await interaction.update({
        embeds: interaction.message.embeds,
        components: [buildBlackMarketActionRow({ soldOut: false, disabled: true })]
    });
    updateLeaderboard().catch(error => console.error('Leaderboard refresh after Black Market charge failed:', error));
    await refreshPurchasePanelGameLock();
    void fulfillBlackMarketPurchase(result, interaction);
}

async function resumeBlackMarketOnStartup() {
    clearBlackMarketTimer();
    const state = getBlackMarketStmt.get();
    if (!state) return;

    if (state.status === 'PROCESSING') {
        console.log('[BLACK MARKET] Recovering interrupted processing state with automatic refund.');
        try {
            refundBlackMarketPurchaseTransaction({
                userId: state.opener_user_id,
                displayName: state.opener_display_name,
                stockDate: state.stock_date,
                reason: 'Black Market purchase refunded after bot restart'
            });
            updateLeaderboard().catch(error => console.error('Leaderboard refresh after Black Market startup refund failed:', error));
        } catch (error) {
            console.error('[BLACK MARKET] Startup refund failed:', error);
            deleteBlackMarketStateStmt.run();
        }
        try {
            const { channel, message } = await fetchBlackMarketControlMessage(state);
            await message.delete().catch(() => null);
            await channel.send({
                content: `🕶️ **${escapeDiscordMarkdown(state.opener_clean_name || state.opener_display_name)}** had a Black Market purchase interrupted by a restart. Their **${BLACK_MARKET_COST} Smash Score** was refunded.`,
                allowedMentions: { parse: [] }
            }).catch(() => null);
        } catch (_) {
            // ignore cleanup failure
        }
        await refreshPurchasePanelGameLock();
        return;
    }

    if (['OPEN', 'SOLD_OUT'].includes(state.status)) {
        if (new Date(state.expires_at).getTime() <= Date.now()) {
            await concludeBlackMarket('expired on startup');
            return;
        }
        armBlackMarketTimer(state);
        await refreshPurchasePanelGameLock();
    }
}

