// ============================================================
// SMASHPUTT UNDERDOG
// ============================================================

let underdogDeadlineTimer = null;
let underdogRefreshTimer = null;
let underdogSpawnInProgress = false;

function clearUnderdogTimers() {
    if (underdogDeadlineTimer) {
        clearTimeout(underdogDeadlineTimer);
        underdogDeadlineTimer = null;
    }
    if (underdogRefreshTimer) {
        clearInterval(underdogRefreshTimer);
        underdogRefreshTimer = null;
    }
}

function armUnderdogResultRetry(gameKey) {
    clearUnderdogTimers();
    underdogDeadlineTimer = setTimeout(() => {
        underdogDeadlineTimer = null;
        finishUnderdogIfDue(gameKey).catch(error => {
            console.error('[UNDERDOG] Result retry failed:', error);
            armUnderdogResultRetry(gameKey);
        });
    }, 10 * 1000);
}

function getUnderdogTimeLeftText(deadlineAt) {
    const deadline = new Date(deadlineAt);
    const seconds = Number.isNaN(deadline.getTime())
        ? 0
        : Math.max(0, Math.ceil((deadline.getTime() - Date.now()) / 1000));
    return `00:${String(seconds).padStart(2, '0')}`;
}

function buildUnderdogButtons(disabled = false) {
    const row = new ActionRowBuilder();
    for (let number = 1; number <= 3; number++) {
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`${UNDERDOG_BUTTON_PREFIX}${number}`)
                .setLabel(String(number))
                .setStyle(ButtonStyle.Primary)
                .setDisabled(disabled)
        );
    }
    return [row];
}

function buildUnderdogActiveEmbed(state) {
    return new EmbedBuilder()
        .setColor(0xE67E22)
        .setTitle('🐶 SMASHPUTT UNDERDOG')
        .setDescription(
            `Pick **1, 2, or 3**. You want to be on the number that is **least popular** when time expires.\n\n` +
            `• One locked choice per player\n` +
            `• Minimum **${UNDERDOG_MIN_PLAYERS} unique players**\n` +
            `• There must be **one clear Underdog**\n` +
            `• Winners receive **+${UNDERDOG_SCORE_PRIZE} 💥 Smash Score each**\n\n` +
            `⏱️ **TIME LEFT: ${getUnderdogTimeLeftText(state.deadline_at)}**`
        )
        .setImage('attachment://underdog.png');
}

function getUnderdogResultSummary(entries) {
    const groups = new Map([[1, []], [2, []], [3, []]]);
    for (const entry of entries) {
        groups.get(Number(entry.chosen_number))?.push(entry);
    }
    const counts = [1, 2, 3].map(number => ({ number, count: groups.get(number).length }));
    // A number nobody picked cannot be the Underdog. Only choices with at least
    // one vote participate in the least-popular comparison.
    const playedChoices = counts.filter(row => row.count > 0);
    const min = playedChoices.length
        ? Math.min(...playedChoices.map(row => row.count))
        : 0;
    const lowest = playedChoices.filter(row => row.count === min);
    const winningChoice = entries.length >= UNDERDOG_MIN_PLAYERS && lowest.length === 1
        ? lowest[0].number
        : null;
    return { groups, counts, winningChoice };
}

function buildUnderdogResultEmbed(state, entries) {
    const summary = getUnderdogResultSummary(entries);
    const lines = [];

    for (const row of summary.counts) {
        const voters = summary.groups.get(row.number);
        const names = voters.length
            ? voters.map(entry => escapeDiscordMarkdown(entry.clean_name || entry.display_name || 'Player')).join(', ')
            : 'None';
        const winning = Number(state.winning_choice) === row.number;
        lines.push(
            winning
                ? `**${row.number} — ${row.count} vote${row.count === 1 ? '' : 's'} 🐶**\n**${names}**`
                : `${row.number} — ${row.count} vote${row.count === 1 ? '' : 's'}\n${names}`
        );
    }

    let resultText;
    if (entries.length < UNDERDOG_MIN_PLAYERS) {
        resultText = `🚫 **NOT ENOUGH PLAYERS — NO PAYOUT**\nMinimum required: ${UNDERDOG_MIN_PLAYERS}`;
    } else if (!state.winning_choice) {
        resultText = '🚫 **NO CLEAR UNDERDOG — NO WINNERS**';
    } else {
        const winners = entries.filter(entry => Number(entry.is_winner) === 1);
        const winnerNames = winners.map(entry => escapeDiscordMarkdown(entry.clean_name || entry.display_name || 'Player')).join(', ') || 'None';
        resultText = `**🏆 Winners:** **${winnerNames}**\n**💥 +${UNDERDOG_SCORE_PRIZE} Smash Score each**`;
    }

    return new EmbedBuilder()
        .setColor(state.winning_choice ? 0xF1C40F : 0x747F8D)
        .setTitle('🐶 UNDERDOG — RESULTS')
        .setDescription(`${lines.join('\n\n')}\n\n${resultText}`)
        .setImage('attachment://underdog.png');
}

async function fetchUnderdogControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Underdog channel could not be found: ${state.channel_id}`);
    }
    const message = await channel.messages.fetch(state.control_message_id);
    return { channel, message };
}

const joinUnderdogTransaction = db.transaction(({ gameKey, userId, displayName, cleanName, chosenNumber }) => {
    const state = getActiveUnderdogStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };
    const deadline = new Date(state.deadline_at);
    if (Number.isNaN(deadline.getTime()) || Date.now() >= deadline.getTime()) return { type: 'EXPIRED' };
    const existing = getUnderdogEntryStmt.get(gameKey, userId);
    if (existing) return { type: 'ALREADY_ENTERED', entry: existing };

    insertUnderdogEntryStmt.run({
        game_key: gameKey,
        user_id: userId,
        display_name: displayName,
        clean_name: cleanName,
        chosen_number: chosenNumber,
        entered_at: new Date().toISOString()
    });

    return { type: 'ACCEPTED', entry: getUnderdogEntryStmt.get(gameKey, userId) };
});

const completeUnderdogTransaction = db.transaction(gameKey => {
    const state = getActiveUnderdogStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'NO_ACTIVE' };
    const deadline = new Date(state.deadline_at);
    if (!Number.isNaN(deadline.getTime()) && Date.now() < deadline.getTime()) {
        return { type: 'NOT_DUE', deadline };
    }

    const entries = getUnderdogEntriesStmt.all(gameKey);
    const summary = getUnderdogResultSummary(entries);
    const now = new Date().toISOString();

    if (summary.winningChoice) {
        for (const entry of entries) {
            if (Number(entry.chosen_number) !== summary.winningChoice) continue;
            ensurePlayer(entry.user_id, entry.display_name);
            addSmashScoreStmt.run({
                user_id: entry.user_id,
                display_name: entry.display_name,
                amount: UNDERDOG_SCORE_PRIZE,
                updated_at: now
            });
            insertScoreTransactionStmt.run({
                user_id: entry.user_id,
                display_name: entry.display_name,
                transaction_type: 'ADD',
                amount: UNDERDOG_SCORE_PRIZE,
                reason: 'SmashPutt Underdog Winner',
                admin_user_id: entry.user_id,
                admin_display_name: entry.display_name,
                created_at: now
            });
            db.prepare(`
                UPDATE smash_underdog_entries
                SET is_winner = 1, reward_processed_at = @reward_processed_at
                WHERE id = @id
            `).run({ id: entry.id, reward_processed_at: now });
        }
    }

    db.prepare(`
        UPDATE smash_underdog_state
        SET status = 'COMPLETE', winning_choice = @winning_choice, completed_at = @completed_at
        WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE'
    `).run({ game_key: gameKey, winning_choice: summary.winningChoice, completed_at: now });

    return {
        type: 'COMPLETE',
        state: getUnderdogStmt.get(),
        entries: getUnderdogEntriesStmt.all(gameKey)
    };
});

async function announceUnderdogResult(state) {
    const entries = getUnderdogEntriesStmt.all(state.game_key);
    const { message } = await fetchUnderdogControlMessage(state);
    await message.edit({
        embeds: [buildUnderdogResultEmbed(state, entries)],
        components: buildUnderdogButtons(true)
    });
    markUnderdogResultAnnouncedStmt.run({
        game_key: state.game_key,
        result_announced_at: new Date().toISOString()
    });
}

function armUnderdogTimers(state) {
    clearUnderdogTimers();

    underdogRefreshTimer = setInterval(async () => {
        const live = getActiveUnderdogStmt.get();
        if (!live || live.game_key !== state.game_key) {
            clearUnderdogTimers();
            return;
        }
        try {
            const { message } = await fetchUnderdogControlMessage(live);
            await message.edit({
                embeds: [buildUnderdogActiveEmbed(live)],
                components: buildUnderdogButtons(false)
            });
        } catch (error) {
            console.error('[UNDERDOG] Live countdown refresh failed:', error);
        }
    }, UNDERDOG_LIVE_REFRESH_MS);

    const dueAt = new Date(state.deadline_at).getTime();
    underdogDeadlineTimer = setTimeout(() => {
        underdogDeadlineTimer = null;
        finishUnderdogIfDue(state.game_key).catch(error =>
            console.error('[UNDERDOG] Finish timer failed:', error)
        );
    }, Math.max(0, dueAt - Date.now()) + 50);
}

async function finishUnderdogIfDue(gameKey) {
    const result = completeUnderdogTransaction(gameKey);
    if (result.type === 'NOT_DUE') {
        const state = getActiveUnderdogStmt.get();
        if (state) armUnderdogTimers(state);
        return;
    }
    if (result.type === 'NO_ACTIVE') {
        const pending = getPendingUnderdogResultStmt.get();
        if (!pending || pending.game_key !== gameKey) return;
        clearUnderdogTimers();
        try {
            await announceUnderdogResult(pending);
        } catch (error) {
            console.error('[UNDERDOG] Pending result announcement failed:', error);
            armUnderdogResultRetry(gameKey);
            return;
        }
    } else {
        clearUnderdogTimers();
        try {
            await announceUnderdogResult(result.state);
        } catch (error) {
            console.error('[UNDERDOG] Final result announcement failed:', error);
            armUnderdogResultRetry(gameKey);
            return;
        }
        const winners = result.entries.filter(entry => Number(entry.is_winner) === 1);
        console.log(`[UNDERDOG COMPLETE] Entries: ${result.entries.length} | Winning choice: ${result.state.winning_choice || 'NONE'} | Winners: ${winners.length}`);
        await sendLogMessage(
            `🐶 **SmashPutt Underdog Complete**\n` +
            `Players: ${result.entries.length}\n` +
            `Underdog: ${result.state.winning_choice || 'No clear winner'}\n` +
            `Winners: ${winners.map(entry => entry.clean_name).join(', ') || 'None'}\n` +
            `Time: ${getCentralTimeString()}`
        );
    }

    updateLeaderboard().catch(error => console.error('[UNDERDOG] Leaderboard refresh failed:', error));

    const completedUnderdog = getUnderdogStmt.get();
    await movePurchasePanelAfterAutomaticActivity(completedUnderdog?.source);

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: true, reason: 'underdog complete' });
    }
}

async function handleUnderdogChoiceButton(interaction) {
    const chosenNumber = Number(interaction.customId.substring(UNDERDOG_BUTTON_PREFIX.length));
    if (![1, 2, 3].includes(chosenNumber)) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }

    const state = getActiveUnderdogStmt.get();
    if (!state || interaction.message.id !== state.control_message_id) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const cleanName = getCleanDiscordName(interaction);
    const result = joinUnderdogTransaction({
        gameKey: state.game_key,
        userId: interaction.user.id,
        displayName,
        cleanName,
        chosenNumber
    });

    if (result.type === 'ALREADY_ENTERED') {
        await interaction.reply({
            content: `Your Underdog choice is already locked on **${result.entry.chosen_number}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (result.type !== 'ACCEPTED') {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }

    await interaction.reply({
        content: `🐶 Choice **${chosenNumber}** locked. Vote totals stay hidden until the result.`,
        flags: MessageFlags.Ephemeral
    });
}

async function createUnderdogInChannel(channelId, source = 'AUTO') {
    if (!channelId) return { ok: false, reason: 'NO_CHANNELS' };
    if (underdogSpawnInProgress || hasActiveSmashPuttActivity()) {
        return { ok: false, reason: 'ACTIVE_ACTIVITY' };
    }
    if (!fs.existsSync(UNDERDOG_IMAGE_PATH)) {
        return { ok: false, reason: 'MISSING_UNDERDOG_IMAGE' };
    }

    underdogSpawnInProgress = true;
    let controlMessage = null;

    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) {
            throw new Error(`Underdog spawn channel could not be found: ${channelId}`);
        }

        const startedAt = new Date();
        const deadlineAt = new Date(startedAt.getTime() + UNDERDOG_DURATION_MS);
        const provisional = { deadline_at: deadlineAt.toISOString() };
        controlMessage = await channel.send({
            embeds: [buildUnderdogActiveEmbed(provisional)],
            files: [new AttachmentBuilder(UNDERDOG_IMAGE_PATH, { name: 'underdog.png' })],
            components: buildUnderdogButtons(false),
            allowedMentions: { parse: [] }
        });

        createUnderdogStmt.run({
            game_key: controlMessage.id,
            channel_id: channel.id,
            control_message_id: controlMessage.id,
            source,
            started_at: startedAt.toISOString(),
            deadline_at: deadlineAt.toISOString()
        });

        pauseSchedulerForActiveGame();
        const state = getActiveUnderdogStmt.get();
        armUnderdogTimers(state);
        console.log(`[UNDERDOG] ${source} started | Key ${state.game_key} | Channel ${channel.id}`);
        return { ok: true, state, controlMessage };
    } catch (error) {
        console.error('[UNDERDOG] Could not start:', error);
        if (controlMessage) {
            try { await controlMessage.delete(); } catch (_) {}
        }
        return { ok: false, reason: 'CREATE_FAILED' };
    } finally {
        underdogSpawnInProgress = false;
    }
}

async function handleUnderdogCommand(interaction) {
    const channelIds = getActiveSpawnChannelIds();
    if (channelIds.length === 0) {
        await interaction.reply({
            content: 'There are no active SmashPutt spawn channels.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }
    if (hasActiveSmashPuttActivity() || underdogSpawnInProgress) {
        await interaction.reply({
            content: 'There is already an active SmashPutt activity.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    pauseSchedulerForActiveGame();
    const channelId = randomItem(channelIds);
    const result = await createUnderdogInChannel(channelId, 'FORCE');

    if (result.ok) {
        await interaction.editReply({ content: `✅ SmashPutt Underdog started in <#${result.controlMessage.channelId}>.` });
        return;
    }

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: true, reason: 'manual underdog failed to start' });
    }
    await interaction.editReply({
        content: result.reason === 'MISSING_UNDERDOG_IMAGE'
            ? `Underdog cannot start because ${UNDERDOG_IMAGE_PATH} is missing.`
            : 'Underdog could not be started. Check the bot logs.'
    });
}

async function resumeUnderdogOnStartup() {
    clearUnderdogTimers();
    const pending = getPendingUnderdogResultStmt.get();
    if (pending) {
        console.log(`[UNDERDOG] Recovering pending result ${pending.game_key}.`);
        try {
            await announceUnderdogResult(pending);
        } catch (error) {
            console.error('[UNDERDOG] Pending-result recovery failed:', error);
            armUnderdogResultRetry(pending.game_key);
            return;
        }
    }

    const state = getActiveUnderdogStmt.get();
    if (!state) {
        console.log('No active SmashPutt Underdog currently exists.');
        return;
    }

    if (!fs.existsSync(UNDERDOG_IMAGE_PATH)) {
        console.error(`[UNDERDOG] Active game image missing: ${UNDERDOG_IMAGE_PATH}`);
    }

    const deadline = new Date(state.deadline_at);
    if (Number.isNaN(deadline.getTime()) || deadline.getTime() <= Date.now()) {
        await finishUnderdogIfDue(state.game_key);
        return;
    }

    try {
        const { message } = await fetchUnderdogControlMessage(state);
        await message.edit({
            embeds: [buildUnderdogActiveEmbed(state)],
            components: buildUnderdogButtons(false)
        });
    } catch (error) {
        console.error('[UNDERDOG] Active display recovery failed:', error);
    }

    pauseSchedulerForActiveGame();
    armUnderdogTimers(state);
    console.log(`[UNDERDOG] Recovered active game ${state.game_key}.`);
}


// ============================================================
// SMASHPUTT PICTIONARY
// ============================================================

let pictionaryDeadlineTimer = null;
let pictionarySpawnInProgress = false;
let pictionaryMessageQueue = Promise.resolve();

function clearPictionaryTimer() {
    if (pictionaryDeadlineTimer) {
        clearTimeout(pictionaryDeadlineTimer);
        pictionaryDeadlineTimer = null;
    }
}

function normalizePictionaryGuess(value) {
    return String(value || '')
        .normalize('NFKC')
        .trim()
        .toLowerCase();
}

function shufflePictionaryAnswers(answers) {
    const shuffled = [...answers];

    for (let index = shuffled.length - 1; index > 0; index--) {
        const swapIndex = randomInteger(0, index);
        [shuffled[index], shuffled[swapIndex]] = [
            shuffled[swapIndex],
            shuffled[index]
        ];
    }

    return shuffled;
}

function getPictionaryWordBag() {
    const allAnswers = PICTIONARY_WORDS.map(word => word.answer);
    const validAnswers = new Set(allAnswers);
    const raw = getSetting(PICTIONARY_WORD_BAG_SETTING);

    if (raw) {
        try {
            const parsed = JSON.parse(raw);
            if (
                Array.isArray(parsed) &&
                parsed.every(answer => typeof answer === 'string' && validAnswers.has(answer)) &&
                new Set(parsed).size === parsed.length
            ) {
                return parsed;
            }
        } catch (error) {
            console.error('[PICTIONARY] Stored word bag was invalid; rebuilding it:', error.message);
        }
    }

    return shufflePictionaryAnswers(allAnswers);
}

function selectPictionaryWordCandidate() {
    let bag = getPictionaryWordBag();

    if (bag.length === 0) {
        bag = shufflePictionaryAnswers(
            PICTIONARY_WORDS.map(word => word.answer)
        );
    }

    const answer = bag[bag.length - 1];
    const word = PICTIONARY_WORD_BY_ANSWER.get(answer);

    if (!word) {
        throw new Error(`Pictionary word bag contained an unknown answer: ${answer}`);
    }

    return {
        word,
        remainingBag: bag.slice(0, -1)
    };
}

function commitPictionaryWordCandidate(candidate) {
    setSetting(
        PICTIONARY_WORD_BAG_SETTING,
        JSON.stringify(candidate.remainingBag)
    );
}

function escapeRegExp(value) {
    return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function sanitizePictionaryBlueprintText(text, answer) {
    const trimmed = String(text || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/^["'`]+/, '')
        .replace(/["'`]+$/, '');

    if (!trimmed) {
        return '';
    }

    const safeAnswer = String(answer || '').trim();
    if (!safeAnswer) {
        return trimmed;
    }

    return trimmed.replace(
        new RegExp(`\\b${escapeRegExp(safeAnswer)}\\b`, 'gi'),
        'shape'
    ).trim();
}

function extractOpenAIResponseText(payload) {
    if (typeof payload?.output_text === 'string' && payload.output_text.trim()) {
        return payload.output_text.trim();
    }

    const parts = Array.isArray(payload?.output)
        ? payload.output.flatMap(item =>
            Array.isArray(item?.content)
                ? item.content
                    .filter(content => typeof content?.text === 'string')
                    .map(content => content.text)
                : []
        )
        : [];

    return parts.join(' ').replace(/\s+/g, ' ').trim();
}

const PICTIONARY_CONTEXT_ANCHOR_ANSWERS = new Set([
    'school', 'library', 'hospital', 'clinic', 'bakery', 'restaurant', 'cafe', 'diner',
    'supermarket', 'mall', 'bank', 'mailroom', 'firehouse', 'jailhouse', 'airport', 'station',
    'factory', 'warehouse', 'stadium', 'theater', 'amphitheater', 'circus', 'museum', 'aquarium',
    'zoo', 'playground', 'park', 'garden', 'farm', 'ranch', 'harbor', 'boardwalk',
    'campsite', 'bedroom', 'kitchen', 'bathroom', 'attic', 'basement', 'hallway'
]);

function pictionaryAllowsSingleContextAnchor(word) {
    return PICTIONARY_CONTEXT_ANCHOR_ANSWERS.has(
        String(word?.answer || '').trim().toLowerCase()
    );
}

const PICTIONARY_ACTION_SPORT_ANSWERS = new Set([
    'boxing', 'wrestling', 'karate', 'judo', 'fencing', 'archery', 'skiing', 'snowboarding',
    'skating', 'surfing', 'swimming', 'diving', 'rowing', 'climbing', 'hiking', 'fishing',
    'gymnastics', 'cheerleading'
]);

const PICTIONARY_COMPOUND_RELATION_ANSWERS = new Set([
    'flowerpot', 'toothbrush', 'toothpaste', 'doorknob', 'mailbox', 'lunchbox', 'coffeemaker',
    'wheelbarrow', 'paintbrush', 'lawnmower', 'snowboard', 'dollhouse', 'treehouse', 'smartwatch',
    'chalkboard', 'whiteboard', 'headboard', 'footboard'
]);

const PICTIONARY_STRUCTURAL_RELATION_ANSWERS = new Set([
    'compass', 'scissors', 'binoculars', 'telescope', 'microscope', 'magnifier', 'protractor',
    'stapler', 'pliers', 'tongs', 'whisk', 'corkscrew', 'funnel', 'slingshot', 'catapult',
    'bicycle', 'tricycle', 'motorcycle'
]);

function getPictionaryBlueprintMode(word) {
    const answer = String(word?.answer || '').trim().toLowerCase();
    if (pictionaryAllowsSingleContextAnchor(word)) return 'CONTEXT';
    if (String(word?.category || '') === 'ACTION' || PICTIONARY_ACTION_SPORT_ANSWERS.has(answer)) return 'ACTION';
    if (PICTIONARY_COMPOUND_RELATION_ANSWERS.has(answer)) return 'COMPOUND';
    if (PICTIONARY_STRUCTURAL_RELATION_ANSWERS.has(answer)) return 'STRUCTURAL';
    return 'STANDARD';
}

function getAdaptivePictionaryBlueprintInstructions(mode) {
    const common = [
        'You prepare intentionally inaccurate visual blueprints for a difficult adult Pictionary game.',
        'Another AI will draw only from your response.',
        'Never write, repeat, spell, abbreviate, or directly name the secret answer.',
        'Never use a synonym or near-synonym for the secret answer.',
        'Never state the category, habitat, normal location, purpose, behavior, or sound.',
        'Keep the drawing intentionally crude, confusing, incomplete, and badly proportioned.',
        'Deliberately distort exactly two major proportions and misplace or slightly disconnect at least one part.'
    ];

    const modeRules = {
        CONTEXT: [
            'This answer depends on context, so preserve exactly ONE crude anchor clue described only as rough visible geometry; never name what the anchor represents.',
            'The anchor must remain incomplete, badly proportioned, misplaced, or difficult to recognize. Do not add a second identifying clue, a complete scene, or multiple associated objects.'
        ],
        ACTION: [
            'This answer is an action or action-based sport. Preserve exactly ONE crude body-to-action relationship so the pose can weakly suggest the action.',
            'Do not add uniforms, equipment, scenery, opponents, labels, or a second action clue. The body and pose must remain badly drawn and ambiguous.'
        ],
        COMPOUND: [
            'This answer is recognizable because two major visual components belong together. Preserve BOTH components, but make each one crude, malformed, incomplete, and badly connected.',
            'Do not add any third clue or surrounding scene. The relationship between the two components may be visible, but neither component should be clean or obvious.'
        ],
        STRUCTURAL: [
            'This answer depends on one essential structural relationship between its parts. Preserve exactly that ONE relationship while drawing every part crudely and inaccurately.',
            'Do not add labels, letters, markings, scenery, or secondary clues. The structure should suggest a family of related objects rather than make the exact answer obvious.'
        ]
    };

    return [
        ...common,
        ...(modeRules[mode] || []),
        'Before answering, silently imagine three plausible guesses from the blueprint alone. The secret answer must be a reasonable difficult possibility among them, but it should not be an obvious first guess.',
        'If the likely guesses are unrelated to the secret answer, revise only the permitted relationship or anchor until the answer becomes a plausible but difficult interpretation.',
        'Return exactly one sentence between 25 and 50 words and nothing else.'
    ];
}

async function generatePictionaryBlueprint(word) {
    const apiKey = String(process.env.OPENAI_API_KEY || '').trim();

    if (!apiKey) {
        const error = new Error('OPENAI_API_KEY is not configured.');
        error.code = 'MISSING_OPENAI_API_KEY';
        throw error;
    }

    const category = String(word?.category || '')
        .replaceAll('_', ' ')
        .toLowerCase();
    const blueprintMode = getPictionaryBlueprintMode(word);
    const allowSingleContextAnchor = blueprintMode === 'CONTEXT';

    let lastError = null;

    for (let attempt = 1; attempt <= PICTIONARY_DESCRIPTION_MAX_ATTEMPTS; attempt++) {
        const controller = new AbortController();
        const timeout = setTimeout(
            () => controller.abort(),
            PICTIONARY_DESCRIPTION_TIMEOUT_MS
        );

        try {
            const response = await fetch(PICTIONARY_DESCRIPTION_API_URL, {
                method: 'POST',
                headers: {
                    Authorization: `Bearer ${apiKey}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    model: PICTIONARY_DESCRIPTION_MODEL,
                    instructions: (blueprintMode === 'STANDARD'
                        ? [
                            'You prepare intentionally inaccurate visual blueprints for a difficult adult Pictionary game.',
                            'Another AI will draw only from your response.',
                            'Never write, repeat, spell, abbreviate, or hint at the secret answer.',
                            'Never use a synonym or near-synonym for the secret answer.',
                            'Never state the category or mention habitat, normal location, purpose, behavior, sound, associated objects, or background scenery.',
                            'Describe visible geometry only: rough shapes, misplaced parts, distorted proportions, crooked marks, and incomplete outlines.',
                            'Include only a vague, incomplete hint of one recognizable visual feature. Describe that feature inaccurately, make it badly proportioned or misplaced, and do not preserve its complete or correct shape.',
                            'Deliberately distort exactly two major proportions.',
                            'Misplace or slightly disconnect at least one part.',
                            'Keep the result barely guessable but still fair.',
                            'Return exactly one sentence between 25 and 50 words and nothing else.'
                        ]
                        : getAdaptivePictionaryBlueprintInstructions(blueprintMode)
                    ).join(' '),
                    input: [
                        `Secret answer: ${word.answer}`,
                        `Use the ${category} meaning of the answer.`
                    ].join(' ')
                }),
                signal: controller.signal
            });

            const requestId = response.headers.get('x-request-id') || 'unknown';
            let payload = null;

            try {
                payload = await response.json();
            } catch (_) {
                payload = null;
            }

            if (!response.ok) {
                const apiCode = payload?.error?.code || payload?.error?.type || 'unknown_error';
                const apiMessage = payload?.error?.message || `HTTP ${response.status}`;
                const error = new Error(`OpenAI blueprint request failed: ${apiMessage}`);
                error.code = apiCode;
                error.type = payload?.error?.type || null;
                error.status = response.status;
                error.requestId = requestId;
                lastError = error;

                console.error(
                    `[PICTIONARY BLUEPRINT] Attempt ${attempt}/${PICTIONARY_DESCRIPTION_MAX_ATTEMPTS} failed | ` +
                    `HTTP ${response.status} | Code ${apiCode} | Request ${requestId} | ${apiMessage}`
                );

                if (
                    attempt < PICTIONARY_DESCRIPTION_MAX_ATTEMPTS &&
                    isRetryablePictionaryApiStatus(response.status)
                ) {
                    await new Promise(resolve => setTimeout(resolve, 1500 * attempt));
                    continue;
                }

                throw error;
            }

            const blueprint = sanitizePictionaryBlueprintText(
                extractOpenAIResponseText(payload),
                word.answer
            );

            if (!blueprint) {
                const error = new Error('OpenAI returned no usable Pictionary blueprint text.');
                error.code = 'EMPTY_BLUEPRINT_RESPONSE';
                error.requestId = requestId;
                throw error;
            }

            console.log(
                `[PICTIONARY BLUEPRINT] Generated distorted drawing blueprint | ` +
                `${blueprint.length} chars | Request ${requestId}`
            );

            return blueprint;
        } catch (error) {
            lastError = error;

            if (error?.name === 'AbortError') {
                const timeoutError = new Error(
                    `OpenAI blueprint generation exceeded ${PICTIONARY_DESCRIPTION_TIMEOUT_MS / 1000} seconds.`
                );
                timeoutError.code = 'BLUEPRINT_GENERATION_TIMEOUT';
                lastError = timeoutError;
            }

            if (
                attempt < PICTIONARY_DESCRIPTION_MAX_ATTEMPTS &&
                (
                    error?.name === 'AbortError' ||
                    !Number.isFinite(error?.status) ||
                    isRetryablePictionaryApiStatus(error.status)
                )
            ) {
                console.error(
                    `[PICTIONARY BLUEPRINT] Attempt ${attempt}/${PICTIONARY_DESCRIPTION_MAX_ATTEMPTS} failed before completion: ` +
                    `${lastError.code || lastError.message}`
                );
                await new Promise(resolve => setTimeout(resolve, 1500 * attempt));
                continue;
            }

            throw lastError;
        } finally {
            clearTimeout(timeout);
        }
    }

    throw lastError || new Error('Pictionary blueprint generation failed.');
}

function getPictionaryPrompt(blueprint, allowSingleContextAnchor = false) {
    return [
        'Create one deliberately terrible, rushed Pictionary drawing using only the flawed visual blueprint below.',
        `Flawed visual blueprint: ${blueprint}`,
        'The drawing must look like an ordinary person had only 20 seconds and very little artistic ability.',
        'Use crude, shaky, uneven thick marker-like lines on a plain white background. Use rough simple colors in the linework as much as possible.',
        'Use awkward proportions, primitive shapes, sparse details, clumsy perspective, and at least one slightly disconnected part.',
        'Use color only in the drawn lines themselves. Do not fill enclosed areas, do not color the background, and do not use shading, gradients, or polished coloring.',
        'Leave part of the outline unfinished and include a couple of stray correction marks.',
        'Do not improve, repair, clarify, complete, or beautify the flawed blueprint.',
        'It should be barely recognizable but still possible to guess.',
        'Show one main subject or one simple action only.',
        'Show only the finished doodle itself; do not show an artist, hand, marker, easel, frame, app interface, or whiteboard border.',
        allowSingleContextAnchor
            ? 'Do not add any contextual clue, scenery, habitat, prop, or background object beyond the single crude geometry-only anchor already described in the flawed blueprint.'
            : 'Do not add contextual clues, scenery, habitat, props, or background objects.',
        'Do not make polished art, clip art, a logo, a cartoon poster, a coloring page, or a realistic image.',
        'ABSOLUTELY NO text, letters, words, numbers, labels, captions, speech bubbles, signs, signatures, watermarks, or written clues anywhere in the image.'
    ].join(' ');
}

function isRetryablePictionaryApiStatus(status) {
    return status === 408 || status === 409 || status === 429 || status >= 500;
}

async function generatePictionaryImageBuffer(word) {
    const apiKey = String(process.env.OPENAI_API_KEY || '').trim();

    if (!apiKey) {
        const error = new Error('OPENAI_API_KEY is not configured.');
        error.code = 'MISSING_OPENAI_API_KEY';
        throw error;
    }

    const blueprintMode = getPictionaryBlueprintMode(word);
    const allowSingleContextAnchor = blueprintMode === 'CONTEXT';
    const blueprint = await generatePictionaryBlueprint(word);
    let lastError = null;

    for (let attempt = 1; attempt <= PICTIONARY_API_MAX_ATTEMPTS; attempt++) {
        const controller = new AbortController();
        const timeout = setTimeout(
            () => controller.abort(),
            PICTIONARY_API_TIMEOUT_MS
        );

        try {
            const response = await fetch(PICTIONARY_IMAGE_API_URL, {
                method: 'POST',
                headers: {
                    Authorization: `Bearer ${apiKey}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    model: PICTIONARY_IMAGE_MODEL,
                    prompt: getPictionaryPrompt(blueprint, allowSingleContextAnchor),
                    size: PICTIONARY_IMAGE_SIZE,
                    quality: PICTIONARY_IMAGE_QUALITY,
                    n: 1
                }),
                signal: controller.signal
            });

            const requestId = response.headers.get('x-request-id') || 'unknown';
            let payload = null;

            try {
                payload = await response.json();
            } catch (_) {
                payload = null;
            }

            if (!response.ok) {
                const apiCode = payload?.error?.code || payload?.error?.type || 'unknown_error';
                const apiMessage = payload?.error?.message || `HTTP ${response.status}`;
                const error = new Error(`OpenAI image request failed: ${apiMessage}`);
                error.code = apiCode;
                error.type = payload?.error?.type || null;
                error.status = response.status;
                error.requestId = requestId;
                lastError = error;

                console.error(
                    `[PICTIONARY API] Attempt ${attempt}/${PICTIONARY_API_MAX_ATTEMPTS} failed | ` +
                    `HTTP ${response.status} | Code ${apiCode} | Request ${requestId} | ${apiMessage}`
                );

                if (
                    attempt < PICTIONARY_API_MAX_ATTEMPTS &&
                    isRetryablePictionaryApiStatus(response.status)
                ) {
                    await new Promise(resolve => setTimeout(resolve, 2500 * attempt));
                    continue;
                }

                throw error;
            }

            const imageBase64 = payload?.data?.[0]?.b64_json;
            let imageBuffer = imageBase64
                ? Buffer.from(imageBase64, 'base64')
                : null;

            if (!imageBuffer && payload?.data?.[0]?.url) {
                const imageResponse = await fetch(payload.data[0].url, {
                    signal: controller.signal
                });

                if (!imageResponse.ok) {
                    throw new Error(`Generated image download failed with HTTP ${imageResponse.status}.`);
                }

                imageBuffer = Buffer.from(await imageResponse.arrayBuffer());
            }

            if (!imageBuffer || imageBuffer.length < 1024) {
                const error = new Error('OpenAI returned no usable Pictionary image data.');
                error.code = 'EMPTY_IMAGE_RESPONSE';
                error.requestId = requestId;
                throw error;
            }

            // Validate the bytes in memory. Nothing is written to disk.
            const metadata = await sharp(imageBuffer).metadata();
            if (!metadata.width || !metadata.height) {
                throw new Error('OpenAI returned image bytes that Sharp could not validate.');
            }

            console.log(
                `[PICTIONARY API] Drawing generated in memory | ` +
                `${metadata.width}x${metadata.height} | ${(imageBuffer.length / 1024).toFixed(0)} KB | ` +
                `Request ${requestId}`
            );

            return imageBuffer;
        } catch (error) {
            lastError = error;

            if (error?.name === 'AbortError') {
                const timeoutError = new Error(
                    `OpenAI image generation exceeded ${PICTIONARY_API_TIMEOUT_MS / 1000} seconds.`
                );
                timeoutError.code = 'IMAGE_GENERATION_TIMEOUT';
                lastError = timeoutError;
            }

            if (
                attempt < PICTIONARY_API_MAX_ATTEMPTS &&
                (
                    error?.name === 'AbortError' ||
                    !Number.isFinite(error?.status) ||
                    isRetryablePictionaryApiStatus(error.status)
                )
            ) {
                console.error(
                    `[PICTIONARY API] Attempt ${attempt}/${PICTIONARY_API_MAX_ATTEMPTS} failed before completion: ` +
                    `${lastError.code || lastError.message}`
                );
                await new Promise(resolve => setTimeout(resolve, 2500 * attempt));
                continue;
            }

            throw lastError;
        } finally {
            clearTimeout(timeout);
        }
    }

    throw lastError || new Error('Pictionary image generation failed.');
}

function getPictionaryTimeLeftText(deadlineAt) {
    const deadline = new Date(deadlineAt);
    const totalSeconds = Number.isNaN(deadline.getTime())
        ? 0
        : Math.max(0, Math.ceil((deadline.getTime() - Date.now()) / 1000));
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function buildPictionaryGuessReceipt(guesses, winnerUserId = null) {
    if (!guesses.length) {
        return '*No guesses yet.*';
    }

    const lines = guesses.map((guess, index) => {
        const name = escapeDiscordMarkdown(
            guess.clean_name || guess.display_name || 'Player'
        );
        const guessText = escapeDiscordMarkdown(guess.guess_text);
        const winning = Number(guess.is_winner) === 1 || guess.user_id === winnerUserId;
        const line = `${index + 1}. ${name} — “${guessText}”${winning ? ' 🏆' : ''}`;
        return winning ? `**${line}**` : line;
    });

    const maxCharacters = 2800;
    const kept = [];
    let used = 0;

    for (const line of lines) {
        const extra = line.length + (kept.length ? 1 : 0);
        if (used + extra > maxCharacters) {
            break;
        }
        kept.push(line);
        used += extra;
    }

    if (kept.length < lines.length) {
        kept.push(`*${lines.length - kept.length} additional guess(es) are preserved in the database.*`);
    }

    return kept.join('\n');
}

function buildPictionaryGuessButton(disabled = false) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(PICTIONARY_GUESS_BUTTON_ID)
            .setLabel('GUESS')
            .setEmoji('✏️')
            .setStyle(ButtonStyle.Success)
            .setDisabled(disabled)
    );
}

function buildPictionaryActiveEmbed(state, guesses) {
    const deadlineUnix = Math.floor(new Date(state.deadline_at).getTime() / 1000);

    return new EmbedBuilder()
        .setColor(0x5865F2)
        .setTitle('🎨 SMASHPUTT PICTIONARY')
        .setDescription(
            `**What is SmashPutt drawing?**\n\n` +
            `Press **GUESS** and submit your one exact answer.\n` +
            `• **One guess per player**\n` +
            `• Capitalization and outside spaces are ignored\n` +
            `• Spelling and singular/plural must match exactly\n` +
            `• First exact answer wins **+${PICTIONARY_SCORE_PRIZE} 💥 Smash Score**\n\n` +
            `⏱️ **TIME LEFT:** <t:${deadlineUnix}:R>\n\n` +
            `**GUESSES**\n${buildPictionaryGuessReceipt(guesses)}`
        )
        .setImage(`attachment://${PICTIONARY_IMAGE_ATTACHMENT_NAME}`);
}

function buildPictionaryResultEmbed(state, guesses) {
    const solved = Boolean(state.winner_user_id);
    const secretWord = escapeDiscordMarkdown(state.secret_word.toUpperCase());
    const winnerName = escapeDiscordMarkdown(
        state.winner_clean_name || state.winner_display_name || 'Winner'
    );

    const resultText = solved
        ? `🏆 **${winnerName} SOLVED IT!**\n` +
          `💥 **+${PICTIONARY_SCORE_PRIZE} Smash Score**\n\n` +
          `🔎 Secret Answer: **${secretWord}**`
        : `⌛ **TIME'S UP — NO WINNER**\n\n` +
          `🔎 Secret Answer: **${secretWord}**`;

    return new EmbedBuilder()
        .setColor(solved ? 0xF1C40F : 0x747F8D)
        .setTitle(solved ? '🎨 PICTIONARY — SOLVED!' : '🎨 PICTIONARY — RESULTS')
        .setDescription(
            `**GUESSES**\n${buildPictionaryGuessReceipt(guesses, state.winner_user_id)}\n\n` +
            resultText
        )
        .setImage(`attachment://${PICTIONARY_IMAGE_ATTACHMENT_NAME}`);
}

function buildPictionaryGuessModal(gameKey) {
    const input = new TextInputBuilder()
        .setCustomId(PICTIONARY_GUESS_INPUT_ID)
        .setLabel('Your one exact guess')
        .setPlaceholder('Type what you think SmashPutt drew')
        .setStyle(TextInputStyle.Short)
        .setRequired(true)
        .setMinLength(1)
        .setMaxLength(PICTIONARY_MAX_GUESS_LENGTH);

    return new ModalBuilder()
        .setCustomId(`${PICTIONARY_MODAL_PREFIX}${gameKey}`)
        .setTitle('SmashPutt Pictionary')
        .addComponents(
            new ActionRowBuilder().addComponents(input)
        );
}

async function fetchPictionaryControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Pictionary channel could not be found: ${state.channel_id}`);
    }
    const message = await channel.messages.fetch(state.control_message_id);
    return { channel, message };
}

function queuePictionaryMessageOperation(operation) {
    const run = pictionaryMessageQueue.then(operation, operation);
    pictionaryMessageQueue = run.catch(() => {});
    return run;
}

function isMissingPictionaryDiscordMessage(error) {
    const code = Number(error?.code ?? error?.rawError?.code);
    return code === 10003 || code === 10008;
}

async function refreshActivePictionaryDisplay(gameKey) {
    return queuePictionaryMessageOperation(async () => {
        const state = getPictionaryStmt.get();
        if (!state || state.game_key !== gameKey || state.status !== 'ACTIVE') {
            return;
        }

        const guesses = getPictionaryGuessesStmt.all(gameKey);
        const { message } = await fetchPictionaryControlMessage(state);
        await message.edit({
            embeds: [buildPictionaryActiveEmbed(state, guesses)],
            components: [buildPictionaryGuessButton(false)]
        });
    });
}

const submitPictionaryGuessTransaction = db.transaction(({
    gameKey,
    userId,
    displayName,
    cleanName,
    guessText
}) => {
    const state = getActivePictionaryStmt.get();
    if (!state || state.game_key !== gameKey) {
        return { type: 'INACTIVE' };
    }

    const deadline = new Date(state.deadline_at);
    if (Number.isNaN(deadline.getTime()) || Date.now() >= deadline.getTime()) {
        return { type: 'EXPIRED' };
    }

    const existing = getPictionaryGuessStmt.get(gameKey, userId);
    if (existing) {
        return { type: 'ALREADY_GUESSED', entry: existing };
    }

    const normalizedGuess = normalizePictionaryGuess(guessText);
    const guessedAt = new Date().toISOString();

    insertPictionaryGuessStmt.run({
        game_key: gameKey,
        user_id: userId,
        display_name: displayName,
        clean_name: cleanName,
        guess_text: guessText,
        normalized_guess: normalizedGuess,
        guessed_at: guessedAt
    });

    if (normalizedGuess !== normalizePictionaryGuess(state.secret_word)) {
        return {
            type: 'WRONG',
            entry: getPictionaryGuessStmt.get(gameKey, userId)
        };
    }

    const completedAt = new Date().toISOString();
    const completion = db.prepare(`
        UPDATE smash_pictionary_state
        SET status = 'COMPLETE',
            winner_user_id = @winner_user_id,
            winner_display_name = @winner_display_name,
            winner_clean_name = @winner_clean_name,
            winning_guess = @winning_guess,
            completed_at = @completed_at
        WHERE id = 1
          AND game_key = @game_key
          AND status = 'ACTIVE'
    `).run({
        game_key: gameKey,
        winner_user_id: userId,
        winner_display_name: displayName,
        winner_clean_name: cleanName,
        winning_guess: guessText,
        completed_at: completedAt
    });

    if (completion.changes !== 1) {
        return { type: 'INACTIVE' };
    }

    ensurePlayer(userId, displayName);

    addSmashScoreStmt.run({
        user_id: userId,
        display_name: displayName,
        amount: PICTIONARY_SCORE_PRIZE,
        updated_at: completedAt
    });

    insertScoreTransactionStmt.run({
        user_id: userId,
        display_name: displayName,
        transaction_type: 'ADD',
        amount: PICTIONARY_SCORE_PRIZE,
        reason: `SmashPutt Pictionary Winner: ${state.secret_word}`,
        admin_user_id: userId,
        admin_display_name: displayName,
        created_at: completedAt
    });

    db.prepare(`
        UPDATE smash_pictionary_guesses
        SET is_winner = 1,
            reward_processed_at = @reward_processed_at
        WHERE game_key = @game_key
          AND user_id = @user_id
    `).run({
        game_key: gameKey,
        user_id: userId,
        reward_processed_at: completedAt
    });

    return {
        type: 'WINNER',
        state: getPictionaryStmt.get(),
        entry: getPictionaryGuessStmt.get(gameKey, userId),
        player: getPlayerStmt.get(userId)
    };
});

const completePictionaryTimeoutTransaction = db.transaction(gameKey => {
    const state = getActivePictionaryStmt.get();
    if (!state || state.game_key !== gameKey) {
        return { type: 'NO_ACTIVE' };
    }

    const deadline = new Date(state.deadline_at);
    if (!Number.isNaN(deadline.getTime()) && Date.now() < deadline.getTime()) {
        return { type: 'NOT_DUE', deadline };
    }

    const completedAt = new Date().toISOString();
    const completion = db.prepare(`
        UPDATE smash_pictionary_state
        SET status = 'COMPLETE',
            winner_user_id = NULL,
            winner_display_name = NULL,
            winner_clean_name = NULL,
            winning_guess = NULL,
            completed_at = @completed_at
        WHERE id = 1
          AND game_key = @game_key
          AND status = 'ACTIVE'
    `).run({
        game_key: gameKey,
        completed_at: completedAt
    });

    return completion.changes === 1
        ? { type: 'COMPLETE', state: getPictionaryStmt.get() }
        : { type: 'NO_ACTIVE' };
});

function armPictionaryResultRetry(gameKey) {
    clearPictionaryTimer();
    pictionaryDeadlineTimer = setTimeout(() => {
        pictionaryDeadlineTimer = null;
        finalizePictionaryResult(gameKey).catch(error => {
            console.error('[PICTIONARY] Result retry failed:', error);
            armPictionaryResultRetry(gameKey);
        });
    }, 10 * 1000);
}

async function finalizePictionaryResult(gameKey) {
    const state = getPictionaryStmt.get();
    if (
        !state ||
        state.game_key !== gameKey ||
        state.status !== 'COMPLETE' ||
        state.result_announced_at
    ) {
        return Boolean(
            state &&
            state.game_key === gameKey &&
            state.result_announced_at
        );
    }

    clearPictionaryTimer();
    let terminalizedByThisCall = false;
    let publicMessageMissing = false;

    try {
        await queuePictionaryMessageOperation(async () => {
            const current = getPictionaryStmt.get();
            if (
                !current ||
                current.game_key !== gameKey ||
                current.status !== 'COMPLETE' ||
                current.result_announced_at
            ) {
                return;
            }

            const guesses = getPictionaryGuessesStmt.all(gameKey);

            try {
                const { message } = await fetchPictionaryControlMessage(current);
                await message.edit({
                    embeds: [buildPictionaryResultEmbed(current, guesses)],
                    components: [buildPictionaryGuessButton(true)]
                });
            } catch (error) {
                if (!isMissingPictionaryDiscordMessage(error)) {
                    throw error;
                }

                publicMessageMissing = true;
                console.error(
                    `[PICTIONARY] Public message ${current.control_message_id} no longer exists; ` +
                    'closing the persistent result so SmashPutt does not remain locked.'
                );
            }

            const marked = markPictionaryResultAnnouncedStmt.run({
                game_key: gameKey,
                result_announced_at: new Date().toISOString()
            });

            terminalizedByThisCall = marked.changes === 1;
        });
    } catch (error) {
        console.error('[PICTIONARY] Final result announcement failed:', error);
        armPictionaryResultRetry(gameKey);
        return false;
    }

    const completed = getPictionaryStmt.get();
    if (!completed?.result_announced_at) {
        return false;
    }

    // A concurrent finalizer may already have completed the receipt. Only the
    // call that changed the terminal marker writes logs and schedules the next game.
    if (!terminalizedByThisCall) {
        return true;
    }

    const guesses = getPictionaryGuessesStmt.all(gameKey);
    console.log(
        `[PICTIONARY COMPLETE] Guesses: ${guesses.length} | ` +
        `Answer: ${completed.secret_word} | ` +
        `Winner: ${completed.winner_clean_name || 'NONE'} | ` +
        `Public receipt: ${publicMessageMissing ? 'MESSAGE MISSING' : 'POSTED'}`
    );

    await sendLogMessage(
        `🎨 **SmashPutt Pictionary Complete**\n` +
        `Answer: ${completed.secret_word}\n` +
        `Guesses: ${guesses.length}\n` +
        `Winner: ${completed.winner_clean_name || 'None'}\n` +
        `Public Receipt: ${publicMessageMissing ? 'Message was missing' : 'Posted'}\n` +
        `Time: ${getCentralTimeString()}`
    );

    updateLeaderboard().catch(error =>
        console.error('[PICTIONARY] Leaderboard refresh failed:', error)
    );

    await movePurchasePanelAfterAutomaticActivity(completed.source);

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({
            forceNew: completed.source === 'AUTO',
            reason: completed.source === 'AUTO'
                ? 'automatic pictionary complete'
                : 'player/manual pictionary complete; automatic schedule resumed'
        });
    }

    return true;
}

async function finishPictionaryIfDue(gameKey) {
    const result = completePictionaryTimeoutTransaction(gameKey);

    if (result.type === 'NOT_DUE') {
        armPictionaryTimer(getActivePictionaryStmt.get());
        return;
    }

    const pending = result.type === 'COMPLETE'
        ? result.state
        : getPendingPictionaryResultStmt.get();

    if (!pending || pending.game_key !== gameKey) {
        return;
    }

    await finalizePictionaryResult(gameKey);
}

function armPictionaryTimer(state) {
    clearPictionaryTimer();
    if (!state?.deadline_at) {
        return;
    }

    const dueAt = new Date(state.deadline_at).getTime();
    const delay = Number.isFinite(dueAt)
        ? Math.max(0, dueAt - Date.now()) + 50
        : 50;

    pictionaryDeadlineTimer = setTimeout(() => {
        pictionaryDeadlineTimer = null;
        finishPictionaryIfDue(state.game_key).catch(error => {
            console.error('[PICTIONARY] Finish timer failed:', error);
            armPictionaryResultRetry(state.game_key);
        });
    }, delay);
}

async function handlePictionaryGuessButton(interaction) {
    const state = getActivePictionaryStmt.get();

    if (
        !state ||
        interaction.channelId !== state.channel_id ||
        interaction.message.id !== state.control_message_id
    ) {
        try {
            await interaction.deferUpdate();
        } catch (_) {}
        return;
    }

    const deadline = new Date(state.deadline_at);
    if (Number.isNaN(deadline.getTime()) || Date.now() >= deadline.getTime()) {
        await interaction.reply({
            content: 'This Pictionary round has ended.',
            flags: MessageFlags.Ephemeral
        });
        finishPictionaryIfDue(state.game_key).catch(error =>
            console.error('[PICTIONARY] Late-button finish failed:', error)
        );
        return;
    }

    const existing = getPictionaryGuessStmt.get(
        state.game_key,
        interaction.user.id
    );

    if (existing) {
        await interaction.reply({
            content: `Your one Pictionary guess is already locked as **${escapeDiscordMarkdown(existing.guess_text)}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.showModal(
        buildPictionaryGuessModal(state.game_key)
    );
}

async function handlePictionaryGuessModal(interaction) {
    const gameKey = interaction.customId.substring(PICTIONARY_MODAL_PREFIX.length);
    const rawGuess = interaction.fields.getTextInputValue(PICTIONARY_GUESS_INPUT_ID);
    const guessText = String(rawGuess || '').normalize('NFKC').trim();

    await interaction.deferReply({
        flags: MessageFlags.Ephemeral
    });

    if (!guessText) {
        await interaction.editReply({
            content: 'Your Pictionary guess cannot be empty.'
        });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const cleanName = getCleanDiscordName(interaction);
    const result = submitPictionaryGuessTransaction({
        gameKey,
        userId: interaction.user.id,
        displayName,
        cleanName,
        guessText
    });

    if (result.type === 'ALREADY_GUESSED') {
        await interaction.editReply({
            content: `Your one Pictionary guess is already locked as **${escapeDiscordMarkdown(result.entry.guess_text)}**.`
        });
        return;
    }

    if (result.type === 'EXPIRED' || result.type === 'INACTIVE') {
        await interaction.editReply({
            content: 'This Pictionary round has already ended.'
        });
        finishPictionaryIfDue(gameKey).catch(error =>
            console.error('[PICTIONARY] Late-modal finish failed:', error)
        );
        return;
    }

    if (result.type === 'WRONG') {
        await interaction.editReply({
            content: `✏️ Your one guess, **${escapeDiscordMarkdown(guessText)}**, is locked and now appears publicly.`
        });

        refreshActivePictionaryDisplay(gameKey).catch(error =>
            console.error('[PICTIONARY] Public guess receipt refresh failed:', error)
        );
        return;
    }

    if (result.type === 'WINNER') {
        clearPictionaryTimer();

        await interaction.editReply({
            content: `🏆 Correct — **${escapeDiscordMarkdown(guessText)}**! You won **+${PICTIONARY_SCORE_PRIZE} 💥 Smash Score**. You solved it!`
        });

        await finalizePictionaryResult(gameKey);
    }
}

async function createPictionaryInChannel(channelId, source = 'AUTO') {
    if (!channelId) {
        return { ok: false, reason: 'NO_CHANNELS' };
    }

    if (!String(process.env.OPENAI_API_KEY || '').trim()) {
        return { ok: false, reason: 'MISSING_OPENAI_API_KEY' };
    }

    if (pictionarySpawnInProgress || hasActiveSmashPuttActivity()) {
        return { ok: false, reason: 'ACTIVE_ACTIVITY' };
    }

    pictionarySpawnInProgress = true;
    let controlMessage = null;
    let candidate = null;

    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) {
            throw new Error(`Pictionary spawn channel could not be found: ${channelId}`);
        }

        candidate = selectPictionaryWordCandidate();

        // The entire image is generated before the public game and timer exist.
        // The returned bytes remain in memory and are attached directly to Discord.
        const imageBuffer = await generatePictionaryImageBuffer(candidate.word);
        const provisionalDeadlineAt = new Date(Date.now() + PICTIONARY_DURATION_MS);
        const provisionalState = {
            deadline_at: provisionalDeadlineAt.toISOString()
        };

        controlMessage = await channel.send({
            embeds: [buildPictionaryActiveEmbed(provisionalState, [])],
            files: [
                new AttachmentBuilder(imageBuffer, {
                    name: PICTIONARY_IMAGE_ATTACHMENT_NAME
                })
            ],
            components: [buildPictionaryGuessButton(false)],
            allowedMentions: { parse: [] }
        });

        // The official 45-second clock starts from Discord's confirmed message
        // creation time, never while the AI drawing is still being generated.
        const startedAt = new Date(
            Number(controlMessage.createdTimestamp) || Date.now()
        );
        const deadlineAt = new Date(startedAt.getTime() + PICTIONARY_DURATION_MS);

        await controlMessage.edit({
            embeds: [buildPictionaryActiveEmbed({
                deadline_at: deadlineAt.toISOString()
            }, [])],
            components: [buildPictionaryGuessButton(false)]
        });

        // Persist the live round and consume the selected answer atomically.
        // If either write fails, SQLite rolls both back before the public message
        // is removed by the outer error handler.
        db.transaction(() => {
            createPictionaryStmt.run({
                game_key: controlMessage.id,
                channel_id: channel.id,
                control_message_id: controlMessage.id,
                source,
                secret_word: candidate.word.answer,
                word_category: candidate.word.category,
                started_at: startedAt.toISOString(),
                deadline_at: deadlineAt.toISOString()
            });

            commitPictionaryWordCandidate(candidate);
        })();
        pauseSchedulerForActiveGame();

        const state = getActivePictionaryStmt.get();
        armPictionaryTimer(state);

        console.log(
            `[PICTIONARY] ${source} round started | Key ${state.game_key} | ` +
            `Channel ${state.channel_id} | 45-second clock began after image upload | ` +
            `${candidate.remainingBag.length} answers remain before reshuffle.`
        );

        return {
            ok: true,
            state,
            controlMessage
        };
    } catch (error) {
        console.error(
            `[PICTIONARY] Could not start | ${error.code || error.message}`,
            error.requestId ? `| Request ${error.requestId}` : ''
        );

        if (controlMessage) {
            try {
                await controlMessage.delete();
            } catch (_) {}
        }

        if (
            candidate &&
            error.code === 'moderation_blocked'
        ) {
            try {
                commitPictionaryWordCandidate(candidate);
                console.log(
                    `[PICTIONARY] Skipped blocked answer and advanced the word bag | ` +
                    `${candidate.remainingBag.length} answers remain before reshuffle.`
                );
            } catch (bagError) {
                console.error('[PICTIONARY] Could not advance past blocked answer:', bagError);
            }
        }

        return {
            ok: false,
            reason: error.code || 'CREATE_FAILED'
        };
    } finally {
        pictionarySpawnInProgress = false;
    }
}

async function handlePictionaryCommand(interaction) {
    const channelIds = getActiveSpawnChannelIds();

    if (channelIds.length === 0) {
        await interaction.reply({
            content: 'There are no active SmashPutt spawn channels.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (!String(process.env.OPENAI_API_KEY || '').trim()) {
        await interaction.reply({
            content: 'Pictionary cannot start because OPENAI_API_KEY is not configured on Hetzner.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (hasActiveSmashPuttActivity() || pictionarySpawnInProgress) {
        await interaction.reply({
            content: 'There is already an active SmashPutt activity.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({
        flags: MessageFlags.Ephemeral
    });

    pauseSchedulerForActiveGame();

    const result = await createPictionaryInChannel(
        randomItem(channelIds),
        'FORCE'
    );

    if (result.ok) {
        await interaction.editReply({
            content:
                `✅ A fresh Pictionary drawing was generated and the 45-second game is live in ` +
                `<#${result.controlMessage.channelId}>.`
        });
        return;
    }

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({
            forceNew: true,
            reason: 'manual pictionary failed to start'
        });
    }

    let message = 'Pictionary could not be started. Check the bot logs.';

    if (result.reason === 'MISSING_OPENAI_API_KEY') {
        message = 'Pictionary cannot start because OPENAI_API_KEY is not configured.';
    } else if (result.reason === 'insufficient_quota') {
        message = 'OpenAI declined the drawing request because the API account has no available billing quota.';
    } else if (result.reason === 'IMAGE_GENERATION_TIMEOUT') {
        message = 'The drawing took too long to generate. No public Pictionary game was posted.';
    } else if (result.reason === 'moderation_blocked') {
        message = 'The selected drawing request was blocked. No public game was posted; try the command again.';
    }

    await interaction.editReply({ content: message });
}

async function resumePictionaryOnStartup() {
    clearPictionaryTimer();

    const pending = getPendingPictionaryResultStmt.get();
    if (pending) {
        console.log(`[PICTIONARY] Recovering pending result ${pending.game_key}.`);
        const announced = await finalizePictionaryResult(pending.game_key);
        if (!announced) {
            return;
        }
    }

    const state = getActivePictionaryStmt.get();
    if (!state) {
        console.log('No active SmashPutt Pictionary currently exists.');
        return;
    }

    const deadline = new Date(state.deadline_at);
    if (Number.isNaN(deadline.getTime()) || deadline.getTime() <= Date.now()) {
        await finishPictionaryIfDue(state.game_key);
        return;
    }

    try {
        const guesses = getPictionaryGuessesStmt.all(state.game_key);
        const { message } = await fetchPictionaryControlMessage(state);
        await message.edit({
            embeds: [buildPictionaryActiveEmbed(state, guesses)],
            components: [buildPictionaryGuessButton(false)]
        });
    } catch (error) {
        if (isMissingPictionaryDiscordMessage(error)) {
            const now = new Date().toISOString();
            db.prepare(`
                UPDATE smash_pictionary_state
                SET status = 'CANCELLED',
                    completed_at = @completed_at,
                    result_announced_at = @result_announced_at
                WHERE id = 1
                  AND game_key = @game_key
                  AND status = 'ACTIVE'
            `).run({
                game_key: state.game_key,
                completed_at: now,
                result_announced_at: now
            });

            console.error(
                `[PICTIONARY] Active public message ${state.control_message_id} was missing at startup; ` +
                'the round was cancelled and the activity lock was released.'
            );

            if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
                await scheduleNextAutoSpawn({
                    forceNew: true,
                    reason: 'missing Pictionary message cancelled on startup'
                });
            }
            return;
        }

        console.error('[PICTIONARY] Active display recovery failed:', error);
    }

    pauseSchedulerForActiveGame();
    armPictionaryTimer(state);
    console.log(`[PICTIONARY] Recovered active game ${state.game_key}.`);
}

// ============================================================
// SMASHPUTT TRIVIA
// ============================================================

let triviaReadTimer = null;
let triviaAnswerTimer = null;
let triviaSpawnInProgress = false;
let triviaMessageQueue = Promise.resolve();

function clearTriviaTimers() {
    if (triviaReadTimer) {
        clearTimeout(triviaReadTimer);
        triviaReadTimer = null;
    }
    if (triviaAnswerTimer) {
        clearTimeout(triviaAnswerTimer);
        triviaAnswerTimer = null;
    }
}

function queueTriviaMessageOperation(operation) {
    const run = triviaMessageQueue.then(operation, operation);
    triviaMessageQueue = run.catch(() => {});
    return run;
}

function parseTriviaChoices(state) {
    try {
        const choices = JSON.parse(state.choices_json);
        return Array.isArray(choices) ? choices : [];
    } catch (_) {
        return [];
    }
}

function shuffleTriviaValues(values) {
    const shuffled = [...values];
    for (let index = shuffled.length - 1; index > 0; index--) {
        const swapIndex = randomInteger(0, index);
        [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
    }
    return shuffled;
}

function getNextTriviaSequenceNumber() {
    const stored = Number(getSetting(TRIVIA_SEQUENCE_SETTING));
    if (!Number.isInteger(stored) || stored < 1 || stored > TRIVIA_QUESTION_BANK.length) {
        return 1;
    }
    return stored;
}

function getFollowingTriviaSequenceNumber(currentNumber) {
    return currentNumber >= TRIVIA_QUESTION_BANK.length ? 1 : currentNumber + 1;
}

function getTriviaQuestionNumber(state) {
    const match = /^fixed_trivia_(\d{4})$/.exec(String(state?.fact_key || ''));
    if (!match) return null;
    const number = Number(match[1]);
    return Number.isInteger(number) && number >= 1 && number <= TRIVIA_QUESTION_BANK.length
        ? number
        : null;
}

function getTriviaHeaderLine(state) {
    const number = getTriviaQuestionNumber(state);
    const category = escapeDiscordMarkdown(String(state?.category || '').toUpperCase());
    return number ? `**TRIVIA #${number} • ${category}**` : `**${category}**`;
}

function getSequentialTriviaCandidate() {
    const number = getNextTriviaSequenceNumber();
    const entry = TRIVIA_QUESTION_BANK[number - 1];
    if (!entry || entry.id !== number) {
        const error = new Error(`Trivia bank entry #${number} is unavailable.`);
        error.code = 'TRIVIA_BANK_ERROR';
        throw error;
    }

    const correctAnswer = entry.correct;
    const choices = shuffleTriviaValues([entry.correct, ...entry.wrong]);
    const correctIndex = choices.indexOf(correctAnswer);
    if (correctIndex < 0 || new Set(choices.map(choice => choice.toLowerCase())).size !== 4) {
        const error = new Error(`Trivia bank entry #${number} has invalid answer choices.`);
        error.code = 'TRIVIA_BANK_ERROR';
        throw error;
    }

    return {
        number,
        category: entry.category,
        question: entry.question,
        choices,
        correct_index: correctIndex,
        explanation: entry.explanation,
        fact_key: `fixed_trivia_${String(number).padStart(4, '0')}`
    };
}

function buildTriviaReadingEmbed(state) {
    const deadlineUnix = Math.floor(new Date(state.read_deadline_at).getTime() / 1000);
    return new EmbedBuilder()
        .setColor(0x5865F2)
        .setTitle('🧠 SMASHPUTT TRIVIA')
        .setDescription(
            `${getTriviaHeaderLine(state)}\n` +
            `**${escapeDiscordMarkdown(state.question_text)}**\n\n` +
            `⏳ **Answers unlock in 5 seconds...** • <t:${deadlineUnix}:R>`
        )
        .setImage(`attachment://${TRIVIA_BANNER_ATTACHMENT_NAME}`);
}

function buildTriviaAnswerButtons(state, disabled = false) {
    const choices = parseTriviaChoices(state);
    const row = new ActionRowBuilder();
    choices.forEach((choice, index) => {
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`${TRIVIA_BUTTON_PREFIX}${state.game_key}:${index}`)
                .setLabel(choice)
                .setStyle(ButtonStyle.Primary)
                .setDisabled(disabled)
        );
    });
    return [row];
}

function buildTriviaAnsweringEmbed(state) {
    const deadlineUnix = Math.floor(new Date(state.answer_deadline_at).getTime() / 1000);
    return new EmbedBuilder()
        .setColor(0x5865F2)
        .setTitle('🧠 SMASHPUTT TRIVIA')
        .setDescription(
            `${getTriviaHeaderLine(state)}\n` +
            `**${escapeDiscordMarkdown(state.question_text)}**\n\n` +
            `Choose one answer. **Your choice is final.**\n` +
            `⏱️ **10 seconds to answer** • <t:${deadlineUnix}:R>`
        )
        .setImage(`attachment://${TRIVIA_BANNER_ATTACHMENT_NAME}`);
}

function buildTriviaResultEmbed(state, answers) {
    const choices = parseTriviaChoices(state);
    const correctIndex = Number(state.correct_index);
    const lines = choices.map((choice, index) => {
        const names = answers
            .filter(answer => Number(answer.choice_index) === index)
            .map(answer => escapeDiscordMarkdown(answer.clean_name || answer.display_name || 'Player'));
        const picked = names.length ? names.join(', ') : 'No picks';
        if (index === correctIndex) {
            return `✅ **${escapeDiscordMarkdown(choice.toUpperCase())}** — ${picked}${names.length ? ` · **+${TRIVIA_SCORE_PRIZE} 💥 Smash Score each**` : ''}`;
        }
        return `❌ **${escapeDiscordMarkdown(choice.toUpperCase())}** — ${picked}`;
    });

    return new EmbedBuilder()
        .setColor(0x2ECC71)
        .setTitle('🧠 SMASHPUTT TRIVIA — RESULTS')
        .setDescription(
            `${getTriviaHeaderLine(state)}\n` +
            `**${escapeDiscordMarkdown(state.question_text)}**\n\n` +
            `${lines.join('\n')}\n\n` +
            `*${escapeDiscordMarkdown(state.explanation)}*`
        )
        .setImage(`attachment://${TRIVIA_BANNER_ATTACHMENT_NAME}`);
}

async function fetchTriviaControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Trivia channel could not be found: ${state.channel_id}`);
    }
    const message = await channel.messages.fetch(state.control_message_id);
    return { channel, message };
}

const submitTriviaAnswerTransaction = db.transaction(({ gameKey, userId, displayName, cleanName, choiceIndex }) => {
    const state = getActiveTriviaStmt.get();
    if (!state || state.game_key !== gameKey || state.phase !== 'ANSWERING') {
        return { type: 'INACTIVE' };
    }

    const deadline = new Date(state.answer_deadline_at);
    if (Number.isNaN(deadline.getTime()) || deadline.getTime() <= Date.now()) {
        return { type: 'EXPIRED' };
    }

    const existing = getTriviaAnswerStmt.get(gameKey, userId);
    if (existing) {
        return { type: 'ALREADY', entry: existing };
    }

    const choices = parseTriviaChoices(state);
    if (!Number.isInteger(choiceIndex) || choiceIndex < 0 || choiceIndex >= choices.length) {
        return { type: 'INVALID' };
    }

    const answeredAt = new Date().toISOString();
    const isCorrect = choiceIndex === Number(state.correct_index) ? 1 : 0;
    insertTriviaAnswerStmt.run({
        game_key: gameKey,
        user_id: userId,
        display_name: displayName,
        clean_name: cleanName,
        choice_index: choiceIndex,
        answered_at: answeredAt,
        is_correct: isCorrect
    });

    return { type: 'LOCKED', choice: choices[choiceIndex] };
});

async function handleTriviaAnswerButton(interaction) {
    const payload = interaction.customId.substring(TRIVIA_BUTTON_PREFIX.length);
    const separator = payload.lastIndexOf(':');
    const gameKey = separator >= 0 ? payload.slice(0, separator) : '';
    const choiceIndex = separator >= 0 ? Number(payload.slice(separator + 1)) : NaN;

    const displayName = interaction.member?.displayName || interaction.user.globalName || interaction.user.username;
    const cleanName = getCleanDiscordName(interaction);
    const result = submitTriviaAnswerTransaction({
        gameKey,
        userId: interaction.user.id,
        displayName,
        cleanName,
        choiceIndex
    });

    if (result.type === 'LOCKED') {
        await interaction.reply({
            content: `✅ Your answer is locked: **${escapeDiscordMarkdown(result.choice)}**`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (result.type === 'ALREADY') {
        const state = getTriviaStmt.get();
        const choices = state ? parseTriviaChoices(state) : [];
        const prior = choices[Number(result.entry.choice_index)] || 'your previous choice';
        await interaction.reply({
            content: `Your Trivia answer is already locked as **${escapeDiscordMarkdown(prior)}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.reply({
        content: result.type === 'EXPIRED' ? 'This Trivia answer window has ended.' : 'This Trivia round is no longer accepting answers.',
        flags: MessageFlags.Ephemeral
    });

    if (result.type === 'EXPIRED') {
        finishTriviaIfDue(gameKey).catch(error => console.error('[TRIVIA] Deadline completion failed:', error));
    }
}

function awardTriviaResultsTransaction(gameKey) {
    const state = getActiveTriviaStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };

    const now = new Date().toISOString();
    const completion = db.prepare(`
        UPDATE smash_trivia_state
        SET status = 'COMPLETE', phase = 'COMPLETE', completed_at = @completed_at
        WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE'
    `).run({ game_key: gameKey, completed_at: now });

    if (completion.changes !== 1) return { type: 'INACTIVE' };

    const questionNumber = getTriviaQuestionNumber(state);
    if (questionNumber && getNextTriviaSequenceNumber() === questionNumber) {
        setSetting(TRIVIA_SEQUENCE_SETTING, getFollowingTriviaSequenceNumber(questionNumber));
    }

    const winners = getTriviaAnswersStmt.all(gameKey).filter(answer => Number(answer.is_correct) === 1);
    for (const winner of winners) {
        ensurePlayer(winner.user_id, winner.display_name);
        addSmashScoreStmt.run({
            user_id: winner.user_id,
            display_name: winner.display_name,
            amount: TRIVIA_SCORE_PRIZE,
            updated_at: now
        });
        insertScoreTransactionStmt.run({
            user_id: winner.user_id,
            display_name: winner.display_name,
            transaction_type: 'ADD',
            amount: TRIVIA_SCORE_PRIZE,
            reason: `SmashPutt Trivia Correct: ${state.question_text}`,
            admin_user_id: winner.user_id,
            admin_display_name: winner.display_name,
            created_at: now
        });
        db.prepare(`
            UPDATE smash_trivia_answers
            SET reward_processed_at = @reward_processed_at
            WHERE game_key = @game_key AND user_id = @user_id AND reward_processed_at IS NULL
        `).run({ reward_processed_at: now, game_key: gameKey, user_id: winner.user_id });
    }

    return { type: 'COMPLETE', state: getTriviaStmt.get(), winners };
}

async function finalizeTriviaResult(gameKey) {
    const state = getTriviaStmt.get();
    if (!state || state.game_key !== gameKey || state.status !== 'COMPLETE') return false;
    if (state.result_announced_at) return true;

    clearTriviaTimers();
    const answers = getTriviaAnswersStmt.all(gameKey);

    try {
        await queueTriviaMessageOperation(async () => {
            const current = getTriviaStmt.get();
            if (!current || current.game_key !== gameKey || current.result_announced_at) return;
            const { message } = await fetchTriviaControlMessage(current);
            await message.edit({
                embeds: [buildTriviaResultEmbed(current, answers)],
                components: []
            });
            markTriviaResultAnnouncedStmt.run({ game_key: gameKey, result_announced_at: new Date().toISOString() });
        });
    } catch (error) {
        console.error('[TRIVIA] Result announcement failed:', error);
        triviaAnswerTimer = setTimeout(() => {
            triviaAnswerTimer = null;
            finalizeTriviaResult(gameKey).catch(retryError => console.error('[TRIVIA] Result retry failed:', retryError));
        }, 10000);
        return false;
    }

    const completed = getTriviaStmt.get();
    const winners = answers.filter(answer => Number(answer.is_correct) === 1);
    console.log(`[TRIVIA COMPLETE] Answers: ${answers.length} | Correct: ${winners.length} | Category: ${completed.category}`);

    try {
        await updateLeaderboard();
    } catch (error) {
        console.error('[TRIVIA] Leaderboard refresh failed:', error);
    }

    await movePurchasePanelAfterAutomaticActivity(completed.source);

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({
            forceNew: completed.source === 'AUTO',
            reason: completed.source === 'AUTO'
                ? 'automatic trivia complete'
                : 'player/manual trivia complete; automatic schedule resumed'
        });
    }

    return true;
}

async function finishTriviaIfDue(gameKey) {
    const state = getActiveTriviaStmt.get();
    if (!state || state.game_key !== gameKey) return;

    if (state.phase === 'READING') {
        const readDeadline = new Date(state.read_deadline_at);
        if (!Number.isNaN(readDeadline.getTime()) && readDeadline.getTime() > Date.now()) {
            armTriviaTimers(state);
            return;
        }
        await beginTriviaAnswerPhase(gameKey);
        return;
    }

    if (state.phase === 'ANSWERING') {
        const answerDeadline = new Date(state.answer_deadline_at);
        if (!Number.isNaN(answerDeadline.getTime()) && answerDeadline.getTime() > Date.now()) {
            armTriviaTimers(state);
            return;
        }
        const result = awardTriviaResultsTransaction(gameKey);
        if (result.type === 'COMPLETE') {
            await finalizeTriviaResult(gameKey);
        }
    }
}

async function beginTriviaAnswerPhase(gameKey) {
    const state = getActiveTriviaStmt.get();
    if (!state || state.game_key !== gameKey || state.phase !== 'READING') return;

    await queueTriviaMessageOperation(async () => {
        const current = getActiveTriviaStmt.get();
        if (!current || current.game_key !== gameKey || current.phase !== 'READING') return;

        const { message } = await fetchTriviaControlMessage(current);
        const answerStartedAt = new Date();
        const answerDeadlineAt = new Date(answerStartedAt.getTime() + TRIVIA_ANSWER_DURATION_MS);

        const updated = db.prepare(`
            UPDATE smash_trivia_state
            SET phase = 'ANSWERING', answer_started_at = @answer_started_at, answer_deadline_at = @answer_deadline_at
            WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE' AND phase = 'READING'
        `).run({
            game_key: gameKey,
            answer_started_at: answerStartedAt.toISOString(),
            answer_deadline_at: answerDeadlineAt.toISOString()
        });

        if (updated.changes !== 1) return;

        const answeringState = getActiveTriviaStmt.get();
        await message.edit({
            embeds: [buildTriviaAnsweringEmbed(answeringState)],
            components: buildTriviaAnswerButtons(answeringState, false)
        });

        // Reset the official answer window from the confirmed Discord edit time.
        const confirmedStartedAt = new Date();
        const confirmedDeadlineAt = new Date(confirmedStartedAt.getTime() + TRIVIA_ANSWER_DURATION_MS);
        db.prepare(`
            UPDATE smash_trivia_state
            SET answer_started_at = @answer_started_at, answer_deadline_at = @answer_deadline_at
            WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE' AND phase = 'ANSWERING'
        `).run({
            game_key: gameKey,
            answer_started_at: confirmedStartedAt.toISOString(),
            answer_deadline_at: confirmedDeadlineAt.toISOString()
        });

        const finalState = getActiveTriviaStmt.get();
        await message.edit({
            embeds: [buildTriviaAnsweringEmbed(finalState)],
            components: buildTriviaAnswerButtons(finalState, false)
        });
        armTriviaTimers(finalState);
    });
}

function armTriviaTimers(state) {
    clearTriviaTimers();
    if (!state || state.status !== 'ACTIVE') return;

    if (state.phase === 'READING') {
        const deadline = new Date(state.read_deadline_at);
        const delay = Math.max(0, deadline.getTime() - Date.now());
        triviaReadTimer = setTimeout(() => {
            triviaReadTimer = null;
            beginTriviaAnswerPhase(state.game_key).catch(error => console.error('[TRIVIA] Answer phase failed:', error));
        }, delay);
        return;
    }

    if (state.phase === 'ANSWERING') {
        const deadline = new Date(state.answer_deadline_at);
        const delay = Math.max(0, deadline.getTime() - Date.now());
        triviaAnswerTimer = setTimeout(() => {
            triviaAnswerTimer = null;
            finishTriviaIfDue(state.game_key).catch(error => console.error('[TRIVIA] Completion failed:', error));
        }, delay);
    }
}

async function createTriviaInChannel(channelId, source = 'AUTO') {
    if (!channelId) return { ok: false, reason: 'NO_CHANNELS' };
    if (!fs.existsSync(TRIVIA_BANNER_PATH)) return { ok: false, reason: 'MISSING_TRIVIA_BANNER' };
    if (triviaSpawnInProgress || hasActiveSmashPuttActivity()) return { ok: false, reason: 'ACTIVE_ACTIVITY' };

    triviaSpawnInProgress = true;
    let controlMessage = null;

    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) throw new Error(`Trivia spawn channel could not be found: ${channelId}`);

        const candidate = getSequentialTriviaCandidate();
        const provisionalReadDeadline = new Date(Date.now() + TRIVIA_READ_DURATION_MS);
        const provisionalState = {
            category: candidate.category,
            question_text: candidate.question,
            fact_key: candidate.fact_key,
            read_deadline_at: provisionalReadDeadline.toISOString()
        };

        controlMessage = await channel.send({
            embeds: [buildTriviaReadingEmbed(provisionalState)],
            files: [new AttachmentBuilder(TRIVIA_BANNER_PATH, { name: TRIVIA_BANNER_ATTACHMENT_NAME })],
            components: [],
            allowedMentions: { parse: [] }
        });

        const startedAt = new Date(Number(controlMessage.createdTimestamp) || Date.now());
        const readDeadlineAt = new Date(startedAt.getTime() + TRIVIA_READ_DURATION_MS);

        await controlMessage.edit({
            embeds: [buildTriviaReadingEmbed({
                ...provisionalState,
                read_deadline_at: readDeadlineAt.toISOString()
            })],
            components: []
        });

        db.transaction(() => {
            createTriviaStmt.run({
                game_key: controlMessage.id,
                channel_id: channel.id,
                control_message_id: controlMessage.id,
                source,
                category: candidate.category,
                question_text: candidate.question,
                choices_json: JSON.stringify(candidate.choices),
                correct_index: candidate.correct_index,
                explanation: candidate.explanation,
                fact_key: candidate.fact_key,
                started_at: startedAt.toISOString(),
                read_deadline_at: readDeadlineAt.toISOString()
            });
        })();

        pauseSchedulerForActiveGame();
        const state = getActiveTriviaStmt.get();
        armTriviaTimers(state);
        console.log(`[TRIVIA] ${source} round started | Trivia #${candidate.number}/1000 | Key ${state.game_key} | Channel ${state.channel_id} | 5-second read + 10-second answer | ZERO OpenAI API calls.`);
        return { ok: true, state, controlMessage };
    } catch (error) {
        console.error(`[TRIVIA] Could not start | ${error.code || error.message}`, error.requestId ? `| Request ${error.requestId}` : '');
        if (controlMessage) {
            try { await controlMessage.delete(); } catch (_) {}
        }
        return { ok: false, reason: error.code || 'CREATE_FAILED' };
    } finally {
        triviaSpawnInProgress = false;
    }
}

async function handleTriviaCommand(interaction) {
    if (!fs.existsSync(TRIVIA_BANNER_PATH)) {
        await interaction.reply({ content: 'Trivia cannot start because Trivia/trivia.png is missing on Hetzner.', flags: MessageFlags.Ephemeral });
        return;
    }
    if (hasActiveSmashPuttActivity() || triviaSpawnInProgress) {
        await interaction.reply({ content: 'There is already an active SmashPutt activity.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    pauseSchedulerForActiveGame();

    const result = await createTriviaInChannel(SCORE_REPORT_CHANNEL_ID, 'FORCE');
    if (result.ok) {
        await interaction.editReply({ content: `✅ SmashPutt Trivia is live in <#${SCORE_REPORT_CHANNEL_ID}>.` });
        return;
    }

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: true, reason: 'manual trivia failed to start' });
    }

    const messages = {
        MISSING_TRIVIA_BANNER: 'Trivia cannot start because Trivia/trivia.png is missing.',
        TRIVIA_BANK_ERROR: 'Trivia could not start because the fixed question bank failed validation.'
    };
    await interaction.editReply({ content: messages[result.reason] || 'Trivia could not be started. Check the bot logs.' });
}

async function resumeTriviaOnStartup() {
    clearTriviaTimers();

    const pending = getPendingTriviaResultStmt.get();
    if (pending) {
        console.log(`[TRIVIA] Recovering pending result ${pending.game_key}.`);
        const announced = await finalizeTriviaResult(pending.game_key);
        if (!announced) return;
    }

    const state = getActiveTriviaStmt.get();
    if (!state) {
        console.log('No active SmashPutt Trivia currently exists.');
        return;
    }

    if (!fs.existsSync(TRIVIA_BANNER_PATH)) {
        console.error(`[TRIVIA] Banner missing during recovery: ${TRIVIA_BANNER_PATH}`);
    }

    try {
        const { message } = await fetchTriviaControlMessage(state);
        if (state.phase === 'READING') {
            await message.edit({ embeds: [buildTriviaReadingEmbed(state)], components: [] });
        } else if (state.phase === 'ANSWERING') {
            await message.edit({ embeds: [buildTriviaAnsweringEmbed(state)], components: buildTriviaAnswerButtons(state, false) });
        }
    } catch (error) {
        console.error('[TRIVIA] Active display recovery failed:', error);
    }

    pauseSchedulerForActiveGame();
    const current = getActiveTriviaStmt.get();
    if (current) {
        await finishTriviaIfDue(current.game_key);
        if (getActiveTriviaStmt.get()) armTriviaTimers(getActiveTriviaStmt.get());
    }
    console.log(`[TRIVIA] Recovered active game ${state.game_key}.`);
}

// ============================================================
// SMASHPUTT BULLSEYE
// ============================================================

db.exec(`
    CREATE TABLE IF NOT EXISTS smash_bullseye_buy_cooldowns (
        user_id TEXT PRIMARY KEY,
        last_started_at TEXT NOT NULL,
        next_available_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS smash_bullseye_state (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        game_key TEXT,
        status TEXT NOT NULL,
        channel_id TEXT,
        control_message_id TEXT,
        source TEXT NOT NULL DEFAULT 'PLAYER',
        target_number INTEGER NOT NULL,
        started_at TEXT,
        deadline_at TEXT,
        completed_at TEXT,
        result_announced_at TEXT
    );
    CREATE TABLE IF NOT EXISTS smash_bullseye_entries (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        game_key TEXT NOT NULL,
        user_id TEXT NOT NULL,
        display_name TEXT NOT NULL,
        clean_name TEXT NOT NULL,
        chosen_number INTEGER NOT NULL,
        entered_at TEXT NOT NULL,
        reward_amount INTEGER NOT NULL DEFAULT 0,
        reward_processed_at TEXT,
        UNIQUE(game_key, user_id)
    );
    CREATE INDEX IF NOT EXISTS idx_smash_bullseye_entries_key
    ON smash_bullseye_entries (game_key, chosen_number, id);
`);

// ============================================================
// SMASHPUTT EMOJI MOVIE TRIVIA
// ============================================================

let emojiMovieDeadlineTimer = null;
let emojiMovieSpawnInProgress = false;
let emojiMovieMessageQueue = Promise.resolve();

function clearEmojiMovieTimer() {
    if (emojiMovieDeadlineTimer) {
        clearTimeout(emojiMovieDeadlineTimer);
        emojiMovieDeadlineTimer = null;
    }
}

function queueEmojiMovieMessageOperation(operation) {
    const run = emojiMovieMessageQueue.then(operation, operation);
    emojiMovieMessageQueue = run.catch(() => {});
    return run;
}

function getEmojiMovieBag() {
    const validIds = new Set(EMOJI_MOVIE_LIBRARY.map(entry => entry.id));
    const raw = getSetting(EMOJI_MOVIE_BAG_SETTING);
    if (raw) {
        try {
            const parsed = JSON.parse(raw);
            if (
                Array.isArray(parsed) &&
                parsed.every(id => Number.isInteger(id) && validIds.has(id)) &&
                new Set(parsed).size === parsed.length
            ) return parsed;
        } catch (error) {
            console.error('[EMOJI MOVIE] Stored movie bag invalid; rebuilding:', error.message);
        }
    }
    return shufflePictionaryAnswers(EMOJI_MOVIE_LIBRARY.map(entry => entry.id));
}

function selectEmojiMovieCandidate() {
    let bag = getEmojiMovieBag();
    if (bag.length === 0) {
        bag = shufflePictionaryAnswers(EMOJI_MOVIE_LIBRARY.map(entry => entry.id));
    }
    const movieId = bag[bag.length - 1];
    const movie = EMOJI_MOVIE_BY_ID.get(movieId);
    if (!movie) throw new Error(`Emoji Movie bag contained unknown movie id ${movieId}`);
    return { movie, remainingBag: bag.slice(0, -1) };
}

function commitEmojiMovieCandidate(candidate) {
    setSetting(EMOJI_MOVIE_BAG_SETTING, JSON.stringify(candidate.remainingBag));
}

function buildEmojiMovieChoices(movie) {
    const sameGroup = EMOJI_MOVIE_LIBRARY.filter(entry => entry.group === movie.group && entry.id !== movie.id);
    const fallback = EMOJI_MOVIE_LIBRARY.filter(entry => entry.id !== movie.id);
    const pool = sameGroup.length >= 3 ? sameGroup : fallback;
    const shuffled = shufflePictionaryAnswers(pool);
    const choices = [movie, ...shuffled.slice(0, 3)];
    const randomized = shufflePictionaryAnswers(choices);
    return {
        choices: randomized.map(entry => entry.title),
        correctIndex: randomized.findIndex(entry => entry.id === movie.id)
    };
}

function parseEmojiMovieChoices(state) {
    try {
        const parsed = JSON.parse(state.choices_json);
        return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
        return [];
    }
}

function getEmojiMovieTimeLeftText(deadlineAt) {
    const deadline = new Date(deadlineAt);
    const seconds = Math.max(0, Math.ceil((deadline.getTime() - Date.now()) / 1000));
    return `${seconds}s`;
}

function buildEmojiMovieActiveEmbed(state) {
    const deadlineUnix = Math.floor(new Date(state.deadline_at).getTime() / 1000);
    return new EmbedBuilder()
        .setColor(0x8E44AD)
        .setTitle('🎬 SMASHPUTT EMOJI MOVIE TRIVIA')
        .setDescription(
            `**What movie do these emojis describe?**\n\n` +
            `# ${state.emoji_clue}\n\n` +
            `Choose one movie. **Your choice is final.**\n` +
            `⏱️ **TIME LEFT: ${getEmojiMovieTimeLeftText(state.deadline_at)}** • <t:${deadlineUnix}:R>`
        )
        .setImage(EMOJI_MOVIE_BANNER_URL);
}

function buildEmojiMovieButtons(state, disabled = false) {
    const choices = parseEmojiMovieChoices(state);
    return [new ActionRowBuilder().addComponents(
        choices.map((choice, index) =>
            new ButtonBuilder()
                .setCustomId(`${EMOJI_MOVIE_BUTTON_PREFIX}${state.game_key}:${index}`)
                .setLabel(choice.slice(0, 80))
                .setStyle(ButtonStyle.Primary)
                .setDisabled(disabled)
        )
    )];
}

function buildEmojiMovieResultEmbed(state, answers) {
    const choices = parseEmojiMovieChoices(state);
    const lines = choices.map((choice, index) => {
        const pickers = answers.filter(answer => Number(answer.choice_index) === index);
        const names = pickers.length
            ? pickers.map(answer => escapeDiscordMarkdown(answer.clean_name || answer.display_name || 'Player')).join(', ')
            : 'No picks';
        const correct = index === Number(state.correct_index);
        return `${correct ? '✅' : '❌'} **${escapeDiscordMarkdown(choice.toUpperCase())}** — ${names}`;
    });

    return new EmbedBuilder()
        .setColor(0x2ECC71)
        .setTitle('🎬 EMOJI MOVIE TRIVIA — RESULTS')
        .setDescription(
            `${state.emoji_clue}\n\n` +
            `${lines.join('\n')}`
        )
        .setImage(EMOJI_MOVIE_BANNER_URL);
}

async function fetchEmojiMovieControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Emoji Movie Trivia channel could not be found: ${state.channel_id}`);
    }
    const message = await channel.messages.fetch(state.control_message_id);
    return { channel, message };
}

const submitEmojiMovieAnswerTransaction = db.transaction(({ gameKey, userId, displayName, cleanName, choiceIndex }) => {
    const state = getActiveEmojiMovieStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };
    if (new Date(state.deadline_at).getTime() <= Date.now()) return { type: 'EXPIRED' };
    const existing = getEmojiMovieAnswerStmt.get(gameKey, userId);
    if (existing) return { type: 'ALREADY', entry: existing };
    const choices = parseEmojiMovieChoices(state);
    if (!Number.isInteger(choiceIndex) || choiceIndex < 0 || choiceIndex >= choices.length) return { type: 'INVALID' };
    const answeredAt = new Date().toISOString();
    const isCorrect = choiceIndex === Number(state.correct_index) ? 1 : 0;
    insertEmojiMovieAnswerStmt.run({
        game_key: gameKey,
        user_id: userId,
        display_name: displayName,
        clean_name: cleanName,
        choice_index: choiceIndex,
        answered_at: answeredAt,
        is_correct: isCorrect
    });
    return { type: 'ACCEPTED', choice: choices[choiceIndex] };
});

async function handleEmojiMovieAnswerButton(interaction) {
    const payload = interaction.customId.substring(EMOJI_MOVIE_BUTTON_PREFIX.length);
    const splitAt = payload.lastIndexOf(':');
    const gameKey = splitAt >= 0 ? payload.slice(0, splitAt) : '';
    const choiceIndex = splitAt >= 0 ? Number(payload.slice(splitAt + 1)) : NaN;
    const displayName = interaction.member?.displayName || interaction.user.globalName || interaction.user.username;
    const cleanName = getCleanDiscordName(interaction);
    const result = submitEmojiMovieAnswerTransaction({
        gameKey,
        userId: interaction.user.id,
        displayName,
        cleanName,
        choiceIndex
    });

    if (result.type === 'ALREADY') {
        const state = getActiveEmojiMovieStmt.get();
        const choices = state ? parseEmojiMovieChoices(state) : [];
        const prior = choices[Number(result.entry.choice_index)] || 'your previous choice';
        await interaction.reply({
            content: `Your Emoji Movie Trivia answer is already locked as **${escapeDiscordMarkdown(prior)}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (result.type === 'EXPIRED' || result.type === 'INACTIVE') {
        await interaction.reply({ content: 'This Emoji Movie Trivia round has ended.', flags: MessageFlags.Ephemeral });
        finishEmojiMovieIfDue(gameKey).catch(error => console.error('[EMOJI MOVIE] Late-click completion failed:', error));
        return;
    }

    if (result.type !== 'ACCEPTED') {
        await interaction.reply({ content: 'That Emoji Movie Trivia choice is no longer valid.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.reply({
        content: `✅ Your answer is locked: **${escapeDiscordMarkdown(result.choice)}**.`,
        flags: MessageFlags.Ephemeral
    });
}

function completeEmojiMovieTransaction(gameKey) {
    const state = getActiveEmojiMovieStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };
    if (new Date(state.deadline_at).getTime() > Date.now()) return { type: 'NOT_DUE' };
    const now = new Date().toISOString();
    const changed = db.prepare(`
        UPDATE smash_emoji_movie_state
        SET status = 'COMPLETE', completed_at = @completed_at
        WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE'
    `).run({ game_key: gameKey, completed_at: now });
    return changed.changes === 1 ? { type: 'COMPLETE', state: getEmojiMovieStmt.get() } : { type: 'INACTIVE' };
}

async function finalizeEmojiMovieResult(gameKey) {
    const state = getEmojiMovieStmt.get();
    if (!state || state.game_key !== gameKey || state.status !== 'COMPLETE') return false;
    if (state.result_announced_at) return true;
    clearEmojiMovieTimer();
    const answers = getEmojiMovieAnswersStmt.all(gameKey);

    try {
        await queueEmojiMovieMessageOperation(async () => {
            const current = getEmojiMovieStmt.get();
            if (!current || current.game_key !== gameKey || current.result_announced_at) return;
            const { message } = await fetchEmojiMovieControlMessage(current);
            await message.edit({ embeds: [buildEmojiMovieResultEmbed(current, answers)], components: [] });
            markEmojiMovieResultAnnouncedStmt.run({
                game_key: gameKey,
                result_announced_at: new Date().toISOString()
            });
        });
    } catch (error) {
        console.error('[EMOJI MOVIE] Result announcement failed:', error);
        emojiMovieDeadlineTimer = setTimeout(() => {
            emojiMovieDeadlineTimer = null;
            finalizeEmojiMovieResult(gameKey).catch(retryError => console.error('[EMOJI MOVIE] Result retry failed:', retryError));
        }, 10000);
        return false;
    }

    const completed = getEmojiMovieStmt.get();
    const winners = answers.filter(answer => Number(answer.is_correct) === 1);
    console.log(`[EMOJI MOVIE COMPLETE] Answers: ${answers.length} | Correct: ${winners.length} | Movie: ${completed.movie_title}`);

    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({
            forceNew: false,
            reason: 'player/manual emoji movie complete; automatic schedule resumed'
        });
    }
    return true;
}

async function finishEmojiMovieIfDue(gameKey) {
    const result = completeEmojiMovieTransaction(gameKey);
    if (result.type === 'NOT_DUE') {
        const state = getActiveEmojiMovieStmt.get();
        if (state) armEmojiMovieTimer(state);
        return;
    }
    if (result.type === 'COMPLETE') await finalizeEmojiMovieResult(gameKey);
}

function armEmojiMovieTimer(state) {
    clearEmojiMovieTimer();
    if (!state || state.status !== 'ACTIVE') return;
    const deadline = new Date(state.deadline_at);
    const delay = Math.max(0, deadline.getTime() - Date.now());
    emojiMovieDeadlineTimer = setTimeout(() => {
        emojiMovieDeadlineTimer = null;
        finishEmojiMovieIfDue(state.game_key).catch(error => console.error('[EMOJI MOVIE] Completion failed:', error));
    }, delay);
}

async function createEmojiMovieInChannel(channelId, source = 'PLAYER') {
    if (!channelId) return { ok: false, reason: 'NO_CHANNELS' };
    if (emojiMovieSpawnInProgress || hasActiveSmashPuttActivity()) return { ok: false, reason: 'ACTIVE_ACTIVITY' };
    emojiMovieSpawnInProgress = true;
    let controlMessage = null;
    let candidate = null;
    let stateCreated = false;

    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) throw new Error(`Emoji Movie Trivia channel could not be found: ${channelId}`);

        candidate = selectEmojiMovieCandidate();
        const choiceData = buildEmojiMovieChoices(candidate.movie);
        const gameKey = `emoji-${Date.now()}-${randomInteger(100000, 999999)}`;
        const provisionalStartedAt = new Date();
        const provisionalDeadlineAt = new Date(provisionalStartedAt.getTime() + EMOJI_MOVIE_DURATION_MS);

        createEmojiMovieStmt.run({
            game_key: gameKey,
            channel_id: channel.id,
            control_message_id: '',
            source,
            movie_id: candidate.movie.id,
            movie_title: candidate.movie.title,
            emoji_clue: candidate.movie.clue,
            choices_json: JSON.stringify(choiceData.choices),
            correct_index: choiceData.correctIndex,
            started_at: provisionalStartedAt.toISOString(),
            deadline_at: provisionalDeadlineAt.toISOString()
        });
        stateCreated = true;

        const provisionalState = getActiveEmojiMovieStmt.get();
        controlMessage = await channel.send({
            embeds: [buildEmojiMovieActiveEmbed(provisionalState)],
            components: buildEmojiMovieButtons(provisionalState, false),
            allowedMentions: { parse: [] }
        });

        const startedAt = new Date(Number(controlMessage.createdTimestamp) || Date.now());
        const deadlineAt = new Date(startedAt.getTime() + EMOJI_MOVIE_DURATION_MS);
        db.prepare(`
            UPDATE smash_emoji_movie_state
            SET control_message_id = @control_message_id,
                started_at = @started_at,
                deadline_at = @deadline_at
            WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE'
        `).run({
            game_key: gameKey,
            control_message_id: controlMessage.id,
            started_at: startedAt.toISOString(),
            deadline_at: deadlineAt.toISOString()
        });

        const state = getActiveEmojiMovieStmt.get();
        await controlMessage.edit({
            embeds: [buildEmojiMovieActiveEmbed(state)],
            components: buildEmojiMovieButtons(state, false)
        });

        commitEmojiMovieCandidate(candidate);
        armEmojiMovieTimer(state);
        pauseSchedulerForActiveGame();

        console.log(
            `[EMOJI MOVIE] ${source} round started | Key ${state.game_key} | Channel ${state.channel_id} | ` +
            `45-second round | ${candidate.remainingBag.length} movies remain before reshuffle | no API calls`
        );
        return { ok: true, state };
    } catch (error) {
        console.error('[EMOJI MOVIE] Spawn failed:', error);
        if (stateCreated) {
            try {
                db.prepare(`
                    UPDATE smash_emoji_movie_state
                    SET status = 'CANCELLED', completed_at = @completed_at, result_announced_at = @completed_at
                    WHERE id = 1 AND status = 'ACTIVE'
                `).run({ completed_at: new Date().toISOString() });
            } catch (stateError) {
                console.error('[EMOJI MOVIE] Failed to clear partially-created state:', stateError);
            }
        }
        if (controlMessage) {
            try { await controlMessage.delete(); } catch (_) {}
        }
        return { ok: false, reason: 'TECHNICAL_ERROR', error };
    } finally {
        emojiMovieSpawnInProgress = false;
    }
}

function getEmojiMovieBuyCooldownStatus(userId) {
    const row = getEmojiMovieBuyCooldownStmt.get(userId);
    if (!row) return { available: true, remainingMs: 0 };
    const started = new Date(row.last_started_at);
    const next = Number.isNaN(started.getTime())
        ? new Date(row.next_available_at)
        : new Date(started.getTime() + EMOJI_MOVIE_BUY_COOLDOWN_MS);
    if (Number.isNaN(next.getTime()) || next.getTime() <= Date.now()) return { available: true, remainingMs: 0 };
    return { available: false, remainingMs: next.getTime() - Date.now() };
}

function formatEmojiMovieCooldown(remainingMs) {
    return `${Math.max(1, Math.ceil(Number(remainingMs || 0) / 60000))}m`;
}

function isEmojiMoviePurchaseBusy() {
    return Boolean(
        emojiMoviePurchaseInProgress ||
        emojiMovieSpawnInProgress ||
        bullseyeSpawnInProgress ||
        pictionaryPurchaseInProgress ||
        triviaPurchaseInProgress ||
        purchasePanelClickInProgress ||
        spawnInProgress || tournamentSpawnInProgress || battleSpawnInProgress ||
        doublesSpawnInProgress || vaultDropSpawnInProgress || auctionSpawnInProgress ||
        lotterySpawnInProgress || underdogSpawnInProgress || pictionarySpawnInProgress ||
        triviaSpawnInProgress || personalPurchaseInProgress || dealSpawnInProgress || safeSpawnInProgress ||
        hasActiveSmashPuttActivity()
    );
}

async function handlePurchasePanelEmojiMovieButton(interaction) {
    const storedMessageId = getSetting(PURCHASE_PANEL_MESSAGE_SETTING);
    if (!storedMessageId || interaction.message.id !== storedMessageId) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }
    if (interaction.channelId !== PURCHASE_PANEL_CHANNEL_ID) {
        await interaction.reply({ content: 'Emoji Movie Trivia is only available from the official SmashPutt Purchases panel.', flags: MessageFlags.Ephemeral });
        return;
    }
    const cooldown = getEmojiMovieBuyCooldownStatus(interaction.user.id);
    if (!cooldown.available) {
        await interaction.reply({ content: `Your next Emoji Movie Trivia activation is available in **${formatEmojiMovieCooldown(cooldown.remainingMs)}**.`, flags: MessageFlags.Ephemeral });
        return;
    }
    if (isEmojiMoviePurchaseBusy()) {
        await interaction.reply({ content: 'SmashPutt is busy with another activity right now. No cooldown was used.', flags: MessageFlags.Ephemeral });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    if (emojiMoviePurchaseInProgress) {
        await interaction.editReply({ content: 'Another Emoji Movie Trivia activation is already being processed. No cooldown was used.' });
        return;
    }

    emojiMoviePurchaseInProgress = true;
    let liveRoundStarted = false;
    try {
        const latestCooldown = getEmojiMovieBuyCooldownStatus(interaction.user.id);
        if (!latestCooldown.available) {
            await interaction.editReply({ content: `Your next Emoji Movie Trivia activation is available in **${formatEmojiMovieCooldown(latestCooldown.remainingMs)}**.` });
            return;
        }
        if (isEmojiMoviePurchaseBusy() && !emojiMoviePurchaseInProgress) {
            await interaction.editReply({ content: 'SmashPutt became busy before Emoji Movie Trivia could start. No cooldown was used.' });
            return;
        }
        pauseSchedulerForActiveGame();
        const result = await createEmojiMovieInChannel(PURCHASE_PANEL_CHANNEL_ID, 'PLAYER');
        if (!result.ok) {
            if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
                await scheduleNextAutoSpawn({ forceNew: false, reason: 'player Emoji Movie launch failed; automatic schedule resumed' });
            }
            await interaction.editReply({ content: 'Emoji Movie Trivia could not be started. No cooldown was used.' });
            return;
        }
        liveRoundStarted = true;
        const startedAt = new Date(result.state.started_at || Date.now());
        upsertEmojiMovieBuyCooldownStmt.run({
            user_id: interaction.user.id,
            last_started_at: startedAt.toISOString(),
            next_available_at: new Date(startedAt.getTime() + EMOJI_MOVIE_BUY_COOLDOWN_MS).toISOString()
        });
        const cleanName = getCleanDiscordName(interaction);
        console.log(`[EMOJI MOVIE BUY] ${cleanName} | Player-launched round live | Cooldown 15 minutes | no API calls`);
        await interaction.editReply({ content: '✅ Emoji Movie Trivia is live now. Your next activation is available in 15 minutes.' });
    } catch (error) {
        console.error('[EMOJI MOVIE BUY] Launch failed:', error);
        try {
            await interaction.editReply({
                content: liveRoundStarted
                    ? '✅ Emoji Movie Trivia is live now.'
                    : 'Emoji Movie Trivia could not be started because of a technical error. No cooldown was used.'
            });
        } catch (_) {}
    } finally {
        emojiMoviePurchaseInProgress = false;
    }
}

async function handleEmojiMovieCommand(interaction) {
    if (hasActiveSmashPuttActivity() || emojiMovieSpawnInProgress) {
        await interaction.reply({ content: 'SmashPutt is busy with another activity right now.', flags: MessageFlags.Ephemeral });
        return;
    }
    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    pauseSchedulerForActiveGame();
    const result = await createEmojiMovieInChannel(interaction.channelId, 'FORCE');
    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: false, reason: 'manual Emoji Movie launch failed; automatic schedule resumed' });
        }
        await interaction.editReply({ content: 'Emoji Movie Trivia could not be started.' });
        return;
    }
    await interaction.editReply({ content: '✅ Emoji Movie Trivia is live.' });
}

async function resumeEmojiMovieOnStartup() {
    clearEmojiMovieTimer();
    const state = getEmojiMovieStmt.get();
    if (!state || state.status !== 'ACTIVE') {
        console.log('No active SmashPutt Emoji Movie Trivia currently exists.');
        return;
    }

    if (new Date(state.deadline_at).getTime() <= Date.now()) {
        const result = completeEmojiMovieTransaction(state.game_key);
        if (result.type === 'COMPLETE') await finalizeEmojiMovieResult(state.game_key);
        return;
    }

    try {
        const { message } = await fetchEmojiMovieControlMessage(state);
        await message.edit({
            embeds: [buildEmojiMovieActiveEmbed(state)],
            components: buildEmojiMovieButtons(state, false)
        });
    } catch (error) {
        if (Number(error?.code) === 10008 || Number(error?.rawError?.code) === 10008) {
            const now = new Date().toISOString();
            db.prepare(`
                UPDATE smash_emoji_movie_state
                SET status = 'CANCELLED', completed_at = @completed_at, result_announced_at = @completed_at
                WHERE id = 1 AND game_key = @game_key AND status = 'ACTIVE'
            `).run({ game_key: state.game_key, completed_at: now });
            console.error('[EMOJI MOVIE] Missing control message cancelled on startup.');
            return;
        }
        console.error('[EMOJI MOVIE] Startup display recovery failed:', error);
    }

    pauseSchedulerForActiveGame();
    const current = getActiveEmojiMovieStmt.get();
    if (current) armEmojiMovieTimer(current);
    console.log(`[EMOJI MOVIE] Recovered active game ${state.game_key}.`);
}

// ============================================================
// SMASHPUTT BULLSEYE
// ============================================================

let bullseyeDeadlineTimer = null;
let bullseyeSpawnInProgress = false;
let bullseyeMessageQueue = Promise.resolve();

function clearBullseyeTimer() {
    if (bullseyeDeadlineTimer) {
        clearTimeout(bullseyeDeadlineTimer);
        bullseyeDeadlineTimer = null;
    }
}

function queueBullseyeMessageOperation(operation) {
    const run = bullseyeMessageQueue.then(operation, operation);
    bullseyeMessageQueue = run.catch(() => {});
    return run;
}

function getBullseyeTimeLeftText(deadlineAt) {
    const seconds = Math.max(0, Math.ceil((new Date(deadlineAt).getTime() - Date.now()) / 1000));
    return `${seconds}s`;
}

function buildBullseyeActiveEmbed(state) {
    const deadlineUnix = Math.floor(new Date(state.deadline_at).getTime() / 1000);
    return new EmbedBuilder()
        .setColor(0xE74C3C)
        .setTitle('🎯 SMASHPUTT BULLSEYE')
        .setDescription(
            `Pick any whole number from **1–100**.\n\n` +
            `Get as close as possible to the hidden target **WITHOUT GOING OVER**.\n` +
            `🏆 Closest winner: **+${BULLSEYE_CLOSEST_PRIZE} 💥 Smash Score**\n` +
            `🎯 Exact Bullseye: **+${BULLSEYE_EXACT_PRIZE} 💥 Smash Score**\n\n` +
            `Your number is private and locked once submitted.\n` +
            `⏱️ **TIME LEFT:** <t:${deadlineUnix}:R>`
        )
        .setImage(BULLSEYE_BANNER_URL);
}

function buildBullseyeEnterRow(disabled = false) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(BULLSEYE_ENTER_BUTTON_ID).setLabel('ENTER NUMBER').setEmoji('🎯').setStyle(ButtonStyle.Success).setDisabled(disabled)
    );
}

function buildBullseyeNumberModal(gameKey) {
    const input = new TextInputBuilder()
        .setCustomId(BULLSEYE_NUMBER_INPUT_ID)
        .setLabel('Your number (1–100)')
        .setPlaceholder('Enter one whole number from 1 to 100')
        .setStyle(TextInputStyle.Short)
        .setRequired(true).setMinLength(1).setMaxLength(3);
    return new ModalBuilder().setCustomId(`${BULLSEYE_MODAL_PREFIX}${gameKey}`).setTitle('SmashPutt Bullseye')
        .addComponents(new ActionRowBuilder().addComponents(input));
}

function buildBullseyeResultEmbed(state, entries) {
    const target = Number(state.target_number);
    const valid = entries.filter(entry => Number(entry.chosen_number) <= target);
    const best = valid.length ? Math.max(...valid.map(entry => Number(entry.chosen_number))) : null;
    const exact = best === target;
    const lines = entries.length ? entries.slice().sort((a,b) => Number(b.chosen_number)-Number(a.chosen_number) || a.id-b.id).map(entry => {
        const number = Number(entry.chosen_number);
        const winner = best !== null && number === best;
        const over = number > target;
        const name = escapeDiscordMarkdown(entry.clean_name || entry.display_name || 'Player');
        const suffix = over ? ' ❌ OVER' : winner ? (exact ? ` 🎯 **BULLSEYE! +${BULLSEYE_EXACT_PRIZE} 💥 Smash Score**` : ` 🏆 **+${BULLSEYE_CLOSEST_PRIZE} 💥 Smash Score**`) : '';
        return `${winner ? (exact ? '🎯' : '🏆') : '•'} **${name} — ${number}**${suffix}`;
    }).join('\n') : '*No numbers were submitted.*';
    const headline = exact ? '🎯 **BULLSEYE!**' : best === null ? '❌ **EVERYONE WENT OVER — NO WINNER**' : `🏆 **Closest without going over: ${best}**`;
    return new EmbedBuilder().setColor(exact ? 0xF1C40F : best === null ? 0x747F8D : 0x2ECC71)
        .setTitle('🎯 BULLSEYE — RESULTS')
        .setDescription(`🎯 **TARGET: ${target}**\n\n${headline}\n\n${lines}`)
        .setImage(BULLSEYE_BANNER_URL);
}

async function fetchBullseyeControlMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) throw new Error(`Bullseye channel could not be found: ${state.channel_id}`);
    return { channel, message: await channel.messages.fetch(state.control_message_id) };
}

const submitBullseyeNumberTransaction = db.transaction(({ gameKey, userId, displayName, cleanName, chosenNumber }) => {
    const state = getActiveBullseyeStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };
    if (new Date(state.deadline_at).getTime() <= Date.now()) return { type: 'EXPIRED' };
    const existing = getBullseyeEntryStmt.get(gameKey, userId);
    if (existing) return { type: 'ALREADY', entry: existing };
    if (!Number.isInteger(chosenNumber) || chosenNumber < 1 || chosenNumber > 100) return { type: 'INVALID' };
    insertBullseyeEntryStmt.run({ game_key: gameKey, user_id: userId, display_name: displayName, clean_name: cleanName, chosen_number: chosenNumber, entered_at: new Date().toISOString() });
    return { type: 'ACCEPTED', chosenNumber };
});

async function handleBullseyeEnterButton(interaction) {
    const state = getActiveBullseyeStmt.get();
    if (!state) return interaction.reply({ content: 'This Bullseye round has ended.', flags: MessageFlags.Ephemeral });
    if (new Date(state.deadline_at).getTime() <= Date.now()) {
        await interaction.reply({ content: 'This Bullseye entry window has ended.', flags: MessageFlags.Ephemeral });
        finishBullseyeIfDue(state.game_key).catch(error => console.error('[BULLSEYE] Late-click completion failed:', error));
        return;
    }
    const existing = getBullseyeEntryStmt.get(state.game_key, interaction.user.id);
    if (existing) return interaction.reply({ content: `Your Bullseye number is already locked as **${existing.chosen_number}**.`, flags: MessageFlags.Ephemeral });
    await interaction.showModal(buildBullseyeNumberModal(state.game_key));
}

async function handleBullseyeNumberModal(interaction) {
    const gameKey = interaction.customId.substring(BULLSEYE_MODAL_PREFIX.length);
    const raw = String(interaction.fields.getTextInputValue(BULLSEYE_NUMBER_INPUT_ID) || '').trim();
    if (!/^\d{1,3}$/.test(raw)) return interaction.reply({ content: 'Enter one whole number from **1 to 100**.', flags: MessageFlags.Ephemeral });
    const chosenNumber = Number(raw);
    const displayName = interaction.member?.displayName || interaction.user.globalName || interaction.user.username;
    const result = submitBullseyeNumberTransaction({ gameKey, userId: interaction.user.id, displayName, cleanName: getCleanDiscordName(interaction), chosenNumber });
    if (result.type === 'ACCEPTED') return interaction.reply({ content: `✅ Your Bullseye number is locked: **${chosenNumber}**`, flags: MessageFlags.Ephemeral });
    if (result.type === 'ALREADY') return interaction.reply({ content: `Your Bullseye number is already locked as **${result.entry.chosen_number}**.`, flags: MessageFlags.Ephemeral });
    if (result.type === 'INVALID') return interaction.reply({ content: 'Enter one whole number from **1 to 100**.', flags: MessageFlags.Ephemeral });
    await interaction.reply({ content: 'This Bullseye round is no longer accepting numbers.', flags: MessageFlags.Ephemeral });
    if (result.type === 'EXPIRED') finishBullseyeIfDue(gameKey).catch(error => console.error('[BULLSEYE] Deadline completion failed:', error));
}

const completeBullseyeTransaction = db.transaction(gameKey => {
    const state = getActiveBullseyeStmt.get();
    if (!state || state.game_key !== gameKey) return { type: 'INACTIVE' };
    if (new Date(state.deadline_at).getTime() > Date.now()) return { type: 'NOT_DUE' };
    const now = new Date().toISOString();
    const completion = db.prepare(`UPDATE smash_bullseye_state SET status='COMPLETE', completed_at=@completed_at WHERE id=1 AND game_key=@game_key AND status='ACTIVE'`).run({ game_key: gameKey, completed_at: now });
    if (completion.changes !== 1) return { type: 'INACTIVE' };
    const completed = getBullseyeStmt.get();
    const entries = getBullseyeEntriesStmt.all(gameKey);
    const target = Number(completed.target_number);
    const eligible = entries.filter(entry => Number(entry.chosen_number) <= target);
    const best = eligible.length ? Math.max(...eligible.map(entry => Number(entry.chosen_number))) : null;
    const exact = best === target;
    const reward = best === null ? 0 : exact ? BULLSEYE_EXACT_PRIZE : BULLSEYE_CLOSEST_PRIZE;
    const winners = best === null ? [] : eligible.filter(entry => Number(entry.chosen_number) === best);
    for (const winner of winners) {
        ensurePlayer(winner.user_id, winner.display_name);
        addSmashScoreStmt.run({ user_id: winner.user_id, display_name: winner.display_name, amount: reward, updated_at: now });
        insertScoreTransactionStmt.run({ user_id: winner.user_id, display_name: winner.display_name, transaction_type: 'ADD', amount: reward, reason: `SmashPutt Bullseye ${exact ? 'Exact' : 'Closest'}: target ${target}, pick ${best}`, admin_user_id: winner.user_id, admin_display_name: winner.display_name, created_at: now });
        db.prepare(`UPDATE smash_bullseye_entries SET reward_amount=@reward_amount, reward_processed_at=@reward_processed_at WHERE game_key=@game_key AND user_id=@user_id AND reward_processed_at IS NULL`).run({ reward_amount: reward, reward_processed_at: now, game_key: gameKey, user_id: winner.user_id });
    }
    return { type:'COMPLETE' };
});

async function finalizeBullseyeResult(gameKey) {
    const state = getBullseyeStmt.get();
    if (!state || state.game_key !== gameKey || state.status !== 'COMPLETE' || state.result_announced_at) return false;
    clearBullseyeTimer();
    try {
        await queueBullseyeMessageOperation(async () => {
            const current = getBullseyeStmt.get();
            if (!current || current.game_key !== gameKey || current.result_announced_at) return;
            const entries = getBullseyeEntriesStmt.all(gameKey);
            try {
                const { message } = await fetchBullseyeControlMessage(current);
                await message.edit({ embeds:[buildBullseyeResultEmbed(current, entries)], components:[] });
            } catch (error) {
                if (Number(error?.code) !== 10008 && Number(error?.rawError?.code) !== 10008) throw error;
            }
            markBullseyeResultAnnouncedStmt.run({ game_key:gameKey, result_announced_at:new Date().toISOString() });
        });
    } catch (error) {
        console.error('[BULLSEYE] Result announcement failed:', error);
        setTimeout(() => finalizeBullseyeResult(gameKey).catch(retryError => console.error('[BULLSEYE] Result retry failed:', retryError)), 3000);
        return false;
    }
    const completed = getBullseyeStmt.get();
    const entries = getBullseyeEntriesStmt.all(gameKey);
    const target = Number(completed.target_number);
    const eligible = entries.filter(entry => Number(entry.chosen_number) <= target);
    const best = eligible.length ? Math.max(...eligible.map(entry => Number(entry.chosen_number))) : null;
    console.log(`[BULLSEYE COMPLETE] Entries: ${entries.length} | Target: ${target} | Best: ${best === null ? 'NONE' : best} | Exact: ${best === target ? 'YES' : 'NO'}`);
    try { await updateLeaderboard(); } catch (error) { console.error('[BULLSEYE] Leaderboard refresh failed:', error); }
    if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) await scheduleNextAutoSpawn({ forceNew:false, reason:'player/manual Bullseye complete; automatic schedule resumed' });
    return true;
}

async function finishBullseyeIfDue(gameKey) {
    const result = completeBullseyeTransaction(gameKey);
    if (result.type === 'NOT_DUE') return armBullseyeTimer(getActiveBullseyeStmt.get());
    if (result.type === 'COMPLETE') await finalizeBullseyeResult(gameKey);
}

function armBullseyeTimer(state) {
    clearBullseyeTimer();
    if (!state || state.status !== 'ACTIVE') return;
    const remaining = Math.max(0, new Date(state.deadline_at).getTime() - Date.now());
    bullseyeDeadlineTimer = setTimeout(() => {
        bullseyeDeadlineTimer = null;
        finishBullseyeIfDue(state.game_key).catch(error => console.error('[BULLSEYE] Completion failed:', error));
    }, Math.min(remaining + 25, 2_147_000_000));
}

async function createBullseyeInChannel(channelId, source='PLAYER') {
    if (!channelId) return { ok:false, reason:'NO_CHANNEL' };
    if (bullseyeSpawnInProgress || hasActiveSmashPuttActivity()) return { ok:false, reason:'ACTIVE_ACTIVITY' };
    bullseyeSpawnInProgress = true;
    let controlMessage = null;
    try {
        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) throw new Error(`Bullseye channel could not be found: ${channelId}`);
        const targetNumber = randomInteger(1,100);
        const provisionalDeadlineAt = new Date(Date.now()+BULLSEYE_DURATION_MS);
        controlMessage = await channel.send({ embeds:[buildBullseyeActiveEmbed({deadline_at:provisionalDeadlineAt.toISOString()})], components:[buildBullseyeEnterRow(false)], allowedMentions:{parse:[]} });
        const startedAt = new Date(Number(controlMessage.createdTimestamp) || Date.now());
        const deadlineAt = new Date(startedAt.getTime()+BULLSEYE_DURATION_MS);
        createBullseyeStmt.run({ game_key:controlMessage.id, channel_id:channel.id, control_message_id:controlMessage.id, source, target_number:targetNumber, started_at:startedAt.toISOString(), deadline_at:deadlineAt.toISOString() });
        const state = getActiveBullseyeStmt.get();
        await controlMessage.edit({ embeds:[buildBullseyeActiveEmbed(state)], components:[buildBullseyeEnterRow(false)] });
        pauseSchedulerForActiveGame();
        armBullseyeTimer(state);
        console.log(`[BULLSEYE] ${source} round started | Key ${state.game_key} | Channel ${state.channel_id} | 45-second entry window.`);
        return { ok:true, state };
    } catch (error) {
        console.error('[BULLSEYE] Spawn failed:', error);
        if (controlMessage) try { await controlMessage.delete(); } catch (_) {}
        return { ok:false, reason:'ERROR', error };
    } finally { bullseyeSpawnInProgress=false; }
}

function getBullseyeBuyCooldownStatus(userId) {
    const row = getBullseyeBuyCooldownStmt.get(userId);
    if (!row) return { available:true, remainingMs:0 };
    const started = new Date(row.last_started_at);
    const effectiveNext = Number.isNaN(started.getTime()) ? new Date(row.next_available_at) : new Date(started.getTime()+BULLSEYE_BUY_COOLDOWN_MS);
    const remainingMs = effectiveNext.getTime()-Date.now();
    return { available:remainingMs<=0, remainingMs:Math.max(0,remainingMs) };
}
function formatBullseyeCooldown(ms) { const m=Math.ceil(ms/60000); return `${m} minute${m===1?'':'s'}`; }

async function handlePurchasePanelBullseyeButton(interaction) {
    const cooldown = getBullseyeBuyCooldownStatus(interaction.user.id);
    if (!cooldown.available) return interaction.reply({ content:`Your next Bullseye activation is available in **${formatBullseyeCooldown(cooldown.remainingMs)}**.`, flags:MessageFlags.Ephemeral });
    if (hasActiveSmashPuttActivity() || bullseyeSpawnInProgress) return interaction.reply({ content:'SmashPutt is busy with another activity right now. No cooldown was used.', flags:MessageFlags.Ephemeral });
    await interaction.deferReply({ flags:MessageFlags.Ephemeral });
    const result = await createBullseyeInChannel(PURCHASE_PANEL_CHANNEL_ID,'PLAYER');
    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) await scheduleNextAutoSpawn({ forceNew:false, reason:'player Bullseye launch failed; automatic schedule resumed' });
        return interaction.editReply({ content:'Bullseye could not be started. No cooldown was used.' });
    }
    const startedAt = new Date(result.state.started_at);
    upsertBullseyeBuyCooldownStmt.run({ user_id:interaction.user.id, last_started_at:startedAt.toISOString(), next_available_at:new Date(startedAt.getTime()+BULLSEYE_BUY_COOLDOWN_MS).toISOString() });
    console.log(`[BULLSEYE BUY] ${getCleanDiscordName(interaction)} | Player-launched round live | Cooldown 15 minutes`);
    await interaction.editReply({ content:'✅ Bullseye is live now. Your 15-minute activation cooldown was recorded.' });
}

async function handleBullseyeCommand(interaction) {
    if (hasActiveSmashPuttActivity() || bullseyeSpawnInProgress) return interaction.reply({ content:'A SmashPutt activity is already live.', flags:MessageFlags.Ephemeral });
    await interaction.deferReply({ flags:MessageFlags.Ephemeral });
    const result = await createBullseyeInChannel(interaction.channelId,'FORCE');
    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) await scheduleNextAutoSpawn({ forceNew:false, reason:'manual Bullseye launch failed; automatic schedule resumed' });
        return interaction.editReply({ content:'Bullseye could not be started.' });
    }
    await interaction.editReply({ content:'✅ Bullseye is live.' });
}

async function resumeBullseyeOnStartup() {
    clearBullseyeTimer();
    const state = getBullseyeStmt.get();
    if (!state || state.status !== 'ACTIVE') { console.log('No active SmashPutt Bullseye currently exists.'); return; }
    if (new Date(state.deadline_at).getTime() <= Date.now()) return finishBullseyeIfDue(state.game_key);
    try {
        const { message } = await fetchBullseyeControlMessage(state);
        await message.edit({ embeds:[buildBullseyeActiveEmbed(state)], components:[buildBullseyeEnterRow(false)] });
    } catch (error) {
        if (Number(error?.code) === 10008 || Number(error?.rawError?.code) === 10008) {
            const now = new Date().toISOString();
            db.prepare(`UPDATE smash_bullseye_state SET status='CANCELLED', completed_at=@completed_at, result_announced_at=@completed_at WHERE id=1 AND game_key=@game_key AND status='ACTIVE'`).run({ game_key:state.game_key, completed_at:now });
            console.error('[BULLSEYE] Missing control message cancelled on startup.');
            return;
        }
        console.error('[BULLSEYE] Startup display recovery failed:', error);
    }
    pauseSchedulerForActiveGame();
    const current = getActiveBullseyeStmt.get();
    if (current) armBullseyeTimer(current);
    console.log(`[BULLSEYE] Recovered active game ${state.game_key}.`);
}

