// WEEKLY SMASHPUTT RACE QUERIES
// ============================================================

const getWeeklySmashPuttStandingsStmt = db.prepare(`
    SELECT
        gh.winner_user_id AS user_id,
        COALESCE(p.display_name, MAX(gh.winner_display_name), 'Player') AS display_name,
        COUNT(*) AS holes,
        MAX(gh.completed_at) AS reached_at
    FROM game_history gh
    LEFT JOIN players p
      ON p.user_id = gh.winner_user_id
    WHERE gh.completed_at >= ?
      AND gh.completed_at < ?
      AND gh.winner_user_id IS NOT NULL
    GROUP BY gh.winner_user_id, p.display_name
    ORDER BY holes DESC, reached_at ASC, gh.winner_user_id ASC
`);

