function randomInteger(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomItem(array) {
    if (!array.length) return null;
    return array[randomInteger(0, array.length - 1)];
}

function randomDistinctItems(array, count) {
    if (array.length < count) {
        throw new Error(
            `Not enough reward items to create ${count} Mystery Pick options. ` +
            `Available: ${array.length}`
        );
    }

    const shuffled = [...array];

    for (let index = shuffled.length - 1; index > 0; index--) {
        const swapIndex = randomInteger(0, index);

        [
            shuffled[index],
            shuffled[swapIndex]
        ] = [
            shuffled[swapIndex],
            shuffled[index]
        ];
    }

    return shuffled.slice(0, count);
}

function isImageFile(filename) {
    const extension = path.extname(filename).toLowerCase();

    return [
        '.png',
        '.jpg',
        '.jpeg',
        '.webp'
    ].includes(extension);
}

function getCentralTimeString(date = new Date()) {
    return new Intl.DateTimeFormat('en-US', {
        timeZone: CENTRAL_TIME_ZONE,
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        second: '2-digit',
        hour12: true,
        timeZoneName: 'short'
    }).format(date);
}

function getCentralDateTimeParts(date = new Date()) {
    const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: CENTRAL_TIME_ZONE,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hourCycle: 'h23'
    });

    const values = {};

    for (const part of formatter.formatToParts(date)) {
        if (part.type !== 'literal') {
            values[part.type] = part.value;
        }
    }

    return {
        year: Number(values.year),
        month: Number(values.month),
        day: Number(values.day),
        hour: Number(values.hour),
        minute: Number(values.minute),
        second: Number(values.second)
    };
}

function formatDateKey(year, month, day) {
    return (
        `${String(year).padStart(4, '0')}-` +
        `${String(month).padStart(2, '0')}-` +
        `${String(day).padStart(2, '0')}`
    );
}

function addDaysToDateKey(dateKey, days) {
    const [year, month, day] =
        dateKey.split('-').map(Number);

    const date = new Date(
        Date.UTC(year, month - 1, day)
    );

    date.setUTCDate(
        date.getUTCDate() + days
    );

    return formatDateKey(
        date.getUTCFullYear(),
        date.getUTCMonth() + 1,
        date.getUTCDate()
    );
}

function getCentralWeekStartKey(date = new Date()) {
    const parts =
        getCentralDateTimeParts(date);

    const localDate = new Date(
        Date.UTC(
            parts.year,
            parts.month - 1,
            parts.day
        )
    );

    localDate.setUTCDate(
        localDate.getUTCDate() -
        localDate.getUTCDay()
    );

    return formatDateKey(
        localDate.getUTCFullYear(),
        localDate.getUTCMonth() + 1,
        localDate.getUTCDate()
    );
}

function centralDateKeyToUtcDate(dateKey) {
    const [year, month, day] =
        dateKey.split('-').map(Number);

    const desiredLocalAsUtc =
        Date.UTC(year, month - 1, day, 0, 0, 0);

    let guess =
        desiredLocalAsUtc;

    for (let attempt = 0; attempt < 4; attempt++) {
        const actual =
            getCentralDateTimeParts(
                new Date(guess)
            );

        const actualLocalAsUtc =
            Date.UTC(
                actual.year,
                actual.month - 1,
                actual.day,
                actual.hour,
                actual.minute,
                actual.second
            );

        const adjustment =
            desiredLocalAsUtc -
            actualLocalAsUtc;

        guess += adjustment;

        if (adjustment === 0) {
            break;
        }
    }

    return new Date(guess);
}

function getCentralWeekWindow(date = new Date()) {
    const startKey =
        getCentralWeekStartKey(date);

    const endKey =
        addDaysToDateKey(
            startKey,
            7
        );

    return {
        startKey,
        endKey,
        startDate:
            centralDateKeyToUtcDate(
                startKey
            ),
        endDate:
            centralDateKeyToUtcDate(
                endKey
            )
    };
}

function escapeXml(value) {
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
}

function escapeDiscordMarkdown(value) {
    return String(value)
        .replace(/\\/g, '\\\\')
        .replace(/([*_~`>|])/g, '\\$1');
}

function getSetting(key) {
    const row = getSettingStmt.get(key);
    return row ? row.setting_value : null;
}

function setSetting(key, value) {
    setSettingStmt.run(key, String(value));
}

function getPersonalPurchasesEnabled() {
    const stored = getSetting(PERSONAL_PURCHASES_SETTING);

    if (
        stored === null ||
        stored === undefined ||
        stored === ''
    ) {
        return true;
    }

    return String(stored).toUpperCase() === 'ON';
}

function setPersonalPurchasesEnabled(enabled) {
    setSetting(
        PERSONAL_PURCHASES_SETTING,
        enabled ? 'ON' : 'OFF'
    );
}

