// ============================================================
// PERSISTENT SPAWN CHANNEL SETTINGS
// ============================================================

function getActiveSpawnChannelIds() {
    const raw = getSetting(SPAWN_CHANNELS_SETTING);

    if (
        raw === null ||
        raw === undefined ||
        raw === ''
    ) {
        return [...DEFAULT_SPAWN_CHANNEL_IDS];
    }

    try {
        const parsed = JSON.parse(raw);

        if (!Array.isArray(parsed)) {
            throw new Error(
                'Stored spawn channel setting is not an array.'
            );
        }

        return [...new Set(
            parsed
                .filter(
                    value =>
                        typeof value === 'string'
                )
                .map(
                    value =>
                        value.trim()
                )
                .filter(Boolean)
        )];
    } catch (error) {
        console.error(
            '[SPAWN CHANNELS] Invalid stored channel list. Falling back to defaults:',
            error
        );

        return [...DEFAULT_SPAWN_CHANNEL_IDS];
    }
}

function setActiveSpawnChannelIds(channelIds) {
    const cleaned = [...new Set(
        channelIds
            .map(
                value =>
                    String(value).trim()
            )
            .filter(Boolean)
    )];

    setSetting(
        SPAWN_CHANNELS_SETTING,
        JSON.stringify(cleaned)
    );

    return cleaned;
}

async function validateSelectableSpawnChannel(
    interaction,
    channel
) {
    if (
        !channel ||
        channel.guildId !== MAIN_SERVER_ID ||
        !channel.isTextBased() ||
        (
            typeof channel.isThread === 'function' &&
            channel.isThread()
        )
    ) {
        return {
            ok: false,
            message:
                'Choose a regular text channel from this server.'
        };
    }

    let botMember =
        interaction.guild.members.me;

    if (!botMember) {
        try {
            botMember =
                await interaction.guild.members.fetchMe();
        } catch (_) {
            botMember = null;
        }
    }

    if (!botMember) {
        return {
            ok: false,
            message:
                'I could not verify the bot permissions for that channel.'
        };
    }

    const permissions =
        channel.permissionsFor(
            botMember
        );

    const requiredPermissions = [
        PermissionFlagsBits.ViewChannel,
        PermissionFlagsBits.SendMessages,
        PermissionFlagsBits.EmbedLinks,
        PermissionFlagsBits.AttachFiles
    ];

    if (
        !permissions ||
        !requiredPermissions.every(
            permission =>
                permissions.has(permission)
        )
    ) {
        return {
            ok: false,
            message:
                'SmashPutt needs View Channel, Send Messages, Embed Links, and Attach Files permissions in that channel.'
        };
    }

    return { ok: true };
}

async function handleSpawnChannelCommand(
    interaction,
    subcommand
) {
    const frequency =
        getSchedulerFrequency();

    const currentIds =
        getActiveSpawnChannelIds();

    if (subcommand === 'channels') {
        const channelText =
            currentIds.length
                ? currentIds
                    .map(
                        id =>
                            `• <#${id}>`
                    )
                    .join('\n')
                : '*No active SmashPutt spawn channels.*';

        const nextSpawn =
            getStoredNextSpawnDate();

        await interaction.reply({
            content:
                `💥 **ACTIVE SMASHPUTT CHANNELS**\n\n` +
                `${channelText}\n\n` +
                `Frequency: **${frequency}**` +
                (
                    nextSpawn &&
                    frequency !== 'OFF'
                        ? `\nNext scheduled spawn: **${getCentralTimeString(nextSpawn)}**`
                        : ''
                ),
            flags:
                MessageFlags.Ephemeral,
            allowedMentions: {
                parse: []
            }
        });

        return;
    }

    const channel =
        interaction.options.getChannel(
            'channel',
            true
        );

    const validation =
        await validateSelectableSpawnChannel(
            interaction,
            channel
        );

    if (!validation.ok) {
        await interaction.reply({
            content:
                validation.message,
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (subcommand === 'onlychannel') {
        setActiveSpawnChannelIds([
            channel.id
        ]);

        console.log(
            `[SPAWN CHANNELS] ${interaction.user.tag} set ONLY channel ${channel.id}.`
        );

        await interaction.reply({
            content:
                `✅ <#${channel.id}> is now the **only** SmashPutt spawn channel.\n` +
                `Frequency remains **${frequency}**. Any already-scheduled spawn time is unchanged.`,
            flags:
                MessageFlags.Ephemeral,
            allowedMentions: {
                parse: []
            }
        });

        return;
    }

    if (subcommand === 'addchannel') {
        if (
            currentIds.includes(
                channel.id
            )
        ) {
            await interaction.reply({
                content:
                    `<#${channel.id}> is already an active SmashPutt spawn channel.`,
                flags:
                    MessageFlags.Ephemeral,
                allowedMentions: {
                    parse: []
                }
            });

            return;
        }

        const updated =
            setActiveSpawnChannelIds([
                ...currentIds,
                channel.id
            ]);

        console.log(
            `[SPAWN CHANNELS] ${interaction.user.tag} added channel ${channel.id}. Active: ${updated.join(', ')}`
        );

        await interaction.reply({
            content:
                `✅ Added <#${channel.id}> to the SmashPutt spawn list.\n` +
                `Active spawn channels: **${updated.length}**\n` +
                `Frequency remains **${frequency}**. Any already-scheduled spawn time is unchanged.`,
            flags:
                MessageFlags.Ephemeral,
            allowedMentions: {
                parse: []
            }
        });

        return;
    }

    if (subcommand === 'removechannel') {
        if (
            !currentIds.includes(
                channel.id
            )
        ) {
            await interaction.reply({
                content:
                    `<#${channel.id}> is not currently an active SmashPutt spawn channel.`,
                flags:
                    MessageFlags.Ephemeral,
                allowedMentions: {
                    parse: []
                }
            });

            return;
        }

        if (
            currentIds.length === 1 &&
            frequency !== 'OFF'
        ) {
            await interaction.reply({
                content:
                    'You cannot remove the last active SmashPutt channel while automatic spawning is enabled. ' +
                    'Add another channel first, use `/smashputt onlychannel`, or turn frequency OFF.',
                flags:
                    MessageFlags.Ephemeral
            });

            return;
        }

        const updated =
            setActiveSpawnChannelIds(
                currentIds.filter(
                    id =>
                        id !== channel.id
                )
            );

        console.log(
            `[SPAWN CHANNELS] ${interaction.user.tag} removed channel ${channel.id}. Active: ${updated.join(', ') || 'NONE'}`
        );

        await interaction.reply({
            content:
                `✅ Removed <#${channel.id}> from future SmashPutt spawns.\n` +
                `Active spawn channels: **${updated.length}**\n` +
                `Frequency remains **${frequency}**. Any currently active SmashPutt activity is unaffected.`,
            flags:
                MessageFlags.Ephemeral,
            allowedMentions: {
                parse: []
            }
        });
    }
}

// ============================================================
// COURSE / FILE UTILITIES
// ============================================================

function cleanHoleCourseFolderName(folderName) {
    const separator = ' - ';
    const firstSeparator =
        folderName.indexOf(separator);

    if (firstSeparator === -1) {
        return folderName;
    }

    return folderName
        .substring(
            firstSeparator +
            separator.length
        )
        .trim();
}

function cleanBallCourseFolderName(folderName) {
    return folderName
        .replace(
            /^\s*\d+\s*-\s*/,
            ''
        )
        .trim();
}

function getHoleNumberFromFilename(filename) {
    if (!isImageFile(filename)) {
        return null;
    }

    const extension =
        path.extname(filename);

    const baseName =
        path.basename(
            filename,
            extension
        );

    if (!/^\d+$/.test(baseName)) {
        return null;
    }

    const number =
        parseInt(
            baseName,
            10
        );

    if (
        number < 1 ||
        number > 18
    ) {
        return null;
    }

    return number;
}

function getBallNumberFromFilename(filename) {
    const extension =
        path.extname(filename);

    const baseName =
        path.basename(
            filename,
            extension
        );

    const number =
        parseInt(
            baseName,
            10
        );

    if (
        Number.isNaN(number) ||
        number < 1
    ) {
        return null;
    }

    return number;
}

function prettifyFilename(filename) {
    const extension =
        path.extname(filename);

    let name =
        path.basename(
            filename,
            extension
        );

    name =
        name.replace(
            /[_\-\s]*8k$/i,
            ''
        );

    name =
        name.replace(
            /[_\-]+/g,
            ' '
        );

    name =
        name.replace(
            /([a-z])([A-Z])/g,
            '$1 $2'
        );

    name =
        name.replace(
            /\s+/g,
            ' '
        ).trim();

    return name;
}

function getPutterDisplayName(filename) {
    const cleanedName =
        prettifyFilename(
            filename
        );

    if (
        /\bputter\b/i.test(
            cleanedName
        )
    ) {
        return cleanedName;
    }

    return `${cleanedName} Putter`;
}

function getBaseCourseName(courseDisplay) {
    return courseDisplay
        .replace(
            /\s+-\s+(Easy|Hard)$/i,
            ''
        )
        .trim();
}

function getDifficulty(courseDisplay) {
    if (
        /\s+-\s+Easy$/i.test(
            courseDisplay
        )
    ) {
        return 'Easy';
    }

    if (
        /\s+-\s+Hard$/i.test(
            courseDisplay
        )
    ) {
        return 'Hard';
    }

    return null;
}

// ============================================================
// NORMAL RESULT ROLL
// ============================================================

function rollGolfResult() {
    const roll =
        randomInteger(
            1,
            200
        );

    if (roll === 1) {
        return {
            key:
                'HOLE_IN_ONE',
            ...RESULT_CONFIG.HOLE_IN_ONE
        };
    }

    if (roll <= 4) {
        return {
            key:
                'BIRDIE',
            ...RESULT_CONFIG.BIRDIE
        };
    }

    if (roll <= 103) {
        return {
            key:
                'PAR',
            ...RESULT_CONFIG.PAR
        };
    }

    if (roll <= 180) {
        return {
            key:
                'BOGEY',
            ...RESULT_CONFIG.BOGEY
        };
    }

    return {
        key:
            'STROKE_OUT',
        ...RESULT_CONFIG.STROKE_OUT
    };
}

// ============================================================
// PERSONAL REWARD ROLL
// ============================================================

function rollPersonalRewardResult() {
    const roll =
        randomInteger(
            1,
            200
        );

    if (roll === 1) {
        return {
            rarity:
                'LEGENDARY',
            itemType:
                'legendary',
            color:
                0xF39C12
        };
    }

    if (roll <= 4) {
        return {
            rarity:
                'RARE',
            itemType:
                'putter',
            color:
                0x3498DB
        };
    }

    return {
        rarity:
            'COMMON',
        itemType:
            'common',
        color:
            0x2ECC71
    };
}

