// ============================================================

function scanHoleImages() {
    const holes = [];

    const courseFolders =
        fs.readdirSync(
            HOLE_IMAGES_FOLDER,
            {
                withFileTypes: true
            }
        );

    for (
        const courseEntry
        of courseFolders
    ) {
        if (
            !courseEntry.isDirectory()
        ) {
            continue;
        }

        const courseFolderName =
            courseEntry.name;

        const courseFolderPath =
            path.join(
                HOLE_IMAGES_FOLDER,
                courseFolderName
            );

        const courseDisplayName =
            cleanHoleCourseFolderName(
                courseFolderName
            );

        const files =
            fs.readdirSync(
                courseFolderPath,
                {
                    withFileTypes: true
                }
            );

        for (
            const fileEntry
            of files
        ) {
            if (
                !fileEntry.isFile()
            ) {
                continue;
            }

            const holeNumber =
                getHoleNumberFromFilename(
                    fileEntry.name
                );

            if (
                holeNumber === null
            ) {
                continue;
            }

            holes.push({
                courseFolder:
                    courseFolderName,
                courseDisplay:
                    courseDisplayName,
                holeNumber,
                filename:
                    fileEntry.name,
                fullPath:
                    path.join(
                        courseFolderPath,
                        fileEntry.name
                    )
            });
        }
    }

    return holes;
}

function scanBallImages() {
    const balls = [];

    const courseFolders =
        fs.readdirSync(
            BALL_IMAGES_FOLDER,
            {
                withFileTypes: true
            }
        );

    for (
        const courseEntry
        of courseFolders
    ) {
        if (
            !courseEntry.isDirectory()
        ) {
            continue;
        }

        const courseFolderName =
            courseEntry.name;

        const courseDisplayName =
            cleanBallCourseFolderName(
                courseFolderName
            );

        const coursePath =
            path.join(
                BALL_IMAGES_FOLDER,
                courseFolderName
            );

        const files =
            fs.readdirSync(
                coursePath,
                {
                    withFileTypes: true
                }
            );

        for (
            const fileEntry
            of files
        ) {
            if (
                !fileEntry.isFile() ||
                !isImageFile(
                    fileEntry.name
                )
            ) {
                continue;
            }

            const ballNumber =
                getBallNumberFromFilename(
                    fileEntry.name
                );

            if (
                ballNumber === null
            ) {
                continue;
            }

            const relativeId =
                path.join(
                    courseFolderName,
                    fileEntry.name
                )
                .replace(
                    /\\/g,
                    '/'
                );

            balls.push({
                type:
                    'ball',
                id:
                    relativeId,
                name:
                    `${courseDisplayName} Ball ${ballNumber}`,
                imagePath:
                    path.join(
                        coursePath,
                        fileEntry.name
                    ),
                courseFolder:
                    courseFolderName,
                courseDisplay:
                    courseDisplayName,
                ballNumber
            });
        }
    }

    return balls;
}

