let holeCatalog = [];
let ballCatalog = [];
let putterCatalog = [];
let legendaryCatalog = [];
let commonMiscCatalog = [];
let auctionOnlyCatalog = [];

let ballCatalogById =
    new Map();

let commonMiscCatalogById =
    new Map();

let legendaryCatalogById =
    new Map();

let putterCatalogById =
    new Map();

// ============================================================
// NORMALIZE STORED PUTTER NAMES
// ============================================================

function normalizeStoredPutterNames() {
    let inventoryChanges = 0;
    let historyChanges = 0;
    let activeChanges = 0;

    for (
        const putter
        of putterCatalog
    ) {
        inventoryChanges +=
            correctInventoryPutterNameStmt.run({
                item_name:
                    putter.name,
                item_id:
                    putter.id
            }).changes;

        historyChanges +=
            correctHistoryPutterNameStmt.run({
                item_name:
                    putter.name,
                item_id:
                    putter.id
            }).changes;

        activeChanges +=
            correctActivePutterNameStmt.run({
                item_name:
                    putter.name,
                item_id:
                    putter.id
            }).changes;
    }

    console.log(
        `Putter name normalization: ${inventoryChanges} inventory, ` +
        `${historyChanges} history, ${activeChanges} active-game record(s) corrected.`
    );
}

// ============================================================
// HISTORICAL MISC BACKFILL
// ============================================================

function resolveHistoricalMiscImagePath(
    itemId,
    storedPath
) {
    if (
        storedPath &&
        fs.existsSync(storedPath)
    ) {
        return storedPath;
    }

    const misc =
        commonMiscCatalogById.get(
            itemId
        );

    if (misc) {
        return misc.imagePath;
    }

    const legendary =
        legendaryCatalogById.get(
            itemId
        );

    if (legendary) {
        return legendary.imagePath;
    }

    const putter =
        putterCatalogById.get(
            itemId
        );

    if (putter) {
        return putter.imagePath;
    }

    return null;
}

function backfillHistoricalMiscInventory() {
    const historyRows =
        db.prepare(`
            SELECT
                id,
                winner_user_id,
                reward_item_id,
                reward_item_name,
                reward_image_path,
                completed_at
            FROM game_history
            WHERE reward_item_type = 'misc'
              AND winner_user_id IS NOT NULL
              AND reward_item_id IS NOT NULL
              AND reward_item_name IS NOT NULL
            ORDER BY id ASC
        `).all();

    const seen =
        new Set();

    let inserted = 0;
    let existing = 0;
    let skippedMissingImage = 0;

    const migrate =
        db.transaction(() => {
            for (
                const row
                of historyRows
            ) {
                const key =
                    `${row.winner_user_id}\u0000${row.reward_item_id}`;

                if (
                    seen.has(key)
                ) {
                    continue;
                }

                seen.add(key);

                const alreadyOwned =
                    getInventoryItemStmt.get(
                        row.winner_user_id,
                        'misc',
                        row.reward_item_id
                    );

                if (
                    alreadyOwned
                ) {
                    existing++;
                    continue;
                }

                const imagePath =
                    resolveHistoricalMiscImagePath(
                        row.reward_item_id,
                        row.reward_image_path
                    );

                if (
                    !imagePath
                ) {
                    skippedMissingImage++;

                    console.warn(
                        `[MISC BACKFILL] Could not find an image for historical item: ${row.reward_item_id}`
                    );

                    continue;
                }

                insertInventoryItemStmt.run({
                    user_id:
                        row.winner_user_id,
                    item_type:
                        'misc',
                    item_id:
                        row.reward_item_id,
                    item_name:
                        row.reward_item_name,
                    image_path:
                        imagePath,
                    first_collected_at:
                        row.completed_at ||
                        new Date().toISOString()
                });

                inserted++;
            }
        });

    migrate();

    console.log(
        `[MISC BACKFILL] Historical unique combinations checked: ${seen.size} | ` +
        `Inserted: ${inserted} | Already present: ${existing} | ` +
        `Skipped missing image: ${skippedMissingImage}`
    );
}

// ============================================================
// COMMON MISC -> GUARANTEED BALL MILESTONES
// ============================================================

function getUnownedBallRewardsForUser(
    userId
) {
    const ownedBallRows =
        getInventoryByTypeStmt.all(
            userId,
            'ball'
        );

    const ownedBallIds =
        new Set(
            ownedBallRows.map(
                row =>
                    row.item_id
            )
        );

    return ballCatalog.filter(
        ball =>
            !ownedBallIds.has(
                ball.id
            )
    );
}

const claimMiscBallMilestonesTransaction =
    db.transaction((userId) => {
        const miscCount =
            countInventoryByTypeStmt.get(
                userId,
                'misc'
            ).count;

        const earnedMilestoneCount =
            Math.floor(
                miscCount /
                MISC_BALL_MILESTONE_SIZE
            );

        if (
            earnedMilestoneCount <= 0
        ) {
            return {
                miscCount,
                earnedMilestoneCount,
                awards: [],
                deferredNoBalls: false
            };
        }

        const existingMilestones =
            getMiscBallMilestonesForUserStmt.all(
                userId
            );

        const claimedMilestoneNumbers =
            new Set(
                existingMilestones.map(
                    row =>
                        row.milestone_number
                )
            );

        const awards = [];

        let deferredNoBalls = false;

        for (
            let milestoneNumber = 1;
            milestoneNumber <=
                earnedMilestoneCount;
            milestoneNumber++
        ) {
            if (
                claimedMilestoneNumbers.has(
                    milestoneNumber
                )
            ) {
                continue;
            }

            const unownedBalls =
                getUnownedBallRewardsForUser(
                    userId
                );

            if (
                unownedBalls.length === 0
            ) {
                deferredNoBalls = true;
                break;
            }

            const ball =
                randomItem(
                    unownedBalls
                );

            const awardedAt =
                new Date().toISOString();

            insertInventoryItemStmt.run({
                user_id:
                    userId,
                item_type:
                    'ball',
                item_id:
                    ball.id,
                item_name:
                    ball.name,
                image_path:
                    ball.imagePath,
                first_collected_at:
                    awardedAt
            });

            insertMiscBallMilestoneStmt.run({
                user_id:
                    userId,
                milestone_number:
                    milestoneNumber,
                threshold_misc_count:
                    milestoneNumber *
                    MISC_BALL_MILESTONE_SIZE,
                ball_item_id:
                    ball.id,
                ball_item_name:
                    ball.name,
                ball_image_path:
                    ball.imagePath,
                awarded_at:
                    awardedAt
            });

            claimedMilestoneNumbers.add(
                milestoneNumber
            );

            awards.push({
                milestoneNumber,
                thresholdMiscCount:
                    milestoneNumber *
                    MISC_BALL_MILESTONE_SIZE,
                ball
            });
        }

        return {
            miscCount,
            earnedMilestoneCount,
            awards,
            deferredNoBalls
        };
    });

function claimMiscBallMilestonesForUser(
    userId
) {
    if (
        ballCatalog.length === 0
    ) {
        return {
            miscCount: 0,
            earnedMilestoneCount: 0,
            awards: [],
            deferredNoBalls: true
        };
    }

    return claimMiscBallMilestonesTransaction(
        userId
    );
}

function claimRetroactiveMiscBallMilestones() {
    const eligibleUsers =
        getUsersEligibleForMiscBallMilestonesStmt.all(
            MISC_BALL_MILESTONE_SIZE
        );

    let awardsCreated = 0;
    let deferredUsers = 0;
    const awardEvents = [];

    for (
        const row
        of eligibleUsers
    ) {
        const result =
            claimMiscBallMilestonesForUser(
                row.user_id
            );

        awardsCreated +=
            result.awards.length;

        for (
            const award
            of result.awards
        ) {
            awardEvents.push({
                userId:
                    row.user_id,
                ball:
                    award.ball
            });
        }

        if (
            result.deferredNoBalls
        ) {
            deferredUsers++;
        }
    }

    const pendingAnnouncements =
        db.prepare(`
            SELECT COUNT(*) AS count
            FROM misc_ball_milestones
            WHERE announced_at IS NULL
        `).get().count;

    console.log(
        `[MISC BALL MILESTONES] Retroactive check | ` +
        `Eligible players: ${eligibleUsers.length} | ` +
        `New Ball awards: ${awardsCreated} | ` +
        `Pending announcements: ${pendingAnnouncements} | ` +
        `Deferred with all Balls owned: ${deferredUsers}`
    );

    return {
        eligibleUsers:
            eligibleUsers.length,
        awardsCreated,
        pendingAnnouncements,
        deferredUsers,
        awardEvents
    };
}

