let miscBallAnnouncementRunning =
    false;

async function announcePendingMiscBallMilestones() {
    if (
        miscBallAnnouncementRunning
    ) {
        return;
    }

    miscBallAnnouncementRunning =
        true;

    try {
        const channel =
            await client.channels.fetch(
                MISC_BALL_REWARD_CHANNEL_ID
            );

        if (
            !channel ||
            !channel.isTextBased()
        ) {
            throw new Error(
                `Misc Ball reward channel could not be found: ${MISC_BALL_REWARD_CHANNEL_ID}`
            );
        }

        while (true) {
            const milestone =
                getNextPendingMiscBallMilestoneStmt.get();

            if (
                !milestone
            ) {
                break;
            }

            let cleanName =
                milestone.fallback_display_name ||
                'Player';

            try {
                const user =
                    await client.users.fetch(
                        milestone.user_id
                    );

                cleanName =
                    getCleanUserName(
                        user
                    );
            } catch (_) {
                // Stored player display name is a safe fallback.
            }

            if (
                !milestone.ball_image_path ||
                !fs.existsSync(
                    milestone.ball_image_path
                )
            ) {
                console.error(
                    `[MISC BALL MILESTONES] Ball image missing for pending announcement: ${milestone.ball_item_name} | ${milestone.ball_image_path}`
                );

                break;
            }

            const {
                embed,
                attachmentName
            } =
                buildMiscBallMilestoneEmbed(
                    cleanName,
                    milestone
                );

            let message;

            try {
                message =
                    await channel.send({
                        embeds: [
                            embed
                        ],
                        files: [
                            new AttachmentBuilder(
                                milestone.ball_image_path,
                                {
                                    name:
                                        attachmentName
                                }
                            )
                        ],
                        allowedMentions: {
                            parse: []
                        }
                    });
            } catch (error) {
                console.error(
                    '[MISC BALL MILESTONES] Public announcement failed:',
                    error
                );

                break;
            }

            markMiscBallMilestoneAnnouncedStmt.run({
                id:
                    milestone.id,
                announced_at:
                    new Date().toISOString(),
                announcement_message_id:
                    message.id
            });

            console.log(
                `[MISC BALL MILESTONE] ${cleanName} | ` +
                `Milestone ${milestone.milestone_number} | ` +
                `${MISC_BALL_MILESTONE_SIZE} unique Misc block | ` +
                `Awarded ${milestone.ball_item_name}`
            );

            await new Promise(
                resolve =>
                    setTimeout(
                        resolve,
                        MISC_BALL_ANNOUNCEMENT_DELAY_MS
                    )
            );
        }
    } catch (error) {
        console.error(
            '[MISC BALL MILESTONES] Announcement queue failed:',
            error
        );
    } finally {
        miscBallAnnouncementRunning =
            false;
    }
}

async function processMiscBallMilestonesAfterReward(
    userId,
    reward,
    duplicate,
    offerImmediateCashIn = false
) {
    if (!reward || reward.type !== 'misc') {
        return;
    }

    if (!duplicate) {
        const result = claimMiscBallMilestonesForUser(userId);

        if (result.awards.length > 0) {
            console.log(
                `[MISC BALL MILESTONES] ${userId} earned ${result.awards.length} guaranteed Ball reward(s) at ${result.miscCount} unique Misc.`
            );
        }

        if (result.deferredNoBalls) {
            console.log(
                `[MISC BALL MILESTONES] ${userId} has an earned Misc milestone waiting because all current Balls are already owned.`
            );
        }

        await announcePendingMiscBallMilestones();

        for (const award of result.awards) {
            await processBountyAfterInventoryReward(userId, award.ball, false);
            await processBallCollectionLegendaryAfterReward(userId, award.ball, false);
        }
    }

    if (offerImmediateCashIn) {
        await offerImmediateMiscCashIn({ userId, reward, duplicate });
    }
}

// ============================================================
// OFFICIAL BALL COLLECTION -> GUARANTEED LEGENDARY
// ============================================================

function getOfficialBallCollection(
    collectionKey
) {
    const balls =
        ballCatalog.filter(
            ball =>
                ball.courseDisplay ===
                collectionKey
        );

    if (
        balls.length <
            BALL_COLLECTION_SIZE
    ) {
        return null;
    }

    return {
        key:
            collectionKey,
        name:
            collectionKey,
        balls
    };
}

function playerOwnsCompleteBallCollection(
    userId,
    collection
) {
    const ownedRows =
        getInventoryByTypeStmt.all(
            userId,
            'ball'
        );

    const ownedIds =
        new Set(
            ownedRows.map(
                row =>
                    row.item_id
            )
        );

    const ownedInCollection =
        collection.balls.filter(
            ball =>
                ownedIds.has(
                    ball.id
                )
        ).length;

    return (
        ownedInCollection >=
        BALL_COLLECTION_SIZE
    );
}

function getUnownedNormalLegendaryRewardsForUser(
    userId
) {
    const ownedLegendaryRows =
        getInventoryByTypeStmt.all(
            userId,
            'legendary'
        );

    const ownedLegendaryIds =
        new Set(
            ownedLegendaryRows.map(
                row =>
                    row.item_id
            )
        );

    return legendaryCatalog.filter(
        legendary =>
            !ownedLegendaryIds.has(
                legendary.id
            )
    );
}

const claimBallCollectionLegendaryTransaction =
    db.transaction(({
        userId,
        collectionKey,
        collectionName
    }) => {
        const existing =
            getBallCollectionLegendaryRewardStmt.get(
                userId,
                collectionKey
            );

        if (existing) {
            return {
                type:
                    'ALREADY_RECORDED',
                row:
                    existing
            };
        }

        const collection =
            getOfficialBallCollection(
                collectionKey
            );

        if (
            !collection ||
            !playerOwnsCompleteBallCollection(
                userId,
                collection
            )
        ) {
            return {
                type:
                    'NOT_COMPLETE'
            };
        }

        const now =
            new Date().toISOString();

        const unownedLegendary =
            getUnownedNormalLegendaryRewardsForUser(
                userId
            );

        if (
            unownedLegendary.length === 0
        ) {
            insertBallCollectionLegendaryRewardStmt.run({
                user_id:
                    userId,
                collection_key:
                    collectionKey,
                collection_name:
                    collectionName ||
                    collection.name,
                legendary_item_id:
                    null,
                legendary_item_name:
                    null,
                legendary_image_path:
                    null,
                completed_at:
                    now,
                awarded_at:
                    null
            });

            return {
                type:
                    'PENDING_NO_LEGENDARY',
                row:
                    getBallCollectionLegendaryRewardStmt.get(
                        userId,
                        collectionKey
                    )
            };
        }

        const legendary =
            randomItem(
                unownedLegendary
            );

        insertInventoryItemStmt.run({
            user_id:
                userId,
            item_type:
                'legendary',
            item_id:
                legendary.id,
            item_name:
                legendary.name,
            image_path:
                legendary.imagePath,
            first_collected_at:
                now
        });

        insertBallCollectionLegendaryRewardStmt.run({
            user_id:
                userId,
            collection_key:
                collectionKey,
            collection_name:
                collectionName ||
                collection.name,
            legendary_item_id:
                legendary.id,
            legendary_item_name:
                legendary.name,
            legendary_image_path:
                legendary.imagePath,
            completed_at:
                now,
            awarded_at:
                now
        });

        return {
            type:
                'AWARDED',
            row:
                getBallCollectionLegendaryRewardStmt.get(
                    userId,
                    collectionKey
                ),
            legendary
        };
    });

const fulfillOnePendingBallCollectionLegendaryTransaction =
    db.transaction((row) => {
        const current =
            getBallCollectionLegendaryRewardByIdStmt.get(
                row.id
            );

        if (
            !current ||
            current.legendary_item_id
        ) {
            return {
                type:
                    'ALREADY_FULFILLED'
            };
        }

        const unownedLegendary =
            getUnownedNormalLegendaryRewardsForUser(
                current.user_id
            );

        if (
            unownedLegendary.length === 0
        ) {
            return {
                type:
                    'STILL_PENDING'
            };
        }

        const legendary =
            randomItem(
                unownedLegendary
            );

        const now =
            new Date().toISOString();

        insertInventoryItemStmt.run({
            user_id:
                current.user_id,
            item_type:
                'legendary',
            item_id:
                legendary.id,
            item_name:
                legendary.name,
            image_path:
                legendary.imagePath,
            first_collected_at:
                now
        });

        const updated =
            assignBallCollectionLegendaryRewardStmt.run({
                id:
                    current.id,
                legendary_item_id:
                    legendary.id,
                legendary_item_name:
                    legendary.name,
                legendary_image_path:
                    legendary.imagePath,
                awarded_at:
                    now
            });

        if (
            updated.changes !== 1
        ) {
            throw new Error(
                `Could not assign pending Ball collection Legendary reward ${current.id}.`
            );
        }

        return {
            type:
                'AWARDED',
            row:
                getBallCollectionLegendaryRewardByIdStmt.get(
                    current.id
                ),
            legendary
        };
    });

function fulfillPendingBallCollectionLegendaryRewards() {
    const pendingRows =
        getPendingBallCollectionLegendaryRewardsStmt.all();

    const awards = [];
    let stillPending = 0;

    for (
        const row
        of pendingRows
    ) {
        const result =
            fulfillOnePendingBallCollectionLegendaryTransaction(
                row
            );

        if (
            result.type ===
                'AWARDED'
        ) {
            awards.push({
                userId:
                    row.user_id,
                row:
                    result.row,
                legendary:
                    result.legendary
            });
        } else if (
            result.type ===
                'STILL_PENDING'
        ) {
            stillPending++;
        }
    }

    console.log(
        `[BALL COLLECTION LEGENDARY] Pending fulfillment | ` +
        `Pending before check: ${pendingRows.length} | ` +
        `New Legendary awards: ${awards.length} | ` +
        `Still pending: ${stillPending}`
    );

    return {
        pendingBefore:
            pendingRows.length,
        awards,
        stillPending
    };
}

