async function processBallCollectionLegendaryAfterReward(
    userId,
    reward,
    duplicate
) {
    if (
        !reward ||
        reward.type !== 'ball' ||
        duplicate
    ) {
        return;
    }

    const officialBall =
        ballCatalogById.get(
            reward.id
        );

    if (
        !officialBall ||
        !officialBall.courseDisplay
    ) {
        return;
    }

    const result =
        claimBallCollectionLegendaryTransaction({
            userId,
            collectionKey:
                officialBall.courseDisplay,
            collectionName:
                officialBall.courseDisplay
        });

    if (
        result.type ===
            'AWARDED'
    ) {
        console.log(
            `[BALL COLLECTION LEGENDARY] ${userId} completed ${result.row.collection_name} ${BALL_COLLECTION_SIZE}/${BALL_COLLECTION_SIZE} and earned ${result.legendary.name}.`
        );

        await processBountyAfterInventoryReward(
            userId,
            result.legendary,
            false
        );

        await announcePendingBallCollectionLegendaryRewards();
    } else if (
        result.type ===
            'PENDING_NO_LEGENDARY'
    ) {
        console.log(
            `[BALL COLLECTION LEGENDARY] ${userId} completed ${result.row.collection_name} ${BALL_COLLECTION_SIZE}/${BALL_COLLECTION_SIZE}; reward is pending because all current normal Legendary items are already owned.`
        );
    }
}

// ============================================================
// REWARD SELECTION
// ============================================================

function selectCommonReward() {
    const ballAvailable =
        ballCatalog.length > 0;

    const miscAvailable =
        commonMiscCatalog.length > 0;

    if (
        !ballAvailable &&
        !miscAvailable
    ) {
        return null;
    }

    if (!miscAvailable) {
        return randomItem(
            ballCatalog
        );
    }

    if (!ballAvailable) {
        return randomItem(
            commonMiscCatalog
        );
    }

    const commonRoll =
        randomInteger(
            1,
            100
        );

    if (
        commonRoll <=
        COMMON_BALL_PERCENT
    ) {
        return randomItem(
            ballCatalog
        );
    }

    return randomItem(
        commonMiscCatalog
    );
}

function selectReward(result) {
    switch (
        result.itemType
    ) {
        case 'common':
            return selectCommonReward();

        case 'putter':
            return randomItem(
                putterCatalog
            );

        case 'legendary':
            return randomItem(
                legendaryCatalog
            );

        default:
            return null;
    }
}

function selectNormalMysteryRewardOptions(
    result
) {
    let rewardPool = null;

    if (
        result.itemType ===
        'legendary'
    ) {
        rewardPool =
            legendaryCatalog;
    } else if (
        result.itemType ===
        'putter'
    ) {
        rewardPool =
            putterCatalog;
    } else if (
        result.itemType ===
        'common'
    ) {
        const commonRoll =
            randomInteger(
                1,
                100
            );

        const ballSelected =
            commonRoll <=
            COMMON_BALL_PERCENT;

        rewardPool =
            ballSelected
                ? ballCatalog
                : commonMiscCatalog;

        /*
        Safe fallback only if a category somehow has fewer than
        three available assets.
        */
        if (
            rewardPool.length < 3
        ) {
            const alternate =
                ballSelected
                    ? commonMiscCatalog
                    : ballCatalog;

            if (
                alternate.length >= 3
            ) {
                rewardPool =
                    alternate;
            }
        }
    }

    if (
        !rewardPool ||
        rewardPool.length < 3
    ) {
        throw new Error(
            `Could not build three Mystery Pick rewards for ${result.displayName}.`
        );
    }

    return randomDistinctItems(
        rewardPool,
        3
    );
}

function isInventoryReward(
    reward
) {
    if (!reward) {
        return false;
    }

    return [
        'ball',
        'putter',
        'legendary',
        'misc'
    ].includes(
        reward.type
    );
}

function earnsDuplicateBonus(
    reward
) {
    if (!reward) {
        return false;
    }

    return [
        'ball',
        'putter',
        'legendary'
    ].includes(
        reward.type
    );
}

// ============================================================
// DISPLAY NAMES
// ============================================================

async function getPlainDisplayName(
    interaction
) {
    try {
        if (
            interaction.member &&
            interaction.member.displayName
        ) {
            return (
                interaction.member.displayName
            );
        }

        if (
            interaction.guild
        ) {
            const member =
                await interaction.guild.members.fetch(
                    interaction.user.id
                );

            if (
                member &&
                member.displayName
            ) {
                return (
                    member.displayName
                );
            }
        }
    } catch (error) {
        console.error(
            'Could not resolve guild display name:',
            error
        );
    }

    if (
        interaction.user.globalName
    ) {
        return (
            interaction.user.globalName
        );
    }

    return (
        interaction.user.username
    );
}

function getCleanUserName(
    user
) {
    if (
        user &&
        user.globalName
    ) {
        return user.globalName;
    }

    if (
        user &&
        user.username
    ) {
        return user.username;
    }

    return 'Player';
}

async function resolveCleanUserNameById(
    userId,
    fallbackName = 'Player'
) {
    try {
        const cachedUser =
            client.users.cache.get(
                userId
            );

        if (cachedUser) {
            return getCleanUserName(
                cachedUser
            );
        }

        const user =
            await client.users.fetch(
                userId
            );

        return getCleanUserName(
            user
        );
    } catch (_) {
        return fallbackName || 'Player';
    }
}

function getCleanDiscordName(
    interaction
) {
    return getCleanUserName(
        interaction.user
    );
}

async function getDisplayNameForUser(
    guild,
    userId
) {
    try {
        const member =
            await guild.members.fetch(
                userId
            );

        if (
            member &&
            member.displayName
        ) {
            return member.displayName;
        }
    } catch (_) {
        // Fall through.
    }

    const player =
        getPlayerStmt.get(
            userId
        );

    if (player) {
        return player.display_name;
    }

    return 'Player';
}

// ============================================================
// PLAYER HELPERS
// ============================================================

function ensurePlayer(
    userId,
    displayName
) {
    const now =
        new Date().toISOString();

    let player =
        getPlayerStmt.get(
            userId
        );

    if (!player) {
        createPlayerStmt.run({
            user_id:
                userId,
            display_name:
                displayName,
            created_at:
                now,
            updated_at:
                now
        });

        player =
            getPlayerStmt.get(
                userId
            );
    } else if (
        player.display_name !==
        displayName
    ) {
        updatePlayerNameStmt.run({
            user_id:
                userId,
            display_name:
                displayName,
            updated_at:
                now
        });

        player =
            getPlayerStmt.get(
                userId
            );
    }

    return player;
}

// ============================================================
// MANUAL SMASH SCORE TRANSACTION
// ============================================================

const adjustSmashScoreTransaction =
    db.transaction(({
        transactionType,
        userId,
        displayName,
        amount,
        reason,
        adminUserId,
        adminDisplayName
    }) => {
        const now =
            new Date().toISOString();

        let player =
            getPlayerStmt.get(
                userId
            );

        if (
            transactionType ===
            'ADD'
        ) {
            if (!player) {
                createPlayerStmt.run({
                    user_id:
                        userId,
                    display_name:
                        displayName,
                    created_at:
                        now,
                    updated_at:
                        now
                });
            }

            addSmashScoreStmt.run({
                user_id:
                    userId,
                display_name:
                    displayName,
                amount,
                updated_at:
                    now
            });
        } else if (
            transactionType ===
            'REMOVE'
        ) {
            if (!player) {
                return {
                    ok: false,
                    reason:
                        'NO_PLAYER',
                    currentScore:
                        0
                };
            }

            if (
                player.smash_score <
                amount
            ) {
                return {
                    ok: false,
                    reason:
                        'INSUFFICIENT',
                    currentScore:
                        player.smash_score
                };
            }

            const result =
                removeSmashScoreStmt.run({
                    user_id:
                        userId,
                    display_name:
                        displayName,
                    amount,
                    updated_at:
                        now
                });

            if (
                result.changes !== 1
            ) {
                return {
                    ok: false,
                    reason:
                        'INSUFFICIENT',
                    currentScore:
                        (
                            getPlayerStmt.get(
                                userId
                            )?.smash_score
                            || 0
                        )
                };
            }
        } else {
            throw new Error(
                `Invalid Smash Score transaction type: ${transactionType}`
            );
        }

        insertScoreTransactionStmt.run({
            user_id:
                userId,
            display_name:
                displayName,
            transaction_type:
                transactionType,
            amount,
            reason,
            admin_user_id:
                adminUserId,
            admin_display_name:
                adminDisplayName,
            created_at:
                now
        });

        player =
            getPlayerStmt.get(
                userId
            );

        return {
            ok: true,
            player
        };
    });

