// ANNOUNCEMENT READ REWARD HELPERS
// ============================================================

function buildReadRewardButton(postId, amount) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(`read_reward_claim:${postId}`)
            .setLabel(`I READ THE POST — 💥 +${amount} Smash Score`)
            .setEmoji('✅')
            .setStyle(ButtonStyle.Success)
    );
}

async function handleReadRewardCommand(interaction) {
    const amount = interaction.options.getInteger('amount', true);

    if (!Number.isInteger(amount) || amount <= 0) {
        await interaction.reply({
            content: 'The Read Reward amount must be greater than zero.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const adminDisplayName = await getPlainDisplayName(interaction);
    const now = new Date().toISOString();
    const result = insertReadRewardPostStmt.run({
        channel_id: ANNOUNCEMENT_CHANNEL_ID,
        amount,
        created_by_user_id: interaction.user.id,
        created_by_display_name: adminDisplayName,
        created_at: now
    });
    const postId = Number(result.lastInsertRowid);

    try {
        const embed = new EmbedBuilder()
            .setTitle('📢 READ REWARD')
            .setDescription('Read the announcement above and claim your reward.');

        await interaction.reply({
            embeds: [embed],
            components: [buildReadRewardButton(postId, amount)],
            allowedMentions: { parse: [] }
        });

        const message = await interaction.fetchReply();
        updateReadRewardPostMessageStmt.run({
            id: postId,
            message_id: message.id
        });

        console.log(
            `[READ REWARD] Created post ${postId} | Message ${message.id} | Amount ${amount} | Admin ${adminDisplayName}`
        );
    } catch (error) {
        deleteReadRewardPostStmt.run(postId);
        throw error;
    }
}

const claimReadRewardTransaction = db.transaction(({
    post,
    userId,
    displayName
}) => {
    const now = new Date().toISOString();

    const claimResult = insertReadRewardClaimStmt.run({
        post_id: post.id,
        user_id: userId,
        display_name: displayName,
        amount: post.amount,
        claimed_at: now
    });

    if (claimResult.changes !== 1) {
        return { ok: false, reason: 'ALREADY_CLAIMED' };
    }

    ensurePlayer(userId, displayName);

    addSmashScoreStmt.run({
        user_id: userId,
        display_name: displayName,
        amount: post.amount,
        updated_at: now
    });

    insertScoreTransactionStmt.run({
        user_id: userId,
        display_name: displayName,
        transaction_type: 'READ_REWARD',
        amount: post.amount,
        reason: `Announcement Read Reward #${post.id}`,
        admin_user_id: post.created_by_user_id,
        admin_display_name: post.created_by_display_name,
        created_at: now
    });

    return {
        ok: true,
        player: getPlayerStmt.get(userId)
    };
});

async function handleReadRewardClaimButton(interaction) {
    const postId = Number(interaction.customId.split(':')[1]);

    if (!Number.isSafeInteger(postId) || postId <= 0) {
        await interaction.reply({
            content: 'This Read Reward is invalid.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const post = getReadRewardPostStmt.get(postId);

    if (
        !post ||
        post.channel_id !== ANNOUNCEMENT_CHANNEL_ID ||
        interaction.channelId !== post.channel_id ||
        !post.message_id ||
        interaction.message.id !== post.message_id
    ) {
        await interaction.reply({
            content: 'This Read Reward is no longer valid.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const result = claimReadRewardTransaction({
        post,
        userId: interaction.user.id,
        displayName
    });

    if (!result.ok && result.reason === 'ALREADY_CLAIMED') {
        await interaction.reply({
            content: '✅ You already claimed this reward.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    console.log(
        `[READ REWARD CLAIM] Post ${post.id} | ${displayName} | +${post.amount} Smash Score`
    );

    await interaction.reply({
        content: `✅ Reward claimed — 💥 +${post.amount} Smash Score.`,
        flags: MessageFlags.Ephemeral
    });
}

// ============================================================
// NEXT GAME VOTE HELPERS
// ============================================================

let activeGameModeVote = null;
let gameModeVoteRefreshTimer = null;
let gameModeVoteRefreshChain = Promise.resolve();

const GAME_MODE_VOTE_CHOICES = Object.freeze({
    vault: {
        label: 'Vault Drop',
        style: ButtonStyle.Primary
    },
    lottery: {
        label: 'Lottery',
        style: ButtonStyle.Success
    },
    safecracker: {
        label: 'Safecracker',
        style: ButtonStyle.Danger
    }
});

function clearGameModeVoteRefreshTimer() {
    if (gameModeVoteRefreshTimer) {
        clearInterval(gameModeVoteRefreshTimer);
        gameModeVoteRefreshTimer = null;
    }
}

function getGameModeVoteRemainingMs(state) {
    return Math.max(0, state.deadlineAt - Date.now());
}

function formatGameModeVoteTimer(remainingMs) {
    const totalSeconds = Math.max(0, Math.ceil(remainingMs / 1000));
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function buildGameModeVoteEmbed(state, closed = false) {
    const embed = new EmbedBuilder()
        .setTitle(closed ? '🎮 VOTING CLOSED — WHAT SHOULD WE PLAY NEXT?' : '🎮 WHAT SHOULD WE PLAY NEXT?')
        .setDescription(
            closed
                ? '**Voting is closed. Final results:**'
                : `**⏱️ Time Remaining:** ${formatGameModeVoteTimer(getGameModeVoteRemainingMs(state))}`
        );

    for (const [choiceKey, choice] of Object.entries(GAME_MODE_VOTE_CHOICES)) {
        const voters = [...state.votes.values()]
            .filter(vote => vote.choice === choiceKey)
            .map(vote => escapeDiscordMarkdown(vote.displayName));

        embed.addFields({
            name: `${choice.label} — ${voters.length}`,
            value: voters.length ? voters.join(', ') : 'No votes yet.',
            inline: false
        });
    }

    return embed;
}

function buildGameModeVoteButtons(disabled = false) {
    const row = new ActionRowBuilder();

    for (const [choiceKey, choice] of Object.entries(GAME_MODE_VOTE_CHOICES)) {
        row.addComponents(
            new ButtonBuilder()
                .setCustomId(`game_mode_vote:${choiceKey}`)
                .setLabel(choice.label)
                .setStyle(choice.style)
                .setDisabled(disabled)
        );
    }

    return [row];
}

function queueGameModeVoteRefresh(state, closed = false) {
    gameModeVoteRefreshChain = gameModeVoteRefreshChain
        .catch(() => {})
        .then(async () => {
            if (!state.message) {
                return;
            }

            await state.message.edit({
                embeds: [buildGameModeVoteEmbed(state, closed)],
                components: buildGameModeVoteButtons(closed)
            });
        })
        .catch(error => {
            console.error('[GAME MODE VOTE] Message refresh failed:', error);
        });

    return gameModeVoteRefreshChain;
}

async function finishGameModeVote(state) {
    if (!activeGameModeVote || activeGameModeVote !== state) {
        return;
    }

    clearGameModeVoteRefreshTimer();
    await queueGameModeVoteRefresh(state, true);
    activeGameModeVote = null;

    const totals = Object.fromEntries(
        Object.keys(GAME_MODE_VOTE_CHOICES).map(choiceKey => [
            choiceKey,
            [...state.votes.values()].filter(vote => vote.choice === choiceKey).length
        ])
    );

    console.log(
        `[GAME MODE VOTE COMPLETE] Vault Drop: ${totals.vault} | Lottery: ${totals.lottery} | Safecracker: ${totals.safecracker}`
    );
}

async function handleGameModeVoteCommand(interaction) {
    if (activeGameModeVote) {
        await interaction.reply({
            content: 'A next-game vote is already active.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });

    const state = {
        channelId: interaction.channelId,
        deadlineAt: Date.now() + GAME_MODE_VOTE_DURATION_MS,
        votes: new Map(),
        message: null
    };

    const message = await interaction.channel.send({
        embeds: [buildGameModeVoteEmbed(state, false)],
        components: buildGameModeVoteButtons(false),
        allowedMentions: { parse: [] }
    });

    state.message = message;
    state.messageId = message.id;
    activeGameModeVote = state;

    gameModeVoteRefreshTimer = setInterval(() => {
        if (!activeGameModeVote || activeGameModeVote !== state) {
            clearGameModeVoteRefreshTimer();
            return;
        }

        if (Date.now() >= state.deadlineAt) {
            finishGameModeVote(state).catch(error =>
                console.error('[GAME MODE VOTE] Finish failed:', error)
            );
            return;
        }

        queueGameModeVoteRefresh(state, false);
    }, GAME_MODE_VOTE_REFRESH_MS);

    setTimeout(() => {
        finishGameModeVote(state).catch(error =>
            console.error('[GAME MODE VOTE] Finish timeout failed:', error)
        );
    }, GAME_MODE_VOTE_DURATION_MS + 100);

    await interaction.editReply({
        content: `✅ Next-game vote posted in <#${GAME_MODE_VOTE_CHANNEL_ID}>.`
    });
}

async function handleGameModeVoteButton(interaction) {
    const state = activeGameModeVote;
    const choiceKey = interaction.customId.split(':')[1];
    const choice = GAME_MODE_VOTE_CHOICES[choiceKey];

    if (
        !state ||
        !choice ||
        interaction.channelId !== state.channelId ||
        interaction.message.id !== state.messageId ||
        Date.now() >= state.deadlineAt
    ) {
        await interaction.reply({
            content: 'This next-game vote is no longer active.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferUpdate();

    const displayName = getCleanDiscordName(interaction);
    const previous = state.votes.get(interaction.user.id);

    state.votes.set(interaction.user.id, {
        choice: choiceKey,
        displayName
    });

    await queueGameModeVoteRefresh(state, false);

    if (previous && previous.choice === choiceKey) {
        await interaction.followUp({
            content: `Your vote is already **${choice.label}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.followUp({
        content: previous
            ? `✅ Vote changed to **${choice.label}**.`
            : `✅ Voted for **${choice.label}**.`,
        flags: MessageFlags.Ephemeral
    });
}

// ============================================================
// RECURRING SMASHPUTT NEWS REWARD HELPERS
// ============================================================

let newsRewardTimer = null;

function clearNewsRewardTimer() {
    if (newsRewardTimer) {
        clearTimeout(newsRewardTimer);
        newsRewardTimer = null;
    }
}

function normalizeNewsMessage(value) {
    return String(value || '')
        .replace(/\s+/g, ' ')
        .trim();
}

function measureNewsBannerTextWidth(text, fontSize) {
    let units = 0;

    for (const char of text) {
        if (char === ' ') {
            units += 0.34;
        } else if ('ilIjtfr'.includes(char)) {
            units += 0.38;
        } else if ('mwMW@#%&QOGD'.includes(char)) {
            units += 0.92;
        } else if (/[A-Z]/.test(char)) {
            units += 0.74;
        } else if (/[0-9]/.test(char)) {
            units += 0.62;
        } else if (/[,.;:!?'\-]/.test(char)) {
            units += 0.34;
        } else {
            units += 0.58;
        }
    }

    return units * fontSize;
}

function wrapNewsMessageForBanner(messageText, fontSize) {
    const normalized = normalizeNewsMessage(messageText);
    const availableWidth = 650;
    const words = normalized.split(' ').filter(Boolean);
    const lines = [];
    let current = '';

    for (const word of words) {
        const candidate = current ? `${current} ${word}` : word;

        if (!current || measureNewsBannerTextWidth(candidate, fontSize) <= availableWidth) {
            current = candidate;
            continue;
        }

        lines.push(current);
        current = word;
    }

    if (current) {
        lines.push(current);
    }

    return lines;
}

function fitNewsMessageForBanner(messageText) {
    const fontSizes = [60, 56, 52, 48, 44, 40, 36, 32, 30];

    for (const fontSize of fontSizes) {
        const lines = wrapNewsMessageForBanner(messageText, fontSize);
        const lineHeight = Math.round(fontSize * 1.16);
        const totalHeight = lines.length * lineHeight;

        if (lines.length <= 4 && totalHeight <= 220) {
            return { lines, fontSize, lineHeight };
        }
    }

    return {
        lines: wrapNewsMessageForBanner(messageText, 30).slice(0, 4),
        fontSize: 30,
        lineHeight: 35
    };
}

async function generateNewsRewardBanner(messageText) {
    if (!fs.existsSync(NEWS_LOGO_PATH)) {
        throw new Error(`SmashPutt News logo is missing: ${NEWS_LOGO_PATH}`);
    }

    const { lines, fontSize, lineHeight } = fitNewsMessageForBanner(messageText);
    const textCenterY = NEWS_BANNER_HEIGHT / 2;
    const textBlockHeight = lines.length * lineHeight;
    const firstBaseline = textCenterY - textBlockHeight / 2 + lineHeight * 0.78;

    const textSvg = lines
        .map((line, index) => `
            <text
                x="760"
                y="${Math.round(firstBaseline + index * lineHeight)}"
                text-anchor="middle"
                font-family="sans-serif"
                font-size="${fontSize}"
                font-weight="800"
                fill="#ffffff"
            >${escapeXml(line)}</text>
        `)
        .join('');

    const backgroundSvg = `
        <svg width="${NEWS_BANNER_WIDTH}" height="${NEWS_BANNER_HEIGHT}" xmlns="http://www.w3.org/2000/svg">
            <rect width="100%" height="100%" rx="20" fill="#050505"/>
            <rect x="4" y="4" width="1192" height="292" rx="18" fill="none" stroke="#E04B4B" stroke-width="5"/>
            <rect x="13" y="13" width="1174" height="274" rx="14" fill="none" stroke="#8F2E2E" stroke-width="2" opacity="0.95"/>
            <line x1="300" y1="38" x2="300" y2="262" stroke="#E04B4B" stroke-width="3" opacity="0.7"/>
            ${textSvg}
        </svg>
    `;

    const logo = await sharp(NEWS_LOGO_PATH)
        .resize(245, 245, { fit: 'contain' })
        .png()
        .toBuffer();

    return sharp(Buffer.from(backgroundSvg))
        .composite([
            {
                input: logo,
                left: 28,
                top: 28
            }
        ])
        .png()
        .toBuffer();
}

function buildNewsRewardClaimRow(postId, amount) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(`news_reward_claim:${postId}`)
            .setLabel(`CLAIM REWARD — +${amount} Smash Score`)
            .setEmoji('💥')
            .setStyle(ButtonStyle.Success)
    );
}

async function createNewsRewardPost({
    messageText,
    rewardAmount,
    createdByUserId,
    createdByDisplayName
}) {
    const channel = await client.channels.fetch(NEWS_PUBLIC_CHANNEL_ID);

    if (!channel || !channel.isTextBased()) {
        throw new Error(`SmashPutt News channel could not be found: ${NEWS_PUBLIC_CHANNEL_ID}`);
    }

    const now = new Date().toISOString();
    const result = insertNewsRewardPostStmt.run({
        channel_id: NEWS_PUBLIC_CHANNEL_ID,
        message_text: messageText,
        amount: rewardAmount,
        created_by_user_id: createdByUserId,
        created_by_display_name: createdByDisplayName,
        created_at: now
    });
    const postId = Number(result.lastInsertRowid);

    try {
        const banner = await generateNewsRewardBanner(messageText);
        const attachmentName = `smashputt-news-${postId}.png`;
        const embed = new EmbedBuilder()
            .setColor(0xE04B4B)
            .setImage(`attachment://${attachmentName}`);

        const message = await channel.send({
            embeds: [embed],
            files: [
                new AttachmentBuilder(banner, { name: attachmentName })
            ],
            components: [buildNewsRewardClaimRow(postId, rewardAmount)],
            allowedMentions: { parse: [] }
        });

        updateNewsRewardPostMessageStmt.run({
            id: postId,
            message_id: message.id
        });

        console.log(
            `[NEWS] Posted #${postId} | Message ${message.id} | Reward ${rewardAmount} | ${messageText}`
        );

        return { postId, messageId: message.id };
    } catch (error) {
        deleteNewsRewardPostStmt.run(postId);
        throw error;
    }
}

function scheduleNextNewsRewardPost(state, nextDate) {
    const nextIso = nextDate.toISOString();

    updateNewsRewardNextPostStmt.run({
        next_post_at: nextIso,
        updated_at: new Date().toISOString()
    });

    armNewsRewardTimer();
}

async function runScheduledNewsRewardPost() {
    const state = getNewsRewardStateStmt.get();

    if (!state || Number(state.active) !== 1) {
        clearNewsRewardTimer();
        return;
    }

    try {
        await createNewsRewardPost({
            messageText: state.message_text,
            rewardAmount: Number(state.reward_amount),
            createdByUserId: state.created_by_user_id,
            createdByDisplayName: state.created_by_display_name
        });

        const nextDate = new Date(
            Date.now() + Number(state.interval_hours) * 60 * 60 * 1000
        );

        scheduleNextNewsRewardPost(state, nextDate);
    } catch (error) {
        console.error('[NEWS] Scheduled post failed; retrying in 5 minutes:', error);
        clearNewsRewardTimer();
        newsRewardTimer = setTimeout(
            () => {
                runScheduledNewsRewardPost().catch(error => {
                    console.error('[NEWS] Retry failed:', error);
                });
            },
            NEWS_RETRY_MS
        );
    }
}

function armNewsRewardTimer() {
    clearNewsRewardTimer();

    const state = getNewsRewardStateStmt.get();

    if (!state || Number(state.active) !== 1 || !state.next_post_at) {
        return;
    }

    const dueAt = new Date(state.next_post_at).getTime();
    const delay = Math.max(0, dueAt - Date.now());

    newsRewardTimer = setTimeout(
        () => {
            runScheduledNewsRewardPost().catch(error => {
                console.error('[NEWS] Timer execution failed:', error);
            });
        },
        delay
    );
}

async function resumeNewsRewardOnStartup() {
    const state = getNewsRewardStateStmt.get();

    if (!state || Number(state.active) !== 1) {
        console.log('[NEWS] No active recurring SmashPutt News schedule.');
        return;
    }

    if (!fs.existsSync(NEWS_LOGO_PATH)) {
        console.error(
            `[NEWS] Active schedule paused because logo is missing: ${NEWS_LOGO_PATH}`
        );
        return;
    }

    const dueAt = state.next_post_at ? new Date(state.next_post_at).getTime() : 0;

    if (!Number.isFinite(dueAt) || dueAt <= Date.now()) {
        console.log('[NEWS] Saved News time was overdue after restart; posting one current update now.');
        await runScheduledNewsRewardPost();
        return;
    }

    console.log(
        `[NEWS] Resumed recurring schedule | Next post: ${new Date(dueAt).toLocaleString('en-US', { timeZone: 'America/Chicago' })} Central`
    );
    armNewsRewardTimer();
}

async function handleNewsStartCommand(interaction) {
    const messageText = normalizeNewsMessage(interaction.options.getString('message', true));
    const intervalHours = interaction.options.getInteger('interval', true);
    const rewardAmount = interaction.options.getInteger('amount', true);

    if (!messageText || messageText.length > NEWS_MESSAGE_MAX_LENGTH) {
        await interaction.reply({
            content: `News message must be between 1 and ${NEWS_MESSAGE_MAX_LENGTH} characters.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (![1, 2, 3, 4, 5].includes(intervalHours)) {
        await interaction.reply({
            content: 'News interval must be 1, 2, 3, 4, or 5 hours.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (!Number.isInteger(rewardAmount) || rewardAmount <= 0) {
        await interaction.reply({
            content: 'News reward amount must be greater than zero.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (!fs.existsSync(NEWS_LOGO_PATH)) {
        await interaction.reply({
            content: `SmashPutt News logo is missing. Upload it to \`${NEWS_LOGO_PATH}\` first.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const existing = getNewsRewardStateStmt.get();

    if (existing && Number(existing.active) === 1) {
        await interaction.reply({
            content: 'A recurring SmashPutt News schedule is already active. Use `/smashputt-news stop` before starting a different one.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });

    const adminDisplayName = await getPlainDisplayName(interaction);

    try {
        await createNewsRewardPost({
            messageText,
            rewardAmount,
            createdByUserId: interaction.user.id,
            createdByDisplayName: adminDisplayName
        });

        const now = new Date();
        const nextDate = new Date(now.getTime() + intervalHours * 60 * 60 * 1000);

        upsertNewsRewardStateStmt.run({
            active: 1,
            message_text: messageText,
            interval_hours: intervalHours,
            reward_amount: rewardAmount,
            next_post_at: nextDate.toISOString(),
            created_by_user_id: interaction.user.id,
            created_by_display_name: adminDisplayName,
            updated_at: now.toISOString()
        });

        armNewsRewardTimer();

        await interaction.editReply({
            content:
                `✅ SmashPutt News started. The first post is live now in <#${NEWS_PUBLIC_CHANNEL_ID}>. ` +
                `It will repeat every ${intervalHours} hour${intervalHours === 1 ? '' : 's'} with a 💥 +${rewardAmount} Smash Score claim.`
        });
    } catch (error) {
        console.error('[NEWS] Could not start recurring News:', error);
        await interaction.editReply({
            content: 'SmashPutt News could not be started. No recurring schedule was saved.'
        });
    }
}

async function handleNewsStopCommand(interaction) {
    const state = getNewsRewardStateStmt.get();

    if (!state || Number(state.active) !== 1) {
        await interaction.reply({
            content: 'No recurring SmashPutt News schedule is currently active.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    stopNewsRewardStateStmt.run({ updated_at: new Date().toISOString() });
    clearNewsRewardTimer();

    await interaction.reply({
        content: '✅ Recurring SmashPutt News stopped. Existing News reward buttons remain permanently claimable.',
        flags: MessageFlags.Ephemeral
    });
}

async function handleNewsStatusCommand(interaction) {
    const state = getNewsRewardStateStmt.get();

    if (!state || Number(state.active) !== 1) {
        await interaction.reply({
            content: 'No recurring SmashPutt News schedule is currently active.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const nextTimestamp = Math.floor(new Date(state.next_post_at).getTime() / 1000);

    await interaction.reply({
        content:
            `📰 **SmashPutt News is active**\n` +
            `Message: ${state.message_text}\n` +
            `Interval: every ${state.interval_hours} hour${Number(state.interval_hours) === 1 ? '' : 's'}\n` +
            `Reward: 💥 +${state.reward_amount} Smash Score per post\n` +
            `Next post: <t:${nextTimestamp}:R>`,
        flags: MessageFlags.Ephemeral,
        allowedMentions: { parse: [] }
    });
}

const claimNewsRewardTransaction = db.transaction(({
    post,
    userId,
    displayName
}) => {
    const now = new Date().toISOString();
    const claimResult = insertNewsRewardClaimStmt.run({
        post_id: post.id,
        user_id: userId,
        display_name: displayName,
        amount: post.amount,
        claimed_at: now
    });

    if (claimResult.changes !== 1) {
        return { ok: false, reason: 'ALREADY_CLAIMED' };
    }

    ensurePlayer(userId, displayName);

    addSmashScoreStmt.run({
        user_id: userId,
        display_name: displayName,
        amount: post.amount,
        updated_at: now
    });

    insertScoreTransactionStmt.run({
        user_id: userId,
        display_name: displayName,
        transaction_type: 'NEWS_REWARD',
        amount: post.amount,
        reason: `SmashPutt News Reward #${post.id}`,
        admin_user_id: post.created_by_user_id,
        admin_display_name: post.created_by_display_name,
        created_at: now
    });

    return {
        ok: true,
        player: getPlayerStmt.get(userId)
    };
});

async function handleNewsRewardClaimButton(interaction) {
    const postId = Number(interaction.customId.split(':')[1]);

    if (!Number.isSafeInteger(postId) || postId <= 0) {
        await interaction.reply({
            content: 'This News reward is invalid.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const post = getNewsRewardPostStmt.get(postId);

    if (
        !post ||
        post.channel_id !== NEWS_PUBLIC_CHANNEL_ID ||
        interaction.channelId !== post.channel_id ||
        !post.message_id ||
        interaction.message.id !== post.message_id
    ) {
        await interaction.reply({
            content: 'This News reward is no longer valid.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const displayName = await getPlainDisplayName(interaction);
    const result = claimNewsRewardTransaction({
        post,
        userId: interaction.user.id,
        displayName
    });

    if (!result.ok && result.reason === 'ALREADY_CLAIMED') {
        await interaction.reply({
            content: '✅ You already claimed this News reward.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    console.log(
        `[NEWS REWARD CLAIM] Post ${post.id} | ${displayName} | +${post.amount} Smash Score`
    );

    await interaction.reply({
        content: `✅ News reward claimed — 💥 +${post.amount} Smash Score.`,
        flags: MessageFlags.Ephemeral
    });
}

// ============================================================
// COMMON MISC CASH-IN / RECOLLECT HELPERS
// ============================================================

const cashInMiscItemTransaction =
    db.transaction(({
        userId,
        inventoryRowId,
        displayName
    }) => {
        const item =
            getInventoryMiscItemByRowIdStmt.get(
                inventoryRowId,
                userId
            );

        if (!item) {
            return {
                ok: false,
                reason: 'NOT_OWNED'
            };
        }

        const currentState =
            getMiscCashStateStmt.get(
                userId,
                item.item_id
            );

        if (
            isItemLockedByActivePlayerAuction(
                userId,
                'misc',
                item.item_id
            )
        ) {
            return {
                ok: false,
                reason: 'PLAYER_AUCTION_LOCKED',
                item
            };
        }

        if (
            currentState &&
            Number(currentState.is_hidden) === 1
        ) {
            return {
                ok: false,
                reason: 'ALREADY_CASHED',
                item
            };
        }

        const now =
            new Date().toISOString();

        ensurePlayer(
            userId,
            displayName
        );

        hideMiscCashStateStmt.run({
            user_id: userId,
            item_id: item.item_id,
            item_name: item.item_name,
            last_cashed_in_at: now
        });

        addSmashScoreStmt.run({
            user_id: userId,
            display_name: displayName,
            amount: MISC_CASH_IN_SCORE,
            updated_at: now
        });

        insertScoreTransactionStmt.run({
            user_id: userId,
            display_name: displayName,
            transaction_type: 'MISC_CASH_IN',
            amount: MISC_CASH_IN_SCORE,
            reason: `Common Misc cash-in: ${item.item_name}`,
            admin_user_id: userId,
            admin_display_name: displayName,
            created_at: now
        });

        const showcaseChanged =
            deleteShowcaseSlotByItemStmt.run({
                user_id: userId,
                item_type: 'misc',
                item_id: item.item_id
            }).changes > 0;

        return {
            ok: true,
            item,
            player: getPlayerStmt.get(userId),
            showcaseChanged
        };
    });

async function announceMiscCashInPublicReceipt({
    userId,
    displayName,
    item
}) {
    const channel =
        await client.channels.fetch(
            MISC_CASH_IN_PUBLIC_CHANNEL_ID
        );

    if (
        !channel ||
        !channel.isTextBased()
    ) {
        throw new Error(
            `Common Misc cash-in public channel could not be found: ${MISC_CASH_IN_PUBLIC_CHANNEL_ID}`
        );
    }

    const safePlayerName =
        escapeDiscordMarkdown(
            displayName ||
            userId ||
            'Player'
        );

    const safeItemName =
        escapeDiscordMarkdown(
            item?.item_name ||
            'Common Misc item'
        );

    const embed =
        new EmbedBuilder()
            .setColor(
                0xF1C40F
            )
            .setDescription(
                `💰 **${safePlayerName}** just cashed in **${safeItemName}** from their inventory for 💥 **${MISC_CASH_IN_SCORE} Smash Score**.`
            );

    const files = [];

    if (
        item?.image_path &&
        fs.existsSync(
            item.image_path
        )
    ) {
        const attachmentExtension =
            path.extname(item.image_path) || '.png';

        const attachmentName =
            `misc-cash-in-${Date.now()}${attachmentExtension}`;

        embed.setImage(
            `attachment://${attachmentName}`
        );

        files.push(
            new AttachmentBuilder(
                item.image_path,
                {
                    name: attachmentName
                }
            )
        );
    } else {
        console.error(
            `[MISC CASH-IN] Public receipt image missing: ${item?.item_name || 'Unknown item'} | ${item?.image_path || 'No image path'}`
        );
    }

    await channel.send({
        embeds: [
            embed
        ],
        files,
        allowedMentions: {
            parse: []
        }
    });
}

const immediateMiscCashTimers = new Map();

function clearImmediateMiscCashTimer(opportunityId) {
    const timer = immediateMiscCashTimers.get(Number(opportunityId));
    if (timer) {
        clearTimeout(timer);
        immediateMiscCashTimers.delete(Number(opportunityId));
    }
}

function getImmediateMiscCashEligibility(userId, reward, duplicate) {
    if (
        !reward ||
        reward.type !== 'misc' ||
        !commonMiscCatalogById.has(reward.id)
    ) {
        return null;
    }

    const inventoryItem = getInventoryItemStmt.get(userId, 'misc', reward.id);
    if (!inventoryItem) return null;

    const cashState = getMiscCashStateStmt.get(userId, reward.id);
    if (cashState && Number(cashState.is_hidden) === 1) return null;

    if (!duplicate) return inventoryItem;

    const restoredAt = cashState?.last_restored_at
        ? new Date(cashState.last_restored_at).getTime()
        : NaN;

    if (!Number.isFinite(restoredAt) || Date.now() - restoredAt > 60 * 1000) {
        return null;
    }

    return inventoryItem;
}

async function removeImmediateMiscCashButton(opportunity, expired = true) {
    if (!opportunity?.message_id || !opportunity?.channel_id) return;

    try {
        const channel = await client.channels.fetch(opportunity.channel_id);
        if (!channel || !channel.isTextBased() || !channel.messages) return;

        const message = await channel.messages.fetch(opportunity.message_id);
        const safePlayer = escapeDiscordMarkdown(opportunity.display_name || 'Player');
        const safeItem = escapeDiscordMarkdown(opportunity.item_name || 'Common Misc item');

        await message.edit({
            content: expired
                ? `🎁 **${safePlayer}** kept **${safeItem}** in their Common Misc inventory.`
                : message.content,
            components: []
        });
    } catch (error) {
        if (error?.code !== 10008) {
            console.error('[MISC IMMEDIATE CASH-IN] Could not remove button:', error);
        }
    }
}

function armImmediateMiscCashTimer(opportunity) {
    if (!opportunity?.id) return;
    clearImmediateMiscCashTimer(opportunity.id);

    const delay = Math.max(0, new Date(opportunity.expires_at).getTime() - Date.now());
    const timer = setTimeout(() => {
        immediateMiscCashTimers.delete(Number(opportunity.id));
        const current = getImmediateMiscCashOpportunityStmt.get(opportunity.id);
        if (!current || current.cashed_in_at || current.expired_at) return;

        markImmediateMiscCashExpiredStmt.run({
            id: opportunity.id,
            expired_at: new Date().toISOString()
        });

        removeImmediateMiscCashButton(current, true).catch(error =>
            console.error('[MISC IMMEDIATE CASH-IN] Expiration cleanup failed:', error)
        );
    }, delay);

    immediateMiscCashTimers.set(Number(opportunity.id), timer);
}

async function offerImmediateMiscCashIn({ userId, reward, duplicate }) {
    const inventoryItem = getImmediateMiscCashEligibility(userId, reward, duplicate);
    if (!inventoryItem) return;

    const now = new Date();
    const nowIso = now.toISOString();
    const existingOpportunity = getRecentOpenImmediateMiscCashForItemStmt.get({
        user_id: userId,
        item_id: reward.id,
        now: nowIso
    });
    if (existingOpportunity) return;

    const player = getPlayerStmt.get(userId);
    const displayName = player?.display_name || userId;
    const cleanName = await resolveCleanUserNameById(userId, displayName);
    const expiresAt = new Date(now.getTime() + MISC_IMMEDIATE_CASH_WINDOW_MS);

    const inserted = insertImmediateMiscCashOpportunityStmt.run({
        user_id: userId,
        display_name: displayName,
        inventory_row_id: inventoryItem.id,
        item_id: reward.id,
        item_name: reward.name,
        channel_id: MISC_CASH_IN_PUBLIC_CHANNEL_ID,
        created_at: nowIso,
        expires_at: expiresAt.toISOString()
    });

    const opportunityId = Number(inserted.lastInsertRowid);

    try {
        const channel = await client.channels.fetch(MISC_CASH_IN_PUBLIC_CHANNEL_ID);
        if (!channel || !channel.isTextBased()) {
            throw new Error(`Common Misc cash-in channel unavailable: ${MISC_CASH_IN_PUBLIC_CHANNEL_ID}`);
        }

        const safePlayer = escapeDiscordMarkdown(cleanName);
        const safeItem = escapeDiscordMarkdown(reward.name);
        const message = await channel.send({
            content:
                `🎁 **${safePlayer}** received **${safeItem}**.\n` +
                `Cash in for 💥 **${MISC_CASH_IN_SCORE} Smash Score**, or ignore to keep it.`,
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setCustomId(`misc_immediate_cash:${opportunityId}`)
                        .setLabel(`CASH IN +${MISC_CASH_IN_SCORE}`)
                        .setEmoji('💰')
                        .setStyle(ButtonStyle.Success)
                )
            ],
            allowedMentions: { parse: [] }
        });

        setImmediateMiscCashMessageStmt.run({ id: opportunityId, message_id: message.id });
        armImmediateMiscCashTimer(getImmediateMiscCashOpportunityStmt.get(opportunityId));

        console.log(
            `[MISC IMMEDIATE CASH-IN] Offered | ${displayName} | ${reward.name} | Expires in ${MISC_IMMEDIATE_CASH_WINDOW_MS / 1000}s`
        );
    } catch (error) {
        console.error('[MISC IMMEDIATE CASH-IN] Could not post optional cash-in button:', error);
    }
}

async function handleImmediateMiscCashButton(interaction) {
    const opportunityId = Number(interaction.customId.split(':')[1]);
    const opportunity = getImmediateMiscCashOpportunityStmt.get(opportunityId);

    if (!opportunity) {
        await interaction.reply({ content: 'This Common Misc cash-in option is no longer available.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (interaction.user.id !== opportunity.user_id) {
        await interaction.reply({ content: 'This Common Misc cash-in option belongs to another player.', flags: MessageFlags.Ephemeral });
        return;
    }

    if (opportunity.message_id !== interaction.message.id || opportunity.channel_id !== interaction.channelId) {
        await interaction.reply({ content: 'This Common Misc cash-in option is no longer valid.', flags: MessageFlags.Ephemeral });
        return;
    }

    const expired = new Date(opportunity.expires_at).getTime() <= Date.now();
    if (opportunity.cashed_in_at || opportunity.expired_at || expired) {
        clearImmediateMiscCashTimer(opportunityId);

        if (expired && !opportunity.expired_at && !opportunity.cashed_in_at) {
            markImmediateMiscCashExpiredStmt.run({
                id: opportunityId,
                expired_at: new Date().toISOString()
            });
        }

        await interaction.update({ components: [] });
        return;
    }

    await interaction.deferUpdate();
    const displayName = await getPlainDisplayName(interaction);
    let result;

    try {
        result = cashInMiscItemTransaction({
            userId: opportunity.user_id,
            inventoryRowId: opportunity.inventory_row_id,
            displayName
        });
    } catch (error) {
        console.error('[MISC IMMEDIATE CASH-IN] Transaction failed:', error);
        markImmediateMiscCashExpiredStmt.run({
            id: opportunityId,
            expired_at: new Date().toISOString()
        });
        clearImmediateMiscCashTimer(opportunityId);
        await interaction.editReply({
            content: 'The cash-in failed. Your item was not removed and no Smash Score was added.',
            components: []
        });
        return;
    }

    if (!result.ok) {
        markImmediateMiscCashExpiredStmt.run({
            id: opportunityId,
            expired_at: new Date().toISOString()
        });
        clearImmediateMiscCashTimer(opportunityId);
        await interaction.editReply({
            content:
                result.reason === 'ALREADY_CASHED'
                    ? 'That Common Misc item has already been cashed in.'
                    : result.reason === 'PLAYER_AUCTION_LOCKED'
                        ? 'That Common Misc item is currently locked in an active Player Auction.'
                        : 'That Common Misc item is no longer available to cash in.',
            components: []
        });
        return;
    }

    markImmediateMiscCashCashedStmt.run({
        id: opportunityId,
        cashed_in_at: new Date().toISOString()
    });
    clearImmediateMiscCashTimer(opportunityId);

    await interaction.editReply({
        content:
            `✅ **${escapeDiscordMarkdown(displayName)}** cashed in **${escapeDiscordMarkdown(result.item.item_name)}** for 💥 **${MISC_CASH_IN_SCORE} Smash Score**.`,
        components: []
    });

    if (result.showcaseChanged) {
        removeItemFromShowcaseManagerSession(opportunity.user_id, 'misc', result.item.item_id);
        try {
            await syncShowcasePublicMessage({
                userId: opportunity.user_id,
                displayName,
                createIfMissing: false
            });
        } catch (error) {
            console.error('[SHOWCASE] Immediate Misc cash-in refresh failed:', error);
        }
    }

    updateLeaderboard().catch(error =>
        console.error('Leaderboard refresh after immediate Common Misc cash-in failed:', error)
    );

    console.log(
        `[MISC IMMEDIATE CASH-IN] ${displayName} | ${result.item.item_name} | +${MISC_CASH_IN_SCORE} Smash Score | Balance: ${result.player.smash_score}`
    );
}

async function resumeImmediateMiscCashInOpportunitiesOnStartup() {
    const opportunities = getOpenImmediateMiscCashOpportunitiesStmt.all();
    for (const opportunity of opportunities) {
        const expired = new Date(opportunity.expires_at).getTime() <= Date.now();
        if (expired) {
            markImmediateMiscCashExpiredStmt.run({
                id: opportunity.id,
                expired_at: new Date().toISOString()
            });
            await removeImmediateMiscCashButton(opportunity, true);
        } else {
            armImmediateMiscCashTimer(opportunity);
        }
    }
}

function restoreCashedInMiscItemIfNeeded(
    userId,
    itemType,
    itemId
) {
    const now =
        new Date().toISOString();

    let restored =
        false;

    if (itemType === 'misc') {
        const miscRestored =
            restoreMiscCashStateStmt.run({
                user_id: userId,
                item_id: itemId,
                last_restored_at: now
            }).changes === 1;

        if (miscRestored) {
            restored = true;

            console.log(
                `[MISC RECOLLECT] ${userId} restored ${itemId} to visible Common Misc inventory.`
            );
        }
    }

    if (
        [
            'misc',
            'putter',
            'legendary'
        ].includes(itemType)
    ) {
        const auctionRestored =
            restorePlayerAuctionItemStmt.run({
                user_id: userId,
                item_type: itemType,
                item_id: itemId,
                last_restored_at: now
            }).changes === 1;

        if (auctionRestored) {
            restored = true;

            console.log(
                `[PLAYER AUCTION RECOLLECT] ${userId} restored ${itemType}:${itemId} to visible inventory.`
            );
        }
    }

    return restored;
}

function isPlayerAuctionState(state) {
    return Boolean(
        state &&
        String(state.auction_type || 'BOT').toUpperCase() === 'PLAYER'
    );
}

function isItemLockedByActivePlayerAuction(
    userId,
    itemType,
    itemId
) {
    const state =
        getActiveAuctionStmt.get();

    return Boolean(
        isPlayerAuctionState(state) &&
        state.seller_user_id === userId &&
        state.item_type === itemType &&
        state.item_id === itemId
    );
}

function isPlayerAuctionItemVisible(
    userId,
    item
) {
    if (
        !item ||
        ![
            'misc',
            'putter',
            'legendary'
        ].includes(item.item_type)
    ) {
        return false;
    }

    const owned =
        getInventoryItemStmt.get(
            userId,
            item.item_type,
            item.item_id
        );

    if (!owned) {
        return false;
    }

    const auctionHidden =
        getPlayerAuctionHiddenStateStmt.get(
            userId,
            item.item_type,
            item.item_id
        );

    if (
        auctionHidden &&
        Number(auctionHidden.is_hidden) === 1
    ) {
        return false;
    }

    if (item.item_type === 'misc') {
        const miscState =
            getMiscCashStateStmt.get(
                userId,
                item.item_id
            );

        if (
            miscState &&
            Number(miscState.is_hidden) === 1
        ) {
            return false;
        }
    }

    return true;
}

function getPlayerAuctionCooldownStatus(userId) {
    const row =
        getPlayerAuctionCooldownStmt.get(
            userId
        );

    if (!row) {
        return {
            available: true,
            row: null,
            remainingMs: 0
        };
    }

    const nextAvailable =
        new Date(
            row.next_available_at
        );

    if (
        Number.isNaN(nextAvailable.getTime()) ||
        nextAvailable.getTime() <= Date.now()
    ) {
        return {
            available: true,
            row,
            remainingMs: 0
        };
    }

    return {
        available: false,
        row,
        remainingMs:
            nextAvailable.getTime() -
            Date.now()
    };
}

function formatPlayerAuctionCooldown(remainingMs) {
    const totalMinutes =
        Math.max(
            1,
            Math.ceil(
                Number(remainingMs || 0) /
                60000
            )
        );

    const hours =
        Math.floor(
            totalMinutes / 60
        );

    const minutes =
        totalMinutes % 60;

    if (hours <= 0) {
        return `${minutes}m`;
    }

    return `${hours}h ${minutes}m`;
}

// ============================================================
// APPLY NORMAL RESULT + REWARD
// ============================================================

function applyResultAndReward(
    userId,
    displayName,
    result,
    reward
) {
    ensurePlayer(
        userId,
        displayName
    );

    const now =
        new Date().toISOString();

    let duplicate = false;

    const inventoryReward =
        isInventoryReward(
            reward
        );

    if (
        inventoryReward
    ) {
        const existingItem =
            getInventoryItemStmt.get(
                userId,
                reward.type,
                reward.id
            );

        if (
            existingItem
        ) {
            duplicate = true;

            restoreCashedInMiscItemIfNeeded(
                userId,
                reward.type,
                reward.id
            );
        } else {
            insertInventoryItemStmt.run({
                user_id:
                    userId,
                item_type:
                    reward.type,
                item_id:
                    reward.id,
                item_name:
                    reward.name,
                image_path:
                    reward.imagePath,
                first_collected_at:
                    now
            });
        }
    }

    const duplicateBonus =
        duplicate &&
        earnsDuplicateBonus(reward)
            ? DUPLICATE_BONUS
            : 0;

    const totalScoreEarned =
        result.baseScore +
        duplicateBonus;

    const updates = [
        'display_name = @display_name',
        'updated_at = @updated_at',
        'holes_completed = holes_completed + 1',
        'smash_score = smash_score + @score_earned'
    ];

    if (
        result.key ===
        'HOLE_IN_ONE'
    ) {
        updates.push(
            'hole_in_ones = hole_in_ones + 1'
        );
    }

    if (
        result.key ===
        'BIRDIE'
    ) {
        updates.push(
            'birdies = birdies + 1'
        );
    }

    if (
        result.key ===
        'PAR'
    ) {
        updates.push(
            'pars = pars + 1'
        );
    }

    if (
        result.key ===
        'BOGEY'
    ) {
        updates.push(
            'bogeys = bogeys + 1'
        );
    }

    if (
        result.key ===
        'STROKE_OUT'
    ) {
        updates.push(
            'stroke_outs = stroke_outs + 1'
        );
    }

    if (
        result.rarity ===
        'COMMON'
    ) {
        updates.push(
            'common_rewards = common_rewards + 1'
        );
    }

    if (
        result.rarity ===
        'RARE'
    ) {
        updates.push(
            'rare_rewards = rare_rewards + 1'
        );
    }

    if (
        result.rarity ===
        'LEGENDARY'
    ) {
        updates.push(
            'legendary_rewards = legendary_rewards + 1'
        );
    }

    if (
        duplicate &&
        earnsDuplicateBonus(reward)
    ) {
        updates.push(
            'duplicate_rewards = duplicate_rewards + 1'
        );
    }

    const updateStatement =
        db.prepare(`
            UPDATE players
            SET ${updates.join(',\n')}
            WHERE user_id = @user_id
        `);

    updateStatement.run({
        user_id:
            userId,
        display_name:
            displayName,
        updated_at:
            now,
        score_earned:
            totalScoreEarned
    });

    const player =
        getPlayerStmt.get(
            userId
        );

    return {
        player,
        duplicate,
        duplicateBonus,
        totalScoreEarned
    };
}

// ============================================================
// PASSIVE TAP WATCH
// ============================================================

const tapWatchSessions =
    new Map();

function pruneTapWatchSessions(
    now = Date.now()
) {
    for (
        const [
            sessionKey,
            session
        ]
        of tapWatchSessions
    ) {
        if (
            now - session.updatedAt >
            TAP_WATCH_SESSION_TTL_MS
        ) {
            tapWatchSessions.delete(
                sessionKey
            );
        }
    }
}

function recordTapWatchHit({
    sessionKey,
    userId,
    cleanName,
    observedAt,
    segmentKey = 'MAIN'
}) {
    try {
        const timestamp =
            Number.isFinite(
                observedAt
            )
                ? observedAt
                : Date.now();

        let session =
            tapWatchSessions.get(
                sessionKey
            );

        if (!session) {
            pruneTapWatchSessions(
                timestamp
            );

            session = {
                createdAt:
                    timestamp,
                updatedAt:
                    timestamp,
                players:
                    new Map()
            };

            tapWatchSessions.set(
                sessionKey,
                session
            );
        }

        session.updatedAt =
            Math.max(
                session.updatedAt,
                timestamp
            );

        let player =
            session.players.get(
                userId
            );

        if (!player) {
            player = {
                userId,
                cleanName:
                    cleanName ||
                    userId,
                hits:
                    0,
                timestampsBySegment:
                    new Map()
            };

            session.players.set(
                userId,
                player
            );
        }

        if (cleanName) {
            player.cleanName =
                cleanName;
        }

        let timestamps =
            player.timestampsBySegment.get(
                segmentKey
            );

        if (!timestamps) {
            timestamps = [];

            player.timestampsBySegment.set(
                segmentKey,
                timestamps
            );
        }

        timestamps.push(
            timestamp
        );

        player.hits +=
            1;
    } catch (error) {
        console.error(
            '[TAP WATCH] Could not record accepted tap:',
            error
        );
    }
}

function medianNumber(
    values
) {
    if (!values.length) {
        return null;
    }

    const sorted = [
        ...values
    ].sort(
        (a, b) =>
            a - b
    );

    const middle =
        Math.floor(
            sorted.length / 2
        );

    if (
        sorted.length % 2 === 1
    ) {
        return sorted[middle];
    }

    return (
        sorted[middle - 1] +
        sorted[middle]
    ) / 2;
}

function getTapWatchStats(
    player
) {
    if (!player) {
        return {
            hits:
                0,
            avgGapMs:
                null,
            tapsPerSecond:
                null
        };
    }

    let gapTotalMs =
        0;

    let gapCount =
        0;

    for (
        const timestamps
        of player.timestampsBySegment.values()
    ) {
        if (
            timestamps.length < 2
        ) {
            continue;
        }

        const sorted = [
            ...timestamps
        ].sort(
            (a, b) =>
                a - b
        );

        for (
            let index = 1;
            index < sorted.length;
            index += 1
        ) {
            const gap =
                sorted[index] -
                sorted[index - 1];

            if (
                gap < 0 ||
                !Number.isFinite(
                    gap
                )
            ) {
                continue;
            }

            gapTotalMs +=
                gap;

            gapCount +=
                1;
        }
    }

    const avgGapMs =
        gapCount > 0
            ? gapTotalMs /
              gapCount
            : null;

    const tapsPerSecond =
        Number.isFinite(
            avgGapMs
        ) &&
        avgGapMs > 0
            ? 1000 /
              avgGapMs
            : null;

    return {
        hits:
            player.hits,
        avgGapMs,
        tapsPerSecond
    };
}

function getTapWatchOutlierLabel(
    userId,
    statsByUser,
    allowOutliers
) {
    if (!allowOutliers) {
        return '';
    }

    const current =
        statsByUser.get(
            userId
        );

    if (
        !current ||
        current.hits <
            TAP_WATCH_MIN_OUTLIER_HITS ||
        !Number.isFinite(
            current.avgGapMs
        ) ||
        !Number.isFinite(
            current.tapsPerSecond
        )
    ) {
        return '';
    }

    const otherSpeeds = [];

    for (
        const [
            otherUserId,
            other
        ]
        of statsByUser
    ) {
        if (
            otherUserId ===
                userId ||
            other.hits <
                TAP_WATCH_MIN_OUTLIER_HITS ||
            !Number.isFinite(
                other.tapsPerSecond
            )
        ) {
            continue;
        }

        otherSpeeds.push(
            other.tapsPerSecond
        );
    }

    const comparisonMedian =
        medianNumber(
            otherSpeeds
        );

    if (
        !Number.isFinite(
            comparisonMedian
        ) ||
        comparisonMedian <= 0
    ) {
        return '';
    }

    const ratio =
        current.tapsPerSecond /
        comparisonMedian;

    if (
        current.avgGapMs <=
            TAP_WATCH_EXTREME_MAX_AVG_GAP_MS &&
        ratio >=
            TAP_WATCH_EXTREME_RATIO
    ) {
        return '🚩 EXTREME OUTLIER';
    }

    if (
        current.avgGapMs <=
            TAP_WATCH_FAST_MAX_AVG_GAP_MS &&
        ratio >=
            TAP_WATCH_FAST_RATIO
    ) {
        return '⚠️ FAST OUTLIER';
    }

    return '';
}

function safeTapWatchName(
    name
) {
    const compact =
        String(
            name ||
            'Unknown'
        )
            .replace(
                /\s+/g,
                ' '
            )
            .trim();

    if (
        compact.length <=
        22
    ) {
        return compact;
    }

    return (
        compact.slice(
            0,
            21
        ) +
        '…'
    );
}

function printTapWatchReport({
    modeLabel,
    sessionKey,
    participants,
    winnerUserIds = [],
    winnerNames = [],
    expectedHitCount = null
}) {
    try {
        const participantRows =
            Array.isArray(
                participants
            )
                ? participants
                : [];

        const session =
            tapWatchSessions.get(
                sessionKey
            );

        const summary =
            session?.players ||
            new Map();

        const winnerSet =
            new Set(
                winnerUserIds
            );

        const statsByUser =
            new Map();

        for (
            const participant
            of participantRows
        ) {
            statsByUser.set(
                participant.user_id,
                getTapWatchStats(
                    summary.get(
                        participant.user_id
                    )
                )
            );
        }

        const capturedHitCount =
            [
                ...statsByUser.values()
            ].reduce(
                (sum, stats) =>
                    sum +
                    stats.hits,
                0
            );

        const partialSample =
            Number.isFinite(
                expectedHitCount
            ) &&
            capturedHitCount !==
                expectedHitCount;

        const winnerText =
            winnerNames.length
                ? winnerNames.join(
                    ' & '
                )
                : 'Unknown';

        const header =
            `[TAP REPORT] ${modeLabel} | ` +
            `${winnerNames.length > 1 ? 'Winners' : 'Winner'}: ${winnerText}` +
            (partialSample
                ? ' | PARTIAL SAMPLE'
                : '');

        const nameWidth =
            Math.min(
                22,
                Math.max(
                    6,
                    ...participantRows.map(
                        participant =>
                            safeTapWatchName(
                                participant.clean_name ||
                                participant.display_name ||
                                participant.user_id
                            ).length
                    )
                )
            );

        const lines = [
            header
        ];

        for (
            const participant
            of participantRows
        ) {
            const stats =
                statsByUser.get(
                    participant.user_id
                );

            const displayName =
                safeTapWatchName(
                    participant.clean_name ||
                    participant.display_name ||
                    participant.user_id
                );

            const nameColumn =
                displayName.padEnd(
                    nameWidth,
                    ' '
                );

            const hitsColumn =
                `${String(stats.hits).padStart(3, ' ')} hits`;

            const gapColumn =
                Number.isFinite(
                    stats.avgGapMs
                )
                    ? `${String(Math.round(stats.avgGapMs)).padStart(4, ' ')} ms`
                    : ' n/a ms';

            const speedColumn =
                Number.isFinite(
                    stats.tapsPerSecond
                )
                    ? `${stats.tapsPerSecond.toFixed(2).padStart(5, ' ')} taps/sec`
                    : '  n/a taps/sec';

            const resultColumn =
                winnerSet.has(
                    participant.user_id
                )
                    ? 'WINNER 🏆'
                    : 'LOSS';

            const outlierLabel =
                getTapWatchOutlierLabel(
                    participant.user_id,
                    statsByUser,
                    !partialSample
                );

            lines.push(
                `${nameColumn} | ${hitsColumn} | ${gapColumn} | ${speedColumn} | ${resultColumn}` +
                (outlierLabel
                    ? ` | ${outlierLabel}`
                    : '')
            );
        }

        lines.push(
            '[TAP REPORT END]'
        );

        console.log(
            lines.join(
                '\n'
            )
        );
    } catch (error) {
        console.error(
            '[TAP WATCH] Report failed:',
            error
        );
    } finally {
        tapWatchSessions.delete(
            sessionKey
        );
    }
}

// ============================================================
// LOGGING
// ============================================================

async function sendLogMessage(
    content
) {
    try {
        const channel =
            await client.channels.fetch(
                LOG_CHANNEL_ID
            );

        if (
            !channel ||
            !channel.isTextBased()
        ) {
            console.error(
                'SmashPutt log channel could not be found.'
            );

            return;
        }

        await channel.send({
            content,
            allowedMentions: {
                parse: []
            }
        });
    } catch (error) {
        console.error(
            'Failed to send SmashPutt log message:',
            error
        );
    }
}

// ============================================================
// PUBLIC MANUAL SCORE REPORT
// ============================================================

async function sendScoreTransactionReport(
    transactionType,
    displayName,
    amount,
    reason
) {
    const channel =
        await client.channels.fetch(
            SCORE_REPORT_CHANNEL_ID
        );

    if (
        !channel ||
        !channel.isTextBased()
    ) {
        throw new Error(
            'Smash Score report channel could not be found.'
        );
    }

    const safeName =
        escapeDiscordMarkdown(
            displayName
        );

    const safeReason =
        escapeDiscordMarkdown(
            reason
        );

    const isRemoval =
        transactionType ===
        'REMOVE';

    const embed =
        new EmbedBuilder()
            .setColor(
                isRemoval
                    ? 0xE67E22
                    : 0x2ECC71
            )
            .setTitle(
                isRemoval
                    ? '💥 SMASH SCORE SPENT'
                    : '💥 SMASH SCORE ADDED'
            )
            .setDescription(
                isRemoval
                    ? `**${safeName}** spent **${amount} 💥 Smash Score**\n\n**Purpose:** ${safeReason}`
                    : `**${safeName}** received **${amount} 💥 Smash Score**\n\n**Reason:** ${safeReason}`
            );

    await channel.send({
        embeds: [
            embed
        ],
        allowedMentions: {
            parse: []
        }
    });
}

