function buildTournamentReportEmbed(
    title,
    requiredSmashes,
    events,
    finalists = null
) {
    const orderedEvents = [
        ...events
    ].sort(
        (a, b) =>
            a.smash_number -
            b.smash_number
    );

    const finalistSmashNumbers =
        new Map();

    if (
        Array.isArray(
            finalists
        ) &&
        finalists.length > 0
    ) {
        const finalistUserIds =
            new Set(
                finalists
                    .map(
                        finalist =>
                            finalist.userId
                    )
                    .filter(Boolean)
            );

        for (
            let index =
                orderedEvents.length - 1;
            index >= 0;
            index--
        ) {
            const event =
                orderedEvents[index];

            if (
                finalistUserIds.has(
                    event.user_id
                ) &&
                !finalistSmashNumbers.has(
                    event.user_id
                )
            ) {
                finalistSmashNumbers.set(
                    event.user_id,
                    event.smash_number
                );
            }
        }
    }

    const lines =
        orderedEvents.map(
            event => {
                const safeName =
                    escapeDiscordMarkdown(
                        event.display_name
                    );

                const isFinalistSmash =
                    finalistSmashNumbers.get(
                        event.user_id
                    ) ===
                    event.smash_number;

                if (
                    event.smash_number ===
                    requiredSmashes
                ) {
                    return (
                        `🎯 ${event.smash_number}/${requiredSmashes} — ` +
                        `**${safeName} — FINAL SMASH${isFinalistSmash ? ' • FINALIST' : ''}**`
                    );
                }

                if (
                    isFinalistSmash
                ) {
                    return (
                        `🏆 ${event.smash_number}/${requiredSmashes} — ` +
                        `**${safeName} — FINALIST**`
                    );
                }

                return (
                    `${event.smash_number}/${requiredSmashes} — ${safeName}`
                );
            }
        );

    if (
        Array.isArray(
            finalists
        ) &&
        finalists.length >= 2
    ) {
        const advancingNames =
            finalists
                .map(
                    finalist =>
                        escapeDiscordMarkdown(
                            finalist.cleanName
                        )
                )
                .join(' & ');

        lines.push(
            '',
            `➡️ **${advancingNames} advance to the Final**`
        );
    }

    return new EmbedBuilder()
        .setColor(
            0xE67E22
        )
        .setTitle(
            title
        )
        .setDescription(
            lines.join('\n')
        );
}

