// ============================================================
// PLAYER 1V1 DUEL CHALLENGE
// ============================================================

let duelChallengeTimer = null;
let duelChallengeMutationInProgress = false;

function clearDuelChallengeTimer() {
    if (duelChallengeTimer) {
        clearTimeout(duelChallengeTimer);
        duelChallengeTimer = null;
    }
}

function getDuelChallengeCooldownStatus(userId) {
    const row = getDuelChallengeCooldownStmt.get(userId);
    if (!row) return { available: true, remainingMs: 0 };
    const next = new Date(row.next_available_at);
    if (Number.isNaN(next.getTime()) || next.getTime() <= Date.now()) {
        return { available: true, remainingMs: 0 };
    }
    return { available: false, remainingMs: next.getTime() - Date.now() };
}

function formatDuelChallengeCooldown(remainingMs) {
    const totalMinutes = Math.max(1, Math.ceil(Number(remainingMs || 0) / 60000));
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    if (hours > 0 && minutes > 0) return `${hours}h ${minutes}m`;
    if (hours > 0) return `${hours}h`;
    return `${minutes}m`;
}

function buildDuelTargetSelectRow(challengerId) {
    return new ActionRowBuilder().addComponents(
        new UserSelectMenuBuilder()
            .setCustomId(`duel_target_select:${challengerId}`)
            .setPlaceholder('Choose who you want to duel')
            .setMinValues(1)
            .setMaxValues(1)
    );
}

function buildDuelChallengeEmbed(state, expiredText = null) {
    const challenger = escapeDiscordMarkdown(state.challenger_clean_name || state.challenger_display_name || 'Player');
    const target = escapeDiscordMarkdown(state.target_clean_name || state.target_display_name || 'Player');
    let description = `⚔️ **${challenger} challenged ${target} to a duel!**\n\n`;
    if (expiredText) {
        description += expiredText;
    } else {
        const expiresUnix = Math.floor(new Date(state.expires_at).getTime() / 1000);
        description += `⏱️ **60 seconds to accept** • <t:${expiresUnix}:R>\n` +
            `Only **${target}** can accept or decline this challenge.`;
    }
    return new EmbedBuilder()
        .setColor(0xE10600)
        .setTitle('⚔️ 1V1 DUEL CHALLENGE')
        .setDescription(description)
        .setImage(SMASH_1V1_IMAGE_URL);
}

function buildDuelChallengeButtons(disabled = false) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId('duel_challenge_accept')
            .setLabel('ACCEPT')
            .setEmoji('✅')
            .setStyle(ButtonStyle.Success)
            .setDisabled(disabled),
        new ButtonBuilder()
            .setCustomId('duel_challenge_decline')
            .setLabel('DECLINE')
            .setEmoji('❌')
            .setStyle(ButtonStyle.Danger)
            .setDisabled(disabled)
    );
}

async function fetchDuelChallengeMessage(state) {
    const channel = await client.channels.fetch(state.channel_id);
    if (!channel || !channel.isTextBased() || !channel.messages) {
        throw new Error(`Duel challenge channel could not be found: ${state.channel_id}`);
    }
    const message = await channel.messages.fetch(state.message_id);
    return { channel, message };
}

async function expireDuelChallenge(challengeKey, reason = 'Challenge expired — no duel started.') {
    const state = getPendingDuelChallengeStmt.get();
    if (!state || state.challenge_key !== challengeKey) return;
    clearDuelChallengeTimer();
    closeDuelChallengeStmt.run({
        challenge_key: challengeKey,
        status: 'EXPIRED',
        completed_at: new Date().toISOString()
    });
    try {
        const { message } = await fetchDuelChallengeMessage(state);
        await message.edit({
            embeds: [buildDuelChallengeEmbed(state, `⌛ **${reason}**`)],
            components: [buildDuelChallengeButtons(true)]
        });
    } catch (error) {
        console.error('[1V1 DUEL] Could not update expired challenge:', error);
    }
    console.log(`[1V1 DUEL] Expired ${challengeKey}.`);
    if (!hasActiveSmashPuttActivity()) {
        await scheduleNextAutoSpawn({ forceNew: true, reason: '1v1 duel challenge expired' });
    }
}

function armDuelChallengeTimer(state) {
    clearDuelChallengeTimer();
    const dueAt = new Date(state.expires_at).getTime();
    const delay = Math.max(0, dueAt - Date.now());
    duelChallengeTimer = setTimeout(() => {
        duelChallengeTimer = null;
        expireDuelChallenge(state.challenge_key).catch(error =>
            console.error('[1V1 DUEL] Expiry timer failed:', error)
        );
    }, delay);
}

async function handlePurchasePanelDuelButton(interaction) {
    const storedMessageId = getSetting(PURCHASE_PANEL_MESSAGE_SETTING);
    if (!storedMessageId || interaction.message.id !== storedMessageId) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }

    if (interaction.channelId !== PURCHASE_PANEL_CHANNEL_ID) {
        await interaction.reply({
            content: '1V1 Duels are only available from the official SmashPutt Purchases panel.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const cooldown = getDuelChallengeCooldownStatus(interaction.user.id);
    if (!cooldown.available) {
        await interaction.reply({
            content: `Your next 1V1 Duel is available in **${formatDuelChallengeCooldown(cooldown.remainingMs)}**.`,
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    if (hasActiveSmashPuttActivity()) {
        await interaction.reply({
            content: 'SmashPutt is busy with another activity right now. Try again after it finishes.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferReply({ flags: MessageFlags.Ephemeral });

    pauseSchedulerForActiveGame();

    const result = await createSmash1v1InChannel(PURCHASE_PANEL_CHANNEL_ID, 'PLAYER');

    if (!result.ok) {
        if (getSchedulerFrequency() !== 'OFF' && !hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: true, reason: 'player 1v1 launch failed' });
        }
        await interaction.editReply({
            content: 'The 1V1 lobby could not be started. No cooldown was used.'
        });
        return;
    }

    const now = new Date();
    upsertDuelChallengeCooldownStmt.run({
        user_id: interaction.user.id,
        last_started_at: now.toISOString(),
        next_available_at: new Date(now.getTime() + DUEL_CHALLENGE_COOLDOWN_MS).toISOString()
    });

    await interaction.editReply({
        content: '✅ Open 1V1 lobby started. Anyone can join. Your next 1V1 Duel activation is available in 1 hour.'
    });
}

async function handleDuelTargetSelect(interaction) {
    const [, challengerId] = interaction.customId.split(':');
    if (interaction.user.id !== challengerId) {
        await interaction.reply({ content: 'This duel selector is not yours.', flags: MessageFlags.Ephemeral });
        return;
    }
    if (duelChallengeMutationInProgress) {
        await interaction.reply({ content: 'A duel challenge is already being created. Try again in a moment.', flags: MessageFlags.Ephemeral });
        return;
    }
    const targetId = interaction.values[0];
    if (!targetId || targetId === challengerId) {
        await interaction.update({ content: 'You cannot challenge yourself. Choose another player.', components: [buildDuelTargetSelectRow(challengerId)] });
        return;
    }
    duelChallengeMutationInProgress = true;
    try {
        const cooldown = getDuelChallengeCooldownStatus(challengerId);
        if (!cooldown.available) {
            await interaction.update({ content: `Your next 1V1 Duel challenge is available in **${formatDuelChallengeCooldown(cooldown.remainingMs)}**.`, components: [] });
            return;
        }
        if (hasActiveSmashPuttActivity()) {
            await interaction.update({ content: 'SmashPutt became busy before the challenge could be sent. No duel was created.', components: [] });
            return;
        }
        const targetMember = await interaction.guild.members.fetch(targetId).catch(() => null);
        if (!targetMember || targetMember.user.bot) {
            await interaction.update({ content: 'Choose a human server member for the duel.', components: [buildDuelTargetSelectRow(challengerId)] });
            return;
        }
        const challengerMember = await interaction.guild.members.fetch(challengerId).catch(() => interaction.member);
        const challengerDisplayName = challengerMember?.displayName || getCleanUserName(interaction.user);
        const challengerCleanName = getCleanUserName(interaction.user);
        const targetDisplayName = targetMember.displayName || getCleanUserName(targetMember.user);
        const targetCleanName = getCleanUserName(targetMember.user);
        const channel = await client.channels.fetch(PURCHASE_PANEL_CHANNEL_ID);
        if (!channel || !channel.isTextBased()) throw new Error('Player/play channel unavailable for duel challenge.');
        const createdAt = new Date();
        const expiresAt = new Date(createdAt.getTime() + DUEL_CHALLENGE_ACCEPT_MS);
        const provisional = {
            challenger_clean_name: challengerCleanName,
            challenger_display_name: challengerDisplayName,
            target_clean_name: targetCleanName,
            target_display_name: targetDisplayName,
            expires_at: expiresAt.toISOString()
        };
        const message = await channel.send({
            embeds: [buildDuelChallengeEmbed(provisional)],
            components: [buildDuelChallengeButtons(false)],
            allowedMentions: { parse: [] }
        });
        const state = {
            challenge_key: message.id,
            status: 'PENDING',
            channel_id: channel.id,
            message_id: message.id,
            challenger_user_id: challengerId,
            challenger_display_name: challengerDisplayName,
            challenger_clean_name: challengerCleanName,
            target_user_id: targetId,
            target_display_name: targetDisplayName,
            target_clean_name: targetCleanName,
            created_at: createdAt.toISOString(),
            expires_at: expiresAt.toISOString()
        };
        upsertDuelChallengeStmt.run(state);
        pauseSchedulerForActiveGame();
        armDuelChallengeTimer(state);
        await interaction.update({
            content: `✅ Your 1V1 Duel challenge to **${escapeDiscordMarkdown(targetCleanName)}** is live for 60 seconds.`,
            components: []
        });
        console.log(`[1V1 DUEL] ${challengerCleanName} challenged ${targetCleanName} | ${message.id}`);
    } catch (error) {
        console.error('[1V1 DUEL] Could not create challenge:', error);
        try { await interaction.update({ content: 'The duel challenge could not be created. Try again later.', components: [] }); } catch (_) {}
    } finally {
        duelChallengeMutationInProgress = false;
    }
}

async function startAcceptedDuelBattle(state, interaction) {
    const battleKey = state.challenge_key;
    const readyAt = new Date(Date.now() + SMASH_1V1_READY_MS);
    const requiredSmashes = randomItem(SMASH_1V1_TARGET_SMASHES);
    const startedAt = new Date();

    createSmash1v1Stmt.run({
        battle_key: battleKey,
        channel_id: state.channel_id,
        control_message_id: state.message_id,
        started_at: startedAt.toISOString(),
        join_deadline_at: startedAt.toISOString()
    });

    // Remove any stale player rows for this message id, then seed exactly the two duelists.
    db.prepare(`DELETE FROM smash_1v1_players WHERE battle_key = ?`).run(battleKey);
    insertSmash1v1PlayerStmt.run({
        battle_key: battleKey,
        user_id: state.challenger_user_id,
        display_name: state.challenger_display_name,
        clean_name: state.challenger_clean_name,
        join_order: 1,
        joined_at: startedAt.toISOString()
    });
    insertSmash1v1PlayerStmt.run({
        battle_key: battleKey,
        user_id: state.target_user_id,
        display_name: state.target_display_name,
        clean_name: state.target_clean_name,
        join_order: 2,
        joined_at: startedAt.toISOString()
    });

    db.prepare(`
        UPDATE smash_1v1_state
        SET status = 'READY', ready_at = @ready_at,
            required_smashes = @required_smashes, current_smashes = 0
        WHERE id = 1 AND battle_key = @battle_key
    `).run({
        battle_key: battleKey,
        ready_at: readyAt.toISOString(),
        required_smashes: requiredSmashes
    });

    const players = getSmash1v1PlayersStmt.all(battleKey);
    await interaction.message.edit({
        embeds: [buildSmash1v1BattleEmbed(players, false)],
        components: [buildSmash1v1ReadyButton()]
    });

    const cooldownStartedAt = new Date();
    upsertDuelChallengeCooldownStmt.run({
        user_id: state.challenger_user_id,
        last_started_at: cooldownStartedAt.toISOString(),
        next_available_at: new Date(cooldownStartedAt.getTime() + DUEL_CHALLENGE_COOLDOWN_MS).toISOString()
    });

    clearDuelChallengeTimer();
    closeDuelChallengeStmt.run({
        challenge_key: state.challenge_key,
        status: 'ACCEPTED',
        completed_at: new Date().toISOString()
    });

    armSmash1v1PhaseTimer(readyAt, () => activateSmash1v1Battle(battleKey));
    console.log(`[1V1 DUEL] Accepted | ${state.challenger_clean_name} vs ${state.target_clean_name} | Hidden target: ${requiredSmashes}`);
}

async function handleDuelChallengeButton(interaction, action) {
    const state = getPendingDuelChallengeStmt.get();
    if (!state || interaction.message.id !== state.message_id || interaction.channelId !== state.channel_id) {
        try { await interaction.deferUpdate(); } catch (_) {}
        return;
    }
    if (interaction.user.id !== state.target_user_id) {
        await interaction.reply({ content: 'This duel challenge is not for you.', flags: MessageFlags.Ephemeral });
        return;
    }
    if (action === 'DECLINE') {
        await interaction.deferUpdate();
        clearDuelChallengeTimer();
        closeDuelChallengeStmt.run({
            challenge_key: state.challenge_key,
            status: 'DECLINED',
            completed_at: new Date().toISOString()
        });
        await interaction.message.edit({
            embeds: [buildDuelChallengeEmbed(state, `❌ **${escapeDiscordMarkdown(state.target_clean_name)} declined the duel.**`)],
            components: [buildDuelChallengeButtons(true)]
        });
        console.log(`[1V1 DUEL] Declined | ${state.challenger_clean_name} vs ${state.target_clean_name}`);
        if (!hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: true, reason: '1v1 duel declined' });
        }
        return;
    }

    await interaction.deferUpdate();
    try {
        await startAcceptedDuelBattle(state, interaction);
    } catch (error) {
        console.error('[1V1 DUEL] Accept/start failed:', error);
        clearDuelChallengeTimer();
        const failedBattle = getActiveSmash1v1Stmt.get();
        if (failedBattle && failedBattle.battle_key === state.challenge_key) {
            cancelSmash1v1Stmt.run({
                battle_key: state.challenge_key,
                completed_at: new Date().toISOString()
            });
            db.prepare(`DELETE FROM smash_1v1_players WHERE battle_key = ?`).run(state.challenge_key);
        }
        closeDuelChallengeStmt.run({
            challenge_key: state.challenge_key,
            status: 'CANCELLED',
            completed_at: new Date().toISOString()
        });
        try {
            await interaction.message.edit({
                embeds: [buildDuelChallengeEmbed(state, '⚠️ **The duel could not be started. No cooldown was used.**')],
                components: [buildDuelChallengeButtons(true)]
            });
        } catch (_) {}
        if (!hasActiveSmashPuttActivity()) {
            await scheduleNextAutoSpawn({ forceNew: true, reason: '1v1 duel start failed' });
        }
    }
}

async function resumeDuelChallengeOnStartup() {
    clearDuelChallengeTimer();
    const state = getPendingDuelChallengeStmt.get();

    if (!state) {
        console.log('No legacy pending 1V1 Duel challenge currently exists.');
        return;
    }

    closeDuelChallengeStmt.run({
        challenge_key: state.challenge_key,
        status: 'CANCELLED',
        completed_at: new Date().toISOString()
    });

    try {
        const { message } = await fetchDuelChallengeMessage(state);
        await message.edit({
            embeds: [buildDuelChallengeEmbed(state, '⚠️ **This legacy direct challenge was retired. Use the 1V1 DUEL panel button to open a lobby.**')],
            components: []
        });
    } catch (_) {}

    console.log(`[1V1 DUEL] Retired legacy pending direct challenge ${state.challenge_key}.`);
}

