function buildSmash1v1JoinEmbed(
    players
) {
    const names =
        players.length
            ? players
                .map(
                    player =>
                        escapeDiscordMarkdown(
                            player.clean_name
                        )
                )
                .join(' • ')
            : '*Waiting for players...*';

    return new EmbedBuilder()
        .setColor(
            0xE10600
        )
        .setTitle(
            '💥 SMASH 1 V 1 BATTLE'
        )
        .setDescription(
            `Players: **${players.length} / ${SMASH_1V1_PLAYER_COUNT}**\n` +
            `${names}`
        )
        .setImage(
            SMASH_1V1_IMAGE_URL
        );
}

function buildSmash1v1RaceLines(
    players
) {
    const orderedPlayers = [
        ...players
    ].sort(
        (a, b) =>
            a.join_order -
            b.join_order
    );

    return orderedPlayers
        .map(
            player => {
                const safeName =
                    escapeDiscordMarkdown(
                        player.clean_name
                    );

                const count =
                    Math.max(
                        0,
                        Number(
                            player.smash_count
                        ) || 0
                    );

                const bar =
                    count > 0
                        ? '█'.repeat(
                            count
                        )
                        : '░';

                return (
                    `${safeName}\n${bar}  **${count}**`
                );
            }
        )
        .join('\n\n');
}

function buildSmash1v1ReadyPlayerList(
    players
) {
    return [...players]
        .sort(
            (a, b) =>
                a.join_order -
                b.join_order
        )
        .map(
            player =>
                escapeDiscordMarkdown(
                    player.clean_name
                )
        )
        .join('\n');
}

