function getDoublesTeamPlayers(
    players,
    teamKey
) {
    return players
        .filter(
            player =>
                player.team_key === teamKey
        )
        .sort(
            (a, b) =>
                a.join_order -
                b.join_order
        );
}

function buildDoublesTeamSection(
    players,
    teamKey,
    includeCounts = false
) {
    const teamPlayers =
        getDoublesTeamPlayers(
            players,
            teamKey
        );

    const lines = [
        `**TEAM ${teamKey}**`
    ];

    for (
        let index = 0;
        index < 2;
        index++
    ) {
        const player =
            teamPlayers[index];

        if (!player) {
            lines.push(
                '*Waiting...*'
            );

            continue;
        }

        const safeName =
            escapeDiscordMarkdown(
                player.clean_name
            );

        if (
            includeCounts
        ) {
            lines.push(
                `${safeName} — **${player.smash_count} smashes**`
            );
        } else {
            lines.push(
                safeName
            );
        }
    }

    if (
        includeCounts
    ) {
        const total =
            teamPlayers.reduce(
                (sum, player) =>
                    sum +
                    player.smash_count,
                0
            );

        const bar =
            total > 0
                ? '█'.repeat(
                    total
                )
                : '░';

        lines.push(
            `${bar}  **${total}**`
        );
    }

    return lines.join('\n');
}

function buildDoublesLiveTeamSection(
    players,
    teamKey
) {
    const teamPlayers =
        getDoublesTeamPlayers(
            players,
            teamKey
        );

    const lines = [
        `**TEAM ${teamKey}**`
    ];

    for (
        let index = 0;
        index < 2;
        index++
    ) {
        const player =
            teamPlayers[index];

        if (!player) {
            lines.push(
                '*Waiting...*'
            );

            continue;
        }

        lines.push(
            escapeDiscordMarkdown(
                player.clean_name
            )
        );
    }

    const total =
        teamPlayers.reduce(
            (sum, player) =>
                sum +
                (Number(player.smash_count) || 0),
            0
        );

    const bar =
        total > 0
            ? '█'.repeat(
                total
            )
            : '░';

    lines.push(
        `${bar}  **${total}**`
    );

    return lines.join('\n');
}

