function buildVaultDropPlayerList(
    players,
    includeCounts = false
) {
    if (
        !players ||
        players.length === 0
    ) {
        return '*Waiting for players...*';
    }

    return players
        .sort(
            (a, b) =>
                a.join_order -
                b.join_order
        )
        .map(
            player => {
                const safeName =
                    escapeDiscordMarkdown(
                        player.clean_name
                    );

                if (
                    includeCounts
                ) {
                    return (
                        `${player.join_order}. ${safeName} — ` +
                        `**${player.smash_count} smashes**`
                    );
                }

                return (
                    `${player.join_order}. ${safeName}`
                );
            }
        )
        .join('\n');
}

function buildVaultDropLivePlayerList(
    players,
    targetSmashes
) {
    if (
        !players ||
        players.length === 0
    ) {
        return '*Waiting for players...*';
    }

    const target =
        Math.max(
            1,
            Number(targetSmashes) ||
            VAULT_DROP_TARGET_SMASHES
        );

    return [...players]
        .sort(
            (a, b) =>
                a.join_order -
                b.join_order
        )
        .map(
            player => {
                const safeName =
                    escapeDiscordMarkdown(
                        player.clean_name
                    );

                const count =
                    Math.max(
                        0,
                        Math.min(
                            Number(player.smash_count) || 0,
                            target
                        )
                    );

                const filled =
                    '█'.repeat(
                        count
                    );

                const empty =
                    '░'.repeat(
                        target -
                        count
                    );

                return (
                    `${player.join_order}. ${safeName} — ` +
                    `${filled}${empty} **${count}**`
                );
            }
        )
        .join('\n');
}

function getVaultDropSelectionLabel(
    selectionSource
) {
    switch (
        String(selectionSource || 'RANDOM').toUpperCase()
    ) {
        case 'COMMON':
            return '🟢 **COMMON VAULT DROP**';

        case 'RARE':
            return '🔵 **RARE VAULT DROP**';

        case 'LEGENDARY':
            return '🟠 **LEGENDARY VAULT DROP**';

        case 'FEATURED':
            return '🎯 **FEATURED VAULT DROP ITEM**';

        default:
            return '🎲 **RANDOMLY SELECTED ITEM**';
    }
}

function buildVaultDropEmbed(
    state,
    players,
    phase
) {
    let phaseText = '';

    if (
        phase === 'JOINING'
    ) {
        phaseText =
            '⏱️ **30 seconds to join.**';
    } else if (
        phase === 'READY'
    ) {
        phaseText =
            '⏱️ **GET READY — 10 SECONDS**';
    } else if (
        phase === 'ACTIVE'
    ) {
        phaseText =
            '👊 **SMASH!**';
    }

    const sponsored = Boolean(state.sponsor_name);
    const attachmentName = sponsored
        ? null
        : `vault-drop-item${path.extname(state.item_image_path)}`;

    const playerHeading =
        phase === 'ACTIVE'
            ? '🔥 **LIVE SMASH RACE**'
            : '**PLAYERS**';

    const playerDisplay =
        phase === 'ACTIVE'
            ? buildVaultDropLivePlayerList(
                players,
                state.target_smashes
            )
            : buildVaultDropPlayerList(
                players
            );

    const sponsorLine = sponsored
        ? `💥 Sponsored by **${escapeDiscordMarkdown(state.sponsor_name)}**\n\n`
        : '';

    const rewardDisplay = sponsored
        ? '🎁 **MYSTERY REWARD**'
        : `${getVaultDropSelectionLabel(state.selection_source)}\n` +
          `🎁 **${escapeDiscordMarkdown(state.item_name)}**`;

    const embed = new EmbedBuilder()
        .setColor(
            0x9B59B6
        )
        .setTitle(
            sponsored
                ? '🏦 PLAYER-SPONSORED VAULT DROP'
                : '💥 SMASHPUTT VAULT DROP'
        )
        .setDescription(
            `${sponsorLine}` +
            `${rewardDisplay}\n\n` +
            `First player to reach **${state.target_smashes} REGISTERED SMASHES** wins!\n\n` +
            `${playerHeading}\n` +
            `${playerDisplay}\n\n` +
            `${phaseText}`
        );

    embed.setImage(
        sponsored
            ? 'attachment://vault-drop-mystery.png'
            : `attachment://${attachmentName}`
    );

    return embed;
}

