function getPlayerAuctionInitials(displayName) {
    const parts =
        String(displayName || 'Player')
            .trim()
            .split(/\s+/)
            .filter(Boolean);

    if (parts.length === 0) {
        return 'P';
    }

    return parts
        .slice(0, 2)
        .map(part => part.charAt(0).toUpperCase())
        .join('');
}

async function generatePlayerAuctionBanner({
    displayName,
    avatarUrl
}) {
    const width = 1000;
    const height = 220;
    const avatarSize = 160;
    const avatarLeft = 42;
    const avatarTop = 30;

    let avatarBuffer = null;

    if (avatarUrl) {
        try {
            const response =
                await fetch(
                    avatarUrl
                );

            if (response.ok) {
                avatarBuffer =
                    Buffer.from(
                        await response.arrayBuffer()
                    );
            }
        } catch (error) {
            console.error(
                '[PLAYER AUCTION] Seller avatar download failed; using initials fallback:',
                error
            );
        }
    }

    const safeName =
        escapeXml(
            String(displayName || 'Player')
                .slice(0, 46)
        );

    const initials =
        escapeXml(
            getPlayerAuctionInitials(
                displayName
            )
        );

    const backgroundSvg = `
        <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <defs>
                <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0%" stop-color="#0b0d10"/>
                    <stop offset="100%" stop-color="#171a1f"/>
                </linearGradient>
                <linearGradient id="gold" x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0%" stop-color="#f1d07a"/>
                    <stop offset="50%" stop-color="#c99938"/>
                    <stop offset="100%" stop-color="#f4db91"/>
                </linearGradient>
            </defs>
            <rect width="100%" height="100%" rx="20" fill="url(#bg)"/>
            <rect x="4" y="4" width="992" height="212" rx="18" fill="none" stroke="#8c6a2b" stroke-width="2"/>
            <rect x="225" y="50" width="5" height="120" rx="2" fill="url(#gold)" opacity="0.9"/>
            <circle cx="${avatarLeft + avatarSize / 2}" cy="${avatarTop + avatarSize / 2}" r="83" fill="#111318" stroke="#d1a94f" stroke-width="4"/>
            ${
                avatarBuffer
                    ? ''
                    : `<circle cx="${avatarLeft + avatarSize / 2}" cy="${avatarTop + avatarSize / 2}" r="76" fill="#252930"/>
                       <text x="${avatarLeft + avatarSize / 2}" y="${avatarTop + avatarSize / 2 + 18}" text-anchor="middle" font-family="sans-serif" font-size="54" font-weight="800" fill="#f1d07a">${initials}</text>`
            }
            <text x="270" y="92" font-family="sans-serif" font-size="42" font-weight="800" fill="#f3f4f6" letter-spacing="3">PLAYER AUCTION</text>
            <text x="270" y="148" font-family="sans-serif" font-size="38" font-weight="650" fill="url(#gold)">${safeName}</text>
        </svg>
    `;

    const composites = [];

    if (avatarBuffer) {
        const circleMask =
            Buffer.from(`
                <svg width="${avatarSize}" height="${avatarSize}" xmlns="http://www.w3.org/2000/svg">
                    <circle cx="${avatarSize / 2}" cy="${avatarSize / 2}" r="${avatarSize / 2}" fill="white"/>
                </svg>
            `);

        const avatar =
            await sharp(avatarBuffer)
                .resize(
                    avatarSize,
                    avatarSize,
                    { fit: 'cover' }
                )
                .composite([
                    {
                        input: circleMask,
                        blend: 'dest-in'
                    }
                ])
                .png()
                .toBuffer();

        composites.push({
            input: avatar,
            left: avatarLeft,
            top: avatarTop
        });
    }

    return sharp(
        Buffer.from(backgroundSvg)
    )
        .composite(composites)
        .png()
        .toBuffer();
}

