function getPersonalPileOnTargetSmashes(
    state
) {
    return (
        1 +
        Math.max(
            0,
            Math.min(
                PERSONAL_PILE_ON_MAX_EXTRA_SMASHES,
                Number(
                    state?.pile_on_extra_smashes
                ) || 0
            )
        )
    );
}

function buildPersonalPileOnProgressBar(
    currentSmashes,
    targetSmashes
) {
    const width = 20;

    const target =
        Math.max(
            1,
            Number(targetSmashes) || 1
        );

    const current =
        Math.max(
            0,
            Math.min(
                Number(currentSmashes) || 0,
                target
            )
        );

    const filledCount =
        Math.min(
            width,
            Math.floor(
                current / target * width
            )
        );

    return (
        `${'█'.repeat(filledCount)}${'░'.repeat(width - filledCount)} ` +
        `**${current} / ${target}**`
    );
}

function buildPersonalPileOnControls(
    state
) {
    const maxed =
        (
            Number(
                state?.pile_on_extra_smashes
            ) || 0
        ) >=
        PERSONAL_PILE_ON_MAX_EXTRA_SMASHES;

    return new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId(
                    PERSONAL_PILE_ON_SMASH_BUTTON_ID
                )
                .setLabel(
                    'SMASH!'
                )
                .setEmoji(
                    '💥'
                )
                .setStyle(
                    ButtonStyle.Success
                ),
            new ButtonBuilder()
                .setCustomId(
                    PERSONAL_PILE_ON_ADD_BUTTON_ID
                )
                .setLabel(
                    maxed
                        ? 'MAXED OUT'
                        : 'ADD 10 SMASHES'
                )
                .setEmoji(
                    maxed
                        ? '🔒'
                        : '💥'
                )
                .setStyle(
                    ButtonStyle.Danger
                )
                .setDisabled(
                    maxed
                )
        );
}

