function buildPersonalCompletionEmbed(
    state,
    reward,
    duplicate,
    attachmentName
) {
    const rarityEmoji =
        getRarityEmoji(
            state.reward_rarity
        );

    let description =
        `⛳ **+1 Hole Completed**\n\n` +
        `${rarityEmoji} **${state.reward_rarity} REWARD**\n` +
        `**${escapeDiscordMarkdown(reward.name)}**`;

    if (
        reward.type ===
        'misc'
    ) {
        if (duplicate) {
            description +=
                `\n\n🎒 Already in your Misc collection.`;
        } else {
            description +=
                `\n\n🎒 Added to your Misc collection — view it in **#smashputt-inventory**.`;
        }
    } else if (
        duplicate
    ) {
        description +=
            `\n\n🔁 **DUPLICATE — NO SMASH SCORE BONUS ON PURCHASED HOLES**\n` +
            `🎒 Already in your collection — view in **#smashputt-inventory**.`;
    } else {
        description +=
            `\n\n${INVENTORY_PROMPT_TEXT}`;
    }

    const embed =
        new EmbedBuilder()
            .setColor(
                state.reward_rarity === 'LEGENDARY'
                    ? 0xF39C12
                    : state.reward_rarity === 'RARE'
                        ? 0x3498DB
                        : 0x2ECC71
            )
            .setTitle(
                `🎟️ ${escapeDiscordMarkdown(state.clean_name).toUpperCase()}'S PERSONAL SMASHPUTT`
            )
            .setDescription(
                description
            );

    if (
        attachmentName
    ) {
        embed.setImage(
            `attachment://${attachmentName}`
        );
    }

    return embed;
}

// ============================================================
// LEADERBOARD
// ============================================================

function getWeeklySmashPuttStandings(
    date = new Date()
) {
    const window =
        getCentralWeekWindow(date);

    return {
        window,
        standings:
            getWeeklySmashPuttStandingsStmt.all(
                window.startDate.toISOString(),
                window.endDate.toISOString()
            )
    };
}

async function buildLeaderboardEmbed() {
    const players =
        getLeaderboardPlayersStmt.all();

    const totals =
        getLeaderboardTotalsStmt.get();

    const weekly =
        getWeeklySmashPuttStandings();

    const userIds =
        new Set(
            players.map(
                player =>
                    player.user_id
            )
        );

    if (
        weekly.standings.length > 0
    ) {
        userIds.add(
            weekly.standings[0].user_id
        );
    }

    const fallbackNames =
        new Map(
            players.map(
                player => [
                    player.user_id,
                    player.display_name
                ]
            )
        );

    for (const standing of weekly.standings) {
        if (
            !fallbackNames.has(
                standing.user_id
            )
        ) {
            fallbackNames.set(
                standing.user_id,
                standing.display_name
            );
        }
    }

    const cleanNames =
        new Map();

    await Promise.all(
        [...userIds].map(
            async userId => {
                cleanNames.set(
                    userId,
                    await resolveCleanUserNameById(
                        userId,
                        fallbackNames.get(userId) ||
                            'Player'
                    )
                );
            }
        )
    );

    let rankingText = '';

    if (
        players.length === 0
    ) {
        rankingText =
            '*No SmashPutt holes have been completed yet.*';
    } else {
        rankingText =
            players
                .map(
                    (player, index) => {
                        const name =
                            escapeDiscordMarkdown(
                                cleanNames.get(
                                    player.user_id
                                ) ||
                                player.display_name
                            );

                        const crown =
                            index === 0
                                ? ' 👑'
                                : '';

                        return (
                            `**#${index + 1}**${crown} ⛳ ${player.holes_completed} • ${name} • 💥${player.smash_score}`
                        );
                    }
                )
                .join('\n');
    }

    let weeklyLeaderText =
        '🔥 This Week\'s Leader: **No holes completed yet**';

    if (
        weekly.standings.length > 0
    ) {
        const leader =
            weekly.standings[0];

        const leaderName =
            escapeDiscordMarkdown(
                cleanNames.get(
                    leader.user_id
                ) ||
                leader.display_name
            );

        weeklyLeaderText =
            `🔥 This Week's Leader: **${leaderName} — ⛳ ${leader.holes}**`;
    }

    return new EmbedBuilder()
        .setColor(
            0x2ECC71
        )
        .setTitle(
            '💥 SMASH PUTT LEADERBOARD'
        )
        .setDescription(
            `**Top 50 • Ranked by Holes Completed**\n\n` +
            `🏌️ Players: **${totals.players}**\n` +
            `⛳ SmashPutt Holes Completed: **${totals.holes}**\n` +
            `🟠 Legendary Rewards Found: **${totals.legendary}**\n` +
            `${weeklyLeaderText}\n\n` +
            `${rankingText}`
        )
        .setFooter({
            text:
                `Last updated: ${getCentralTimeString()}`
        });
}

let leaderboardUpdateRunning =
    false;

let leaderboardUpdatePending =
    false;

async function performLeaderboardUpdate() {
    const channel =
        await client.channels.fetch(
            LEADERBOARD_CHANNEL_ID
        );

    if (
        !channel ||
        !channel.isTextBased() ||
        !channel.messages
    ) {
        throw new Error(
            'Leaderboard channel could not be found.'
        );
    }

    const embed =
        await buildLeaderboardEmbed();

    const components = [
        buildLeaderboardButtonRow()
    ];

    const storedMessageId =
        getSetting(
            LEADERBOARD_MESSAGE_SETTING
        );

    let leaderboardMessage =
        null;

    if (
        storedMessageId
    ) {
        try {
            leaderboardMessage =
                await channel.messages.fetch(
                    storedMessageId
                );
        } catch (_) {
            leaderboardMessage =
                null;
        }
    }

    if (
        leaderboardMessage
    ) {
        await leaderboardMessage.edit({
            embeds: [
                embed
            ],
            components
        });

        console.log(
            `[LEADERBOARD] Updated message ${leaderboardMessage.id}`
        );

        return;
    }

    const newMessage =
        await channel.send({
            embeds: [
                embed
            ],
            components,
            allowedMentions: {
                parse: []
            }
        });

    setSetting(
        LEADERBOARD_MESSAGE_SETTING,
        newMessage.id
    );

    console.log(
        `[LEADERBOARD] Created message ${newMessage.id}`
    );
}

async function updateLeaderboard() {
    if (
        leaderboardUpdateRunning
    ) {
        leaderboardUpdatePending =
            true;

        return;
    }

    leaderboardUpdateRunning =
        true;

    try {
        do {
            leaderboardUpdatePending =
                false;

            await performLeaderboardUpdate();
        } while (
            leaderboardUpdatePending
        );
    } catch (error) {
        console.error(
            'Failed to update SmashPutt leaderboard:',
            error
        );
    } finally {
        leaderboardUpdateRunning =
            false;
    }
}

// ============================================================
// MANUAL SCORE COMMAND
// ============================================================

async function handleScoreAdjustmentCommand(
    interaction,
    transactionType
) {
    const targetUser =
        interaction.options.getUser(
            'member',
            true
        );

    const amount =
        interaction.options.getInteger(
            'amount',
            true
        );

    const reason =
        interaction.options
            .getString(
                'reason',
                true
            )
            .trim();

    if (
        !Number.isInteger(
            amount
        ) ||
        amount <= 0
    ) {
        await interaction.reply({
            content:
                'The Smash Score amount must be greater than zero.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (!reason) {
        await interaction.reply({
            content:
                'You must enter a reason for the Smash Score transaction.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    await interaction.deferReply({
        flags:
            MessageFlags.Ephemeral
    });

    let databaseDisplayName =
        getCleanUserName(
            targetUser
        );

    try {
        const targetMember =
            await interaction.guild.members.fetch(
                targetUser.id
            );

        if (
            targetMember &&
            targetMember.displayName
        ) {
            databaseDisplayName =
                targetMember.displayName;
        }
    } catch (_) {
        // Clean Discord name is a safe fallback.
    }

    const publicDisplayName =
        getCleanUserName(
            targetUser
        );

    const adminDisplayName =
        await getPlainDisplayName(
            interaction
        );

    let transactionResult;

    try {
        transactionResult =
            adjustSmashScoreTransaction({
                transactionType,
                userId:
                    targetUser.id,
                displayName:
                    databaseDisplayName,
                amount,
                reason,
                adminUserId:
                    interaction.user.id,
                adminDisplayName
            });
    } catch (error) {
        console.error(
            'Manual Smash Score transaction failed:',
            error
        );

        await interaction.editReply({
            content:
                'The Smash Score transaction failed. No score was changed.'
        });

        return;
    }

    if (
        !transactionResult.ok
    ) {
        if (
            transactionResult.reason ===
            'NO_PLAYER'
        ) {
            await interaction.editReply({
                content:
                    `${publicDisplayName} does not have any Smash Score to remove.`
            });

            return;
        }

        if (
            transactionResult.reason ===
            'INSUFFICIENT'
        ) {
            await interaction.editReply({
                content:
                    `${publicDisplayName} does not have enough Smash Score. ` +
                    `They currently have ${transactionResult.currentScore}.`
            });

            return;
        }

        await interaction.editReply({
            content:
                'The Smash Score transaction could not be completed.'
        });

        return;
    }

    console.log(
        `[SCORE ${transactionType}] ${adminDisplayName} | ` +
        `${publicDisplayName} | ${amount} | ${reason}`
    );

    let reportPosted =
        true;

    try {
        await sendScoreTransactionReport(
            transactionType,
            publicDisplayName,
            amount,
            reason
        );
    } catch (error) {
        reportPosted =
            false;

        console.error(
            'Smash Score was adjusted, but public report failed:',
            error
        );
    }

    updateLeaderboard()
        .catch(
            error =>
                console.error(
                    'Leaderboard refresh after manual Smash Score transaction failed:',
                    error
                )
        );

    if (
        transactionType ===
        'REMOVE'
    ) {
        await interaction.editReply({
            content:
                reportPosted
                    ? `✅ Removed ${amount} Smash Score from ${publicDisplayName}. The spending report was posted.`
                    : `⚠️ Removed ${amount} Smash Score from ${publicDisplayName}, but the public spending report could not be posted.`
        });

        return;
    }

    await interaction.editReply({
        content:
            reportPosted
                ? `✅ Added ${amount} Smash Score to ${publicDisplayName}. The report was posted.`
                : `⚠️ Added ${amount} Smash Score to ${publicDisplayName}, but the public report could not be posted.`
    });
}

