// ============================================================
// MY STATS
// ============================================================

async function handleMyStatsButton(
    interaction
) {
    const displayName =
        await getPlainDisplayName(
            interaction
        );

    ensurePlayer(
        interaction.user.id,
        displayName
    );

    const player =
        getPlayerStmt.get(
            interaction.user.id
        );

    if (
        !player ||
        player.holes_completed <= 0
    ) {
        await interaction.reply({
            content:
                'You have not completed a SmashPutt hole yet.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const rankRow =
        getPlayerRankStmt.get(
            player.holes_completed
        );

    const counts =
        getInventoryCounts(
            interaction.user.id
        );

    const weekly =
        getWeeklySmashPuttStandings();

    const weeklyIndex =
        weekly.standings.findIndex(
            standing =>
                standing.user_id ===
                interaction.user.id
        );

    const weeklyHoles =
        weeklyIndex >= 0
            ? weekly.standings[weeklyIndex].holes
            : 0;

    const weeklyRank =
        weeklyIndex >= 0
            ? `#${weeklyIndex + 1}`
            : '—';

    const safeName =
        escapeDiscordMarkdown(
            displayName
        );

    const embed =
        new EmbedBuilder()
            .setColor(
                0x2ECC71
            )
            .setTitle(
                '📊 MY SMASHPUTT STATS'
            )
            .setDescription(
                `**${safeName}**\n\n` +
                `🏆 Leaderboard Rank: **#${rankRow.rank}**\n` +
                `⛳ Holes Completed: **${player.holes_completed}**\n` +
                `💥 Smash Score: **${player.smash_score}**\n` +
                `🔥 This Week: ⛳ **${weeklyHoles}** Holes • Weekly Rank: **${weeklyRank}**\n\n` +
                `🟢 Unique Balls: **${counts.balls} / ${ballCatalog.length}**\n` +
                `🔵 Unique Putters: **${counts.putters}**\n` +
                `🟠 Legendary Items: **${counts.legendary}**\n` +
                `🎁 Common Misc: **${counts.misc}**\n` +
                `🔁 Duplicate Rewards: **${player.duplicate_rewards}**\n\n` +
                `⭐ Hole-in-Ones: **${player.hole_in_ones}**\n` +
                `🐦 Birdies: **${player.birdies}**\n` +
                `⛳ Pars: **${player.pars}**\n` +
                `🟤 Bogeys: **${player.bogeys}**\n` +
                `🚫 Stroke Outs: **${player.stroke_outs}**\n\n` +
                `Leaderboard rank is based only on total holes completed.\n` +
                `Weekly rank resets every Sunday at midnight Central Time.`
            );

    await interaction.reply({
        embeds: [
            embed
        ],
        flags:
            MessageFlags.Ephemeral,
        allowedMentions: {
            parse: []
        }
    });
}

