// ============================================================
// OWNED BALL COURSES
// ============================================================

function getOwnedBallCourseNames(
    userId
) {
    const inventory =
        getInventoryByTypeStmt.all(
            userId,
            'ball'
        );

    const courseNames =
        new Set();

    for (
        const item
        of inventory
    ) {
        const catalogItem =
            ballCatalogById.get(
                item.item_id
            );

        if (!catalogItem) {
            continue;
        }

        courseNames.add(
            catalogItem.courseDisplay
        );
    }

    return Array
        .from(
            courseNames
        )
        .sort(
            (a, b) =>
                a.localeCompare(b)
        );
}

// ============================================================
// BALL COLLECTION BOARD
// ============================================================

async function generateBallCourseBoard(
    userId,
    courseDisplay
) {
    const courseBalls =
        ballCatalog
            .filter(
                ball =>
                    ball.courseDisplay ===
                    courseDisplay
            )
            .sort(
                (a, b) =>
                    a.ballNumber -
                    b.ballNumber
            );

    const ownedItems =
        getInventoryByTypeStmt.all(
            userId,
            'ball'
        );

    const ownedIds =
        new Set(
            ownedItems.map(
                item =>
                    item.item_id
            )
        );

    const ownedCount =
        courseBalls.filter(
            ball =>
                ownedIds.has(
                    ball.id
                )
        ).length;

    const width = 1000;
    const height = 650;
    const columns = 6;
    const cellWidth = 145;
    const cellHeight = 145;
    const startX = 55;
    const startY = 155;
    const gapX = 12;
    const gapY = 18;

    let slotSvg = '';
    const composites = [];

    for (
        let index = 0;
        index < courseBalls.length;
        index++
    ) {
        const ball =
            courseBalls[index];

        const column =
            index % columns;

        const row =
            Math.floor(
                index / columns
            );

        const x =
            startX +
            column *
            (
                cellWidth +
                gapX
            );

        const y =
            startY +
            row *
            (
                cellHeight +
                gapY
            );

        const owned =
            ownedIds.has(
                ball.id
            );

        slotSvg += `
            <rect
                x="${x}"
                y="${y}"
                width="${cellWidth}"
                height="${cellHeight}"
                rx="18"
                fill="${owned ? '#20242a' : '#16191d'}"
                stroke="${owned ? '#68717c' : '#353a40'}"
                stroke-width="2"
            />
        `;

        if (!owned) {
            slotSvg += `
                <circle
                    cx="${x + cellWidth / 2}"
                    cy="${y + 64}"
                    r="42"
                    fill="#252a30"
                    stroke="#40464d"
                    stroke-width="3"
                />
                <text
                    x="${x + cellWidth / 2}"
                    y="${y + 75}"
                    text-anchor="middle"
                    font-family="sans-serif"
                    font-size="34"
                    font-weight="700"
                    fill="#69717a"
                >?</text>
            `;
        }

        slotSvg += `
            <text
                x="${x + cellWidth / 2}"
                y="${y + 132}"
                text-anchor="middle"
                font-family="sans-serif"
                font-size="18"
                font-weight="700"
                fill="${owned ? '#ffffff' : '#727982'}"
            >BALL ${ball.ballNumber}</text>
        `;

        if (owned) {
            const resizedBall =
                await sharp(
                    ball.imagePath
                )
                    .resize(
                        105,
                        105,
                        {
                            fit:
                                'contain'
                        }
                    )
                    .png()
                    .toBuffer();

            composites.push({
                input:
                    resizedBall,
                left:
                    Math.round(
                        x +
                        (
                            cellWidth -
                            105
                        ) / 2
                    ),
                top:
                    Math.round(
                        y + 10
                    )
            });
        }
    }

    const backgroundSvg = `
        <svg
            width="${width}"
            height="${height}"
            xmlns="http://www.w3.org/2000/svg"
        >
            <rect
                width="100%"
                height="100%"
                fill="#101214"
            />

            <text
                x="50"
                y="65"
                font-family="sans-serif"
                font-size="38"
                font-weight="800"
                fill="#ffffff"
            >${escapeXml(courseDisplay)}</text>

            <text
                x="50"
                y="105"
                font-family="sans-serif"
                font-size="25"
                font-weight="600"
                fill="#aeb6bf"
            >BALL COLLECTION — ${ownedCount} / ${courseBalls.length}</text>

            ${slotSvg}
        </svg>
    `;

    return sharp(
        Buffer.from(
            backgroundSvg
        )
    )
        .composite(
            composites
        )
        .png()
        .toBuffer();
}

// ============================================================
// GENERIC ITEM COLLECTION BOARD
// PUTTERS / LEGENDARY PRESERVED
// ============================================================

async function generateItemGridBoard({
    title,
    items,
    page,
    pageSize,
    columns,
    thumbSize
}) {
    const totalPages =
        Math.max(
            1,
            Math.ceil(
                items.length /
                pageSize
            )
        );

    const safePage =
        Math.min(
            Math.max(
                page,
                0
            ),
            totalPages - 1
        );

    const pageItems =
        items.slice(
            safePage *
            pageSize,
            safePage *
            pageSize +
            pageSize
        );

    const rows =
        Math.ceil(
            pageSize /
            columns
        );

    const width = 1000;

    const cellWidth =
        Math.floor(
            900 /
            columns
        );

    const cellHeight =
        thumbSize +
        80;

    const height =
        150 +
        rows *
        cellHeight;

    const startX = 50;
    const startY = 125;

    let slotSvg = '';

    const composites = [];

    for (
        let index = 0;
        index < pageItems.length;
        index++
    ) {
        const item =
            pageItems[index];

        const column =
            index % columns;

        const row =
            Math.floor(
                index /
                columns
            );

        const x =
            startX +
            column *
            cellWidth;

        const y =
            startY +
            row *
            cellHeight;

        const displayItemName =
            item.item_name.length > 24
                ? item.item_name.substring(
                    0,
                    22
                ) + '…'
                : item.item_name;

        slotSvg += `
            <rect
                x="${x + 8}"
                y="${y}"
                width="${cellWidth - 16}"
                height="${cellHeight - 12}"
                rx="18"
                fill="#191d21"
                stroke="#3c4249"
                stroke-width="2"
            />

            <text
                x="${x + cellWidth / 2}"
                y="${y + thumbSize + 45}"
                text-anchor="middle"
                font-family="sans-serif"
                font-size="17"
                font-weight="650"
                fill="#ffffff"
            >${escapeXml(displayItemName)}</text>
        `;

        const resizedImage =
            await sharp(
                item.image_path
            )
                .resize(
                    thumbSize,
                    thumbSize,
                    {
                        fit:
                            'contain'
                    }
                )
                .png()
                .toBuffer();

        composites.push({
            input:
                resizedImage,
            left:
                Math.round(
                    x +
                    (
                        cellWidth -
                        thumbSize
                    ) / 2
                ),
            top:
                Math.round(
                    y + 10
                )
        });
    }

    const backgroundSvg = `
        <svg
            width="${width}"
            height="${height}"
            xmlns="http://www.w3.org/2000/svg"
        >
            <rect
                width="100%"
                height="100%"
                fill="#101214"
            />

            <text
                x="50"
                y="60"
                font-family="sans-serif"
                font-size="38"
                font-weight="800"
                fill="#ffffff"
            >${escapeXml(title)}</text>

            <text
                x="50"
                y="98"
                font-family="sans-serif"
                font-size="21"
                fill="#aeb6bf"
            >Page ${safePage + 1} of ${totalPages}</text>

            ${slotSvg}
        </svg>
    `;

    const buffer =
        await sharp(
            Buffer.from(
                backgroundSvg
            )
        )
            .composite(
                composites
            )
            .png()
            .toBuffer();

    return {
        buffer,
        page:
            safePage,
        totalPages
    };
}

// ============================================================
// MISC TITLE WRAPPING
// ============================================================

function wrapMiscTitle(
    text,
    maxCharacters = 22,
    maxLines = 3
) {
    const words =
        String(text)
            .trim()
            .split(/\s+/);

    const lines = [];

    let current = '';

    for (
        const word
        of words
    ) {
        const proposed =
            current
                ? `${current} ${word}`
                : word;

        if (
            proposed.length <=
            maxCharacters
        ) {
            current =
                proposed;

            continue;
        }

        if (current) {
            lines.push(
                current
            );
        }

        current =
            word;

        if (
            lines.length ===
            maxLines - 1
        ) {
            break;
        }
    }

    const usedWordCount =
        lines
            .join(' ')
            .split(/\s+/)
            .filter(Boolean)
            .length +
        (
            current
                ? current
                    .split(/\s+/)
                    .filter(Boolean)
                    .length
                : 0
        );

    if (
        current &&
        lines.length <
        maxLines
    ) {
        lines.push(
            current
        );
    }

    if (
        usedWordCount <
        words.length &&
        lines.length > 0
    ) {
        const lastIndex =
            lines.length - 1;

        let lastLine =
            lines[lastIndex];

        if (
            lastLine.length >
            maxCharacters - 1
        ) {
            lastLine =
                lastLine.substring(
                    0,
                    maxCharacters - 1
                );
        }

        lines[lastIndex] =
            `${lastLine}…`;
    }

    return lines.slice(
        0,
        maxLines
    );
}

// ============================================================
// PLAYER TOP-3 SHOWCASE
// ============================================================

const showcaseManagerSessions =
    new Map();

function pruneShowcaseManagerSessions() {
    const cutoff =
        Date.now() -
        SHOWCASE_MANAGER_SESSION_TTL_MS;

    for (
        const [userId, session]
        of showcaseManagerSessions.entries()
    ) {
        if (session.lastTouched < cutoff) {
            showcaseManagerSessions.delete(userId);
        }
    }
}

function clonePublishedShowcaseSlots(
    userId
) {
    const slots =
        Array(
            SHOWCASE_MAX_SLOTS
        ).fill(null);

    for (
        const row
        of getShowcaseSlotsStmt.all(
            userId
        )
    ) {
        if (
            row.slot_number >= 1 &&
            row.slot_number <= SHOWCASE_MAX_SLOTS
        ) {
            slots[
                row.slot_number - 1
            ] = {
                item_type:
                    row.item_type,
                item_id:
                    row.item_id,
                item_name:
                    row.item_name,
                image_path:
                    row.image_path
            };
        }
    }

    return slots;
}

function startShowcaseManagerSession(
    userId
) {
    pruneShowcaseManagerSessions();

    const session = {
        slots:
            clonePublishedShowcaseSlots(
                userId
            ),
        lastTouched:
            Date.now()
    };

    showcaseManagerSessions.set(
        userId,
        session
    );

    return session;
}

function getShowcaseManagerSession(
    userId
) {
    pruneShowcaseManagerSessions();

    let session =
        showcaseManagerSessions.get(
            userId
        );

    if (!session) {
        session =
            startShowcaseManagerSession(
                userId
            );
    }

    session.lastTouched =
        Date.now();

    return session;
}

function removeItemFromShowcaseManagerSession(
    userId,
    itemType,
    itemId
) {
    const session =
        showcaseManagerSessions.get(
            userId
        );

    if (!session) {
        return;
    }

    for (
        let index = 0;
        index < session.slots.length;
        index++
    ) {
        const slot =
            session.slots[index];

        if (
            slot &&
            slot.item_type === itemType &&
            slot.item_id === itemId
        ) {
            session.slots[index] =
                null;
        }
    }

    session.lastTouched =
        Date.now();
}

function getShowcaseEligibleItems(
    userId,
    itemType
) {
    if (itemType === 'misc') {
        return getVisibleMiscInventoryStmt.all(
            userId
        );
    }

    if (
        ![
            'ball',
            'putter',
            'legendary'
        ].includes(itemType)
    ) {
        return [];
    }

    if (itemType === 'ball') {
        return getInventoryByTypeStmt.all(
            userId,
            itemType
        );
    }

    return getVisibleInventoryByTypeStmt.all(
        userId,
        itemType
    );
}

function getShowcaseCategoryLabel(
    itemType
) {
    if (itemType === 'ball') {
        return 'BALL';
    }

    if (itemType === 'misc') {
        return 'MISC';
    }

    if (itemType === 'putter') {
        return 'PUTTER';
    }

    if (itemType === 'legendary') {
        return 'LEGENDARY';
    }

    return 'ITEM';
}

function isShowcaseItemCurrentlyEligible(
    userId,
    item
) {
    if (
        !item ||
        ![
            'ball',
            'misc',
            'putter',
            'legendary'
        ].includes(item.item_type)
    ) {
        return false;
    }

    const owned =
        getInventoryItemStmt.get(
            userId,
            item.item_type,
            item.item_id
        );

    if (!owned) {
        return false;
    }

    if (item.item_type === 'misc') {
        const state =
            getMiscCashStateStmt.get(
                userId,
                item.item_id
            );

        if (
            state &&
            Number(state.is_hidden) === 1
        ) {
            return false;
        }
    }

    if (
        [
            'misc',
            'putter',
            'legendary'
        ].includes(item.item_type)
    ) {
        const auctionState =
            getPlayerAuctionHiddenStateStmt.get(
                userId,
                item.item_type,
                item.item_id
            );

        if (
            auctionState &&
            Number(auctionState.is_hidden) === 1
        ) {
            return false;
        }
    }

    return true;
}

function buildShowcaseManagerEmbed(
    displayName,
    session,
    statusText = null
) {
    const slotLines = [];

    for (
        let index = 0;
        index < SHOWCASE_MAX_SLOTS;
        index++
    ) {
        const item =
            session.slots[index];

        slotLines.push(
            `**${index + 1}.** ${
                item
                    ? escapeDiscordMarkdown(item.item_name)
                    : 'Empty'
            }`
        );
    }

    return new EmbedBuilder()
        .setColor(
            0xF1C40F
        )
        .setTitle(
            '🌟 YOUR TOP 3 SHOWCASE'
        )
        .setDescription(
            `**${escapeDiscordMarkdown(displayName)}**\n\n` +
            `${slotLines.join('\n')}\n\n` +
            `Choose a slot to add, replace, or remove an item.` +
            (
                statusText
                    ? `\n\n${statusText}`
                    : ''
            )
        );
}

