function getShowcaseBrowseState(
    userId,
    itemType,
    requestedPage
) {
    const items =
        getShowcaseEligibleItems(
            userId,
            itemType
        );

    const totalPages =
        Math.max(
            1,
            Math.ceil(
                items.length /
                SHOWCASE_PAGE_SIZE
            )
        );

    const page =
        Math.min(
            Math.max(
                Number(requestedPage) || 0,
                0
            ),
            totalPages - 1
        );

    return {
        items,
        page,
        totalPages,
        pageItems:
            items.slice(
                page * SHOWCASE_PAGE_SIZE,
                page * SHOWCASE_PAGE_SIZE +
                    SHOWCASE_PAGE_SIZE
            )
    };
}

function buildShowcaseBrowseRows({
    ownerId,
    slotNumber,
    itemType,
    page,
    totalPages,
    pageItems
}) {
    const rows = [];

    if (pageItems.length > 0) {
        const select =
            new StringSelectMenuBuilder()
                .setCustomId(
                    `showcase_item:${ownerId}:${slotNumber}:${itemType}:${page}`
                )
                .setPlaceholder(
                    'Choose an item for this slot'
                )
                .addOptions(
                    pageItems.map(
                        item => ({
                            label:
                                String(item.item_name)
                                    .slice(0, 100),
                            value:
                                String(item.id),
                            description:
                                getShowcaseCategoryLabel(
                                    item.item_type
                                )
                        })
                    )
                );

        rows.push(
            new ActionRowBuilder()
                .addComponents(
                    select
                )
        );
    }

    rows.push(
        new ActionRowBuilder()
            .addComponents(
                new ButtonBuilder()
                    .setCustomId(
                        `showcase_page:${ownerId}:${slotNumber}:${itemType}:${Math.max(0, page - 1)}:prev`
                    )
                    .setLabel(
                        'Previous'
                    )
                    .setEmoji(
                        '◀️'
                    )
                    .setStyle(
                        ButtonStyle.Primary
                    )
                    .setDisabled(
                        page <= 0
                    ),

                new ButtonBuilder()
                    .setCustomId(
                        `showcase_page:${ownerId}:${slotNumber}:${itemType}:${Math.min(totalPages - 1, page + 1)}:next`
                    )
                    .setLabel(
                        'Next'
                    )
                    .setEmoji(
                        '▶️'
                    )
                    .setStyle(
                        ButtonStyle.Primary
                    )
                    .setDisabled(
                        page >= totalPages - 1
                    ),

                new ButtonBuilder()
                    .setCustomId(
                        `showcase_slot:${ownerId}:${slotNumber}`
                    )
                    .setLabel(
                        'BACK'
                    )
                    .setEmoji(
                        '↩️'
                    )
                    .setStyle(
                        ButtonStyle.Secondary
                    )
            )
    );

    return rows;
}

async function generateShowcaseBoard({
    displayName,
    slots
}) {
    const width = 1200;
    const height = 520;
    const startX = 45;
    const startY = 125;
    const gap = 25;
    const cardWidth = 350;
    const cardHeight = 345;
    const imageSize = 235;

    let cardSvg = '';
    const composites = [];

    for (
        let index = 0;
        index < SHOWCASE_MAX_SLOTS;
        index++
    ) {
        const item =
            slots[index] || null;

        const x =
            startX +
            index * (cardWidth + gap);

        cardSvg += `
            <rect
                x="${x}"
                y="${startY}"
                width="${cardWidth}"
                height="${cardHeight}"
                rx="24"
                fill="#181b1f"
                stroke="#3c4249"
                stroke-width="2"
            />

            <text
                x="${x + 24}"
                y="${startY + 38}"
                font-family="sans-serif"
                font-size="20"
                font-weight="800"
                fill="#aeb6bf"
            >#${index + 1}</text>
        `;

        if (!item) {
            cardSvg += `
                <text
                    x="${x + cardWidth / 2}"
                    y="${startY + 180}"
                    text-anchor="middle"
                    font-family="sans-serif"
                    font-size="26"
                    font-weight="700"
                    fill="#59616a"
                >EMPTY</text>
            `;

            continue;
        }

        const titleLines =
            wrapMiscTitle(
                item.item_name,
                28,
                2
            );

        const titleSvg =
            titleLines
                .map(
                    (line, lineIndex) => `
                        <text
                            x="${x + cardWidth / 2}"
                            y="${startY + 305 + lineIndex * 24}"
                            text-anchor="middle"
                            font-family="sans-serif"
                            font-size="18"
                            font-weight="700"
                            fill="#ffffff"
                        >${escapeXml(line)}</text>
                    `
                )
                .join('');

        cardSvg += `
            <text
                x="${x + cardWidth - 24}"
                y="${startY + 38}"
                text-anchor="end"
                font-family="sans-serif"
                font-size="15"
                font-weight="700"
                fill="#7f8c8d"
            >${getShowcaseCategoryLabel(item.item_type)}</text>
            ${titleSvg}
        `;

        if (
            item.image_path &&
            fs.existsSync(
                item.image_path
            )
        ) {
            try {
                const image =
                    await sharp(
                        item.image_path
                    )
                        .resize(
                            imageSize,
                            imageSize,
                            {
                                fit: 'contain'
                            }
                        )
                        .png()
                        .toBuffer();

                composites.push({
                    input: image,
                    left:
                        Math.round(
                            x +
                            (cardWidth - imageSize) / 2
                        ),
                    top:
                        startY + 45
                });
            } catch (error) {
                console.error(
                    `[SHOWCASE] Could not render item image: ${item.item_name}`,
                    error
                );
            }
        }
    }

    const backgroundSvg = `
        <svg
            width="${width}"
            height="${height}"
            xmlns="http://www.w3.org/2000/svg"
        >
            <rect
                width="100%"
                height="100%"
                fill="#101214"
            />

            <text
                x="45"
                y="62"
                font-family="sans-serif"
                font-size="40"
                font-weight="800"
                fill="#ffffff"
            >${escapeXml(displayName)}'s Showcase</text>

            <text
                x="45"
                y="98"
                font-family="sans-serif"
                font-size="20"
                font-weight="600"
                fill="#aeb6bf"
            >TOP 3 FAVORITES</text>

            ${cardSvg}
        </svg>
    `;

    return sharp(
        Buffer.from(
            backgroundSvg
        )
    )
        .composite(
            composites
        )
        .png()
        .toBuffer();
}

function getPublishedShowcaseSlots(
    userId
) {
    const slots =
        Array(
            SHOWCASE_MAX_SLOTS
        ).fill(null);

    for (
        const row
        of getShowcaseSlotsStmt.all(
            userId
        )
    ) {
        if (
            row.slot_number >= 1 &&
            row.slot_number <= SHOWCASE_MAX_SLOTS
        ) {
            slots[
                row.slot_number - 1
            ] = row;
        }
    }

    return slots;
}

async function buildShowcasePublicPayload(
    userId,
    displayName
) {
    const slots =
        getPublishedShowcaseSlots(
            userId
        );

    const board =
        await generateShowcaseBoard({
            displayName,
            slots
        });

    const attachmentName =
        `smashputt-showcase-${userId}.png`;

    const attachment =
        new AttachmentBuilder(
            board,
            {
                name:
                    attachmentName
            }
        );

    const embed =
        new EmbedBuilder()
            .setColor(
                0xF1C40F
            )
            .setTitle(
                `🌟 ${escapeDiscordMarkdown(displayName)}'s Showcase`
            )
            .setImage(
                `attachment://${attachmentName}`
            );

    return {
        embeds: [embed],
        files: [attachment],
        allowedMentions: {
            parse: []
        }
    };
}

async function syncShowcasePublicMessage({
    userId,
    displayName,
    createIfMissing
}) {
    const channel =
        await client.channels.fetch(
            SHOWCASE_CHANNEL_ID
        );

    if (
        !channel ||
        !channel.isTextBased()
    ) {
        throw new Error(
            `Showcase channel could not be found: ${SHOWCASE_CHANNEL_ID}`
        );
    }

    let profile =
        getShowcaseProfileStmt.get(
            userId
        );

    let existingMessage = null;

    if (
        profile &&
        profile.message_id
    ) {
        try {
            existingMessage =
                await channel.messages.fetch(
                    profile.message_id
                );
        } catch (_) {
            clearShowcaseProfileMessageStmt.run({
                user_id: userId,
                updated_at:
                    new Date().toISOString()
            });

            profile =
                getShowcaseProfileStmt.get(
                    userId
                );
        }
    }

    if (
        !existingMessage &&
        !createIfMissing
    ) {
        return null;
    }

    const payload =
        await buildShowcasePublicPayload(
            userId,
            displayName
        );

    if (existingMessage) {
        await existingMessage.edit({
            ...payload,
            attachments: []
        });

        return existingMessage;
    }

    const message =
        await channel.send(
            payload
        );

    const now =
        new Date().toISOString();

    upsertShowcaseProfileStmt.run({
        user_id: userId,
        message_id: message.id,
        created_at:
            profile?.created_at || now,
        updated_at: now
    });

    return message;
}

const saveShowcaseSlotsTransaction =
    db.transaction(({
        userId,
        session
    }) => {
        const validated = [];

        for (
            let index = 0;
            index < SHOWCASE_MAX_SLOTS;
            index++
        ) {
            const item =
                session.slots[index];

            if (!item) {
                validated.push(null);
                continue;
            }

            if (
                !isShowcaseItemCurrentlyEligible(
                    userId,
                    item
                )
            ) {
                validated.push(null);
                continue;
            }

            const owned =
                getInventoryItemStmt.get(
                    userId,
                    item.item_type,
                    item.item_id
                );

            validated.push(
                owned || null
            );
        }

        deleteShowcaseSlotsForUserStmt.run(
            userId
        );

        const now =
            new Date().toISOString();

        for (
            let index = 0;
            index < validated.length;
            index++
        ) {
            const item =
                validated[index];

            if (!item) {
                continue;
            }

            insertShowcaseSlotStmt.run({
                user_id: userId,
                slot_number: index + 1,
                item_type: item.item_type,
                item_id: item.item_id,
                item_name: item.item_name,
                image_path: item.image_path,
                updated_at: now
            });
        }

        return validated;
    });

async function renderShowcaseManager(
    interaction,
    ownerId,
    statusText = null
) {
    const displayName =
        await getDisplayNameForUser(
            interaction.guild,
            ownerId
        );

    const session =
        getShowcaseManagerSession(
            ownerId
        );

    await interaction.update({
        content: null,
        embeds: [
            buildShowcaseManagerEmbed(
                displayName,
                session,
                statusText
            )
        ],
        components:
            buildShowcaseManagerRows(
                ownerId
            )
    });
}

async function handleShowcaseOpenButton(
    interaction
) {
    const ownerId =
        interaction.customId.split(':')[1];

    if (
        interaction.user.id !== ownerId
    ) {
        await interaction.reply({
            content:
                'This Showcase belongs to another player.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const displayName =
        await getDisplayNameForUser(
            interaction.guild,
            ownerId
        );

    const session =
        startShowcaseManagerSession(
            ownerId
        );

    await interaction.reply({
        embeds: [
            buildShowcaseManagerEmbed(
                displayName,
                session
            )
        ],
        components:
            buildShowcaseManagerRows(
                ownerId
            ),
        flags:
            MessageFlags.Ephemeral
    });
}

async function handleShowcaseSlotButton(
    interaction
) {
    const parts =
        interaction.customId.split(':');

    const ownerId =
        parts[1];

    const slotNumber =
        Number(parts[2]);

    if (
        interaction.user.id !== ownerId ||
        slotNumber < 1 ||
        slotNumber > SHOWCASE_MAX_SLOTS
    ) {
        await interaction.reply({
            content:
                'This Showcase control is not available to you.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const session =
        getShowcaseManagerSession(
            ownerId
        );

    const currentItem =
        session.slots[
            slotNumber - 1
        ];

    const embed =
        new EmbedBuilder()
            .setColor(
                0xF1C40F
            )
            .setTitle(
                `🌟 SHOWCASE SLOT ${slotNumber}`
            )
            .setDescription(
                `Current: **${
                    currentItem
                        ? escapeDiscordMarkdown(currentItem.item_name)
                        : 'Empty'
                }**\n\nChoose which collection to browse.`
            );

    await interaction.update({
        content: null,
        embeds: [embed],
        components:
            buildShowcaseSlotEditorRows(
                ownerId,
                slotNumber,
                Boolean(currentItem)
            )
    });
}

async function renderShowcaseBrowse(
    interaction,
    ownerId,
    slotNumber,
    itemType,
    requestedPage
) {
    const state =
        getShowcaseBrowseState(
            ownerId,
            itemType,
            requestedPage
        );

    const itemLines =
        state.pageItems.length > 0
            ? state.pageItems
                .map(
                    (item, index) =>
                        `**${index + 1}.** ${escapeDiscordMarkdown(item.item_name)}`
                )
                .join('\n')
            : 'No currently owned items are available in this collection.';

    const embed =
        new EmbedBuilder()
            .setColor(
                0xF1C40F
            )
            .setTitle(
                `🌟 SLOT ${slotNumber} — ${getShowcaseCategoryLabel(itemType)}`
            )
            .setDescription(
                `${itemLines}\n\nPage **${state.page + 1} / ${state.totalPages}**`
            );

    await interaction.update({
        content: null,
        embeds: [embed],
        components:
            buildShowcaseBrowseRows({
                ownerId,
                slotNumber,
                itemType,
                page: state.page,
                totalPages:
                    state.totalPages,
                pageItems:
                    state.pageItems
            })
    });
}

