async function handleShowcaseItemSelect(
    interaction
) {
    const parts =
        interaction.customId.split(':');

    const ownerId =
        parts[1];

    const slotNumber =
        Number(parts[2]);

    const itemType =
        parts[3];

    if (
        interaction.user.id !== ownerId
    ) {
        await interaction.reply({
            content:
                'This Showcase menu belongs to another player.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const inventoryRowId =
        Number(
            interaction.values[0]
        );

    const item =
        getInventoryItemByRowIdStmt.get(
            inventoryRowId,
            ownerId
        );

    if (
        !item ||
        item.item_type !== itemType ||
        !isShowcaseItemCurrentlyEligible(
            ownerId,
            item
        )
    ) {
        await interaction.update({
            content:
                'That item is no longer available. Reopen the Showcase manager.',
            embeds: [],
            components: []
        });

        return;
    }

    const session =
        getShowcaseManagerSession(
            ownerId
        );

    // Keep one collectible from occupying multiple Showcase slots.
    for (
        let index = 0;
        index < session.slots.length;
        index++
    ) {
        const existing =
            session.slots[index];

        if (
            existing &&
            existing.item_type === item.item_type &&
            existing.item_id === item.item_id
        ) {
            session.slots[index] =
                null;
        }
    }

    session.slots[
        slotNumber - 1
    ] = {
        item_type: item.item_type,
        item_id: item.item_id,
        item_name: item.item_name,
        image_path: item.image_path
    };

    session.lastTouched =
        Date.now();

    await renderShowcaseManager(
        interaction,
        ownerId,
        `✅ Slot ${slotNumber} set to **${escapeDiscordMarkdown(item.item_name)}**.`
    );
}

