async function handleShowcasePublishButton(
    interaction
) {
    const ownerId =
        interaction.customId.split(':')[1];

    if (
        interaction.user.id !== ownerId
    ) {
        await interaction.reply({
            content:
                'This Showcase control belongs to another player.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    await interaction.deferUpdate();

    const session =
        getShowcaseManagerSession(
            ownerId
        );

    if (
        !session.slots.some(Boolean)
    ) {
        const displayName =
            await getDisplayNameForUser(
                interaction.guild,
                ownerId
            );

        await interaction.editReply({
            content:
                'Choose at least one item before publishing your Showcase.',
            embeds: [
                buildShowcaseManagerEmbed(
                    displayName,
                    session
                )
            ],
            components:
                buildShowcaseManagerRows(
                    ownerId
                )
        });

        return;
    }

    const validated =
        saveShowcaseSlotsTransaction({
            userId: ownerId,
            session
        });

    session.slots =
        validated.map(
            item =>
                item
                    ? {
                        item_type: item.item_type,
                        item_id: item.item_id,
                        item_name: item.item_name,
                        image_path: item.image_path
                    }
                    : null
        );

    session.lastTouched =
        Date.now();

    const displayName =
        await getDisplayNameForUser(
            interaction.guild,
            ownerId
        );

    try {
        await syncShowcasePublicMessage({
            userId: ownerId,
            displayName,
            createIfMissing: true
        });
    } catch (error) {
        console.error(
            '[SHOWCASE] Publish/update failed:',
            error
        );

        await interaction.editReply({
            content:
                'The Showcase could not be published. Your selections are still saved; try again in a moment.',
            embeds: [
                buildShowcaseManagerEmbed(
                    displayName,
                    session
                )
            ],
            components:
                buildShowcaseManagerRows(
                    ownerId
                )
        });

        return;
    }

    await interaction.editReply({
        content:
            '✅ Your public Showcase has been published/updated.',
        embeds: [
            buildShowcaseManagerEmbed(
                displayName,
                session
            )
        ],
        components:
            buildShowcaseManagerRows(
                ownerId
            )
    });
}

// ============================================================
// PLAYER AUCTION INVENTORY MANAGER
// ============================================================

function getPlayerAuctionEligibleItems(userId, itemType) {
    if (itemType === 'misc') {
        return getVisibleMiscInventoryStmt.all(userId);
    }

    if (!['putter', 'legendary'].includes(itemType)) {
        return [];
    }

    return getVisibleInventoryByTypeStmt.all(userId, itemType);
}

function getPlayerAuctionCategoryLabel(itemType) {
    if (itemType === 'misc') return 'COMMON MISC';
    if (itemType === 'putter') return 'PUTTERS';
    if (itemType === 'legendary') return 'LEGENDARY';
    return 'ITEMS';
}

function buildPlayerAuctionManagerEmbed(displayName, cooldownStatus, statusText = null) {
    const cooldownLine = cooldownStatus.available
        ? '✅ **Player Auction available now.**'
        : `⏳ **Next Player Auction available in ${formatPlayerAuctionCooldown(cooldownStatus.remainingMs)}.**`;

    return new EmbedBuilder()
        .setColor(0xD6A84B)
        .setTitle('🔥 PLAYER AUCTION')
        .setDescription(
            `**${escapeDiscordMarkdown(displayName)}**\n\n` +
            `${cooldownLine}\n` +
            `One Player Auction may be started every **24 hours**.\n` +
            `Eligible inventory: **Misc, Putters, Legendary**.\n` +
            `Official Ball collections and Courses cannot be auctioned.\n\n` +
            `💥 **80% of the proceeds go to the seller.**` +
            (statusText ? `\n\n${statusText}` : '')
        );
}

function buildPlayerAuctionManagerRows(ownerId, available) {
    const rows = [];

    if (available) {
        const categoryMenu = new StringSelectMenuBuilder()
            .setCustomId(`player_auction_category:${ownerId}`)
            .setPlaceholder('Choose inventory to auction from')
            .addOptions(
                { label: 'Misc', value: 'misc', emoji: '🎁' },
                { label: 'Putters', value: 'putter', emoji: '🔵' },
                { label: 'Legendary', value: 'legendary', emoji: '🟠' }
            );

        rows.push(new ActionRowBuilder().addComponents(categoryMenu));
    }

    rows.push(
        new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId(`player_auction_inventory_back:${ownerId}`)
                .setLabel('BACK TO INVENTORY')
                .setEmoji('◀️')
                .setStyle(ButtonStyle.Secondary)
        )
    );

    return rows;
}

function getPlayerAuctionBrowseState(ownerId, itemType, requestedPage) {
    const items = getPlayerAuctionEligibleItems(ownerId, itemType);
    const totalPages = Math.max(1, Math.ceil(items.length / PLAYER_AUCTION_PAGE_SIZE));
    const page = Math.min(Math.max(Number(requestedPage) || 0, 0), totalPages - 1);

    return {
        items,
        page,
        totalPages,
        pageItems: items.slice(
            page * PLAYER_AUCTION_PAGE_SIZE,
            page * PLAYER_AUCTION_PAGE_SIZE + PLAYER_AUCTION_PAGE_SIZE
        )
    };
}

function buildPlayerAuctionBrowseRows({ ownerId, itemType, page, totalPages, pageItems }) {
    const rows = [];

    if (pageItems.length > 0) {
        const select = new StringSelectMenuBuilder()
            .setCustomId(`player_auction_item:${ownerId}:${itemType}:${page}`)
            .setPlaceholder('Choose the item to auction')
            .addOptions(
                pageItems.map(item => ({
                    label: String(item.item_name).slice(0, 100),
                    value: String(item.id)
                }))
            );

        rows.push(new ActionRowBuilder().addComponents(select));
    }

    rows.push(
        new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId(`player_auction_page:${ownerId}:${itemType}:${Math.max(0, page - 1)}:prev`)
                .setLabel('Previous')
                .setEmoji('◀️')
                .setStyle(ButtonStyle.Primary)
                .setDisabled(page <= 0),
            new ButtonBuilder()
                .setCustomId(`player_auction_page:${ownerId}:${itemType}:${Math.min(totalPages - 1, page + 1)}:next`)
                .setLabel('Next')
                .setEmoji('▶️')
                .setStyle(ButtonStyle.Primary)
                .setDisabled(page >= totalPages - 1),
            new ButtonBuilder()
                .setCustomId(`player_auction_open:${ownerId}`)
                .setLabel('BACK')
                .setStyle(ButtonStyle.Secondary)
        )
    );

    return rows;
}

async function renderPlayerAuctionBrowse(interaction, ownerId, itemType, requestedPage) {
    const state = getPlayerAuctionBrowseState(ownerId, itemType, requestedPage);
    const itemLines = state.pageItems.length > 0
        ? state.pageItems.map((item, index) => `**${index + 1}.** ${escapeDiscordMarkdown(item.item_name)}`).join('\n')
        : 'No currently visible items are available in this collection.';

    const embed = new EmbedBuilder()
        .setColor(0xD6A84B)
        .setTitle(`🔥 PLAYER AUCTION — ${getPlayerAuctionCategoryLabel(itemType)}`)
        .setDescription(`${itemLines}\n\nPage **${state.page + 1} / ${state.totalPages}**`);

    await interaction.update({
        content: null,
        embeds: [embed],
        components: buildPlayerAuctionBrowseRows({
            ownerId,
            itemType,
            page: state.page,
            totalPages: state.totalPages,
            pageItems: state.pageItems
        }),
        attachments: []
    });
}

