async function handlePlayerAuctionItemSelect(interaction) {
    const parts = interaction.customId.split(':');
    const ownerId = parts[1];
    const itemType = parts[2];

    if (interaction.user.id !== ownerId) {
        await interaction.reply({
            content: 'This Player Auction menu belongs to another player.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    const inventoryRowId = Number(interaction.values[0]);
    const item = getInventoryItemByRowIdStmt.get(inventoryRowId, ownerId);

    if (!item || item.item_type !== itemType || !isPlayerAuctionItemVisible(ownerId, item)) {
        await interaction.update({
            content: 'That item is no longer available to auction. Reopen Player Auction.',
            embeds: [],
            components: [],
            attachments: []
        });
        return;
    }

    const cooldown = getPlayerAuctionCooldownStatus(ownerId);

    if (!cooldown.available) {
        const displayName = await getDisplayNameForUser(interaction.guild, ownerId);
        await interaction.update({
            content: null,
            embeds: [buildPlayerAuctionManagerEmbed(displayName, cooldown)],
            components: buildPlayerAuctionManagerRows(ownerId, false),
            attachments: []
        });
        return;
    }

    const embed = new EmbedBuilder()
        .setColor(0xD6A84B)
        .setTitle('🔥 START PLAYER AUCTION?')
        .setDescription(
            `🎁 **${escapeDiscordMarkdown(item.item_name)}**\n\n` +
            `This will start a public **60-second Player Auction** in the SmashPutt play channel.\n` +
            `💥 **80% of the proceeds go to the seller.**\n` +
            `🏠 House Fee: **20%**\n\n` +
            `⚠️ Starting this auction uses your **one Player Auction for the next 24 hours**, even if nobody bids.`
        );

    const row = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(`player_auction_confirm:${ownerId}:${inventoryRowId}`)
            .setLabel('START AUCTION')
            .setEmoji('🔥')
            .setStyle(ButtonStyle.Success),
        new ButtonBuilder()
            .setCustomId(`player_auction_open:${ownerId}`)
            .setLabel('CANCEL')
            .setStyle(ButtonStyle.Secondary)
    );

    await interaction.update({
        content: null,
        embeds: [embed],
        components: [row],
        attachments: []
    });
}

async function handlePlayerAuctionInventoryBackButton(interaction) {
    const ownerId = interaction.customId.split(':')[1];

    if (interaction.user.id !== ownerId) {
        await interaction.reply({
            content: 'This inventory control belongs to another player.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferUpdate();
    await renderInventorySummary(interaction.message, interaction.guild, ownerId);
}

async function handlePlayerAuctionConfirmButton(interaction) {
    const parts = interaction.customId.split(':');
    const ownerId = parts[1];
    const inventoryRowId = Number(parts[2]);

    if (interaction.user.id !== ownerId) {
        await interaction.reply({
            content: 'This Player Auction confirmation belongs to another player.',
            flags: MessageFlags.Ephemeral
        });
        return;
    }

    await interaction.deferUpdate();

    const item = getInventoryItemByRowIdStmt.get(inventoryRowId, ownerId);

    if (!item || !isPlayerAuctionItemVisible(ownerId, item)) {
        await interaction.editReply({
            content: 'That item is no longer available to auction. Reopen your inventory and choose another item.',
            embeds: [],
            components: [],
            attachments: []
        });
        return;
    }

    const cooldown = getPlayerAuctionCooldownStatus(ownerId);

    if (!cooldown.available) {
        await interaction.editReply({
            content: `Your next Player Auction is available in **${formatPlayerAuctionCooldown(cooldown.remainingMs)}**.`,
            embeds: [],
            components: buildPlayerAuctionManagerRows(ownerId, false),
            attachments: []
        });
        return;
    }

    const sellerDisplayName = await getPlainDisplayName(interaction);
    const sellerCleanName = getCleanDiscordName(interaction);
    const sellerAvatarUrl = interaction.user.displayAvatarURL({ extension: 'png', size: 256 });

    const result = await createPlayerAuctionInChannel({
        channelId: PLAYER_AUCTION_CHANNEL_ID,
        sellerUserId: ownerId,
        sellerDisplayName,
        sellerCleanName,
        sellerAvatarUrl,
        item
    });

    if (!result.ok) {
        let message = 'Player Auction could not be started. No cooldown was used.';

        if (result.reason === 'ACTIVE_ACTIVITY' || result.reason === 'SPAWN_IN_PROGRESS') {
            message = 'SmashPutt is busy with another activity right now. Your Player Auction was not started and your 24-hour cooldown was not used.';
        } else if (result.reason === 'COOLDOWN') {
            message = `Your next Player Auction is available in **${formatPlayerAuctionCooldown(result.remainingMs)}**.`;
        } else if (result.reason === 'ITEM_UNAVAILABLE') {
            message = 'That item is no longer available in your visible inventory. Your 24-hour cooldown was not used.';
        }

        await interaction.editReply({
            content: message,
            embeds: [],
            components: buildPlayerAuctionManagerRows(ownerId, result.reason !== 'COOLDOWN'),
            attachments: []
        });
        return;
    }

    await renderInventorySummary(interaction.message, interaction.guild, ownerId);

    await interaction.followUp({
        content: `✅ Your Player Auction for **${escapeDiscordMarkdown(item.item_name)}** is live in <#${PLAYER_AUCTION_CHANNEL_ID}>. Your next Player Auction will be available in 24 hours.`,
        flags: MessageFlags.Ephemeral,
        allowedMentions: { parse: [] }
    });
}

// ============================================================
// MISC COLLECTION BOARD
// ============================================================

const miscInventorySessions =
    new Map();

function pruneMiscInventorySessions() {
    const cutoff =
        Date.now() -
        MISC_INVENTORY_SESSION_TTL_MS;

    for (
        const [key, session]
        of miscInventorySessions.entries()
    ) {
        if (session.lastTouched < cutoff) {
            miscInventorySessions.delete(key);
        }
    }
}

function getMiscInventorySessionKey(
    messageId,
    ownerId
) {
    return `${messageId}:${ownerId}`;
}

function getOrCreateMiscInventorySession(
    messageId,
    ownerId
) {
    pruneMiscInventorySessions();

    const key =
        getMiscInventorySessionKey(
            messageId,
            ownerId
        );

    let session =
        miscInventorySessions.get(
            key
        );

    if (!session) {
        session = {
            ownerId,
            items: getVisibleMiscInventoryStmt.all(ownerId),
            lastTouched: Date.now()
        };

        miscInventorySessions.set(
            key,
            session
        );
    } else {
        session.lastTouched =
            Date.now();
    }

    return session;
}

function getMiscSessionPageItems(
    session,
    requestedPage
) {
    const pageSize = 8;

    const totalPages =
        Math.max(
            1,
            Math.ceil(
                session.items.length /
                pageSize
            )
        );

    const page =
        Math.min(
            Math.max(
                requestedPage,
                0
            ),
            totalPages - 1
        );

    return {
        page,
        totalPages,
        pageItems: session.items.slice(
            page * pageSize,
            page * pageSize + pageSize
        )
    };
}

function removeMiscItemFromInventorySession(
    messageId,
    ownerId,
    inventoryRowId
) {
    const key =
        getMiscInventorySessionKey(
            messageId,
            ownerId
        );

    const session =
        miscInventorySessions.get(
            key
        );

    if (!session) {
        return;
    }

    session.items =
        session.items.map(
            item =>
                item &&
                Number(item.id) ===
                    Number(inventoryRowId)
                    ? null
                    : item
        );

    session.lastTouched =
        Date.now();
}

function removeMiscItemFromAllInventorySessions(
    ownerId,
    itemId
) {
    for (
        const session
        of miscInventorySessions.values()
    ) {
        if (session.ownerId !== ownerId) {
            continue;
        }

        session.items =
            session.items.map(
                item =>
                    item &&
                    item.item_id === itemId
                        ? null
                        : item
            );

        session.lastTouched =
            Date.now();
    }
}

async function generateMiscGridBoard({
    title,
    pageItems,
    page,
    totalPages
}) {
    const columns = 4;
    const rows = 2;

    const safePage =
        Math.min(
            Math.max(
                page,
                0
            ),
            Math.max(
                0,
                totalPages - 1
            )
        );

    const width = 1000;
    const cellWidth = 225;
    const cellHeight = 270;
    const thumbSize = 165;
    const startX = 50;
    const startY = 125;

    const height =
        150 +
        rows *
        cellHeight;

    let slotSvg = '';

    const composites = [];

    for (
        let index = 0;
        index < pageItems.length;
        index++
    ) {
        const item =
            pageItems[index];

        if (!item) {
            continue;
        }

        const column =
            index % columns;

        const row =
            Math.floor(
                index /
                columns
            );

        const x =
            startX +
            column *
            cellWidth;

        const y =
            startY +
            row *
            cellHeight;

        const titleLines =
            wrapMiscTitle(
                item.item_name,
                22,
                3
            );

        slotSvg += `
            <rect
                x="${x + 8}"
                y="${y}"
                width="${cellWidth - 16}"
                height="${cellHeight - 12}"
                rx="18"
                fill="#191d21"
                stroke="#3c4249"
                stroke-width="2"
            />
        `;

        const titleStartY =
            y +
            thumbSize +
            36;

        slotSvg += `
            <text
                x="${x + cellWidth / 2}"
                y="${titleStartY}"
                text-anchor="middle"
                font-family="sans-serif"
                font-size="16"
                font-weight="650"
                fill="#ffffff"
            >
        `;

        for (
            let lineIndex = 0;
            lineIndex < titleLines.length;
            lineIndex++
        ) {
            slotSvg += `
                <tspan
                    x="${x + cellWidth / 2}"
                    dy="${lineIndex === 0 ? 0 : 20}"
                >${escapeXml(titleLines[lineIndex])}</tspan>
            `;
        }

        slotSvg += `
            </text>
        `;

        let imagePath =
            item.image_path;

        if (
            !fs.existsSync(
                imagePath
            )
        ) {
            imagePath =
                resolveHistoricalMiscImagePath(
                    item.item_id,
                    imagePath
                );
        }

        if (
            imagePath &&
            fs.existsSync(
                imagePath
            )
        ) {
            const resizedImage =
                await sharp(
                    imagePath
                )
                    .resize(
                        thumbSize,
                        thumbSize,
                        {
                            fit:
                                'contain'
                        }
                    )
                    .png()
                    .toBuffer();

            composites.push({
                input:
                    resizedImage,
                left:
                    Math.round(
                        x +
                        (
                            cellWidth -
                            thumbSize
                        ) / 2
                    ),
                top:
                    Math.round(
                        y + 10
                    )
            });
        }
    }

    const backgroundSvg = `
        <svg
            width="${width}"
            height="${height}"
            xmlns="http://www.w3.org/2000/svg"
        >
            <rect
                width="100%"
                height="100%"
                fill="#101214"
            />

            <text
                x="50"
                y="60"
                font-family="sans-serif"
                font-size="38"
                font-weight="800"
                fill="#ffffff"
            >${escapeXml(title)}</text>

            <text
                x="50"
                y="98"
                font-family="sans-serif"
                font-size="21"
                fill="#aeb6bf"
            >Page ${safePage + 1} of ${totalPages}</text>

            ${slotSvg}
        </svg>
    `;

    const buffer =
        await sharp(
            Buffer.from(
                backgroundSvg
            )
        )
            .composite(
                composites
            )
            .png()
            .toBuffer();

    return {
        buffer,
        page:
            safePage,
        totalPages
    };
}

// ============================================================
// COURSE PROGRESS
// ============================================================

function getCourseProgress(
    userId
) {
    const progress =
        new Map();

    function ensureCourse(
        courseName
    ) {
        if (
            !progress.has(
                courseName
            )
        ) {
            progress.set(
                courseName,
                {
                    name:
                        courseName,
                    easy:
                        new Set(),
                    hard:
                        new Set()
                }
            );
        }

        return progress.get(
            courseName
        );
    }

    const history =
        getPlayerHistoryStmt.all(
            userId
        );

    for (
        const row
        of history
    ) {
        const baseCourse =
            getBaseCourseName(
                row.course_display
            );

        const difficulty =
            getDifficulty(
                row.course_display
            );

        if (!difficulty) {
            continue;
        }

        const course =
            ensureCourse(
                baseCourse
            );

        if (
            difficulty ===
            'Easy'
        ) {
            course.easy.add(
                row.hole_number
            );
        }

        if (
            difficulty ===
            'Hard'
        ) {
            course.hard.add(
                row.hole_number
            );
        }
    }

    return Array
        .from(
            progress.values()
        )
        .filter(
            course =>
                course.easy.size > 0 ||
                course.hard.size > 0
        )
        .sort(
            (a, b) =>
                a.name.localeCompare(
                    b.name
                )
        );
}

