async function renderBallsPage(
    message,
    guild,
    ownerId,
    requestedPage
) {
    const displayName =
        await getDisplayNameForUser(
            guild,
            ownerId
        );

    const courseNames =
        getOwnedBallCourseNames(
            ownerId
        );

    const counts =
        getInventoryCounts(
            ownerId
        );

    if (
        courseNames.length === 0
    ) {
        const embed =
            new EmbedBuilder()
                .setColor(
                    0x2ECC71
                )
                .setTitle(
                    '🟢 BALL COLLECTION'
                )
                .setDescription(
                    `**${escapeDiscordMarkdown(displayName)}** has not collected any balls yet.`
                );

        await message.edit({
            embeds: [
                embed
            ],
            components:
                buildInventoryCategoryRows(
                    ownerId,
                    counts
                ),
            attachments: []
        });

        return;
    }

    const page =
        Math.min(
            Math.max(
                requestedPage,
                0
            ),
            courseNames.length - 1
        );

    const courseDisplay =
        courseNames[page];

    const imageBuffer =
        await generateBallCourseBoard(
            ownerId,
            courseDisplay
        );

    const attachmentName =
        `smashputt-balls-${ownerId}-${page}.png`;

    const attachment =
        new AttachmentBuilder(
            imageBuffer,
            {
                name:
                    attachmentName
            }
        );

    const ownedItems =
        getInventoryByTypeStmt.all(
            ownerId,
            'ball'
        );

    const ownedForCourse =
        ownedItems.filter(
            item => {
                const catalog =
                    ballCatalogById.get(
                        item.item_id
                    );

                return (
                    catalog &&
                    catalog.courseDisplay ===
                    courseDisplay
                );
            }
        ).length;

    const embed =
        new EmbedBuilder()
            .setColor(
                0x2ECC71
            )
            .setTitle(
                `🟢 ${courseDisplay} Balls`
            )
            .setDescription(
                `**${escapeDiscordMarkdown(displayName)}** has collected **${ownedForCourse} / 18** balls from this course.\n\n` +
                `Course ${page + 1} of ${courseNames.length}`
            )
            .setImage(
                `attachment://${attachmentName}`
            );

    await message.edit({
        embeds: [
            embed
        ],
        components: [
            ...buildInventoryCategoryRows(
                ownerId,
                counts
            ),
            buildPageNavigationRow(
                'balls',
                ownerId,
                page,
                courseNames.length
            )
        ],
        attachments: [],
        files: [
            attachment
        ]
    });
}

