// CREATE INVENTORY
// ============================================================

async function createInventory(
    interaction
) {
    const displayName =
        await getPlainDisplayName(
            interaction
        );

    ensurePlayer(
        interaction.user.id,
        displayName
    );

    const player =
        getPlayerStmt.get(
            interaction.user.id
        );

    const counts =
        getInventoryCounts(
            interaction.user.id
        );

    const embed =
        buildInventorySummaryEmbed(
            player,
            displayName,
            counts
        );

    await interaction.reply({
        embeds: [
            embed
        ],
        components:
            buildInventoryCategoryRows(
                interaction.user.id,
                counts
            ),
        allowedMentions: {
            parse: []
        }
    });
}

