function awardMiniTournamentChampion(
    tournamentKey,
    userId
) {
    const tournamentPlayer =
        getMiniTournamentPlayerStmt.get(
            tournamentKey,
            userId
        );

    if (
        !tournamentPlayer
    ) {
        throw new Error(
            `Mini Tournament player record missing for ${userId}.`
        );
    }

    ensurePlayer(
        userId,
        tournamentPlayer.display_name
    );

    const now =
        new Date().toISOString();

    addSmashScoreStmt.run({
        user_id:
            userId,
        display_name:
            tournamentPlayer.display_name,
        amount:
            TOURNAMENT_SCORE_PRIZE,
        updated_at:
            now
    });

    return getPlayerStmt.get(
        userId
    );
}

// ============================================================
// MINI TOURNAMENT SMASH TRANSACTION
// ============================================================

const processMiniTournamentSmashTransaction =
    db.transaction(({
        tournamentKey,
        userId,
        cleanName
    }) => {
        const state =
            getActiveMiniTournamentStmt.get();

        if (
            !state ||
            state.tournament_key !==
            tournamentKey
        ) {
            return {
                type:
                    'INACTIVE'
            };
        }

        if (
            state.status ===
            'ROUND1_ACTIVE'
        ) {
            const participant =
                getMiniTournamentPlayerStmt.get(
                    tournamentKey,
                    userId
                );

            if (
                !participant
            ) {
                return {
                    type:
                        'NOT_ELIGIBLE'
                };
            }

            const smashNumber =
                state.round1_current_smashes +
                1;

            const update =
                db.prepare(`
                    UPDATE mini_tournament_state
                    SET
                        round1_current_smashes = @smash_number
                    WHERE id = 1
                      AND tournament_key = @tournament_key
                      AND status = 'ROUND1_ACTIVE'
                      AND round1_current_smashes = @previous_smashes
                `).run({
                    tournament_key:
                        tournamentKey,
                    smash_number:
                        smashNumber,
                    previous_smashes:
                        state.round1_current_smashes
                });

            if (
                update.changes !== 1
            ) {
                return {
                    type:
                        'INACTIVE'
                };
            }

            insertMiniTournamentEventStmt.run({
                tournament_key:
                    tournamentKey,
                round_key:
                    'ROUND1',
                smash_number:
                    smashNumber,
                user_id:
                    userId,
                display_name:
                    cleanName,
                smashed_at:
                    new Date().toISOString()
            });

            const updatedState =
                getActiveMiniTournamentStmt.get();

            if (
                smashNumber <
                updatedState.round1_required_smashes
            ) {
                return {
                    type:
                        'ROUND1_SMASH',
                    state:
                        updatedState
                };
            }

            const events =
                getMiniTournamentEventsStmt.all(
                    tournamentKey,
                    'ROUND1'
                );

            const finalists = [];
            const seenUserIds =
                new Set();

            for (
                let index =
                    events.length - 1;
                index >= 0;
                index--
            ) {
                const event =
                    events[index];

                if (
                    seenUserIds.has(
                        event.user_id
                    )
                ) {
                    continue;
                }

                seenUserIds.add(
                    event.user_id
                );

                finalists.push({
                    userId:
                        event.user_id,
                    cleanName:
                        event.display_name
                });

                if (
                    finalists.length ===
                    2
                ) {
                    break;
                }
            }

            if (
                finalists.length < 2
            ) {
                const joinedPlayers =
                    getMiniTournamentPlayersStmt.all(
                        tournamentKey
                    );

                const fallbackCandidates =
                    joinedPlayers.filter(
                        player =>
                            !seenUserIds.has(
                                player.user_id
                            )
                    );

                const fallbackPlayer =
                    randomItem(
                        fallbackCandidates
                    );

                if (
                    !fallbackPlayer
                ) {
                    throw new Error(
                        'Mini Tournament could not determine two finalists.'
                    );
                }

                finalists.push({
                    userId:
                        fallbackPlayer.user_id,
                    cleanName:
                        fallbackPlayer.clean_name
                });

                console.log(
                    `[MINI TOURNAMENT] Only one unique Round 1 smasher. ` +
                    `Fallback finalist selected: ${fallbackPlayer.clean_name}`
                );
            }

            const transition =
                db.prepare(`
                    UPDATE mini_tournament_state
                    SET
                        status = 'ROUND1_COMPLETE',
                        finalist1_user_id = @finalist1_user_id,
                        finalist1_clean_name = @finalist1_clean_name,
                        finalist2_user_id = @finalist2_user_id,
                        finalist2_clean_name = @finalist2_clean_name
                    WHERE id = 1
                      AND tournament_key = @tournament_key
                      AND status = 'ROUND1_ACTIVE'
                `).run({
                    tournament_key:
                        tournamentKey,
                    finalist1_user_id:
                        finalists[0].userId,
                    finalist1_clean_name:
                        finalists[0].cleanName,
                    finalist2_user_id:
                        finalists[1].userId,
                    finalist2_clean_name:
                        finalists[1].cleanName
                });

            if (
                transition.changes !== 1
            ) {
                return {
                    type:
                        'INACTIVE'
                };
            }

            return {
                type:
                    'ROUND1_COMPLETE',
                state:
                    getActiveMiniTournamentStmt.get(),
                events,
                finalists
            };
        }

        if (
            state.status ===
            'FINAL_ACTIVE'
        ) {
            const eligible = [
                state.finalist1_user_id,
                state.finalist2_user_id
            ].includes(
                userId
            );

            if (
                !eligible
            ) {
                return {
                    type:
                        'NOT_ELIGIBLE'
                };
            }

            const smashNumber =
                state.final_current_smashes +
                1;

            const update =
                db.prepare(`
                    UPDATE mini_tournament_state
                    SET
                        final_current_smashes = @smash_number
                    WHERE id = 1
                      AND tournament_key = @tournament_key
                      AND status = 'FINAL_ACTIVE'
                      AND final_current_smashes = @previous_smashes
                `).run({
                    tournament_key:
                        tournamentKey,
                    smash_number:
                        smashNumber,
                    previous_smashes:
                        state.final_current_smashes
                });

            if (
                update.changes !== 1
            ) {
                return {
                    type:
                        'INACTIVE'
                };
            }

            insertMiniTournamentEventStmt.run({
                tournament_key:
                    tournamentKey,
                round_key:
                    'FINAL',
                smash_number:
                    smashNumber,
                user_id:
                    userId,
                display_name:
                    cleanName,
                smashed_at:
                    new Date().toISOString()
            });

            const updatedState =
                getActiveMiniTournamentStmt.get();

            if (
                smashNumber <
                updatedState.final_required_smashes
            ) {
                return {
                    type:
                        'FINAL_SMASH',
                    state:
                        updatedState
                };
            }

            const player =
                awardMiniTournamentChampion(
                    tournamentKey,
                    userId
                );

            db.prepare(`
                UPDATE mini_tournament_state
                SET
                    status = 'COMPLETED',
                    winner_user_id = @winner_user_id,
                    winner_clean_name = @winner_clean_name,
                    completed_at = @completed_at
                WHERE id = 1
                  AND tournament_key = @tournament_key
                  AND status = 'FINAL_ACTIVE'
            `).run({
                tournament_key:
                    tournamentKey,
                winner_user_id:
                    userId,
                winner_clean_name:
                    cleanName,
                completed_at:
                    new Date().toISOString()
            });

            return {
                type:
                    'FINAL_COMPLETE',
                state:
                    getMiniTournamentStmt.get(),
                events:
                    getMiniTournamentEventsStmt.all(
                        tournamentKey,
                        'FINAL'
                    ),
                winner: {
                    userId,
                    cleanName
                },
                player
            };
        }

        return {
            type:
                'INACTIVE'
        };
    });

// ============================================================
// MINI ROUND 1 -> FINAL
// ============================================================

async function finishMiniTournamentRound1(
    state,
    events
) {
    if (
        !state ||
        state.status !==
        'ROUND1_COMPLETE'
    ) {
        return;
    }

    const tournamentKey =
        state.tournament_key;

    try {
        const channel =
            await client.channels.fetch(
                state.channel_id
            );

        if (
            !channel ||
            !channel.isTextBased() ||
            !channel.messages
        ) {
            throw new Error(
                'Mini Tournament channel is unavailable.'
            );
        }

        const reportEmbed =
            buildTournamentReportEmbed(
                '👊 MINI SMASH TOURNEY — ROUND 1 REPORT',
                state.round1_required_smashes,
                events,
                [
                    {
                        userId:
                            state.finalist1_user_id,
                        cleanName:
                            state.finalist1_clean_name
                    },
                    {
                        userId:
                            state.finalist2_user_id,
                        cleanName:
                            state.finalist2_clean_name
                    }
                ]
            );

        await channel.send({
            embeds: [
                reportEmbed
            ],
            allowedMentions: {
                parse: []
            }
        });

        let oldControlMessage =
            null;

        try {
            oldControlMessage =
                await channel.messages.fetch(
                    state.control_message_id
                );
        } catch (_) {
            oldControlMessage =
                null;
        }

        await removeTournamentControlMessage(
            oldControlMessage
        );

        const finalRequiredSmashes =
            randomInteger(
                MIN_SMASHES,
                MAX_SMASHES
            );

        const finalReadyAt =
            new Date(
                Date.now() +
                TOURNAMENT_FINAL_READY_MS
            );

        const finalControl =
            await channel.send({
                embeds: [
                    buildTournamentFinalEmbed(
                        state,
                        false
                    )
                ],
                components: [
                    buildTournamentReadyButton()
                ],
                allowedMentions: {
                    parse: []
                }
            });

        const update =
            db.prepare(`
                UPDATE mini_tournament_state
                SET
                    status = 'FINAL_READY',
                    control_message_id = @control_message_id,
                    final_required_smashes = @final_required_smashes,
                    final_current_smashes = 0,
                    final_ready_at = @final_ready_at
                WHERE id = 1
                  AND tournament_key = @tournament_key
                  AND status = 'ROUND1_COMPLETE'
            `).run({
                tournament_key:
                    tournamentKey,
                control_message_id:
                    finalControl.id,
                final_required_smashes:
                    finalRequiredSmashes,
                final_ready_at:
                    finalReadyAt.toISOString()
            });

        if (
            update.changes !== 1
        ) {
            try {
                await finalControl.delete();
            } catch (_) {
                // Ignore cleanup failure.
            }

            return;
        }

        console.log(
            `[MINI TOURNAMENT] Round 1 complete | ` +
            `Finalists: ${state.finalist1_clean_name} vs ${state.finalist2_clean_name} | ` +
            `Final starts in 10 seconds.`
        );

        armTournamentPhaseTimer(
            finalReadyAt,
            () =>
                activateMiniTournamentFinal(
                    tournamentKey
                )
        );
    } catch (error) {
        await abortMiniTournament(
            tournamentKey,
            `Could not move from Round 1 to Final: ${error.message}`
        );
    }
}

// ============================================================
// MINI FINAL COMPLETION
// ============================================================

async function finishMiniTournamentFinal(
    result
) {
    const state =
        result.state;

    try {
        const channel =
            await client.channels.fetch(
                state.channel_id
            );

        if (
            !channel ||
            !channel.isTextBased() ||
            !channel.messages
        ) {
            throw new Error(
                'Mini Tournament channel is unavailable.'
            );
        }

        const reportEmbed =
            buildTournamentReportEmbed(
                '👊 MINI SMASH TOURNEY — FINAL ROUND REPORT',
                state.final_required_smashes,
                result.events
            );

        await channel.send({
            embeds: [
                reportEmbed
            ],
            allowedMentions: {
                parse: []
            }
        });

        let controlMessage =
            null;

        try {
            controlMessage =
                await channel.messages.fetch(
                    state.control_message_id
                );
        } catch (_) {
            controlMessage =
                null;
        }

        await removeTournamentControlMessage(
            controlMessage
        );

        await channel.send({
            embeds: [
                buildTournamentChampionEmbed(
                    result.winner.cleanName
                )
            ],
            allowedMentions: {
                parse: []
            }
        });

        console.log(
            `[MINI TOURNAMENT] CHAMPION ${result.winner.cleanName} | ` +
            `+${TOURNAMENT_SCORE_PRIZE} Smash Score | Total: ${result.player.smash_score}`
        );

        const tapWatchMiniRound1Events =
            getMiniTournamentEventsStmt.all(
                state.tournament_key,
                'ROUND1'
            );

        const tapWatchMiniFinalEvents =
            getMiniTournamentEventsStmt.all(
                state.tournament_key,
                'FINAL'
            );

        printTapWatchReport({
            modeLabel:
                'MINI TOURNAMENT',
            sessionKey:
                `MINI:${state.tournament_key}`,
            participants:
                getMiniTournamentPlayersStmt.all(
                    state.tournament_key
                ),
            winnerUserIds: [
                result.winner.userId
            ],
            winnerNames: [
                result.winner.cleanName
            ],
            expectedHitCount:
                tapWatchMiniRound1Events.length +
                tapWatchMiniFinalEvents.length
        });

        await sendLogMessage(
            `🏆 **Mini SmashPutt Champion**\n` +
            `Winner: ${result.winner.cleanName}\n` +
            `Smash Score Earned: +${TOURNAMENT_SCORE_PRIZE}\n` +
            `Total Smash Score: ${result.player.smash_score}\n` +
            `Time: ${getCentralTimeString()}`
        );

        updateLeaderboard()
            .catch(
                error =>
                    console.error(
                        'Leaderboard refresh after Mini Tournament failed:',
                        error
                    )
            );

        await movePurchasePanelAfterAutomaticActivity(state.source);

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'mini tournament completed'
        });
    } catch (error) {
        console.error(
            '[MINI TOURNAMENT] Completion output error:',
            error
        );

        updateLeaderboard()
            .catch(
                () => {}
            );

        await movePurchasePanelAfterAutomaticActivity(state.source);

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'mini tournament completion output error'
        });
    }
}

// ============================================================
// MINI BUTTON HANDLERS
// ============================================================

async function handleMiniTournamentJoinButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[MINI TOURNAMENT] Could not acknowledge join click:',
            error
        );

        return;
    }

    const state =
        getActiveMiniTournamentStmt.get();

    if (
        !state ||
        state.status !==
            'JOINING' ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    const displayName =
        await getPlainDisplayName(
            interaction
        );

    const cleanName =
        getCleanDiscordName(
            interaction
        );

    const result =
        joinMiniTournamentTransaction({
            tournamentKey:
                state.tournament_key,
            userId:
                interaction.user.id,
            displayName,
            cleanName
        });

    if (
        result.type ===
        'ALREADY_JOINED'
    ) {
        await interaction.followUp({
            content:
                'You are already in this Mini SmashPutt Tournament.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (
        result.type ===
        'CLOSED'
    ) {
        return;
    }

    if (
        result.type ===
        'JOINED'
    ) {
        await interaction.message.edit({
            embeds: [
                buildTournamentJoinEmbed(
                    result.players
                )
            ],
            components: [
                buildTournamentJoinButton()
            ]
        });

        console.log(
            `[MINI TOURNAMENT JOIN] ${displayName} | ${result.players.length}/${TOURNAMENT_PLAYER_COUNT}`
        );

        return;
    }

    if (
        result.type ===
        'ROUND1_READY'
    ) {
        clearTournamentPhaseTimer();

        await interaction.message.edit({
            embeds: [
                buildTournamentRound1Embed(
                    false,
                    result.players
                )
            ],
            components: [
                buildTournamentReadyButton()
            ]
        });

        console.log(
            `[MINI TOURNAMENT] Four players joined. Round 1 starts in 10 seconds | ` +
            `Required smashes: ${result.state.round1_required_smashes}`
        );

        const readyAt =
            new Date(
                result.state.round1_ready_at
            );

        armTournamentPhaseTimer(
            readyAt,
            () =>
                activateMiniTournamentRound1(
                    state.tournament_key
                )
        );
    }
}

async function handleMiniTournamentSmashButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[MINI TOURNAMENT] Could not acknowledge smash click:',
            error
        );

        return;
    }

    const state =
        getActiveMiniTournamentStmt.get();

    if (
        !state ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    if (
        ![
            'ROUND1_ACTIVE',
            'FINAL_ACTIVE'
        ].includes(
            state.status
        )
    ) {
        return;
    }

    if (
        state.status ===
        'ROUND1_ACTIVE'
    ) {
        const participant =
            getMiniTournamentPlayerStmt.get(
                state.tournament_key,
                interaction.user.id
            );

        if (
            !participant
        ) {
            await interaction.followUp({
                content:
                    'Only the four tournament players can smash in this round.',
                flags:
                    MessageFlags.Ephemeral
            });

            return;
        }
    }

    if (
        state.status ===
        'FINAL_ACTIVE'
    ) {
        const isFinalist = [
            state.finalist1_user_id,
            state.finalist2_user_id
        ].includes(
            interaction.user.id
        );

        if (
            !isFinalist
        ) {
            await interaction.followUp({
                content:
                    'Finalists only.',
                flags:
                    MessageFlags.Ephemeral
            });

            return;
        }
    }

    const cleanName =
        getCleanDiscordName(
            interaction
        );

    let result;

    try {
        result =
            processMiniTournamentSmashTransaction({
                tournamentKey:
                    state.tournament_key,
                userId:
                    interaction.user.id,
                cleanName
            });
    } catch (error) {
        console.error(
            '[MINI TOURNAMENT] Smash transaction failed:',
            error
        );

        return;
    }

    if (
        [
            'ROUND1_SMASH',
            'ROUND1_COMPLETE',
            'FINAL_SMASH',
            'FINAL_COMPLETE'
        ].includes(
            result.type
        )
    ) {
        recordTapWatchHit({
            sessionKey:
                `MINI:${state.tournament_key}`,
            userId:
                interaction.user.id,
            cleanName,
            observedAt:
                interaction.createdTimestamp,
            segmentKey:
                state.status ===
                    'FINAL_ACTIVE'
                    ? 'FINAL'
                    : 'ROUND1'
        });
    }

    if (
        result.type ===
        'ROUND1_SMASH'
    ) {
        console.log(
            `[MINI TOURNAMENT ROUND 1] ${cleanName} | ` +
            `${result.state.round1_current_smashes}/${result.state.round1_required_smashes}`
        );

        return;
    }

    if (
        result.type ===
        'FINAL_SMASH'
    ) {
        console.log(
            `[MINI TOURNAMENT FINAL] ${cleanName} | ` +
            `${result.state.final_current_smashes}/${result.state.final_required_smashes}`
        );

        return;
    }

    if (
        result.type ===
        'ROUND1_COMPLETE'
    ) {
        console.log(
            `[MINI TOURNAMENT ROUND 1 COMPLETE] ` +
            `${result.state.finalist1_clean_name} and ${result.state.finalist2_clean_name} advance.`
        );

        await finishMiniTournamentRound1(
            result.state,
            result.events
        );

        return;
    }

    if (
        result.type ===
        'FINAL_COMPLETE'
    ) {
        await finishMiniTournamentFinal(
            result
        );
    }
}

// ============================================================
// CREATE MINI TOURNAMENT
// ============================================================

async function createMiniTournamentInChannel(
    channelId,
    source
) {
    if (!channelId) {
        return {
            ok: false,
            reason:
                'NO_CHANNELS'
        };
    }

    if (
        tournamentSpawnInProgress ||
        spawnInProgress ||
        battleSpawnInProgress ||
        doublesSpawnInProgress ||
        vaultDropSpawnInProgress ||
        auctionSpawnInProgress ||
        lotterySpawnInProgress ||
        underdogSpawnInProgress ||
        pictionarySpawnInProgress ||
        triviaSpawnInProgress ||
        personalPurchaseInProgress
    ) {
        return {
            ok: false,
            reason:
                'SPAWN_IN_PROGRESS'
        };
    }

    if (
        getActiveNormalActivityStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_GAME'
        };
    }

    if (
        getActiveMiniTournamentStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_TOURNAMENT'
        };
    }

    if (
        getActiveSmash1v1Stmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_BATTLE'
        };
    }

    if (
        getActiveDoublesStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_DOUBLES'
        };
    }

    if (
        getActiveVaultDropStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_VAULT_DROP'
        };
    }

    if (
        getActiveAuctionStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_AUCTION'
        };
    }

    if (
        getBlockingLotteryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_LOTTERY'
        };
    }

    if (
        getBlockingUnderdogStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_UNDERDOG'
        };
    }

    if (
        getBlockingPictionaryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PICTIONARY'
        };
    }

    if (
        getActivePersonalSmashStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PERSONAL'
        };
    }

    tournamentSpawnInProgress =
        true;

    try {
        const targetChannel =
            await client.channels.fetch(
                channelId
            );

        if (
            !targetChannel ||
            !targetChannel.isTextBased()
        ) {
            throw new Error(
                `Mini Tournament spawn channel could not be found: ${channelId}`
            );
        }

        const controlMessage =
            await targetChannel.send({
                embeds: [
                    buildTournamentJoinEmbed(
                        []
                    )
                ],
                components: [
                    buildTournamentJoinButton()
                ],
                allowedMentions: {
                    parse: []
                }
            });

        const startedAt =
            new Date();

        const joinDeadlineAt =
            new Date(
                startedAt.getTime() +
                TOURNAMENT_JOIN_WINDOW_MS
            );

        const tournamentKey =
            controlMessage.id;

        createMiniTournamentStmt.run({
            tournament_key:
                tournamentKey,
            source,
            channel_id:
                controlMessage.channelId,
            control_message_id:
                controlMessage.id,
            started_at:
                startedAt.toISOString(),
            join_deadline_at:
                joinDeadlineAt.toISOString()
        });

        pauseSchedulerForActiveGame();

        const logPrefix =
            source === 'AUTO'
                ? '[AUTO TOURNAMENT]'
                : '[FORCE TOURNAMENT]';

        console.log(
            `${logPrefix} Mini SmashPutt Tournament | ` +
            `Channel: ${controlMessage.channelId} | Message: ${controlMessage.id}`
        );

        await sendLogMessage(
            `🏆 **Mini SmashPutt Tournament Spawned**\n` +
            `Type: ${source === 'AUTO' ? 'Automatic' : source === 'PLAYER' ? 'Player Activated' : 'Forced'}\n` +
            `Channel: <#${controlMessage.channelId}>\n` +
            `Players Needed: ${TOURNAMENT_PLAYER_COUNT}\n` +
            `Time: ${getCentralTimeString()}`
        );

        armTournamentPhaseTimer(
            joinDeadlineAt,
            () =>
                cancelMiniTournamentForNotEnoughPlayers(
                    tournamentKey
                )
        );

        return {
            ok: true,
            controlMessage,
            tournamentKey
        };
    } catch (error) {
        console.error(
            `[${source} TOURNAMENT] Failed to create Mini Tournament:`,
            error
        );

        return {
            ok: false,
            reason:
                'ERROR',
            error
        };
    } finally {
        tournamentSpawnInProgress =
            false;
    }
}

// ============================================================
// RESUME MINI TOURNAMENT
// ============================================================

async function resumeMiniTournamentOnStartup() {
    clearTournamentPhaseTimer();

    const state =
        getActiveMiniTournamentStmt.get();

    if (!state) {
        console.log(
            'No active Mini SmashPutt Tournament currently exists.'
        );

        return;
    }

    console.log(
        `[MINI TOURNAMENT] Recovering ${state.status} tournament ${state.tournament_key}.`
    );

    try {
        if (
            state.status ===
            'JOINING'
        ) {
            const deadline =
                new Date(
                    state.join_deadline_at
                );

            if (
                deadline.getTime() <=
                Date.now()
            ) {
                await cancelMiniTournamentForNotEnoughPlayers(
                    state.tournament_key
                );

                return;
            }

            const players =
                getMiniTournamentPlayersStmt.all(
                    state.tournament_key
                );

            const {
                message
            } =
                await fetchTournamentControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildTournamentJoinEmbed(
                        players
                    )
                ],
                components: [
                    buildTournamentJoinButton()
                ]
            });

            armTournamentPhaseTimer(
                deadline,
                () =>
                    cancelMiniTournamentForNotEnoughPlayers(
                        state.tournament_key
                    )
            );

            return;
        }

        if (
            state.status ===
            'ROUND1_READY'
        ) {
            const players =
                getMiniTournamentPlayersStmt.all(
                    state.tournament_key
                );

            const {
                message
            } =
                await fetchTournamentControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildTournamentRound1Embed(
                        false,
                        players
                    )
                ],
                components: [
                    buildTournamentReadyButton()
                ]
            });

            const readyAt =
                new Date(
                    state.round1_ready_at
                );

            if (
                readyAt.getTime() <=
                Date.now()
            ) {
                await activateMiniTournamentRound1(
                    state.tournament_key
                );
            } else {
                armTournamentPhaseTimer(
                    readyAt,
                    () =>
                        activateMiniTournamentRound1(
                            state.tournament_key
                        )
                );
            }

            return;
        }

        if (
            state.status ===
            'ROUND1_ACTIVE'
        ) {
            const players =
                getMiniTournamentPlayersStmt.all(
                    state.tournament_key
                );

            const {
                message
            } =
                await fetchTournamentControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildTournamentRound1Embed(
                        true,
                        players
                    )
                ],
                components: [
                    buildTournamentSmashButton()
                ]
            });

            return;
        }

        if (
            state.status ===
            'ROUND1_COMPLETE'
        ) {
            const events =
                getMiniTournamentEventsStmt.all(
                    state.tournament_key,
                    'ROUND1'
                );

            await finishMiniTournamentRound1(
                state,
                events
            );

            return;
        }

        if (
            state.status ===
            'FINAL_READY'
        ) {
            const {
                message
            } =
                await fetchTournamentControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildTournamentFinalEmbed(
                        state,
                        false
                    )
                ],
                components: [
                    buildTournamentReadyButton()
                ]
            });

            const readyAt =
                new Date(
                    state.final_ready_at
                );

            if (
                readyAt.getTime() <=
                Date.now()
            ) {
                await activateMiniTournamentFinal(
                    state.tournament_key
                );
            } else {
                armTournamentPhaseTimer(
                    readyAt,
                    () =>
                        activateMiniTournamentFinal(
                            state.tournament_key
                        )
                );
            }

            return;
        }

        if (
            state.status ===
            'FINAL_ACTIVE'
        ) {
            const {
                message
            } =
                await fetchTournamentControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildTournamentFinalEmbed(
                        state,
                        true
                    )
                ],
                components: [
                    buildTournamentSmashButton()
                ]
            });
        }
    } catch (error) {
        await abortMiniTournament(
            state.tournament_key,
            `Startup recovery failed: ${error.message}`,
            false
        );
    }
}

// ============================================================
// SMASH 1 V 1
// ============================================================

let smash1v1PhaseTimer =
    null;

let smash1v1LiveRefreshTimer =
    null;

let smash1v1LiveRefreshRunning =
    false;

let smash1v1LiveRefreshPending =
    false;

let battleSpawnInProgress =
    false;

function clearSmash1v1LiveRefreshTimer() {
    if (
        smash1v1LiveRefreshTimer
    ) {
        clearTimeout(
            smash1v1LiveRefreshTimer
        );

        smash1v1LiveRefreshTimer =
            null;
    }

    smash1v1LiveRefreshPending =
        false;
}

async function refreshSmash1v1LiveDisplay(
    battleKey
) {
    if (
        smash1v1LiveRefreshRunning
    ) {
        smash1v1LiveRefreshPending =
            true;

        return;
    }

    smash1v1LiveRefreshRunning =
        true;

    try {
        let state =
            getActiveSmash1v1Stmt.get();

        if (
            !state ||
            state.battle_key !==
                battleKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        const players =
            getSmash1v1PlayersStmt.all(
                battleKey
            );

        const {
            message
        } =
            await fetchSmash1v1ControlMessage(
                state
            );

        state =
            getActiveSmash1v1Stmt.get();

        if (
            !state ||
            state.battle_key !==
                battleKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        await message.edit({
            embeds: [
                buildSmash1v1BattleEmbed(
                    players,
                    true
                )
            ],
            components: [
                buildSmash1v1SmashButton()
            ]
        });
    } catch (error) {
        console.error(
            '[SMASH 1V1] Live progress refresh failed:',
            error
        );
    } finally {
        smash1v1LiveRefreshRunning =
            false;

        if (
            smash1v1LiveRefreshPending
        ) {
            smash1v1LiveRefreshPending =
                false;

            const state =
                getActiveSmash1v1Stmt.get();

            if (
                state &&
                state.battle_key ===
                    battleKey &&
                state.status ===
                    'ACTIVE'
            ) {
                queueSmash1v1LiveRefresh(
                    battleKey
                );
            }
        }
    }
}

function queueSmash1v1LiveRefresh(
    battleKey
) {
    if (
        smash1v1LiveRefreshTimer
    ) {
        return;
    }

    if (
        smash1v1LiveRefreshRunning
    ) {
        smash1v1LiveRefreshPending =
            true;

        return;
    }

    smash1v1LiveRefreshTimer =
        setTimeout(
            () => {
                smash1v1LiveRefreshTimer =
                    null;

                refreshSmash1v1LiveDisplay(
                    battleKey
                ).catch(
                    error => {
                        console.error(
                            '[SMASH 1V1] Live refresh timer error:',
                            error
                        );
                    }
                );
            },
            SMASH_1V1_LIVE_REFRESH_MS
        );
}

async function waitForSmash1v1LiveRefreshIdle() {
    const deadline =
        Date.now() +
        3000;

    while (
        smash1v1LiveRefreshRunning &&
        Date.now() <
            deadline
    ) {
        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    25
                )
        );
    }
}

function clearSmash1v1PhaseTimer() {
    if (
        smash1v1PhaseTimer
    ) {
        clearTimeout(
            smash1v1PhaseTimer
        );

        smash1v1PhaseTimer =
            null;
    }
}

function armSmash1v1PhaseTimer(
    targetDate,
    callback
) {
    clearSmash1v1PhaseTimer();

    const delay =
        Math.max(
            250,
            targetDate.getTime() -
            Date.now()
        );

    smash1v1PhaseTimer =
        setTimeout(
            () => {
                smash1v1PhaseTimer =
                    null;

                Promise
                    .resolve(
                        callback()
                    )
                    .catch(
                        error => {
                            console.error(
                                '[SMASH 1V1] Phase timer error:',
                                error
                            );
                        }
                    );
            },
            delay
        );
}

async function fetchSmash1v1ControlMessage(
    state
) {
    const channel =
        await client.channels.fetch(
            state.channel_id
        );

    if (
        !channel ||
        !channel.isTextBased() ||
        !channel.messages
    ) {
        throw new Error(
            `Smash 1 V 1 channel could not be found: ${state.channel_id}`
        );
    }

    const message =
        await channel.messages.fetch(
            state.control_message_id
        );

    return {
        channel,
        message
    };
}

async function abortSmash1v1Battle(
    battleKey,
    reason,
    scheduleNext = true
) {
    clearSmash1v1PhaseTimer();

    const state =
        getSmash1v1Stmt.get();

    if (
        !state ||
        state.battle_key !==
        battleKey
    ) {
        return;
    }

    cancelSmash1v1Stmt.run({
        battle_key:
            battleKey,
        completed_at:
            new Date().toISOString()
    });

    console.error(
        `[SMASH 1V1] Aborted ${battleKey}: ${reason}`
    );

    try {
        const {
            message
        } =
            await fetchSmash1v1ControlMessage(
                state
            );

        await message.edit({
            embeds: [
                new EmbedBuilder()
                    .setColor(
                        0x747F8D
                    )
                    .setTitle(
                        '💥 SMASH 1 V 1 BATTLE'
                    )
                    .setDescription(
                        'Battle ended due to a technical issue.'
                    )
                    .setImage(
                        SMASH_1V1_IMAGE_URL
                    )
            ],
            components: []
        });
    } catch (_) {
        // Message may no longer exist.
    }

    await sendLogMessage(
        `⚠️ **Smash 1 V 1 Battle Ended**\n` +
        `Reason: ${reason}\n` +
        `Time: ${getCentralTimeString()}`
    );

    if (
        scheduleNext
    ) {
        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'smash 1v1 battle ended'
        });
    }
}

async function cancelSmash1v1ForNotEnoughPlayers(
    battleKey
) {
    const state =
        getSmash1v1Stmt.get();

    if (
        !state ||
        state.battle_key !==
            battleKey ||
        state.status !==
            'JOINING'
    ) {
        return;
    }

    const count =
        countSmash1v1PlayersStmt
            .get(
                battleKey
            )
            .count;

    if (
        count >=
        SMASH_1V1_PLAYER_COUNT
    ) {
        return;
    }

    clearSmash1v1PhaseTimer();

    cancelSmash1v1Stmt.run({
        battle_key:
            battleKey,
        completed_at:
            new Date().toISOString()
    });

    console.log(
        `[SMASH 1V1] Cancelled ${battleKey}: only ${count}/${SMASH_1V1_PLAYER_COUNT} players joined.`
    );

    try {
        const {
            message
        } =
            await fetchSmash1v1ControlMessage(
                state
            );

        await message.edit({
            embeds: [
                buildSmash1v1CancelledEmbed()
            ],
            components: []
        });
    } catch (error) {
        console.error(
            '[SMASH 1V1] Could not edit cancelled battle message:',
            error
        );
    }

    await sendLogMessage(
        `💥 **Smash 1 V 1 Battle Cancelled**\n` +
        `Players Joined: ${count} / ${SMASH_1V1_PLAYER_COUNT}\n` +
        `Time: ${getCentralTimeString()}`
    );

    await scheduleNextAutoSpawn({
        forceNew:
            true,
        reason:
            'smash 1v1 battle cancelled'
    });
}

const joinSmash1v1Transaction =
    db.transaction(({
        battleKey,
        userId,
        displayName,
        cleanName
    }) => {
        const state =
            getActiveSmash1v1Stmt.get();

        if (
            !state ||
            state.battle_key !==
                battleKey ||
            state.status !==
                'JOINING'
        ) {
            return {
                type:
                    'CLOSED'
            };
        }

        const existing =
            getSmash1v1PlayerStmt.get(
                battleKey,
                userId
            );

        if (
            existing
        ) {
            return {
                type:
                    'ALREADY_JOINED'
            };
        }

        const countBefore =
            countSmash1v1PlayersStmt
                .get(
                    battleKey
                )
                .count;

        if (
            countBefore >=
            SMASH_1V1_PLAYER_COUNT
        ) {
            return {
                type:
                    'CLOSED'
            };
        }

        insertSmash1v1PlayerStmt.run({
            battle_key:
                battleKey,
            user_id:
                userId,
            display_name:
                displayName,
            clean_name:
                cleanName,
            join_order:
                countBefore + 1,
            joined_at:
                new Date().toISOString()
        });

        const players =
            getSmash1v1PlayersStmt.all(
                battleKey
            );

        if (
            players.length <
            SMASH_1V1_PLAYER_COUNT
        ) {
            return {
                type:
                    'JOINED',
                players
            };
        }

        const requiredSmashes =
            randomItem(
                SMASH_1V1_TARGET_SMASHES
            );

        const readyAt =
            new Date(
                Date.now() +
                SMASH_1V1_READY_MS
            );

        db.prepare(`
            UPDATE smash_1v1_state
            SET
                status = 'READY',
                ready_at = @ready_at,
                required_smashes = @required_smashes,
                current_smashes = 0
            WHERE id = 1
              AND battle_key = @battle_key
              AND status = 'JOINING'
        `).run({
            battle_key:
                battleKey,
            ready_at:
                readyAt.toISOString(),
            required_smashes:
                requiredSmashes
        });

        return {
            type:
                'READY',
            players,
            state:
                getActiveSmash1v1Stmt.get()
        };
    });

async function activateSmash1v1Battle(
    battleKey
) {
    const state =
        getActiveSmash1v1Stmt.get();

    if (
        !state ||
        state.battle_key !==
            battleKey ||
        state.status !==
            'READY'
    ) {
        return;
    }

    const readyAt =
        new Date(
            state.ready_at
        );

    if (
        readyAt.getTime() >
        Date.now()
    ) {
        armSmash1v1PhaseTimer(
            readyAt,
            () =>
                activateSmash1v1Battle(
                    battleKey
                )
        );

        return;
    }

    const update =
        db.prepare(`
            UPDATE smash_1v1_state
            SET status = 'ACTIVE'
            WHERE id = 1
              AND battle_key = ?
              AND status = 'READY'
        `).run(
            battleKey
        );

    if (
        update.changes !== 1
    ) {
        return;
    }

    const activeState =
        getActiveSmash1v1Stmt.get();

    const players =
        getSmash1v1PlayersStmt.all(
            battleKey
        );

    try {
        const {
            message
        } =
            await fetchSmash1v1ControlMessage(
                activeState
            );

        await message.edit({
            embeds: [
                buildSmash1v1BattleEmbed(
                    players,
                    true
                )
            ],
            components: [
                buildSmash1v1SmashButton()
            ]
        });

        console.log(
            `[SMASH 1V1] LIVE | ${players[0].clean_name} vs ${players[1].clean_name} | ` +
            `Hidden combined target: ${activeState.required_smashes} | Key: ${battleKey}`
        );
    } catch (error) {
        await abortSmash1v1Battle(
            battleKey,
            `Could not activate battle: ${error.message}`
        );
    }
}

function awardSmash1v1Champion(
    battleKey,
    userId
) {
    const battlePlayer =
        getSmash1v1PlayerStmt.get(
            battleKey,
            userId
        );

    if (
        !battlePlayer
    ) {
        throw new Error(
            `Smash 1 V 1 player record missing for ${userId}.`
        );
    }

    ensurePlayer(
        userId,
        battlePlayer.display_name
    );

    addSmashScoreStmt.run({
        user_id:
            userId,
        display_name:
            battlePlayer.display_name,
        amount:
            SMASH_1V1_SCORE_PRIZE,
        updated_at:
            new Date().toISOString()
    });

    return getPlayerStmt.get(
        userId
    );
}

const processSmash1v1HitTransaction =
    db.transaction(({
        battleKey,
        userId
    }) => {
        const state =
            getActiveSmash1v1Stmt.get();

        if (
            !state ||
            state.battle_key !==
                battleKey ||
            state.status !==
                'ACTIVE'
        ) {
            return {
                type:
                    'INACTIVE'
            };
        }

        const participant =
            getSmash1v1PlayerStmt.get(
                battleKey,
                userId
            );

        if (
            !participant
        ) {
            return {
                type:
                    'NOT_ELIGIBLE'
            };
        }

        const nextTotal =
            state.current_smashes +
            1;

        const stateUpdate =
            db.prepare(`
                UPDATE smash_1v1_state
                SET
                    current_smashes = @next_total
                WHERE id = 1
                  AND battle_key = @battle_key
                  AND status = 'ACTIVE'
                  AND current_smashes = @previous_total
            `).run({
                battle_key:
                    battleKey,
                next_total:
                    nextTotal,
                previous_total:
                    state.current_smashes
            });

        if (
            stateUpdate.changes !== 1
        ) {
            return {
                type:
                    'INACTIVE'
            };
        }

        db.prepare(`
            UPDATE smash_1v1_players
            SET
                smash_count = smash_count + 1
            WHERE battle_key = ?
              AND user_id = ?
        `).run(
            battleKey,
            userId
        );

        if (
            nextTotal <
            state.required_smashes
        ) {
            return {
                type:
                    'SMASH',
                state:
                    getActiveSmash1v1Stmt.get(),
                player:
                    getSmash1v1PlayerStmt.get(
                        battleKey,
                        userId
                    )
            };
        }

        const players =
            getSmash1v1PlayersStmt.all(
                battleKey
            );

        if (
            players.length !==
            SMASH_1V1_PLAYER_COUNT
        ) {
            throw new Error(
                'Smash 1 V 1 battle does not have exactly two players.'
            );
        }

        const ranked = [
            ...players
        ].sort(
            (a, b) => {
                if (
                    b.smash_count !==
                    a.smash_count
                ) {
                    return (
                        b.smash_count -
                        a.smash_count
                    );
                }

                return (
                    a.join_order -
                    b.join_order
                );
            }
        );

        if (
            ranked[0].smash_count ===
            ranked[1].smash_count
        ) {
            throw new Error(
                'Smash 1 V 1 ended in an impossible tied smash count.'
            );
        }

        const winner =
            ranked[0];

        const player =
            awardSmash1v1Champion(
                battleKey,
                winner.user_id
            );

        const completedAt =
            new Date().toISOString();

        db.prepare(`
            UPDATE smash_1v1_state
            SET
                status = 'COMPLETED',
                winner_user_id = @winner_user_id,
                winner_clean_name = @winner_clean_name,
                completed_at = @completed_at
            WHERE id = 1
              AND battle_key = @battle_key
              AND status = 'ACTIVE'
        `).run({
            battle_key:
                battleKey,
            winner_user_id:
                winner.user_id,
            winner_clean_name:
                winner.clean_name,
            completed_at:
                completedAt
        });

        return {
            type:
                'COMPLETE',
            state:
                getSmash1v1Stmt.get(),
            players:
                getSmash1v1PlayersStmt.all(
                    battleKey
                ),
            winner,
            player
        };
    });

async function finishSmash1v1Battle(
    result
) {
    clearSmash1v1PhaseTimer();

    clearSmash1v1LiveRefreshTimer();

    await waitForSmash1v1LiveRefreshIdle();

    try {
        const {
            message
        } =
            await fetchSmash1v1ControlMessage(
                result.state
            );

        await message.edit({
            embeds: [
                buildSmash1v1FinalEmbed(
                    result.players,
                    result.winner.clean_name
                )
            ],
            components: []
        });

        console.log(
            `[SMASH 1V1] CHAMPION ${result.winner.clean_name} | ` +
            `${result.players[0].clean_name}: ${result.players[0].smash_count} | ` +
            `${result.players[1].clean_name}: ${result.players[1].smash_count} | ` +
            `+${SMASH_1V1_SCORE_PRIZE} Smash Score | Total Score: ${result.player.smash_score}`
        );

        printTapWatchReport({
            modeLabel:
                'SMASH 1 V 1',
            sessionKey:
                `SMASH_1V1:${result.state.battle_key}`,
            participants:
                result.players,
            winnerUserIds: [
                result.winner.user_id
            ],
            winnerNames: [
                result.winner.clean_name
            ],
            expectedHitCount:
                result.players.reduce(
                    (sum, player) =>
                        sum +
                        player.smash_count,
                    0
                )
        });

        await sendLogMessage(
            `🏆 **Smash 1 V 1 Champion**\n` +
            `Winner: ${result.winner.clean_name}\n` +
            `${result.players[0].clean_name}: ${result.players[0].smash_count} smashes\n` +
            `${result.players[1].clean_name}: ${result.players[1].smash_count} smashes\n` +
            `Hidden Combined Target: ${result.state.required_smashes}\n` +
            `Smash Score Earned: +${SMASH_1V1_SCORE_PRIZE}\n` +
            `Total Smash Score: ${result.player.smash_score}\n` +
            `Time: ${getCentralTimeString()}`
        );

        updateLeaderboard()
            .catch(
                error =>
                    console.error(
                        'Leaderboard refresh after Smash 1 V 1 failed:',
                        error
                    )
            );

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'smash 1v1 battle completed'
        });
    } catch (error) {
        console.error(
            '[SMASH 1V1] Completion output error:',
            error
        );

        updateLeaderboard()
            .catch(
                () => {}
            );

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'smash 1v1 completion output error'
        });
    }
}

async function handleSmash1v1JoinButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[SMASH 1V1] Could not acknowledge join click:',
            error
        );

        return;
    }

    const state =
        getActiveSmash1v1Stmt.get();

    if (
        !state ||
        state.status !==
            'JOINING' ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    const displayName =
        await getPlainDisplayName(
            interaction
        );

    const cleanName =
        getCleanDiscordName(
            interaction
        );

    const result =
        joinSmash1v1Transaction({
            battleKey:
                state.battle_key,
            userId:
                interaction.user.id,
            displayName,
            cleanName
        });

    if (
        result.type ===
        'ALREADY_JOINED'
    ) {
        await interaction.followUp({
            content:
                'You are already in this Smash 1 V 1 Battle.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (
        result.type ===
        'CLOSED'
    ) {
        return;
    }

    if (
        result.type ===
        'JOINED'
    ) {
        await interaction.message.edit({
            embeds: [
                buildSmash1v1JoinEmbed(
                    result.players
                )
            ],
            components: [
                buildSmash1v1JoinButton()
            ]
        });

        console.log(
            `[SMASH 1V1 JOIN] ${displayName} | ${result.players.length}/${SMASH_1V1_PLAYER_COUNT}`
        );

        return;
    }

    if (
        result.type ===
        'READY'
    ) {
        clearSmash1v1PhaseTimer();

        await interaction.message.edit({
            embeds: [
                buildSmash1v1BattleEmbed(
                    result.players,
                    false
                )
            ],
            components: [
                buildSmash1v1ReadyButton()
            ]
        });

        console.log(
            `[SMASH 1V1] Two players joined. Battle starts in 10 seconds | ` +
            `Hidden combined target: ${result.state.required_smashes}`
        );

        const readyAt =
            new Date(
                result.state.ready_at
            );

        armSmash1v1PhaseTimer(
            readyAt,
            () =>
                activateSmash1v1Battle(
                    state.battle_key
                )
        );
    }
}

async function handleSmash1v1SmashButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[SMASH 1V1] Could not acknowledge smash click:',
            error
        );

        return;
    }

    const state =
        getActiveSmash1v1Stmt.get();

    if (
        !state ||
        state.status !==
            'ACTIVE' ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    const participant =
        getSmash1v1PlayerStmt.get(
            state.battle_key,
            interaction.user.id
        );

    if (
        !participant
    ) {
        await interaction.followUp({
            content:
                'Only the two battle players can smash in this 1 V 1.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    let result;

    try {
        result =
            processSmash1v1HitTransaction({
                battleKey:
                    state.battle_key,
                userId:
                    interaction.user.id
            });
    } catch (error) {
        console.error(
            '[SMASH 1V1] Smash transaction failed:',
            error
        );

        return;
    }

    if (
        [
            'SMASH',
            'COMPLETE'
        ].includes(
            result.type
        )
    ) {
        recordTapWatchHit({
            sessionKey:
                `SMASH_1V1:${state.battle_key}`,
            userId:
                interaction.user.id,
            cleanName:
                participant.clean_name,
            observedAt:
                interaction.createdTimestamp
        });
    }

    if (
        result.type ===
        'SMASH'
    ) {
        console.log(
            `[SMASH 1V1 HIT] ${participant.clean_name} | ` +
            `Player: ${result.player.smash_count} | ` +
            `Combined: ${result.state.current_smashes}/${result.state.required_smashes}`
        );

        queueSmash1v1LiveRefresh(
            state.battle_key
        );

        return;
    }

    if (
        result.type ===
        'COMPLETE'
    ) {
        await finishSmash1v1Battle(
            result
        );
    }
}

async function createSmash1v1InChannel(
    channelId,
    source = 'FORCE'
) {
    if (!channelId) {
        return {
            ok: false,
            reason:
                'NO_CHANNELS'
        };
    }

    if (
        spawnInProgress ||
        tournamentSpawnInProgress ||
        battleSpawnInProgress ||
        doublesSpawnInProgress ||
        vaultDropSpawnInProgress ||
        auctionSpawnInProgress ||
        lotterySpawnInProgress ||
        underdogSpawnInProgress ||
        pictionarySpawnInProgress ||
        triviaSpawnInProgress ||
        personalPurchaseInProgress
    ) {
        return {
            ok: false,
            reason:
                'SPAWN_IN_PROGRESS'
        };
    }

    if (
        getActiveNormalActivityStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_GAME'
        };
    }

    if (
        getActiveMiniTournamentStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_TOURNAMENT'
        };
    }

    if (
        getActiveSmash1v1Stmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_BATTLE'
        };
    }

    if (
        getActiveDoublesStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_DOUBLES'
        };
    }

    if (
        getActiveVaultDropStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_VAULT_DROP'
        };
    }

    if (
        getActiveAuctionStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_AUCTION'
        };
    }

    if (
        getBlockingLotteryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_LOTTERY'
        };
    }

    if (
        getBlockingUnderdogStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_UNDERDOG'
        };
    }

    if (
        getBlockingPictionaryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PICTIONARY'
        };
    }

    if (
        getActivePersonalSmashStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PERSONAL'
        };
    }

    battleSpawnInProgress =
        true;

    try {
        const targetChannel =
            await client.channels.fetch(
                channelId
            );

        if (
            !targetChannel ||
            !targetChannel.isTextBased()
        ) {
            throw new Error(
                `Smash 1 V 1 spawn channel could not be found: ${channelId}`
            );
        }

        const controlMessage =
            await targetChannel.send({
                embeds: [
                    buildSmash1v1JoinEmbed(
                        []
                    )
                ],
                components: [
                    buildSmash1v1JoinButton()
                ],
                allowedMentions: {
                    parse: []
                }
            });

        const startedAt =
            new Date();

        const joinDeadlineAt =
            new Date(
                startedAt.getTime() +
                SMASH_1V1_JOIN_WINDOW_MS
            );

        const battleKey =
            controlMessage.id;

        createSmash1v1Stmt.run({
            battle_key:
                battleKey,
            channel_id:
                controlMessage.channelId,
            control_message_id:
                controlMessage.id,
            started_at:
                startedAt.toISOString(),
            join_deadline_at:
                joinDeadlineAt.toISOString()
        });

        pauseSchedulerForActiveGame();

        const logPrefix =
            source === 'AUTO'
                ? '[AUTO 1V1]'
                : source === 'PLAYER'
                    ? '[PLAYER 1V1]'
                    : '[FORCE 1V1]';

        console.log(
            `${logPrefix} Smash 1 V 1 Battle | ` +
            `Channel: ${controlMessage.channelId} | Message: ${controlMessage.id}`
        );

        await sendLogMessage(
            `💥 **Smash 1 V 1 Battle Spawned**\n` +
            `Type: ${source === 'AUTO' ? 'Automatic' : 'Forced'}\n` +
            `Channel: <#${controlMessage.channelId}>\n` +
            `Players Needed: ${SMASH_1V1_PLAYER_COUNT}\n` +
            `Time: ${getCentralTimeString()}`
        );

        armSmash1v1PhaseTimer(
            joinDeadlineAt,
            () =>
                cancelSmash1v1ForNotEnoughPlayers(
                    battleKey
                )
        );

        return {
            ok: true,
            controlMessage,
            battleKey
        };
    } catch (error) {
        console.error(
            `[${source} 1V1] Failed to create Smash 1 V 1 Battle:`,
            error
        );

        return {
            ok: false,
            reason:
                'ERROR',
            error
        };
    } finally {
        battleSpawnInProgress =
            false;
    }
}

async function forceSmash1v1Battle(
    interaction
) {
    if (
        spawnInProgress ||
        tournamentSpawnInProgress ||
        battleSpawnInProgress ||
        doublesSpawnInProgress ||
        vaultDropSpawnInProgress ||
        auctionSpawnInProgress ||
        lotterySpawnInProgress ||
        underdogSpawnInProgress ||
        pictionarySpawnInProgress ||
        triviaSpawnInProgress ||
        personalPurchaseInProgress
    ) {
        await interaction.reply({
            content:
                'A SmashPutt activity is already being created. Try again in a moment.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (
        hasActiveSmashPuttActivity()
    ) {
        await interaction.reply({
            content:
                'There is already an active SmashPutt activity. Complete that one before forcing a 1 V 1 Battle.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const activeSpawnChannelIds =
        getActiveSpawnChannelIds();

    if (
        activeSpawnChannelIds.length ===
        0
    ) {
        await interaction.reply({
            content:
                'There are no active SmashPutt spawn channels. Add one with `/smashputt addchannel` or `/smashputt onlychannel` first.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    await interaction.deferReply({
        flags:
            MessageFlags.Ephemeral
    });

    pauseSchedulerForActiveGame();

    const randomSpawnChannelId =
        randomItem(
            activeSpawnChannelIds
        );

    const result =
        await createSmash1v1InChannel(
            randomSpawnChannelId,
            'FORCE'
        );

    if (
        result.ok
    ) {
        await interaction.editReply({
            content:
                `Smash 1 V 1 Battle was forced successfully in <#${result.controlMessage.channelId}>.`
        });

        return;
    }

    if (
        getSchedulerFrequency() !==
            'OFF' &&
        !hasActiveSmashPuttActivity()
    ) {
        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'forced smash 1v1 battle failed'
        });
    }

    await interaction.editReply({
        content:
            'Smash 1 V 1 Battle could not be created. Check the bot logs.'
    });
}

async function resumeSmash1v1OnStartup() {
    clearSmash1v1PhaseTimer();

    clearSmash1v1LiveRefreshTimer();

    const state =
        getActiveSmash1v1Stmt.get();

    if (!state) {
        console.log(
            'No active Smash 1 V 1 Battle currently exists.'
        );

        return;
    }

    console.log(
        `[SMASH 1V1] Recovering ${state.status} battle ${state.battle_key}.`
    );

    try {
        if (
            state.status ===
            'JOINING'
        ) {
            const deadline =
                new Date(
                    state.join_deadline_at
                );

            if (
                deadline.getTime() <=
                Date.now()
            ) {
                await cancelSmash1v1ForNotEnoughPlayers(
                    state.battle_key
                );

                return;
            }

            const players =
                getSmash1v1PlayersStmt.all(
                    state.battle_key
                );

            const {
                message
            } =
                await fetchSmash1v1ControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildSmash1v1JoinEmbed(
                        players
                    )
                ],
                components: [
                    buildSmash1v1JoinButton()
                ]
            });

            armSmash1v1PhaseTimer(
                deadline,
                () =>
                    cancelSmash1v1ForNotEnoughPlayers(
                        state.battle_key
                    )
            );

            return;
        }

        if (
            state.status ===
            'READY'
        ) {
            const players =
                getSmash1v1PlayersStmt.all(
                    state.battle_key
                );

            const {
                message
            } =
                await fetchSmash1v1ControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildSmash1v1BattleEmbed(
                        players,
                        false
                    )
                ],
                components: [
                    buildSmash1v1ReadyButton()
                ]
            });

            const readyAt =
                new Date(
                    state.ready_at
                );

            if (
                readyAt.getTime() <=
                Date.now()
            ) {
                await activateSmash1v1Battle(
                    state.battle_key
                );
            } else {
                armSmash1v1PhaseTimer(
                    readyAt,
                    () =>
                        activateSmash1v1Battle(
                            state.battle_key
                        )
                );
            }

            return;
        }

        if (
            state.status ===
            'ACTIVE'
        ) {
            const players =
                getSmash1v1PlayersStmt.all(
                    state.battle_key
                );

            const {
                message
            } =
                await fetchSmash1v1ControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildSmash1v1BattleEmbed(
                        players,
                        true
                    )
                ],
                components: [
                    buildSmash1v1SmashButton()
                ]
            });
        }
    } catch (error) {
        await abortSmash1v1Battle(
            state.battle_key,
            `Startup recovery failed: ${error.message}`,
            false
        );
    }
}

// ============================================================
// SMASHPUTT DOUBLES
// ============================================================

let doublesPhaseTimer =
    null;

let doublesLiveRefreshTimer =
    null;

let doublesLiveRefreshRunning =
    false;

let doublesLiveRefreshPending =
    false;

let doublesSpawnInProgress =
    false;

function clearDoublesLiveRefreshTimer() {
    if (
        doublesLiveRefreshTimer
    ) {
        clearTimeout(
            doublesLiveRefreshTimer
        );

        doublesLiveRefreshTimer =
            null;
    }

    doublesLiveRefreshPending =
        false;
}

async function refreshDoublesLiveDisplay(
    matchKey
) {
    if (
        doublesLiveRefreshRunning
    ) {
        doublesLiveRefreshPending =
            true;

        return;
    }

    doublesLiveRefreshRunning =
        true;

    try {
        let state =
            getActiveDoublesStmt.get();

        if (
            !state ||
            state.match_key !==
                matchKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        const players =
            getDoublesPlayersStmt.all(
                matchKey
            );

        const {
            message
        } =
            await fetchDoublesControlMessage(
                state
            );

        state =
            getActiveDoublesStmt.get();

        if (
            !state ||
            state.match_key !==
                matchKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        await message.edit({
            embeds: [
                buildDoublesMatchEmbed(
                    players,
                    true
                )
            ],
            components: [
                buildDoublesSmashButton()
            ]
        });
    } catch (error) {
        console.error(
            '[DOUBLES] Live progress refresh failed:',
            error
        );
    } finally {
        doublesLiveRefreshRunning =
            false;

        if (
            doublesLiveRefreshPending
        ) {
            doublesLiveRefreshPending =
                false;

            const state =
                getActiveDoublesStmt.get();

            if (
                state &&
                state.match_key ===
                    matchKey &&
                state.status ===
                    'ACTIVE'
            ) {
                queueDoublesLiveRefresh(
                    matchKey
                );
            }
        }
    }
}

function queueDoublesLiveRefresh(
    matchKey
) {
    if (
        doublesLiveRefreshTimer
    ) {
        return;
    }

    if (
        doublesLiveRefreshRunning
    ) {
        doublesLiveRefreshPending =
            true;

        return;
    }

    doublesLiveRefreshTimer =
        setTimeout(
            () => {
                doublesLiveRefreshTimer =
                    null;

                refreshDoublesLiveDisplay(
                    matchKey
                ).catch(
                    error => {
                        console.error(
                            '[DOUBLES] Live refresh timer error:',
                            error
                        );
                    }
                );
            },
            DOUBLES_LIVE_REFRESH_MS
        );
}

async function waitForDoublesLiveRefreshIdle() {
    const deadline =
        Date.now() +
        3000;

    while (
        doublesLiveRefreshRunning &&
        Date.now() <
            deadline
    ) {
        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    25
                )
        );
    }
}

function clearDoublesPhaseTimer() {
    if (
        doublesPhaseTimer
    ) {
        clearTimeout(
            doublesPhaseTimer
        );

        doublesPhaseTimer =
            null;
    }
}

function armDoublesPhaseTimer(
    targetDate,
    callback
) {
    clearDoublesPhaseTimer();

    const delay =
        Math.max(
            250,
            targetDate.getTime() -
            Date.now()
        );

    doublesPhaseTimer =
        setTimeout(
            () => {
                doublesPhaseTimer =
                    null;

                Promise
                    .resolve(
                        callback()
                    )
                    .catch(
                        error => {
                            console.error(
                                '[DOUBLES] Phase timer error:',
                                error
                            );
                        }
                    );
            },
            delay
        );
}

async function fetchDoublesControlMessage(
    state
) {
    const channel =
        await client.channels.fetch(
            state.channel_id
        );

    if (
        !channel ||
        !channel.isTextBased() ||
        !channel.messages
    ) {
        throw new Error(
            `SmashPutt Doubles channel could not be found: ${state.channel_id}`
        );
    }

    const message =
        await channel.messages.fetch(
            state.control_message_id
        );

    return {
        channel,
        message
    };
}

async function abortDoublesMatch(
    matchKey,
    reason,
    scheduleNext = true
) {
    clearDoublesPhaseTimer();

    clearDoublesLiveRefreshTimer();

    const state =
        getDoublesStmt.get();

    if (
        !state ||
        state.match_key !==
        matchKey
    ) {
        return;
    }

    cancelDoublesStmt.run({
        match_key:
            matchKey,
        completed_at:
            new Date().toISOString()
    });

    console.error(
        `[DOUBLES] Aborted ${matchKey}: ${reason}`
    );

    try {
        const {
            message
        } =
            await fetchDoublesControlMessage(
                state
            );

        await message.edit({
            embeds: [
                new EmbedBuilder()
                    .setColor(
                        0x747F8D
                    )
                    .setTitle(
                        '💥 SMASHPUTT DOUBLES'
                    )
                    .setDescription(
                        'Doubles match ended due to a technical issue.'
                    )
                    .setImage(
                        DOUBLES_IMAGE_URL
                    )
            ],
            components: []
        });
    } catch (_) {
        // Control message may no longer exist.
    }

    await sendLogMessage(
        `⚠️ **SmashPutt Doubles Ended**\n` +
        `Reason: ${reason}\n` +
        `Time: ${getCentralTimeString()}`
    );

    if (
        scheduleNext
    ) {
        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'doubles match ended'
        });
    }
}

async function cancelDoublesForNotEnoughPlayers(
    matchKey
) {
    const state =
        getDoublesStmt.get();

    if (
        !state ||
        state.match_key !==
            matchKey ||
        state.status !==
            'JOINING'
    ) {
        return;
    }

    const count =
        countDoublesPlayersStmt
            .get(
                matchKey
            )
            .count;

    if (
        count >=
        DOUBLES_PLAYER_COUNT
    ) {
        return;
    }

    clearDoublesPhaseTimer();

    clearDoublesLiveRefreshTimer();

    cancelDoublesStmt.run({
        match_key:
            matchKey,
        completed_at:
            new Date().toISOString()
    });

    console.log(
        `[DOUBLES] Cancelled ${matchKey}: only ${count}/${DOUBLES_PLAYER_COUNT} players joined.`
    );

    try {
        const {
            message
        } =
            await fetchDoublesControlMessage(
                state
            );

        await message.edit({
            embeds: [
                buildDoublesCancelledEmbed()
            ],
            components: []
        });
    } catch (error) {
        console.error(
            '[DOUBLES] Could not edit cancelled Doubles message:',
            error
        );
    }

    await sendLogMessage(
        `💥 **SmashPutt Doubles Cancelled**\n` +
        `Players Joined: ${count} / ${DOUBLES_PLAYER_COUNT}\n` +
        `Time: ${getCentralTimeString()}`
    );

    await scheduleNextAutoSpawn({
        forceNew:
            true,
        reason:
            'doubles match cancelled'
    });
}

const joinDoublesTransaction =
    db.transaction(({
        matchKey,
        userId,
        displayName,
        cleanName
    }) => {
        const state =
            getActiveDoublesStmt.get();

        if (
            !state ||
            state.match_key !==
                matchKey ||
            state.status !==
                'JOINING'
        ) {
            return {
                type:
                    'CLOSED'
            };
        }

        const existing =
            getDoublesPlayerStmt.get(
                matchKey,
                userId
            );

        if (
            existing
        ) {
            return {
                type:
                    'ALREADY_JOINED'
            };
        }

        const countBefore =
            countDoublesPlayersStmt
                .get(
                    matchKey
                )
                .count;

        if (
            countBefore >=
            DOUBLES_PLAYER_COUNT
        ) {
            return {
                type:
                    'CLOSED'
            };
        }

        const joinOrder =
            countBefore + 1;

        const teamKey =
            joinOrder <= 2
                ? 'A'
                : 'B';

        insertDoublesPlayerStmt.run({
            match_key:
                matchKey,
            user_id:
                userId,
            display_name:
                displayName,
            clean_name:
                cleanName,
            join_order:
                joinOrder,
            team_key:
                teamKey,
            joined_at:
                new Date().toISOString()
        });

        const players =
            getDoublesPlayersStmt.all(
                matchKey
            );

        if (
            players.length <
            DOUBLES_PLAYER_COUNT
        ) {
            return {
                type:
                    'JOINED',
                players
            };
        }

        const requiredSmashes =
            randomItem(
                DOUBLES_TARGET_SMASHES
            );

        const readyAt =
            new Date(
                Date.now() +
                DOUBLES_READY_MS
            );

        db.prepare(`
            UPDATE smash_doubles_state
            SET
                status = 'READY',
                ready_at = @ready_at,
                required_smashes = @required_smashes,
                current_smashes = 0
            WHERE id = 1
              AND match_key = @match_key
              AND status = 'JOINING'
        `).run({
            match_key:
                matchKey,
            ready_at:
                readyAt.toISOString(),
            required_smashes:
                requiredSmashes
        });

        return {
            type:
                'READY',
            players,
            state:
                getActiveDoublesStmt.get()
        };
    });

async function activateDoublesMatch(
    matchKey
) {
    const state =
        getActiveDoublesStmt.get();

    if (
        !state ||
        state.match_key !==
            matchKey ||
        state.status !==
            'READY'
    ) {
        return;
    }

    const readyAt =
        new Date(
            state.ready_at
        );

    if (
        readyAt.getTime() >
        Date.now()
    ) {
        armDoublesPhaseTimer(
            readyAt,
            () =>
                activateDoublesMatch(
                    matchKey
                )
        );

        return;
    }

    const update =
        db.prepare(`
            UPDATE smash_doubles_state
            SET status = 'ACTIVE'
            WHERE id = 1
              AND match_key = ?
              AND status = 'READY'
        `).run(
            matchKey
        );

    if (
        update.changes !== 1
    ) {
        return;
    }

    const activeState =
        getActiveDoublesStmt.get();

    const players =
        getDoublesPlayersStmt.all(
            matchKey
        );

    try {
        const {
            message
        } =
            await fetchDoublesControlMessage(
                activeState
            );

        await message.edit({
            embeds: [
                buildDoublesMatchEmbed(
                    players,
                    true
                )
            ],
            components: [
                buildDoublesSmashButton()
            ]
        });

        console.log(
            `[DOUBLES] LIVE | Hidden combined target: ${activeState.required_smashes} | ` +
            `Key: ${matchKey}`
        );
    } catch (error) {
        await abortDoublesMatch(
            matchKey,
            `Could not activate Doubles match: ${error.message}`
        );
    }
}

function awardDoublesWinningTeam(
    matchKey,
    winnerTeam
) {
    const winners =
        getDoublesPlayersStmt
            .all(
                matchKey
            )
            .filter(
                player =>
                    player.team_key ===
                    winnerTeam
            );

    if (
        winners.length !== 2
    ) {
        throw new Error(
            `Doubles winning team ${winnerTeam} does not have exactly two players.`
        );
    }

    const awarded = [];

    for (
        const winner
        of winners
    ) {
        ensurePlayer(
            winner.user_id,
            winner.display_name
        );

        addSmashScoreStmt.run({
            user_id:
                winner.user_id,
            display_name:
                winner.display_name,
            amount:
                DOUBLES_SCORE_PRIZE,
            updated_at:
                new Date().toISOString()
        });

        awarded.push({
            userId:
                winner.user_id,
            cleanName:
                winner.clean_name,
            player:
                getPlayerStmt.get(
                    winner.user_id
                )
        });
    }

    return awarded;
}

const processDoublesHitTransaction =
    db.transaction(({
        matchKey,
        userId
    }) => {
        const state =
            getActiveDoublesStmt.get();

        if (
            !state ||
            state.match_key !==
                matchKey ||
            state.status !==
                'ACTIVE'
        ) {
            return {
                type:
                    'INACTIVE'
            };
        }

        const participant =
            getDoublesPlayerStmt.get(
                matchKey,
                userId
            );

        if (
            !participant
        ) {
            return {
                type:
                    'NOT_ELIGIBLE'
            };
        }

        const nextTotal =
            state.current_smashes +
            1;

        const stateUpdate =
            db.prepare(`
                UPDATE smash_doubles_state
                SET
                    current_smashes = @next_total
                WHERE id = 1
                  AND match_key = @match_key
                  AND status = 'ACTIVE'
                  AND current_smashes = @previous_total
            `).run({
                match_key:
                    matchKey,
                next_total:
                    nextTotal,
                previous_total:
                    state.current_smashes
            });

        if (
            stateUpdate.changes !== 1
        ) {
            return {
                type:
                    'INACTIVE'
            };
        }

        db.prepare(`
            UPDATE smash_doubles_players
            SET
                smash_count = smash_count + 1
            WHERE match_key = ?
              AND user_id = ?
        `).run(
            matchKey,
            userId
        );

        if (
            nextTotal <
            state.required_smashes
        ) {
            return {
                type:
                    'SMASH',
                state:
                    getActiveDoublesStmt.get(),
                player:
                    getDoublesPlayerStmt.get(
                        matchKey,
                        userId
                    )
            };
        }

        const players =
            getDoublesPlayersStmt.all(
                matchKey
            );

        if (
            players.length !==
            DOUBLES_PLAYER_COUNT
        ) {
            throw new Error(
                'SmashPutt Doubles does not have exactly four players.'
            );
        }

        const teamATotal =
            players
                .filter(
                    player =>
                        player.team_key === 'A'
                )
                .reduce(
                    (sum, player) =>
                        sum +
                        player.smash_count,
                    0
                );

        const teamBTotal =
            players
                .filter(
                    player =>
                        player.team_key === 'B'
                )
                .reduce(
                    (sum, player) =>
                        sum +
                        player.smash_count,
                    0
                );

        if (
            teamATotal ===
            teamBTotal
        ) {
            throw new Error(
                'SmashPutt Doubles ended in an impossible tied team total.'
            );
        }

        const winnerTeam =
            teamATotal >
            teamBTotal
                ? 'A'
                : 'B';

        const awardedPlayers =
            awardDoublesWinningTeam(
                matchKey,
                winnerTeam
            );

        db.prepare(`
            UPDATE smash_doubles_state
            SET
                status = 'COMPLETED',
                winner_team = @winner_team,
                completed_at = @completed_at
            WHERE id = 1
              AND match_key = @match_key
              AND status = 'ACTIVE'
        `).run({
            match_key:
                matchKey,
            winner_team:
                winnerTeam,
            completed_at:
                new Date().toISOString()
        });

        return {
            type:
                'COMPLETE',
            state:
                getDoublesStmt.get(),
            players:
                getDoublesPlayersStmt.all(
                    matchKey
                ),
            winnerTeam,
            teamATotal,
            teamBTotal,
            awardedPlayers
        };
    });

async function finishDoublesMatch(
    result
) {
    clearDoublesPhaseTimer();

    clearDoublesLiveRefreshTimer();

    await waitForDoublesLiveRefreshIdle();

    clearVaultDropPhaseTimer();

    try {
        const {
            message
        } =
            await fetchDoublesControlMessage(
                result.state
            );

        await message.edit({
            embeds: [
                buildDoublesFinalEmbed(
                    result.players,
                    result.winnerTeam
                )
            ],
            components: []
        });

        const winners =
            result.awardedPlayers
                .map(
                    award =>
                        award.cleanName
                )
                .join(' & ');

        console.log(
            `[DOUBLES] TEAM ${result.winnerTeam} WINS | ` +
            `Team A: ${result.teamATotal} | Team B: ${result.teamBTotal} | ` +
            `Winners: ${winners} | +${DOUBLES_SCORE_PRIZE} each`
        );

        const tapWatchDoublesWinners =
            result.players.filter(
                player =>
                    player.team_key ===
                    result.winnerTeam
            );

        printTapWatchReport({
            modeLabel:
                'DOUBLES',
            sessionKey:
                `DOUBLES:${result.state.match_key}`,
            participants:
                result.players,
            winnerUserIds:
                tapWatchDoublesWinners.map(
                    player =>
                        player.user_id
                ),
            winnerNames:
                tapWatchDoublesWinners.map(
                    player =>
                        player.clean_name
                ),
            expectedHitCount:
                result.players.reduce(
                    (sum, player) =>
                        sum +
                        player.smash_count,
                    0
                )
        });

        await sendLogMessage(
            `🏆 **SmashPutt Doubles — Team ${result.winnerTeam} Wins**\n` +
            `${result.players[0].clean_name}: ${result.players[0].smash_count} smashes\n` +
            `${result.players[1].clean_name}: ${result.players[1].smash_count} smashes\n` +
            `Team A Total: ${result.teamATotal}\n` +
            `${result.players[2].clean_name}: ${result.players[2].smash_count} smashes\n` +
            `${result.players[3].clean_name}: ${result.players[3].smash_count} smashes\n` +
            `Team B Total: ${result.teamBTotal}\n` +
            `Hidden Combined Target: ${result.state.required_smashes}\n` +
            `Winning Players: ${winners}\n` +
            `Smash Score Earned: +${DOUBLES_SCORE_PRIZE} each\n` +
            `Time: ${getCentralTimeString()}`
        );

        updateLeaderboard()
            .catch(
                error =>
                    console.error(
                        'Leaderboard refresh after SmashPutt Doubles failed:',
                        error
                    )
            );

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'doubles match completed'
        });
    } catch (error) {
        console.error(
            '[DOUBLES] Completion output error:',
            error
        );

        updateLeaderboard()
            .catch(
                () => {}
            );

        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'doubles completion output error'
        });
    }
}

async function handleDoublesJoinButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[DOUBLES] Could not acknowledge join click:',
            error
        );

        return;
    }

    const state =
        getActiveDoublesStmt.get();

    if (
        !state ||
        state.status !==
            'JOINING' ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    const displayName =
        await getPlainDisplayName(
            interaction
        );

    const cleanName =
        getCleanDiscordName(
            interaction
        );

    const result =
        joinDoublesTransaction({
            matchKey:
                state.match_key,
            userId:
                interaction.user.id,
            displayName,
            cleanName
        });

    if (
        result.type ===
        'ALREADY_JOINED'
    ) {
        await interaction.followUp({
            content:
                'You are already in this SmashPutt Doubles match.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (
        result.type ===
        'CLOSED'
    ) {
        return;
    }

    if (
        result.type ===
        'JOINED'
    ) {
        await interaction.message.edit({
            embeds: [
                buildDoublesJoinEmbed(
                    result.players
                )
            ],
            components: [
                buildDoublesJoinButton()
            ]
        });

        console.log(
            `[DOUBLES JOIN] ${displayName} | ` +
            `${result.players.length}/${DOUBLES_PLAYER_COUNT}`
        );

        return;
    }

    if (
        result.type ===
        'READY'
    ) {
        clearDoublesPhaseTimer();

        await interaction.message.edit({
            embeds: [
                buildDoublesMatchEmbed(
                    result.players,
                    false
                )
            ],
            components: [
                buildDoublesReadyButton()
            ]
        });

        console.log(
            `[DOUBLES] Four players joined. Match starts in 10 seconds | ` +
            `Hidden combined target: ${result.state.required_smashes}`
        );

        const readyAt =
            new Date(
                result.state.ready_at
            );

        armDoublesPhaseTimer(
            readyAt,
            () =>
                activateDoublesMatch(
                    state.match_key
                )
        );
    }
}

async function handleDoublesSmashButton(
    interaction
) {
    try {
        await interaction.deferUpdate();
    } catch (error) {
        console.error(
            '[DOUBLES] Could not acknowledge smash click:',
            error
        );

        return;
    }

    const state =
        getActiveDoublesStmt.get();

    if (
        !state ||
        state.status !==
            'ACTIVE' ||
        interaction.channelId !==
            state.channel_id ||
        interaction.message.id !==
            state.control_message_id
    ) {
        return;
    }

    const participant =
        getDoublesPlayerStmt.get(
            state.match_key,
            interaction.user.id
        );

    if (
        !participant
    ) {
        await interaction.followUp({
            content:
                'Only the four Doubles players can smash in this match.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    let result;

    try {
        result =
            processDoublesHitTransaction({
                matchKey:
                    state.match_key,
                userId:
                    interaction.user.id
            });
    } catch (error) {
        console.error(
            '[DOUBLES] Smash transaction failed:',
            error
        );

        return;
    }

    if (
        [
            'SMASH',
            'COMPLETE'
        ].includes(
            result.type
        )
    ) {
        recordTapWatchHit({
            sessionKey:
                `DOUBLES:${state.match_key}`,
            userId:
                interaction.user.id,
            cleanName:
                participant.clean_name,
            observedAt:
                interaction.createdTimestamp
        });
    }

    if (
        result.type ===
        'SMASH'
    ) {
        console.log(
            `[DOUBLES HIT] ${participant.clean_name} | ` +
            `Player: ${result.player.smash_count} | ` +
            `Combined: ${result.state.current_smashes}/${result.state.required_smashes}`
        );

        queueDoublesLiveRefresh(
            state.match_key
        );

        return;
    }

    if (
        result.type ===
        'COMPLETE'
    ) {
        await finishDoublesMatch(
            result
        );
    }
}

async function createDoublesInChannel(
    channelId,
    source = 'FORCE'
) {
    if (!channelId) {
        return {
            ok: false,
            reason:
                'NO_CHANNELS'
        };
    }

    if (
        spawnInProgress ||
        tournamentSpawnInProgress ||
        battleSpawnInProgress ||
        doublesSpawnInProgress ||
        vaultDropSpawnInProgress ||
        auctionSpawnInProgress ||
        lotterySpawnInProgress ||
        underdogSpawnInProgress ||
        pictionarySpawnInProgress ||
        triviaSpawnInProgress ||
        personalPurchaseInProgress
    ) {
        return {
            ok: false,
            reason:
                'SPAWN_IN_PROGRESS'
        };
    }

    if (
        getActiveNormalActivityStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_GAME'
        };
    }

    if (
        getActiveMiniTournamentStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_TOURNAMENT'
        };
    }

    if (
        getActiveSmash1v1Stmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_BATTLE'
        };
    }

    if (
        getActiveDoublesStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_DOUBLES'
        };
    }

    if (
        getActiveVaultDropStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_VAULT_DROP'
        };
    }

    if (
        getActiveAuctionStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_AUCTION'
        };
    }

    if (
        getBlockingLotteryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_LOTTERY'
        };
    }

    if (
        getBlockingUnderdogStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_UNDERDOG'
        };
    }

    if (
        getBlockingPictionaryStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PICTIONARY'
        };
    }

    if (
        getActivePersonalSmashStmt.get()
    ) {
        return {
            ok: false,
            reason:
                'ACTIVE_PERSONAL'
        };
    }

    doublesSpawnInProgress =
        true;

    try {
        const targetChannel =
            await client.channels.fetch(
                channelId
            );

        if (
            !targetChannel ||
            !targetChannel.isTextBased()
        ) {
            throw new Error(
                `SmashPutt Doubles spawn channel could not be found: ${channelId}`
            );
        }

        const controlMessage =
            await targetChannel.send({
                embeds: [
                    buildDoublesJoinEmbed(
                        []
                    )
                ],
                components: [
                    buildDoublesJoinButton()
                ],
                allowedMentions: {
                    parse: []
                }
            });

        const startedAt =
            new Date();

        const joinDeadlineAt =
            new Date(
                startedAt.getTime() +
                DOUBLES_JOIN_WINDOW_MS
            );

        const matchKey =
            controlMessage.id;

        createDoublesStmt.run({
            match_key:
                matchKey,
            channel_id:
                controlMessage.channelId,
            control_message_id:
                controlMessage.id,
            started_at:
                startedAt.toISOString(),
            join_deadline_at:
                joinDeadlineAt.toISOString()
        });

        pauseSchedulerForActiveGame();

        const logPrefix =
            source === 'AUTO'
                ? '[AUTO DOUBLES]'
                : source === 'PLAYER'
                    ? '[PLAYER DOUBLES]'
                    : '[FORCE DOUBLES]';

        console.log(
            `${logPrefix} SmashPutt Doubles | ` +
            `Channel: ${controlMessage.channelId} | ` +
            `Message: ${controlMessage.id}`
        );

        await sendLogMessage(
            `💥 **SmashPutt Doubles Spawned**\n` +
            `Type: ${source === 'AUTO' ? 'Automatic' : source === 'PLAYER' ? 'Player Activated' : 'Forced'}\n` +
            `Channel: <#${controlMessage.channelId}>\n` +
            `Players Needed: ${DOUBLES_PLAYER_COUNT}\n` +
            `Time: ${getCentralTimeString()}`
        );

        armDoublesPhaseTimer(
            joinDeadlineAt,
            () =>
                cancelDoublesForNotEnoughPlayers(
                    matchKey
                )
        );

        return {
            ok: true,
            controlMessage,
            matchKey
        };
    } catch (error) {
        console.error(
            `[${source} DOUBLES] Failed to create SmashPutt Doubles:`,
            error
        );

        return {
            ok: false,
            reason:
                'ERROR',
            error
        };
    } finally {
        doublesSpawnInProgress =
            false;
    }
}

async function forceDoublesMatch(
    interaction
) {
    if (
        spawnInProgress ||
        tournamentSpawnInProgress ||
        battleSpawnInProgress ||
        doublesSpawnInProgress ||
        vaultDropSpawnInProgress ||
        auctionSpawnInProgress ||
        lotterySpawnInProgress ||
        underdogSpawnInProgress ||
        pictionarySpawnInProgress ||
        triviaSpawnInProgress ||
        personalPurchaseInProgress
    ) {
        await interaction.reply({
            content:
                'A SmashPutt activity is already being created. Try again in a moment.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    if (
        hasActiveSmashPuttActivity()
    ) {
        await interaction.reply({
            content:
                'There is already an active SmashPutt activity. Complete that one before forcing Doubles.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    const activeSpawnChannelIds =
        getActiveSpawnChannelIds();

    if (
        activeSpawnChannelIds.length ===
        0
    ) {
        await interaction.reply({
            content:
                'There are no active SmashPutt spawn channels. Add one with `/smashputt addchannel` or `/smashputt onlychannel` first.',
            flags:
                MessageFlags.Ephemeral
        });

        return;
    }

    await interaction.deferReply({
        flags:
            MessageFlags.Ephemeral
    });

    pauseSchedulerForActiveGame();

    const randomSpawnChannelId =
        randomItem(
            activeSpawnChannelIds
        );

    const result =
        await createDoublesInChannel(
            randomSpawnChannelId,
            'FORCE'
        );

    if (
        result.ok
    ) {
        await interaction.editReply({
            content:
                `SmashPutt Doubles was forced successfully in <#${result.controlMessage.channelId}>.`
        });

        return;
    }

    if (
        getSchedulerFrequency() !==
            'OFF' &&
        !hasActiveSmashPuttActivity()
    ) {
        await scheduleNextAutoSpawn({
            forceNew:
                true,
            reason:
                'forced doubles failed'
        });
    }

    await interaction.editReply({
        content:
            'SmashPutt Doubles could not be created. Check the bot logs.'
    });
}

async function resumeDoublesOnStartup() {
    clearDoublesPhaseTimer();

    clearDoublesLiveRefreshTimer();

    const state =
        getActiveDoublesStmt.get();

    if (!state) {
        console.log(
            'No active SmashPutt Doubles match currently exists.'
        );

        return;
    }

    console.log(
        `[DOUBLES] Recovering ${state.status} match ${state.match_key}.`
    );

    try {
        if (
            state.status ===
            'JOINING'
        ) {
            const deadline =
                new Date(
                    state.join_deadline_at
                );

            if (
                deadline.getTime() <=
                Date.now()
            ) {
                await cancelDoublesForNotEnoughPlayers(
                    state.match_key
                );

                return;
            }

            const players =
                getDoublesPlayersStmt.all(
                    state.match_key
                );

            const {
                message
            } =
                await fetchDoublesControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildDoublesJoinEmbed(
                        players
                    )
                ],
                components: [
                    buildDoublesJoinButton()
                ]
            });

            armDoublesPhaseTimer(
                deadline,
                () =>
                    cancelDoublesForNotEnoughPlayers(
                        state.match_key
                    )
            );

            return;
        }

        if (
            state.status ===
            'READY'
        ) {
            const players =
                getDoublesPlayersStmt.all(
                    state.match_key
                );

            const {
                message
            } =
                await fetchDoublesControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildDoublesMatchEmbed(
                        players,
                        false
                    )
                ],
                components: [
                    buildDoublesReadyButton()
                ]
            });

            const readyAt =
                new Date(
                    state.ready_at
                );

            if (
                readyAt.getTime() <=
                Date.now()
            ) {
                await activateDoublesMatch(
                    state.match_key
                );
            } else {
                armDoublesPhaseTimer(
                    readyAt,
                    () =>
                        activateDoublesMatch(
                            state.match_key
                        )
                );
            }

            return;
        }

        if (
            state.status ===
            'ACTIVE'
        ) {
            const players =
                getDoublesPlayersStmt.all(
                    state.match_key
                );

            const {
                message
            } =
                await fetchDoublesControlMessage(
                    state
                );

            await message.edit({
                embeds: [
                    buildDoublesMatchEmbed(
                        players,
                        true
                    )
                ],
                components: [
                    buildDoublesSmashButton()
                ]
            });
        }
    } catch (error) {
        await abortDoublesMatch(
            state.match_key,
            `Startup recovery failed: ${error.message}`,
            false
        );
    }
}

// ============================================================
// SMASHPUTT VAULT DROP
// ============================================================

let vaultDropPhaseTimer =
    null;

let vaultDropLiveRefreshTimer =
    null;

let vaultDropLiveRefreshRunning =
    false;

let vaultDropLiveRefreshPending =
    false;

let vaultDropSpawnInProgress =
    false;

function clearVaultDropLiveRefreshTimer() {
    if (
        vaultDropLiveRefreshTimer
    ) {
        clearTimeout(
            vaultDropLiveRefreshTimer
        );

        vaultDropLiveRefreshTimer =
            null;
    }

    vaultDropLiveRefreshPending =
        false;
}

async function refreshVaultDropLiveDisplay(
    dropKey
) {
    if (
        vaultDropLiveRefreshRunning
    ) {
        vaultDropLiveRefreshPending =
            true;

        return;
    }

    vaultDropLiveRefreshRunning =
        true;

    try {
        let state =
            getActiveVaultDropStmt.get();

        if (
            !state ||
            state.drop_key !==
                dropKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        const players =
            getVaultDropPlayersStmt.all(
                dropKey
            );

        const {
            message
        } =
            await fetchVaultDropControlMessage(
                state
            );

        state =
            getActiveVaultDropStmt.get();

        if (
            !state ||
            state.drop_key !==
                dropKey ||
            state.status !==
                'ACTIVE'
        ) {
            return;
        }

        await message.edit({
            embeds: [
                buildVaultDropEmbed(
                    state,
                    players,
                    'ACTIVE'
                )
            ],
            components: [
                buildVaultDropSmashButton()
            ]
        });
    } catch (error) {
        console.error(
            '[VAULT DROP] Live progress refresh failed:',
            error
        );
    } finally {
        vaultDropLiveRefreshRunning =
            false;

        if (
            vaultDropLiveRefreshPending
        ) {
            vaultDropLiveRefreshPending =
                false;

            const state =
                getActiveVaultDropStmt.get();

            if (
                state &&
                state.drop_key ===
                    dropKey &&
                state.status ===
                    'ACTIVE'
            ) {
                queueVaultDropLiveRefresh(
                    dropKey
                );
            }
        }
    }
}

function queueVaultDropLiveRefresh(
    dropKey
) {
    if (
        vaultDropLiveRefreshTimer
    ) {
        return;
    }

    if (
        vaultDropLiveRefreshRunning
    ) {
        vaultDropLiveRefreshPending =
            true;

        return;
    }

    vaultDropLiveRefreshTimer =
        setTimeout(
            () => {
                vaultDropLiveRefreshTimer =
                    null;

                refreshVaultDropLiveDisplay(
                    dropKey
                ).catch(
                    error => {
                        console.error(
                            '[VAULT DROP] Live refresh timer error:',
                            error
                        );
                    }
                );
            },
            VAULT_DROP_LIVE_REFRESH_MS
        );
}

async function waitForVaultDropLiveRefreshIdle() {
    const deadline =
        Date.now() +
        3000;

    while (
        vaultDropLiveRefreshRunning &&
        Date.now() <
            deadline
    ) {
        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    25
                )
        );
    }
}

function clearVaultDropPhaseTimer() {
    if (
        vaultDropPhaseTimer
    ) {
        clearTimeout(
            vaultDropPhaseTimer
        );

        vaultDropPhaseTimer =
            null;
    }
}

function armVaultDropPhaseTimer(
    targetDate,
    callback
) {
    clearVaultDropPhaseTimer();

    const delay =
        Math.max(
            250,
            targetDate.getTime() -
            Date.now()
        );

    vaultDropPhaseTimer =
        setTimeout(
            () => {
                vaultDropPhaseTimer =
                    null;

                Promise
                    .resolve(
                        callback()
                    )
                    .catch(
                        error => {
                            console.error(
                                '[VAULT DROP] Phase timer error:',
                                error
                            );
                        }
                    );
            },
            delay
        );
}

function selectRandomVaultDropItem() {
    const pool = [
        ...ballCatalog,
        ...putterCatalog,
        ...legendaryCatalog,
        ...commonMiscCatalog
    ];

    return randomItem(
        pool
    );
}

function selectVaultDropItemForSource(
    selectionSource,
    selectedItem = null
) {
    if (
        selectedItem
    ) {
        return selectedItem;
    }

    switch (
        String(selectionSource || 'RANDOM').toUpperCase()
    ) {
        case 'COMMON':
            return selectCommonReward();

        case 'RARE':
            return randomItem(
                putterCatalog
            );

        case 'LEGENDARY':
            return randomItem(
                legendaryCatalog
            );

        default:
            return selectRandomVaultDropItem();
    }
}

function getVaultDropSelectionDescription(
    selectionSource
) {
    switch (
        String(selectionSource || 'RANDOM').toUpperCase()
    ) {
        case 'COMMON':
            return 'Common Item';

        case 'RARE':
            return 'Rare Item';

        case 'LEGENDARY':
            return 'Legendary Item';

        case 'FEATURED':
            return 'Featured Item';

        default:
            return 'Random Item';
    }
}

function getAuctionItemPool() {
    return [
        ...ballCatalog,
        ...putterCatalog,
        ...legendaryCatalog,
        ...commonMiscCatalog
    ];
}

function getFeaturedAuctionItemPool() {
    return [
        ...getAuctionItemPool(),
        ...auctionOnlyCatalog
    ];
}

function getAuctionItemTypeLabel(itemType) {
    if (itemType === 'ball') return 'BALL';
    if (itemType === 'putter') return 'PUTTER';
    if (itemType === 'legendary') return 'LEGENDARY';
    return 'MISC';
}

function getAuctionExclusiveReferenceLabel(rarity) {
    return `AUCTION-${String(rarity || 'COMMON').toUpperCase()}`;
}

function resolveAuctionItemReference(input) {
    const rawInput = String(input || '').trim();

    if (!rawInput) {
        return { ok: false, reason: 'EMPTY' };
    }

    let requestedType = null;
    let requestedName = rawInput;

    const qualifiedMatch = rawInput.match(
        /^(BALL|PUTTER|LEGENDARY|MISC)\s*:\s*(.+)$/i
    );

    if (qualifiedMatch) {
        const typeMap = {
            BALL: 'ball',
            PUTTER: 'putter',
            LEGENDARY: 'legendary',
            MISC: 'misc'
        };

        requestedType = typeMap[qualifiedMatch[1].toUpperCase()];
        requestedName = qualifiedMatch[2].trim();
    }

    const normalizedName = requestedName.toLocaleLowerCase();
    const matches = getAuctionItemPool().filter(
        item =>
            (!requestedType || item.type === requestedType) &&
            item.name.toLocaleLowerCase() === normalizedName
    );

    if (matches.length === 1) {
        return { ok: true, item: matches[0] };
    }

    if (matches.length > 1) {
        return { ok: false, reason: 'AMBIGUOUS', matches };
    }

    return { ok: false, reason: 'NOT_FOUND' };
}

function resolveFeaturedAuctionItemReference(input) {
    const rawInput = String(input || '').trim();

    if (!rawInput) {
        return { ok: false, reason: 'EMPTY' };
    }

    let requestedType = null;
    let requestedAuctionRarity = null;
    let requestedAuctionExclusive = null;
    let requestedName = rawInput;

    const qualifiedMatch = rawInput.match(
        /^(BALL|PUTTER|LEGENDARY|MISC|AUCTION-COMMON|AUCTION-RARE|AUCTION-LEGENDARY)\s*:\s*(.+)$/i
    );

    if (qualifiedMatch) {
        const qualifier =
            qualifiedMatch[1].toUpperCase();

        const typeMap = {
            BALL: 'ball',
            PUTTER: 'putter',
            LEGENDARY: 'legendary',
            MISC: 'misc'
        };

        if (
            qualifier.startsWith(
                'AUCTION-'
            )
        ) {
            requestedAuctionExclusive =
                true;

            requestedAuctionRarity =
                qualifier.substring(
                    'AUCTION-'.length
                );
        } else {
            requestedAuctionExclusive =
                false;

            requestedType =
                typeMap[qualifier];
        }

        requestedName =
            qualifiedMatch[2].trim();
    }

    const normalizedName =
        requestedName.toLocaleLowerCase();

    const matches =
        getFeaturedAuctionItemPool().filter(
            item =>
                (
                    !requestedType ||
                    item.type === requestedType
                ) &&
                (
                    requestedAuctionExclusive === null ||
                    Boolean(item.auctionExclusive) === requestedAuctionExclusive
                ) &&
                (
                    !requestedAuctionRarity ||
                    item.auctionRarity === requestedAuctionRarity
                ) &&
                item.name.toLocaleLowerCase() === normalizedName
        );

    if (matches.length === 1) {
        return {
            ok: true,
            item: matches[0]
        };
    }

    if (matches.length > 1) {
        return {
            ok: false,
            reason: 'AMBIGUOUS',
            matches
        };
    }

    return {
        ok: false,
        reason: 'NOT_FOUND'
    };
}

function buildAuctionItemReferenceText() {
    const sections = [
        { title: 'BALLS', type: 'ball', items: ballCatalog },
        { title: 'PUTTERS', type: 'putter', items: putterCatalog },
        { title: 'LEGENDARY', type: 'legendary', items: legendaryCatalog },
        { title: 'COMMON MISC', type: 'misc', items: commonMiscCatalog }
    ];

    const exclusiveSections = [
        { title: 'AUCTION ONLY - COMMON', rarity: 'COMMON' },
        { title: 'AUCTION ONLY - RARE', rarity: 'RARE' },
        { title: 'AUCTION ONLY - LEGENDARY', rarity: 'LEGENDARY' }
    ];

    const lines = [
        'SMASHPUTT AUCTION ITEM REFERENCE',
        '=================================',
        '',
        'Copy an exact line below into the optional item field for /smashputt auction or /smashputt-lottery.',
        'Using the category prefix guarantees the exact collectible is selected.',
        'AUCTION-* items are manual-select Auction Exclusives and are never randomized.',
        ''
    ];

    for (const section of sections) {
        lines.push(`${section.title} (${section.items.length})`);
        lines.push('-'.repeat(section.title.length + String(section.items.length).length + 3));

        const sortedItems = [...section.items].sort(
            (a, b) => a.name.localeCompare(b.name)
        );

        for (const item of sortedItems) {
            lines.push(`${getAuctionItemTypeLabel(section.type)}: ${item.name}`);
        }

        lines.push('');
    }

    for (
        const section
        of exclusiveSections
    ) {
        const items =
            auctionOnlyCatalog.filter(
                item =>
                    item.auctionRarity ===
                    section.rarity
            );

        lines.push(
            `${section.title} (${items.length})`
        );

        lines.push(
            '-'.repeat(
                section.title.length +
                String(items.length).length +
                3
            )
        );

        const sortedItems =
            [...items].sort(
                (a, b) =>
                    a.name.localeCompare(
                        b.name
                    )
            );

        for (
            const item
            of sortedItems
        ) {
            lines.push(
                `${getAuctionExclusiveReferenceLabel(section.rarity)}: ${item.name}`
            );
        }

        lines.push('');
    }

    return lines.join('\n');
}

async function handleAuctionItemsCommand(interaction) {
    const attachment = new AttachmentBuilder(
        Buffer.from(buildAuctionItemReferenceText(), 'utf8'),
        { name: 'smashputt-auction-items.txt' }
    );

    await interaction.reply({
        content:
            '📋 Current SmashPutt item reference. Save this text file and copy an exact item line into the optional `item` field when you want a featured Auction or Lottery.',
        files: [attachment],
        flags: MessageFlags.Ephemeral
    });
}

