async function clearOldTestServerCommands() {
    try {
        const testGuild =
            await client.guilds.fetch(
                OLD_TEST_SERVER_ID
            );

        await testGuild.commands.set(
            []
        );

        console.log(
            'Old SmashPutt test-server slash commands cleared.'
        );
    } catch (_) {
        // Fine if bot is no longer in test server.
    }
}

